INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s0', 'start', 0, 'set', 0, '', '', '', '', '', 'ai_sprite_outfit', 'stage', 's1', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1', 'start', 0, 'scene', 1, '', '', '', 'bg station_sunbreak', '', '', '', 's2', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2', 'start', 0, 'narration', 2, '', '', '穿过隧道，沿途的电线杆便被抛之身后。', '', '', '', '', 's3', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3', 'start', 0, 'narration', 3, '', '', '隆隆作响的火车在信号所前缓缓停下，灰暗的云朵将太阳遮的密不透风。', '', '', '', '', 's4', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s4', 'start', 0, 'narration', 4, '', '', '车窗外，捏着报纸等待列车进站的乘客已经拿上行李站起身，几个身穿制服的车辆乘务员下车负责引导。', '', '', '', '', 's5', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s5', 'start', 0, 'narration', 5, '', '', '白茫茫的天空，十一月的冷风钻不进车厢。', '', '', '', '', 's6', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s6', 'start', 0, 'narration', 6, '', '', '第三节车厢，在靠近窗户的某个座位，顾天鹏望着窗外，叹了口气。', '', '', '', '', 's7', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s7', 'start', 0, 'narration', 7, '', '', '重生到岛国的第十七年，刚从神川私塾毕业的顾天鹏，在十一月的第二周伊始，下定决心出门远足。', '', '', '', '', 's8', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s8', 'start', 0, 'narration', 8, '', '', '和其他人的重生不同。', '', '', '', '', 's9', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s9', 'start', 0, 'narration', 9, '', '', '没有觉醒系统之类的金手指，也没有好用的经验面板。', '', '', '', '', 's10', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s10', 'start', 0, 'narration', 10, '', '', '唯一和别人不一样的地方，只是顾天鹏有个特殊的、难以派上用场的能力：', '', '', '', '', 's11', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s11', 'start', 0, 'narration', 11, '', '', '只要在心里重复一遍对方说过的话，便能知道那句话是不是谎言。', '', '', '', '', 's12', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s12', 'start', 0, 'narration', 12, '', '', '放在军事、政治领域，或许称得上了不得。', '', '', '', '', 's13', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s13', 'start', 0, 'narration', 13, '', '', '但前提是别人会相信他能力确实存在，否则只会被当做开玩笑，或者中二过头了。', '', '', '', '', 's14', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s14', 'start', 0, 'narration', 14, '', '', '六岁那一年，父亲在建筑工地意外丧生，母亲不久也病倒离世，顾天鹏没有其他可以依靠的任何亲戚。', '', '', '', '', 's15', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s15', 'start', 0, 'narration', 15, '', '', '勉强靠社会资助完成了义务教育，不准备继续念大学。', '', '', '', '', 's16', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s16', 'start', 0, 'narration', 16, '', '', '这次出门，顾天鹏手里只剩可以维持半年生计的一些现金，行李也只有用来更换的另一套衣服。', '', '', '', '', 's17', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s17', 'start', 0, 'narration', 17, '', '', '他决定去越后汤泽放松一下。', '', '', '', '', 's18', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s18', 'start', 0, 'narration', 18, '', '', '在春天来临的时候，也同样是在他正式找工作之前。', '', '', '', '', 's19', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s19', 'start', 0, 'narration', 19, '', '', '合上德语杂志，顾天鹏靠在软软的靠背上，用手揉着眼皮放松。', '', '', '', '', 's20', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s20', 'start', 0, 'narration', 20, '', '', '四下传来交谈声，仿佛将车厢闷进了玻璃瓶里，声音忽远忽近。', '', '', '', '', 's21', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s21', 'start', 0, 'narration', 21, '', '', '行李箱的滚轮压过地板，发出清晰的吱咬声。', '', '', '', '', 's22', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s22', 'start', 0, 'narration', 22, '', '', '火车停靠很长时间，乘客大都上了车。', '', '', '', '', 's23', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s23', 'start', 0, 'narration', 23, '', '', '外面的乘务员正要收起方便残障人士进入的踏板，一个急匆匆的女声突然透过玻璃窗灌进来：', '', '', '', '', 's24', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s24', 'start', 0, 'dialogue', 24, 'ai', '星野爱', '等等，等等！我还没上车！', '', '', '', '', 's25', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s25', 'start', 0, 'set', 25, '', '', '', '', '', 'ai_sprite_mode', 'false', 's26', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s26', 'start', 0, 'set', 26, '', '', '', '', '', 'event_cg_mode', 'true', 's27', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s27', 'start', 0, 'scene', 27, '', '', '', 'cg station_hurry_suitcase', '', '', '', 's28', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s28', 'start', 0, 'narration', 28, '', '', '被这声音惊扰的顾天鹏，不怎么感兴趣地抬起半只眼睛瞄去。', '', '', '', '', 's29', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s29', 'start', 0, 'narration', 29, '', '', '只是一瞬间，能见的空气里，如同电影中一闪而过的某个画面。', '', '', '', '', 's30', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s30', 'start', 0, 'narration', 30, '', '', '久违的阳光穿透云层，温柔的金色闪现在少女的眼里。', '', '', '', '', 's31', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s31', 'start', 0, 'narration', 31, '', '', '秋日凄清荡然无存，凝眸望去，长空寥廓，白鸽掠过低空。', '', '', '', '', 's32', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s32', 'start', 0, 'narration', 32, '', '', '无论经过一年，三年，还是二十年，一辈子。', '', '', '', '', 's33', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s33', 'start', 0, 'narration', 33, '', '', '那副闯进灵魂的画面，顾天鹏永远记得真真切切。', '', '', '', '', 's34', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s34', 'start', 0, 'narration', 34, '', '', '吹进站台的风扬起少女的深蓝色长发。', '', '', '', '', 's35', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s35', 'start', 0, 'narration', 35, '', '', '她一手压低帽檐，一手拉着白色行李箱，碎花的连衣裙和羊绒围巾因风飘浮。', '', '', '', '', 's36', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s36', 'start', 0, 'dialogue', 36, 'conductor', '短发女乘务员', '下次要早点在这等着哦。', '', '', '', '', 's37', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s37', 'start', 0, 'narration', 37, '', '', '短发女乘务员像是责怪孩子一样说她，顺手接过她的行李箱。', '', '', '', '', 's38', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s38', 'start', 0, 'scene', 38, '', '', '', 'cg station_thanks_suitcase', '', '', '', 's39', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s39', 'start', 0, 'dialogue', 39, 'ai', '星野爱', '嗯嗯，谢谢！', '', '', '', '', 's40', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s40', 'start', 0, 'narration', 40, '', '', '少女漾出甜甜的笑，那笑容让人心情愉悦。', '', '', '', '', 's41', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s41', 'start', 0, 'set', 41, '', '', '', '', '', 'ai_sprite_mode', 'false', 's42', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s42', 'start', 0, 'set', 42, '', '', '', '', '', 'event_cg_mode', 'true', 's43', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s43', 'start', 0, 'scene', 43, '', '', '', 'cg train_find_seat', '', '', '', 's44', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s44', 'start', 0, 'narration', 44, '', '', '不一会儿，火车缓缓启动，少女钻进车厢里，和顾天鹏在同一节。', '', '', '', '', 's45', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s45', 'start', 0, 'narration', 45, '', '', '她对着座位上的序号挨个查看过去，像是检查座位损坏程度似的，最后停在顾天鹏身边。', '', '', '', '', 's46', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s46', 'start', 0, 'dialogue', 46, 'ai', '星野爱', '找到了。', '', '', '', '', 's47', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s47', 'start', 0, 'narration', 47, '', '', '她眯细的眼睛终于舒展开，脸上挂着惊喜的表情。', '', '', '', '', 's48', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s48', 'start', 0, 'narration', 48, '', '', '听见声音，顾天鹏支着手臂看过去。', '', '', '', '', 's49', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s49', 'start', 0, 'narration', 49, '', '', '那是一双仿佛藏着星星的双眼。', '', '', '', '', 's50', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s50', 'start', 0, 'narration', 50, '', '', '光是对视一眼，就让人仿若置身大山里的深空之下，想到皎洁的月光，又想到闪亮的舞台。', '', '', '', '', 's51', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s51', 'start', 0, 'narration', 51, '', '', '即使没有阳光的点缀，那眼睛也美得让人失神，像是要把顾天鹏的气息全部夺走。', '', '', '', '', 's52', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s52', 'start', 0, 'narration', 52, '', '', '少女没有立刻坐下，反而望了一眼头顶的行李架，又刻意拖动行李箱的滚轮。', '', '', '', '', 's53', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s53', 'start', 0, 'dialogue', 53, 'taku', '顾天鹏', '要帮忙吗？', '', '', '', '', 's54', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s54', 'start', 0, 'narration', 54, '', '', '他犹豫了下问。', '', '', '', '', 's55', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s56', 'start', 0, 'narration', 56, '', '', '顾天鹏没有等她第二次暗示，起身把白色行李箱接到手里。', '', '', '', '', 's57', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s57', 'start', 0, 'dialogue', 57, 'ai', '星野爱', '谢谢！那就拜托你了。', '', '', '', '', 's58', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s58', 'start', 0, 'narration', 58, '', '', '她退后半步，把过道让出来。于是这场原本独自开始的旅行，在第一件行李被举起来时就改变了形状。', '', '', '', '', 's76', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s59', 'start', 0, 'narration', 59, '', '', '顾天鹏没有立刻表现得过分热心，只是把手停在半空，等她真的需要帮助时再伸过去。', '', '', '', '', 's60', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s60', 'start', 0, 'narration', 60, '', '', '他习惯给陌生人留出一点距离，即使对方有一双让人很难移开视线的眼睛。', '', '', '', '', 's61', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s61', 'start', 0, 'dialogue', 61, 'ai', '星野爱', '那个，可以帮我一下吗？', '', '', '', '', 's62', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s62', 'start', 0, 'dialogue', 62, 'taku', '顾天鹏', '当然。', '', '', '', '', 's63', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s63', 'start', 0, 'narration', 63, '', '', '等她把请求说出口，他才接过行李箱。这个短短的停顿，让两个人都确认了彼此愿意靠近的速度。', '', '', '', '', 's64', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s64', 'start', 0, 'narration', 64, '', '', '行李箱被稳稳推进行李架时，星野爱像验收工程一样抬头看了看，又把一只小兔子发卡从刘海边拨正。', '', '', '', '', 's65', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s65', 'start', 0, 'dialogue', 65, 'ai', '星野爱', '顾天鹏，你是不是那种一定要等别人开口，才会觉得不冒犯的人？', '', '', '', '', 's66', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s66', 'start', 0, 'dialogue', 66, 'taku', '顾天鹏', '差不多。', '', '', '', '', 's67', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s67', 'start', 0, 'dialogue', 67, 'ai', '星野爱', '那我要是不说，你就会一直看着？', '', '', '', '', 's68', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s68', 'start', 0, 'dialogue', 68, 'taku', '顾天鹏', '我会判断。', '', '', '', '', 's69', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s69', 'start', 0, 'dialogue', 69, 'ai', '星野爱', '判断失败的话呢？', '', '', '', '', 's70', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s70', 'start', 0, 'dialogue', 70, 'taku', '顾天鹏', '道歉。', '', '', '', '', 's71', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s71', 'start', 0, 'narration', 71, '', '', '她听见这个答案，忍不住笑起来，却没有继续追问他的名字、年龄和秘密。', '', '', '', '', 's72', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s72', 'start', 0, 'narration', 72, '', '', '两个人把话题停在车票、天气和下一站的时刻表上。那是一条更礼貌的路线，像在湿玻璃上画出的直线，清楚，却不够贪心。', '', '', '', '', 's73', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s73', 'start', 0, 'narration', 73, '', '', '后来乘务员推着小车经过，星野爱买了一瓶热茶，没有买便当。顾天鹏也没有把巧克力拿出来。', '', '', '', '', 's74', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s74', 'start', 0, 'narration', 74, '', '', '他们在同一张小桌前各自保留着一点空白，直到列车穿过县界，窗外的雨色慢慢压下来。', '', '', '', '', 's75', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s75', 'start', 0, 'jump', 75, '', '', '', '', '', '', '', 's217', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s55', 'start', 0, 'menu', 55, '', '', '', '', '', '', '', 's76', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s76', 'start', 0, 'narration', 76, '', '', '等行李箱终于安置到头顶，少女整理好裙子，在他正对面的位置坐下。', '', '', '', '', 's77', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s77', 'start', 0, 'scene', 77, '', '', '', 'bg train_table', '', '', '', 's78', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s78', 'start', 0, 'set', 78, '', '', '', '', '', 'ai_sprite_mode', 'true', 's79', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s79', 'start', 0, 'set', 79, '', '', '', '', '', 'event_cg_mode', 'false', 's80', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s80', 'start', 0, 'sprite', 80, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's81', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s81', 'start', 0, 'narration', 81, '', '', '行李摆上架子，顾天鹏拍了拍手，重新坐好。', '', '', '', '', 's82', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s82', 'start', 0, 'dialogue', 82, 'ai', '星野爱', '谢谢，你叫什么呢？', '', '', '', '', 's83', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s83', 'start', 0, 'narration', 83, '', '', '少女的脸上很适合挂着笑容。', '', '', '', '', 's84', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s84', 'start', 0, 'dialogue', 84, 'taku', '顾天鹏', '顾天鹏。', '', '', '', '', 's85', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s85', 'start', 0, 'dialogue', 85, 'ai', '星野爱', '星野爱。', '', '', '', '', 's86', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s86', 'start', 0, 'narration', 86, '', '', '她把帽子摘下来，撩了下搭在脖颈和羊绒围巾交界处的长发。', '', '', '', '', 's87', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s87', 'start', 0, 'narration', 87, '', '', '一股淡淡的清香弥散到空气中，如同刚摘下的樱桃一般。', '', '', '', '', 's88', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s88', 'start', 0, 'narration', 88, '', '', '顾天鹏看愣神似的望着她。', '', '', '', '', 's89', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s89', 'start', 0, 'set', 89, '', '', '', '', '', 'ai_sprite_mode', 'false', 's90', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s90', 'start', 0, 'set', 90, '', '', '', '', '', 'event_cg_mode', 'true', 's91', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s91', 'start', 0, 'scene', 91, '', '', '', 'cg train_table_chat', '', '', '', 's92', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s92', 'start', 0, 'dialogue', 92, 'ai', '星野爱', '看什么呢？', '', '', '', '', 's93', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s93', 'start', 0, 'narration', 93, '', '', '被盯了一阵子，星野爱才语调婉转地说。', '', '', '', '', 's94', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s94', 'start', 0, 'dialogue', 94, 'taku', '顾天鹏', '抱歉。', '', '', '', '', 's95', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s95', 'start', 0, 'narration', 95, '', '', '顾天鹏为自己不够绅士的表现道歉。', '', '', '', '', 's96', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s96', 'start', 0, 'dialogue', 96, 'taku', '顾天鹏', '星野小姐太好看了，一不小心就。', '', '', '', '', 's97', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s97', 'start', 0, 'dialogue', 97, 'ai', '星野爱', '你这人才是吧。', '', '', '', '', 's98', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s98', 'start', 0, 'narration', 98, '', '', '她完全没有生气，反倒前倾上半身，兴趣盎然地盯着顾天鹏的眼睛。', '', '', '', '', 's99', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s99', 'start', 0, 'dialogue', 99, 'ai', '星野爱', '长那么好看，莫非职业是演员？', '', '', '', '', 's100', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s100', 'start', 0, 'dialogue', 100, 'taku', '顾天鹏', '谬赞了。', '', '', '', '', 's101', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s101', 'start', 0, 'dialogue', 101, 'ai', '星野爱', '多大？', '', '', '', '', 's102', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s102', 'start', 0, 'dialogue', 102, 'taku', '顾天鹏', '十七。', '', '', '', '', 's103', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s103', 'start', 0, 'narration', 103, '', '', '说完他又补充。', '', '', '', '', 's104', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s104', 'start', 0, 'dialogue', 104, 'taku', '顾天鹏', '上个月刚满。', '', '', '', '', 's105', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s105', 'start', 0, 'dialogue', 105, 'ai', '星野爱', '是高中生啊？', '', '', '', '', 's106', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s106', 'start', 0, 'dialogue', 106, 'taku', '顾天鹏', '已经高中毕业。', '', '', '', '', 's107', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s107', 'start', 0, 'dialogue', 107, 'ai', '星野爱', '哦，我比你大一岁。', '', '', '', '', 's108', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s108', 'start', 0, 'narration', 108, '', '', '她仿佛在说一件很了不起的事情，把手搭在发育良好的胸前。', '', '', '', '', 's109', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s109', 'start', 0, 'dialogue', 109, 'ai', '星野爱', '我十八，算是你姐姐。', '', '', '', '', 's110', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s110', 'start', 0, 'narration', 110, '', '', '谎言。', '', '', '', '', 's111', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s111', 'start', 0, 'narration', 111, '', '', '这种简单的谎言，顾天鹏一下便能轻松识破。', '', '', '', '', 's112', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s112', 'start', 0, 'dialogue', 112, 'ai', '星野爱', '怎么可能是谎言嘛。', '', '', '', '', 's113', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s113', 'start', 0, 'dialogue', 113, 'ai', '星野爱', '这种事情哪有撒谎的必要。', '', '', '', '', 's114', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s114', 'start', 0, 'narration', 114, '', '', '顾天鹏没在意她解释了什么，径自问：', '', '', '', '', 's115', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s115', 'start', 0, 'dialogue', 115, 'taku', '顾天鹏', '十七？', '', '', '', '', 's116', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s116', 'start', 0, 'dialogue', 116, 'ai', '星野爱', '十八！', '', '', '', '', 's117', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s117', 'start', 0, 'dialogue', 117, 'taku', '顾天鹏', '不过看长相又像是十六……', '', '', '', '', 's118', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s118', 'start', 0, 'narration', 118, '', '', '他托起下巴。', '', '', '', '', 's119', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s119', 'start', 0, 'dialogue', 119, 'ai', '星野爱', '真的是十八啦。', '', '', '', '', 's120', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s120', 'start', 0, 'set', 120, '', '', '', '', '', 'ai_sprite_mode', 'true', 's121', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s121', 'start', 0, 'set', 121, '', '', '', '', '', 'event_cg_mode', 'false', 's122', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s122', 'start', 0, 'scene', 122, '', '', '', 'bg train_mountains', '', '', '', 's123', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s123', 'start', 0, 'sprite', 123, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's124', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s124', 'start', 0, 'narration', 124, '', '', '火车开进住宅区，绿色的房子一闪而过，每隔几米便有塔台，电缆呈乱糟糟的直线。', '', '', '', '', 's125', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s125', 'start', 0, 'dialogue', 125, 'taku', '顾天鹏', '星野小姐。', '', '', '', '', 's126', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s126', 'start', 0, 'narration', 126, '', '', '顾天鹏把手里合上的德语杂志搭在桌面上，凝视星野爱的眼睛。', '', '', '', '', 's127', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s127', 'start', 0, 'dialogue', 127, 'taku', '顾天鹏', '你骗不了我，我可是能识破所有谎言的。', '', '', '', '', 's128', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s128', 'start', 0, 'scene', 128, '', '', '', 'bg train_table', '', '', '', 's129', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s129', 'start', 0, 'set', 129, '', '', '', '', '', 'ai_sprite_mode', 'true', 's130', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s130', 'start', 0, 'set', 130, '', '', '', '', '', 'event_cg_mode', 'false', 's131', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s131', 'start', 0, 'sprite', 131, '', '', '', '', '[{"image": "heroine stage_surprised", "pos": "heroine_bust_center"}]', '', '', 's132', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s132', 'start', 0, 'dialogue', 132, 'ai', '星野爱', '识破谎言？', '', '', '', '', 's133', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s133', 'start', 0, 'narration', 133, '', '', '星野爱眼睛都瞪的更大了。', '', '', '', '', 's134', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s134', 'start', 0, 'dialogue', 134, 'taku', '顾天鹏', '具体的原因。', '', '', '', '', 's135', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s135', 'start', 0, 'narration', 135, '', '', '顾天鹏思考片刻。', '', '', '', '', 's136', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s136', 'start', 0, 'dialogue', 136, 'taku', '顾天鹏', '我想你高中没毕业，现在又是十一月八号……逃学出来的？', '', '', '', '', 's137', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s137', 'start', 0, 'dialogue', 137, 'ai', '星野爱', '才不是！', '', '', '', '', 's138', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s138', 'start', 0, 'dialogue', 138, 'taku', '顾天鹏', '奇怪，这次没有撒谎。', '', '', '', '', 's139', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s139', 'start', 0, 'dialogue', 139, 'ai', '星野爱', '你这能力还真是好用啊。', '', '', '', '', 's140', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s140', 'start', 0, 'narration', 140, '', '', '她赌气似的鼓起脸颊朝外看去，顾天鹏也眼望远方。', '', '', '', '', 's141', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s141', 'start', 0, 'set', 141, '', '', '', '', '', 'ai_sprite_mode', 'true', 's142', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s142', 'start', 0, 'set', 142, '', '', '', '', '', 'event_cg_mode', 'false', 's143', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s143', 'start', 0, 'scene', 143, '', '', '', 'bg lake_bridge', '', '', '', 's144', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s144', 'start', 0, 'sprite', 144, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's145', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s145', 'start', 0, 'narration', 145, '', '', '风景变换到大桥之上。', '', '', '', '', 's146', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s146', 'start', 0, 'narration', 146, '', '', '脆弱的薄云像是被冻僵一样凝滞在天空，外面竟是白茫茫一片，连湖面都泛着冰冷的微光。', '', '', '', '', 's147', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s147', 'start', 0, 'narration', 147, '', '', '有人起身将车窗打开，十一月的北风从不大的缝隙涌进来。', '', '', '', '', 's148', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s148', 'start', 0, 'narration', 148, '', '', '冷倒是不冷，倒不如说，车厢内的空气还因此清新起来。', '', '', '', '', 's149', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s149', 'start', 0, 'narration', 149, '', '', '将视线从窗外拉回来，过了大约十几秒，星野爱边整理围巾边若无其事地说：', '', '', '', '', 's150', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s150', 'start', 0, 'scene', 150, '', '', '', 'bg train_table', '', '', '', 's151', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s151', 'start', 0, 'set', 151, '', '', '', '', '', 'ai_sprite_mode', 'true', 's152', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s152', 'start', 0, 'set', 152, '', '', '', '', '', 'event_cg_mode', 'false', 's153', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s153', 'start', 0, 'sprite', 153, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's154', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s154', 'start', 0, 'dialogue', 154, 'ai', '星野爱', '我其实十六。', '', '', '', '', 's155', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s155', 'start', 0, 'dialogue', 155, 'taku', '顾天鹏', '猜到了。', '', '', '', '', 's156', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s156', 'start', 0, 'narration', 156, '', '', '顾天鹏仍看着窗外，思考海天交接的地方泛白的原因。', '', '', '', '', 's157', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s157', 'start', 0, 'dialogue', 157, 'ai', '星野爱', '不过没有逃学。', '', '', '', '', 's158', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s158', 'start', 0, 'dialogue', 158, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's159', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s159', 'start', 0, 'narration', 159, '', '', '顾天鹏知道这不是谎言。', '', '', '', '', 's160', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s160', 'start', 0, 'narration', 160, '', '', '他把手支在窗边，摸着不存在胡须的下巴，等待对方继续往下说。', '', '', '', '', 's161', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s161', 'start', 0, 'dialogue', 161, 'ai', '星野爱', '我要是说我是个孤儿。', '', '', '', '', 's162', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s162', 'start', 0, 'narration', 162, '', '', '她抬起头。', '', '', '', '', 's163', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s163', 'start', 0, 'dialogue', 163, 'ai', '星野爱', '这你也相信吗？', '', '', '', '', 's164', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s164', 'start', 0, 'narration', 164, '', '', '顾天鹏听了，有点意外地扭头望着她。', '', '', '', '', 's165', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s165', 'start', 0, 'narration', 165, '', '', '他在心里将这句话重复一遍。', '', '', '', '', 's166', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s166', 'start', 0, 'dialogue', 166, 'taku', '顾天鹏', '我信。', '', '', '', '', 's167', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s167', 'start', 0, 'dialogue', 167, 'ai', '星野爱', '那我要是说我是离家出走的，你也信吗？', '', '', '', '', 's168', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s168', 'start', 0, 'dialogue', 168, 'taku', '顾天鹏', '这大概是谎言。', '', '', '', '', 's169', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s169', 'start', 0, 'set', 169, '', '', '', '', '', 'ai_sprite_mode', 'false', 's170', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s170', 'start', 0, 'set', 170, '', '', '', '', '', 'event_cg_mode', 'true', 's171', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s171', 'start', 0, 'scene', 171, '', '', '', 'cg train_table_chat', '', '', '', 's172', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s172', 'start', 0, 'dialogue', 172, 'ai', '星野爱', '有趣！', '', '', '', '', 's173', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s173', 'start', 0, 'narration', 173, '', '', '她笑了。', '', '', '', '', 's174', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s174', 'start', 0, 'narration', 174, '', '', '这是顾天鹏在世界上见过的最美的笑容。', '', '', '', '', 's175', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s175', 'start', 0, 'dialogue', 175, 'taku', '顾天鹏', '不能实话实说？', '', '', '', '', 's176', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s176', 'start', 0, 'dialogue', 176, 'ai', '星野爱', '这个嘛……', '', '', '', '', 's177', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s177', 'start', 0, 'narration', 177, '', '', '她沉吟一下，仿佛把微笑用笔描了一遍，还娇俏地吐出舌头，样子可爱极了。', '', '', '', '', 's178', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s178', 'start', 0, 'dialogue', 178, 'ai', '星野爱', '是秘密！', '', '', '', '', 's179', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s179', 'start', 0, 'dialogue', 179, 'taku', '顾天鹏', '是秘密啊……', '', '', '', '', 's180', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s180', 'start', 0, 'dialogue', 180, 'ai', '星野爱', '嘻嘻。', '', '', '', '', 's181', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s181', 'start', 0, 'narration', 181, '', '', '顾天鹏装出忧伤的样子叹了口气。', '', '', '', '', 's182', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s182', 'start', 0, 'dialogue', 182, 'taku', '顾天鹏', '我可是连最宝贵的秘密都告诉你了，这样一点都不公平。', '', '', '', '', 's183', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s183', 'start', 0, 'dialogue', 183, 'ai', '星野爱', '啊，你别难过呀。', '', '', '', '', 's184', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s184', 'start', 0, 'narration', 184, '', '', '她看起来有些自责。', '', '', '', '', 's185', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s185', 'start', 0, 'dialogue', 185, 'ai', '星野爱', '你那不是逗我玩的吗？', '', '', '', '', 's186', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s186', 'start', 0, 'dialogue', 186, 'taku', '顾天鹏', '是真的。', '', '', '', '', 's187', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s187', 'start', 0, 'dialogue', 187, 'ai', '星野爱', '那简直是超能力了吧？', '', '', '', '', 's188', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s188', 'start', 0, 'dialogue', 188, 'taku', '顾天鹏', '所以我只和你一个人说过。', '', '', '', '', 's189', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s189', 'start', 0, 'dialogue', 189, 'ai', '星野爱', '怕被抓去做研究？', '', '', '', '', 's190', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s190', 'start', 0, 'dialogue', 190, 'taku', '顾天鹏', '别转移话题。', '', '', '', '', 's191', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s191', 'start', 0, 'dialogue', 191, 'ai', '星野爱', '嘿嘿。', '', '', '', '', 's192', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s192', 'start', 0, 'narration', 192, '', '', '她用小粉拳砸在自己的脑袋上。', '', '', '', '', 's193', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s193', 'start', 0, 'narration', 193, '', '', '这是顾天鹏在世界上见过的最可爱的少女。', '', '', '', '', 's194', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s194', 'start', 0, 'scene', 194, '', '', '', 'bg train_table', '', '', '', 's195', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s195', 'start', 0, 'set', 195, '', '', '', '', '', 'ai_sprite_mode', 'true', 's196', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s196', 'start', 0, 'set', 196, '', '', '', '', '', 'event_cg_mode', 'false', 's197', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s197', 'start', 0, 'sprite', 197, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's198', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s198', 'start', 0, 'dialogue', 198, 'taku', '顾天鹏', '说吧。', '', '', '', '', 's199', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s199', 'start', 0, 'dialogue', 199, 'ai', '星野爱', '勉为其难告诉你哦。', '', '', '', '', 's200', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s200', 'start', 0, 'narration', 200, '', '', '她对着车窗玻璃哈了口气，在上面写上“星野爱”的字样，然后重新坐正身体。', '', '', '', '', 's201', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s201', 'start', 0, 'dialogue', 201, 'ai', '星野爱', '我的名字是星野爱，不是没毕业的高中生，也不是离家出走的任性少女。', '', '', '', '', 's202', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s202', 'start', 0, 'dialogue', 202, 'ai', '星野爱', '因为家里的监护人想让我当偶像出道，可我还没做好决定，就想着一个人出来旅行放松放松，回去再给他答复。就这么简单。', '', '', '', '', 's203', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s203', 'start', 0, 'dialogue', 203, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's204', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s204', 'start', 0, 'narration', 204, '', '', '顾天鹏若有所思地点点头。', '', '', '', '', 's205', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s205', 'start', 0, 'dialogue', 205, 'taku', '顾天鹏', '不过刚开始为什么要撒谎呢？', '', '', '', '', 's206', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s206', 'start', 0, 'dialogue', 206, 'ai', '星野爱', '你问为什么……', '', '', '', '', 's207', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s207', 'start', 0, 'narration', 207, '', '', '星野爱摸了摸下唇，看着窗玻璃中倒影的影子。', '', '', '', '', 's208', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s208', 'start', 0, 'dialogue', 208, 'ai', '星野爱', '为什么……这我也说不清啦。', '', '', '', '', 's209', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s209', 'start', 0, 'dialogue', 209, 'taku', '顾天鹏', '笨蛋少女？', '', '', '', '', 's210', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s210', 'start', 0, 'dialogue', 210, 'ai', '星野爱', '保持神秘！', '', '', '', '', 's211', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s211', 'start', 0, 'dialogue', 211, 'taku', '顾天鹏', '可爱。', '', '', '', '', 's212', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s212', 'start', 0, 'dialogue', 212, 'ai', '星野爱', '可恨的帅哥！', '', '', '', '', 's213', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s213', 'start', 0, 'dialogue', 213, 'taku', '顾天鹏', '头发吃进嘴里了哦。', '', '', '', '', 's214', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s214', 'start', 0, 'dialogue', 214, 'ai', '星野爱', '哪里哪里？', '', '', '', '', 's215', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s215', 'start', 0, 'narration', 215, '', '', '十一月的秋色中，黑色的火车驶向前方，闯进未知的土地。', '', '', '', '', 's216', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s216', 'start', 0, 'narration', 216, '', '', '窗外的世界，山棱线模糊不清，鸟叫声由远及近。', '', '', '', '', 's217', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s217', 'ch1_rain_stop', 1, 'set', 217, '', '', '', '', '', 'ai_sprite_mode', 'false', 's218', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s218', 'ch1_rain_stop', 1, 'set', 218, '', '', '', '', '', 'event_cg_mode', 'true', 's219', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s219', 'ch1_rain_stop', 1, 'scene', 219, '', '', '', 'cg takasaki_rain_stop', '', '', '', 's220', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s220', 'ch1_rain_stop', 1, 'narration', 220, '', '', '穿过县界，霏霏细雨飘下空漠，附上车窗，抬眼不见晚霞。', '', '', '', '', 's221', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s221', 'ch1_rain_stop', 1, 'narration', 221, '', '', '临近黄昏，火车在沿站靠停。', '', '', '', '', 's222', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s222', 'ch1_rain_stop', 1, 'narration', 222, '', '', '下次发车大约是十五分钟后，顾天鹏合上翻了七遍的杂志，从包里取出宝特瓶喝水。', '', '', '', '', 's223', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s223', 'ch1_rain_stop', 1, 'narration', 223, '', '', '沉闷的车厢有乘客上来，周围响起零碎的对话声，一个妇女在安抚哭泣的小孩。', '', '', '', '', 's224', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s224', 'ch1_rain_stop', 1, 'narration', 224, '', '', '星野爱好奇地望向窗外，乘务员用温柔的声音提醒大家车内的灯光即将打开。', '', '', '', '', 's225', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s225', 'ch1_rain_stop', 1, 'narration', 225, '', '', '灯一亮，外面的世界好像突然暗了一分。', '', '', '', '', 's226', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s226', 'ch1_rain_stop', 1, 'narration', 226, '', '', '窗玻璃上倒影着星野爱的侧脸，在顾天鹏眼里，那双眼睛变得格外柔和、透明。', '', '', '', '', 's227', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s227', 'ch1_rain_stop', 1, 'scene', 227, '', '', '', 'cg train_open_window_rain', '', '', '', 's228', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s228', 'ch1_rain_stop', 1, 'narration', 228, '', '', '她站起身，把胸前的围巾拨到脖子后面，用手推开车窗。', '', '', '', '', 's229', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s229', 'ch1_rain_stop', 1, 'narration', 229, '', '', '冷空气席卷进来，带着两三颗踪迹鲜明的雨点，但不足以打湿桌面。', '', '', '', '', 's230', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s230', 'ch1_rain_stop', 1, 'narration', 230, '', '', '和出发时相比，空气的温度降了不少。', '', '', '', '', 's231', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s231', 'ch1_rain_stop', 1, 'narration', 231, '', '', '星野爱把下巴缩进羊绒围巾之中，只露出鼻子和眼睛。', '', '', '', '', 's232', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s232', 'ch1_rain_stop', 1, 'narration', 232, '', '', '一口白气从柔软的布料钻出来，她将身子探到外边，好看的脸颊眺望远方。', '', '', '', '', 's233', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s233', 'ch1_rain_stop', 1, 'narration', 233, '', '', '似有似无的雾霭之中，乌鸦落在交错的电线上，灰色的橘猫从低矮的屋舍跳下来，转瞬消失不见。', '', '', '', '', 's234', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s234', 'ch1_rain_stop', 1, 'dialogue', 234, 'ai', '星野爱', '真美。', '', '', '', '', 's235', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s235', 'ch1_rain_stop', 1, 'narration', 235, '', '', '但这交谈没有对象，像是在自言自语。', '', '', '', '', 's236', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s236', 'ch1_rain_stop', 1, 'narration', 236, '', '', '视线从她微微泛红的脸上移开，顾天鹏将目光投向被雨水涂黑的大地，并行的铁轨生了锈。', '', '', '', '', 's237', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s237', 'ch1_rain_stop', 1, 'dialogue', 237, 'taku', '顾天鹏', '是高崎。', '', '', '', '', 's238', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s238', 'ch1_rain_stop', 1, 'dialogue', 238, 'ai', '星野爱', '高崎？', '', '', '', '', 's239', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s239', 'ch1_rain_stop', 1, 'narration', 239, '', '', '她回身。', '', '', '', '', 's240', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s240', 'ch1_rain_stop', 1, 'dialogue', 240, 'taku', '顾天鹏', '之后是越后汤泽。', '', '', '', '', 's241', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s241', 'ch1_rain_stop', 1, 'dialogue', 241, 'ai', '星野爱', '这我倒是知道。', '', '', '', '', 's242', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s242', 'ch1_rain_stop', 1, 'scene', 242, '', '', '', 'bg train_table_rain', '', '', '', 's243', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s243', 'ch1_rain_stop', 1, 'set', 243, '', '', '', '', '', 'ai_sprite_mode', 'true', 's244', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s244', 'ch1_rain_stop', 1, 'set', 244, '', '', '', '', '', 'event_cg_mode', 'false', 's245', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s245', 'ch1_rain_stop', 1, 'sprite', 245, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's246', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s246', 'ch1_rain_stop', 1, 'dialogue', 246, 'taku', '顾天鹏', '你要去哪？', '', '', '', '', 's247', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s247', 'ch1_rain_stop', 1, 'narration', 247, '', '', '他随口问，把宝特瓶收好，一手搭着桌子，一手托起下颚，眼睛凝视星野爱。', '', '', '', '', 's248', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s248', 'ch1_rain_stop', 1, 'dialogue', 248, 'ai', '星野爱', '越后汤泽吧……', '', '', '', '', 's249', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s249', 'ch1_rain_stop', 1, 'narration', 249, '', '', '星野爱将食指抵在唇上。', '', '', '', '', 's250', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s250', 'ch1_rain_stop', 1, 'dialogue', 250, 'ai', '星野爱', '其实去哪都一样，我只是想去一个可以放松的地方休息。', '', '', '', '', 's251', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s251', 'ch1_rain_stop', 1, 'dialogue', 251, 'taku', '顾天鹏', '只是这样？', '', '', '', '', 's252', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s252', 'ch1_rain_stop', 1, 'dialogue', 252, 'ai', '星野爱', '只是这样。', '', '', '', '', 's253', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s253', 'ch1_rain_stop', 1, 'narration', 253, '', '', '顾天鹏点头。', '', '', '', '', 's254', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s254', 'ch1_rain_stop', 1, 'dialogue', 254, 'taku', '顾天鹏', '温泉，赏雪，滑雪，吃草莓村的“越后姬”，体验手打荞麦面，享受热腾腾的炸天妇罗。我为这个来的。', '', '', '', '', 's255', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s255', 'ch1_rain_stop', 1, 'dialogue', 255, 'ai', '星野爱', '你很了解这一带嘛。', '', '', '', '', 's256', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s256', 'ch1_rain_stop', 1, 'narration', 256, '', '', '他晃了晃上车前买的旅行攻略。', '', '', '', '', 's257', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s257', 'ch1_rain_stop', 1, 'dialogue', 257, 'ai', '星野爱', '喔，竟然还有这种东西！', '', '', '', '', 's258', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s258', 'ch1_rain_stop', 1, 'narration', 258, '', '', '顾天鹏把册子递给她，她很自然地接过。', '', '', '', '', 's259', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s259', 'ch1_rain_stop', 1, 'narration', 259, '', '', '为了防止毛毛雨打湿纸张，她把窗户严严实实地关好，然后坐回位置翻了几页。', '', '', '', '', 's260', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s260', 'ch1_rain_stop', 1, 'set', 260, '', '', '', '', '', 'ai_sprite_mode', 'false', 's261', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s261', 'ch1_rain_stop', 1, 'set', 261, '', '', '', '', '', 'event_cg_mode', 'true', 's262', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s262', 'ch1_rain_stop', 1, 'scene', 262, '', '', '', 'cg train_guidebook', '', '', '', 's263', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s263', 'ch1_rain_stop', 1, 'dialogue', 263, 'ai', '星野爱', '喔，喔～', '', '', '', '', 's264', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s264', 'ch1_rain_stop', 1, 'narration', 264, '', '', '她对着小册子时不时发出惊叹，偶尔还象征性地点头。', '', '', '', '', 's265', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s265', 'ch1_rain_stop', 1, 'dialogue', 265, 'taku', '顾天鹏', '还不错吧。', '', '', '', '', 's266', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s266', 'ch1_rain_stop', 1, 'dialogue', 266, 'ai', '星野爱', '东京外面还有这种地方。', '', '', '', '', 's267', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s267', 'ch1_rain_stop', 1, 'narration', 267, '', '', '星野爱啪的一声把册子合上，抬起头说。', '', '', '', '', 's268', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s268', 'ch1_rain_stop', 1, 'dialogue', 268, 'ai', '星野爱', '东京，真厉害！', '', '', '', '', 's269', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s269', 'ch1_rain_stop', 1, 'dialogue', 269, 'taku', '顾天鹏', '这和东京没关系了吧。', '', '', '', '', 's270', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s270', 'ch1_rain_stop', 1, 'dialogue', 270, 'ai', '星野爱', '日本那么小，全算进东京里也没问题啦。', '', '', '', '', 's271', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s271', 'ch1_rain_stop', 1, 'dialogue', 271, 'taku', '顾天鹏', '正常才不会这么想吧。', '', '', '', '', 's272', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s272', 'ch1_rain_stop', 1, 'dialogue', 272, 'ai', '星野爱', '这不就说明我和谁都不一样？', '', '', '', '', 's273', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s273', 'ch1_rain_stop', 1, 'narration', 273, '', '', '她露出有些得意，又有些搞怪的笑容。', '', '', '', '', 's274', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s274', 'ch1_rain_stop', 1, 'narration', 274, '', '', '顾天鹏想了想。', '', '', '', '', 's275', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s275', 'ch1_rain_stop', 1, 'dialogue', 275, 'taku', '顾天鹏', '算是。', '', '', '', '', 's276', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s276', 'ch1_rain_stop', 1, 'narration', 276, '', '', '在制服里面添了件厚衣服的乘务员从过道经过，被座位上的少年和少女吸引了视线。', '', '', '', '', 's277', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s277', 'ch1_rain_stop', 1, 'narration', 277, '', '', '但也只是匆匆看一眼，身影很快离开。', '', '', '', '', 's278', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s278', 'ch1_rain_stop', 1, 'scene', 278, '', '', '', 'bg train_table_rain', '', '', '', 's279', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s279', 'ch1_rain_stop', 1, 'set', 279, '', '', '', '', '', 'ai_sprite_mode', 'true', 's280', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s280', 'ch1_rain_stop', 1, 'set', 280, '', '', '', '', '', 'event_cg_mode', 'false', 's281', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s281', 'ch1_rain_stop', 1, 'sprite', 281, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's282', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s282', 'ch1_rain_stop', 1, 'narration', 282, '', '', '星野爱继续打开册子翻阅。', '', '', '', '', 's283', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s283', 'ch1_rain_stop', 1, 'dialogue', 283, 'ai', '星野爱', '这个地方。', '', '', '', '', 's284', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s284', 'ch1_rain_stop', 1, 'narration', 284, '', '', '过了一会儿，她用那修长的手指对准攻略上的一幅插图。', '', '', '', '', 's285', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s285', 'ch1_rain_stop', 1, 'dialogue', 285, 'ai', '星野爱', '看起来很好玩的样子！', '', '', '', '', 's286', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s286', 'ch1_rain_stop', 1, 'narration', 286, '', '', '顾天鹏盯过去。', '', '', '', '', 's287', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s287', 'ch1_rain_stop', 1, 'dialogue', 287, 'taku', '顾天鹏', '轻井泽。', '', '', '', '', 's288', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s288', 'ch1_rain_stop', 1, 'dialogue', 288, 'ai', '星野爱', '也在那？', '', '', '', '', 's289', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s289', 'ch1_rain_stop', 1, 'dialogue', 289, 'taku', '顾天鹏', '你说越后汤泽？', '', '', '', '', 's290', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s290', 'ch1_rain_stop', 1, 'narration', 290, '', '', '他调整了下坐姿。', '', '', '', '', 's291', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s291', 'ch1_rain_stop', 1, 'dialogue', 291, 'taku', '顾天鹏', '离那不远，应该说是周边吧……东京的周边的周边？', '', '', '', '', 's292', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s292', 'ch1_rain_stop', 1, 'dialogue', 292, 'ai', '星野爱', '这个说法真有趣。', '', '', '', '', 's293', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s293', 'ch1_rain_stop', 1, 'narration', 293, '', '', '她声音让人安心。', '', '', '', '', 's294', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s294', 'ch1_rain_stop', 1, 'narration', 294, '', '', '顾天鹏揶揄她。', '', '', '', '', 's295', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s295', 'ch1_rain_stop', 1, 'dialogue', 295, 'taku', '顾天鹏', '这样子，我也是和谁都不一样的人了。', '', '', '', '', 's296', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s296', 'ch1_rain_stop', 1, 'dialogue', 296, 'ai', '星野爱', '不愧是你！', '', '', '', '', 's297', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s297', 'ch1_rain_stop', 1, 'dialogue', 297, 'taku', '顾天鹏', '过奖。', '', '', '', '', 's298', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s298', 'ch1_rain_stop', 1, 'dialogue', 298, 'ai', '星野爱', '但我们就一样了呢。', '', '', '', '', 's299', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s299', 'ch1_rain_stop', 1, 'dialogue', 299, 'taku', '顾天鹏', '总会有点相似的地方。', '', '', '', '', 's300', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s300', 'ch1_rain_stop', 1, 'set', 300, '', '', '', '', '', 'ai_sprite_mode', 'false', 's301', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s301', 'ch1_rain_stop', 1, 'set', 301, '', '', '', '', '', 'event_cg_mode', 'true', 's302', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s302', 'ch1_rain_stop', 1, 'scene', 302, '', '', '', 'cg train_karuizawa_invite', '', '', '', 's303', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s303', 'ch1_rain_stop', 1, 'dialogue', 303, 'ai', '星野爱', '去完越后汤泽，就去轻井泽吧！', '', '', '', '', 's304', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s304', 'ch1_rain_stop', 1, 'narration', 304, '', '', '星野爱突然站起来说。', '', '', '', '', 's305', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s305', 'ch1_rain_stop', 1, 'narration', 305, '', '', '她脸上挂着期待的表情，连眼角都漾着笑意。', '', '', '', '', 's306', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s306', 'ch1_rain_stop', 1, 'narration', 306, '', '', '顾天鹏看着她，总感觉她像是天真的十岁小孩。', '', '', '', '', 's307', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s307', 'ch1_rain_stop', 1, 'narration', 307, '', '', '她也定定地注视顾天鹏，双手支在桌面，旅行攻略被她压在手心下面。', '', '', '', '', 's308', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s308', 'ch1_rain_stop', 1, 'dialogue', 308, 'taku', '顾天鹏', '嗯？', '', '', '', '', 's309', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s309', 'ch1_rain_stop', 1, 'dialogue', 309, 'ai', '星野爱', '我和你！', '', '', '', '', 's310', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s310', 'ch1_rain_stop', 1, 'dialogue', 310, 'taku', '顾天鹏', '怎么突然说这个。', '', '', '', '', 's311', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s311', 'ch1_rain_stop', 1, 'narration', 311, '', '', '他问。', '', '', '', '', 's312', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s312', 'ch1_rain_stop', 1, 'dialogue', 312, 'ai', '星野爱', '反正我们的目的地都一样。', '', '', '', '', 's313', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s313', 'ch1_rain_stop', 1, 'dialogue', 313, 'ai', '星野爱', '你不也是来旅行放松的吗，干脆一起玩个彻底！', '', '', '', '', 's314', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s315', 'ch1_rain_stop', 1, 'narration', 315, '', '', '顾天鹏看着她压在攻略上的手，忽然觉得拒绝这样明亮的邀请，反倒像在对旅行本身撒谎。', '', '', '', '', 's316', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s316', 'ch1_rain_stop', 1, 'dialogue', 316, 'taku', '顾天鹏', '那就一起吧。路线你来挑，迷路算我的。', '', '', '', '', 's317', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s317', 'ch1_rain_stop', 1, 'dialogue', 317, 'ai', '星野爱', '成交！', '', '', '', '', 's341', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s318', 'ch1_rain_stop', 1, 'narration', 318, '', '', '顾天鹏没有被那份热情完全带走。他提醒自己，越是像命运一样突然降临的事，越需要好好确认。', '', '', '', '', 's319', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s319', 'ch1_rain_stop', 1, 'narration', 319, '', '', '同行可以，但要记得他们今天才刚认识。', '', '', '', '', 's320', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s320', 'ch1_rain_stop', 1, 'dialogue', 320, 'taku', '顾天鹏', '同行可以。不过住处、行程、钱，都先说清楚。', '', '', '', '', 's321', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s321', 'ch1_rain_stop', 1, 'dialogue', 321, 'ai', '星野爱', '好认真哦。', '', '', '', '', 's322', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s322', 'ch1_rain_stop', 1, 'dialogue', 322, 'taku', '顾天鹏', '认真是为了玩得安心。', '', '', '', '', 's323', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s323', 'ch1_rain_stop', 1, 'dialogue', 323, 'ai', '星野爱', '那也成交！', '', '', '', '', 's324', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s324', 'ch1_rain_stop', 1, 'narration', 324, '', '', '星野爱从包里翻出一支蓝色圆珠笔，把旅行攻略翻到空白页，煞有介事地写下“临时同行协议”。', '', '', '', '', 's325', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s325', 'ch1_rain_stop', 1, 'dialogue', 325, 'ai', '星野爱', '第一条，迷路时不许说‘我早就知道’。', '', '', '', '', 's326', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s326', 'ch1_rain_stop', 1, 'dialogue', 326, 'taku', '顾天鹏', '这种话本来就不礼貌。', '', '', '', '', 's327', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s327', 'ch1_rain_stop', 1, 'dialogue', 327, 'ai', '星野爱', '第二条，每天至少做一件贪心的事。', '', '', '', '', 's328', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s328', 'ch1_rain_stop', 1, 'dialogue', 328, 'taku', '顾天鹏', '第三条，危险的贪心要提前申报。', '', '', '', '', 's329', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s329', 'ch1_rain_stop', 1, 'dialogue', 329, 'ai', '星野爱', '第四条，顾天鹏不许把所有事都安排得像考试。', '', '', '', '', 's330', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s330', 'ch1_rain_stop', 1, 'dialogue', 330, 'taku', '顾天鹏', '第五条，星野小姐不许把所有事都变成突击测验。', '', '', '', '', 's331', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s331', 'ch1_rain_stop', 1, 'narration', 331, '', '', '他们一人写一条，把那张空白页写得像幼稚又认真的契约。星野爱最后还在角落画了一个歪歪扭扭的星星，旁边补上一句“违反者负责买热饮”。', '', '', '', '', 's332', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s332', 'ch1_rain_stop', 1, 'narration', 332, '', '', '规则让他们的同行变得清楚，也让之后的几站多了一种奇怪的秩序感。她每想绕路前都会举起攻略问“可以申报吗”，顾天鹏则认真到真的点头或摇头。', '', '', '', '', 's333', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s333', 'ch1_rain_stop', 1, 'narration', 333, '', '', '那晚的夜车没有便当交换，也没有甜食秘密，取而代之的是一本被写满规则的旅行攻略。', '', '', '', '', 's334', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s334', 'ch1_rain_stop', 1, 'jump', 334, '', '', '', '', '', '', '', 's432', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s335', 'ch1_rain_stop', 1, 'narration', 335, '', '', '顾天鹏看着她期待的眼睛，最终还是摇了摇头。', '', '', '', '', 's336', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s336', 'ch1_rain_stop', 1, 'dialogue', 336, 'taku', '顾天鹏', '抱歉。我还是习惯一个人旅行。', '', '', '', '', 's337', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s337', 'ch1_rain_stop', 1, 'narration', 337, '', '', '星野爱愣了一下，随即笑得和刚才一样明亮。', '', '', '', '', 's338', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s338', 'ch1_rain_stop', 1, 'dialogue', 338, 'ai', '星野爱', '这样啊。那祝你玩得开心。', '', '', '', '', 's339', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s339', 'ch1_rain_stop', 1, 'narration', 339, '', '', '她把攻略轻轻推回桌面，像把一条还没开始的路线折回原处。', '', '', '', '', 's340', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s340', 'ch1_rain_stop', 1, 'jump', 340, '', '', '', '', '', '', '', 's3627', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s314', 'ch1_rain_stop', 1, 'menu', 314, '', '', '', '', '', '', '', 's341', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s341', 'ch1_rain_stop', 1, 'scene', 341, '', '', '', 'bg train_table_window', '', '', '', 's342', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s342', 'ch1_rain_stop', 1, 'set', 342, '', '', '', '', '', 'ai_sprite_mode', 'true', 's343', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s343', 'ch1_rain_stop', 1, 'set', 343, '', '', '', '', '', 'event_cg_mode', 'false', 's344', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s344', 'ch1_rain_stop', 1, 'sprite', 344, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's345', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s345', 'ch1_rain_stop', 1, 'narration', 345, '', '', '同行这件事，就这样被列车驶过铁轨的声音钉牢了。', '', '', '', '', 's346', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s346', 'ch1_rain_stop', 1, 'dialogue', 346, 'taku', '顾天鹏', '不过你不怕？我们才刚认识。', '', '', '', '', 's347', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s347', 'ch1_rain_stop', 1, 'dialogue', 347, 'ai', '星野爱', '你才十七岁，我怕什么？', '', '', '', '', 's348', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s348', 'ch1_rain_stop', 1, 'dialogue', 348, 'taku', '顾天鹏', '十七怎么了。', '', '', '', '', 's349', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s349', 'ch1_rain_stop', 1, 'dialogue', 349, 'ai', '星野爱', '花一样的年龄，这种年龄怎么会犯罪嘛。', '', '', '', '', 's350', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s350', 'ch1_rain_stop', 1, 'dialogue', 350, 'taku', '顾天鹏', '犯罪者怎么能从年龄判断。', '', '', '', '', 's351', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s351', 'ch1_rain_stop', 1, 'dialogue', 351, 'ai', '星野爱', '怎么不行？毕竟那么年轻。世界上还有那么多人可以去见，还有那么多地方可以去玩，还有那么多……', '', '', '', '', 's352', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s352', 'ch1_rain_stop', 1, 'narration', 352, '', '', '她停下来，像是在寻找合适的词汇。', '', '', '', '', 's353', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s353', 'ch1_rain_stop', 1, 'dialogue', 353, 'taku', '顾天鹏', '还有那么多？', '', '', '', '', 's354', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s354', 'ch1_rain_stop', 1, 'narration', 354, '', '', '仿佛在怀念某种逝去东西一样，星野爱的眼神难得显得有些落寞。', '', '', '', '', 's355', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s355', 'ch1_rain_stop', 1, 'narration', 355, '', '', '她轻轻开阖樱花色的双唇，将声音放低。', '', '', '', '', 's356', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s356', 'ch1_rain_stop', 1, 'dialogue', 356, 'ai', '星野爱', '各种各样的爱。', '', '', '', '', 's357', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s357', 'ch1_rain_stop', 1, 'dialogue', 357, 'taku', '顾天鹏', '爱？', '', '', '', '', 's358', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s358', 'ch1_rain_stop', 1, 'dialogue', 358, 'ai', '星野爱', '是。', '', '', '', '', 's359', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s359', 'ch1_rain_stop', 1, 'narration', 359, '', '', '落寞之色转瞬即逝。', '', '', '', '', 's360', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s360', 'ch1_rain_stop', 1, 'set', 360, '', '', '', '', '', 'ai_sprite_mode', 'false', 's361', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s361', 'ch1_rain_stop', 1, 'set', 361, '', '', '', '', '', 'event_cg_mode', 'true', 's362', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s362', 'ch1_rain_stop', 1, 'scene', 362, '', '', '', 'cg train_greedy_girl', '', '', '', 's363', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s363', 'ch1_rain_stop', 1, 'dialogue', 363, 'ai', '星野爱', '不管怎么说，总之看得出来……', '', '', '', '', 's364', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s364', 'ch1_rain_stop', 1, 'narration', 364, '', '', '没等顾天鹏先张口，星野爱突然把身子压上来，眯起眼睛和他对视。', '', '', '', '', 's365', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s365', 'ch1_rain_stop', 1, 'dialogue', 365, 'ai', '星野爱', '你，绝对是个好人！', '', '', '', '', 's366', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s366', 'ch1_rain_stop', 1, 'narration', 366, '', '', '一股比刚才更加强烈的香味钻进鼻尖，渗入顾天鹏的每一个毛孔，他感觉自己仿佛置身花海之中。', '', '', '', '', 's367', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s367', 'ch1_rain_stop', 1, 'dialogue', 367, 'taku', '顾天鹏', '谢谢。', '', '', '', '', 's368', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s368', 'ch1_rain_stop', 1, 'dialogue', 368, 'ai', '星野爱', '看吧，连这也要道谢。', '', '', '', '', 's369', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s369', 'ch1_rain_stop', 1, 'narration', 369, '', '', '星野爱坐回位置，像是有了新发现似的满面春风。', '', '', '', '', 's370', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s370', 'ch1_rain_stop', 1, 'dialogue', 370, 'taku', '顾天鹏', '我想你也一样。', '', '', '', '', 's371', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s371', 'ch1_rain_stop', 1, 'narration', 371, '', '', '顾天鹏笑着说。', '', '', '', '', 's372', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s372', 'ch1_rain_stop', 1, 'dialogue', 372, 'ai', '星野爱', '错！', '', '', '', '', 's373', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s373', 'ch1_rain_stop', 1, 'narration', 373, '', '', '塔台的远光闪在星野爱脸上。', '', '', '', '', 's374', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s374', 'ch1_rain_stop', 1, 'narration', 374, '', '', '窗外边，天色逐渐变暗，沿线的路灯像是早就准备好似的全部亮起。', '', '', '', '', 's375', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s375', 'ch1_rain_stop', 1, 'narration', 375, '', '', '星野爱了不起地回答：', '', '', '', '', 's376', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s376', 'ch1_rain_stop', 1, 'dialogue', 376, 'ai', '星野爱', '我是星野爱，是这个世界上，最坏最坏，最最贪婪的少女！', '', '', '', '', 's377', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s377', 'ch1_rain_stop', 1, 'scene', 377, '', '', '', 'bg train_table_night', '', '', '', 's378', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s378', 'ch1_rain_stop', 1, 'set', 378, '', '', '', '', '', 'ai_sprite_mode', 'true', 's379', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s379', 'ch1_rain_stop', 1, 'set', 379, '', '', '', '', '', 'event_cg_mode', 'false', 's380', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s380', 'ch1_rain_stop', 1, 'sprite', 380, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's381', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s381', 'ch1_rain_stop', 1, 'narration', 381, '', '', '这一刻，连迷人暮色也化作了背景。', '', '', '', '', 's382', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s382', 'ch1_rain_stop', 1, 'narration', 382, '', '', '她目不转睛地盯视顾天鹏。', '', '', '', '', 's383', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s383', 'ch1_rain_stop', 1, 'narration', 383, '', '', '那是一双拥有一切美好的眼睛。', '', '', '', '', 's384', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s384', 'ch1_rain_stop', 1, 'narration', 384, '', '', '在瞳仁的深处，流淌着一种近乎不可思议的彩色液体，旋转出难以置信的图形。', '', '', '', '', 's385', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s385', 'ch1_rain_stop', 1, 'dialogue', 385, 'taku', '顾天鹏', '了不起。', '', '', '', '', 's386', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s386', 'ch1_rain_stop', 1, 'narration', 386, '', '', '顾天鹏收回失神的目光。', '', '', '', '', 's387', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s387', 'ch1_rain_stop', 1, 'dialogue', 387, 'ai', '星野爱', '是吧！', '', '', '', '', 's388', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s388', 'ch1_rain_stop', 1, 'narration', 388, '', '', '星野爱温柔地拨开耳边的长发。', '', '', '', '', 's389', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s389', 'ch1_rain_stop', 1, 'dialogue', 389, 'taku', '顾天鹏', '那我就是世界上最礼貌的十七岁少年。', '', '', '', '', 's390', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s390', 'ch1_rain_stop', 1, 'dialogue', 390, 'ai', '星野爱', '好。', '', '', '', '', 's391', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s391', 'ch1_rain_stop', 1, 'dialogue', 391, 'ai', '星野爱', '顾天鹏是世界上最礼貌的十七岁少年！', '', '', '', '', 's392', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s392', 'ch1_rain_stop', 1, 'dialogue', 392, 'taku', '顾天鹏', '谢谢你认可。', '', '', '', '', 's393', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s393', 'ch1_rain_stop', 1, 'set', 393, '', '', '', '', '', 'ai_sprite_mode', 'false', 's394', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s394', 'ch1_rain_stop', 1, 'set', 394, '', '', '', '', '', 'event_cg_mode', 'true', 's395', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s395', 'ch1_rain_stop', 1, 'scene', 395, '', '', '', 'cg train_bento_exchange', '', '', '', 's396', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s396', 'ch1_rain_stop', 1, 'dialogue', 396, 'ai', '星野爱', '对了，饿了吗？带吃的了？', '', '', '', '', 's397', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s397', 'ch1_rain_stop', 1, 'dialogue', 397, 'taku', '顾天鹏', '带了巧克力，饼干，面包。', '', '', '', '', 's398', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s398', 'ch1_rain_stop', 1, 'dialogue', 398, 'ai', '星野爱', '都是我爱吃的！', '', '', '', '', 's399', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s399', 'ch1_rain_stop', 1, 'dialogue', 399, 'taku', '顾天鹏', '是你饿了啊？', '', '', '', '', 's400', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s400', 'ch1_rain_stop', 1, 'dialogue', 400, 'ai', '星野爱', '我只买到一份便当。', '', '', '', '', 's401', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s401', 'ch1_rain_stop', 1, 'narration', 401, '', '', '她将用塑料盒和保鲜膜包装的即食便当从包里拿出来，放到桌面。', '', '', '', '', 's402', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s402', 'ch1_rain_stop', 1, 'narration', 402, '', '', '里面有白米饭，炸鸡块，章鱼烧，胡萝卜和几朵新鲜的西兰花。', '', '', '', '', 's403', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s403', 'ch1_rain_stop', 1, 'dialogue', 403, 'taku', '顾天鹏', '很丰盛嘛。', '', '', '', '', 's404', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s404', 'ch1_rain_stop', 1, 'dialogue', 404, 'ai', '星野爱', '那我和你交换。', '', '', '', '', 's405', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s405', 'ch1_rain_stop', 1, 'dialogue', 405, 'taku', '顾天鹏', '交换？', '', '', '', '', 's406', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s406', 'ch1_rain_stop', 1, 'dialogue', 406, 'ai', '星野爱', '用便当换你的巧克力。', '', '', '', '', 's407', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s407', 'ch1_rain_stop', 1, 'dialogue', 407, 'taku', '顾天鹏', '当然可以，送你也没问题。', '', '', '', '', 's408', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s408', 'ch1_rain_stop', 1, 'narration', 408, '', '', '顾天鹏将巧克力从包里取出来递给她。', '', '', '', '', 's409', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s409', 'ch1_rain_stop', 1, 'scene', 409, '', '', '', 'bg train_table_night', '', '', '', 's410', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s410', 'ch1_rain_stop', 1, 'set', 410, '', '', '', '', '', 'ai_sprite_mode', 'true', 's411', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s411', 'ch1_rain_stop', 1, 'set', 411, '', '', '', '', '', 'event_cg_mode', 'false', 's412', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s412', 'ch1_rain_stop', 1, 'sprite', 412, '', '', '', '', '[{"image": "heroine stage_shy", "pos": "heroine_bust_center"}]', '', '', 's413', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s413', 'ch1_rain_stop', 1, 'dialogue', 413, 'taku', '顾天鹏', '这么喜欢吃甜的？', '', '', '', '', 's414', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s414', 'ch1_rain_stop', 1, 'narration', 414, '', '', '星野爱接过一起送来的巧克力，苏打饼干，点了下头。', '', '', '', '', 's415', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s415', 'ch1_rain_stop', 1, 'dialogue', 415, 'ai', '星野爱', '嗯。', '', '', '', '', 's416', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s416', 'ch1_rain_stop', 1, 'narration', 416, '', '', '顾天鹏沉吟似的望着她。', '', '', '', '', 's417', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s417', 'ch1_rain_stop', 1, 'dialogue', 417, 'ai', '星野爱', '怎么了？', '', '', '', '', 's418', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s418', 'ch1_rain_stop', 1, 'dialogue', 418, 'taku', '顾天鹏', '谎言。', '', '', '', '', 's419', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s419', 'ch1_rain_stop', 1, 'dialogue', 419, 'ai', '星野爱', '什么谎言呀？', '', '', '', '', 's420', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s420', 'ch1_rain_stop', 1, 'narration', 420, '', '', '她若无其事地说。', '', '', '', '', 's421', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s421', 'ch1_rain_stop', 1, 'narration', 421, '', '', '顾天鹏看着她手里的巧克力包装。', '', '', '', '', 's422', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s422', 'ch1_rain_stop', 1, 'dialogue', 422, 'taku', '顾天鹏', '你不喜欢甜食，或者没那么喜欢？', '', '', '', '', 's423', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s423', 'ch1_rain_stop', 1, 'dialogue', 423, 'ai', '星野爱', '什么是喜欢呢？', '', '', '', '', 's424', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s424', 'ch1_rain_stop', 1, 'narration', 424, '', '', '她来回拨弄锡纸包装。', '', '', '', '', 's425', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s425', 'ch1_rain_stop', 1, 'dialogue', 425, 'ai', '星野爱', '不讨厌就算喜欢吧？', '', '', '', '', 's426', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s426', 'ch1_rain_stop', 1, 'dialogue', 426, 'taku', '顾天鹏', '哪有这样定义的……', '', '', '', '', 's427', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s427', 'ch1_rain_stop', 1, 'dialogue', 427, 'ai', '星野爱', '总而言之，是无关紧要的谎言。', '', '', '', '', 's428', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s428', 'ch1_rain_stop', 1, 'dialogue', 428, 'taku', '顾天鹏', '这倒是。', '', '', '', '', 's429', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s429', 'ch1_rain_stop', 1, 'narration', 429, '', '', '顾天鹏没再开口。', '', '', '', '', 's430', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s430', 'ch1_rain_stop', 1, 'narration', 430, '', '', '两人解决完晚饭的时候，火车已经启动很久。', '', '', '', '', 's431', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s431', 'ch1_rain_stop', 1, 'narration', 431, '', '', '正值十一月的天空早就黑成一片，抬眼望去，远方山体却泛着可爱的白色。', '', '', '', '', 's432', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s432', 'ch2_train_night_sleep', 2, 'set', 432, '', '', '', '', '', 'ai_sprite_mode', 'false', 's433', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s433', 'ch2_train_night_sleep', 2, 'set', 433, '', '', '', '', '', 'event_cg_mode', 'true', 's434', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s434', 'ch2_train_night_sleep', 2, 'scene', 434, '', '', '', 'cg train_night_sleep', '', '', '', 's435', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s435', 'ch2_train_night_sleep', 2, 'narration', 435, '', '', '夜晚，用围巾枕着手臂的星野爱，趴在桌上乖巧地睡着了。', '', '', '', '', 's436', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s436', 'ch2_train_night_sleep', 2, 'narration', 436, '', '', '路途遥远，车身摇摇晃晃，在一片岑寂之中，火车运行的咣当声愈发明显。', '', '', '', '', 's437', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s437', 'ch2_train_night_sleep', 2, 'narration', 437, '', '', '车厢里的灯是不太耀眼的淡黄色，窗玻璃像块显示屏幕一样展现着外面的北国风光。', '', '', '', '', 's438', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s438', 'ch2_train_night_sleep', 2, 'narration', 438, '', '', '仔细看去时，这块玻璃又仿佛成了清晰的镜面，始终浮现出星野爱那淡淡的睡颜。', '', '', '', '', 's439', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s439', 'ch2_train_night_sleep', 2, 'narration', 439, '', '', '她是世界上最最贪婪的少女。', '', '', '', '', 's440', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s440', 'ch2_train_night_sleep', 2, 'narration', 440, '', '', '对少女而言，这句话不是谎言。', '', '', '', '', 's441', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s441', 'ch2_train_night_sleep', 2, 'narration', 441, '', '', '心里想着明天旅行的事情，顾天鹏收回视线。', '', '', '', '', 's442', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s442', 'ch2_train_night_sleep', 2, 'narration', 442, '', '', '他将有线耳机接上手机，用免费试听的音乐器播放了一首《圣诞快乐，劳伦斯先生》，选择单曲循环。', '', '', '', '', 's443', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s443', 'ch2_train_night_sleep', 2, 'narration', 443, '', '', '闭上眼睛，困意逐渐袭来，他靠在软垫上入睡。', '', '', '', '', 's444', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s444', 'chapter_3', 3, 'set', 444, '', '', '', '', '', 'ai_sprite_mode', 'false', 's445', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s445', 'chapter_3', 3, 'set', 445, '', '', '', '', '', 'event_cg_mode', 'true', 's446', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s446', 'chapter_3', 3, 'scene', 446, '', '', '', 'cg yuzawa_morning_wake', '', '', '', 's447', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s447', 'chapter_3', 3, 'narration', 447, '', '', '越后汤泽的温泉旅馆', '', '', '', '', 's448', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s448', 'chapter_3', 3, 'narration', 448, '', '', '凌晨的时候，火车穿过隧道，开进山里，周围已经完全亮了起来。', '', '', '', '', 's449', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s449', 'chapter_3', 3, 'narration', 449, '', '', '窗外的景物像是蒙上了一层轻薄的白纱。', '', '', '', '', 's450', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s450', 'chapter_3', 3, 'narration', 450, '', '', '穿着深色风衣的扫雪工、点缀雪地的低矮木楼、路边三三两两的嫩绿青葱。', '', '', '', '', 's451', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s451', 'chapter_3', 3, 'narration', 451, '', '', '无论看到什么，心里总有一种跟着蓝天白云浮起来的梦幻之意，整个人都无比轻松。', '', '', '', '', 's452', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s452', 'chapter_3', 3, 'set', 452, '', '', '', '', '', 'ai_sprite_outfit', 'stage', 's453', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s453', 'chapter_3', 3, 'set', 453, '', '', '', '', '', 'ai_sprite_mode', 'true', 's454', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s454', 'chapter_3', 3, 'set', 454, '', '', '', '', '', 'event_cg_mode', 'false', 's455', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s455', 'chapter_3', 3, 'scene', 455, '', '', '', 'bg train_table_snow_morning', '', '', '', 's456', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s456', 'chapter_3', 3, 'sprite', 456, '', '', '', '', '[{"image": "heroine stage_surprised", "pos": "heroine_bust_center"}]', '', '', 's457', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s457', 'chapter_3', 3, 'narration', 457, '', '', '车厢里，从睡梦中苏醒的星野爱呻吟一声，搓着眼睛抬起头，望着白色的冰天雪地，长长地伸了个懒腰。', '', '', '', '', 's458', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s458', 'chapter_3', 3, 'dialogue', 458, 'ai', '星野爱', '到了？', '', '', '', '', 's459', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s459', 'chapter_3', 3, 'narration', 459, '', '', '她用软软糯糯的声音问。', '', '', '', '', 's460', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s460', 'chapter_3', 3, 'dialogue', 460, 'taku', '顾天鹏', '三十分钟。', '', '', '', '', 's461', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s461', 'chapter_3', 3, 'narration', 461, '', '', '顾天鹏说。', '', '', '', '', 's462', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s462', 'chapter_3', 3, 'scene', 462, '', '', '', 'bg train_table_snow_morning', '', '', '', 's463', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s463', 'chapter_3', 3, 'sprite', 463, '', '', '', '', '[{"image": "heroine stage_shy", "pos": "heroine_bust_center"}]', '', '', 's464', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s464', 'chapter_3', 3, 'narration', 464, '', '', '他从包里拿出剩下半包的低糖苏打饼递过去。', '', '', '', '', 's465', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s465', 'chapter_3', 3, 'dialogue', 465, 'taku', '顾天鹏', '将就一下。早饭。', '', '', '', '', 's466', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s466', 'chapter_3', 3, 'dialogue', 466, 'ai', '星野爱', '谢谢。', '', '', '', '', 's467', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s467', 'chapter_3', 3, 'narration', 467, '', '', '星野爱轻声说，摊开双手接过，然后又忽然想起似的问。', '', '', '', '', 's468', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s468', 'chapter_3', 3, 'dialogue', 468, 'ai', '星野爱', '你自己呢，还有别的吃的吗？', '', '', '', '', 's469', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s469', 'chapter_3', 3, 'dialogue', 469, 'taku', '顾天鹏', '我不太饿。', '', '', '', '', 's470', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s470', 'chapter_3', 3, 'dialogue', 470, 'ai', '星野爱', '不饿？', '', '', '', '', 's471', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s471', 'chapter_3', 3, 'narration', 471, '', '', '她歪了下脑袋。', '', '', '', '', 's472', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s472', 'chapter_3', 3, 'narration', 472, '', '', '顾天鹏用不清不楚的音量嗯了一句。', '', '', '', '', 's473', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s473', 'chapter_3', 3, 'set', 473, '', '', '', '', '', 'ai_sprite_mode', 'false', 's474', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s474', 'chapter_3', 3, 'set', 474, '', '', '', '', '', 'event_cg_mode', 'true', 's475', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s475', 'chapter_3', 3, 'scene', 475, '', '', '', 'cg yuzawa_lie_nose', '', '', '', 's476', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s476', 'chapter_3', 3, 'narration', 476, '', '', '他把背包的拉链拉上，抬起头，一只如白玉般洁净的手指点上他的鼻尖。', '', '', '', '', 's477', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s477', 'chapter_3', 3, 'dialogue', 477, 'taku', '顾天鹏', '干嘛呢。', '', '', '', '', 's478', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s478', 'chapter_3', 3, 'dialogue', 478, 'ai', '星野爱', '谎言！', '', '', '', '', 's479', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s479', 'chapter_3', 3, 'narration', 479, '', '', '星野爱笑嘻嘻地说。那是一种类似恶作剧般顽皮的笑。', '', '', '', '', 's480', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s481', 'chapter_3', 3, 'narration', 481, '', '', '顾天鹏把视线移开，终于承认胃里确实空得厉害。', '', '', '', '', 's482', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s482', 'chapter_3', 3, 'set', 482, '', '', '', '', '', 'ai_sprite_mode', 'true', 's483', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s483', 'chapter_3', 3, 'set', 483, '', '', '', '', '', 'event_cg_mode', 'false', 's484', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s484', 'chapter_3', 3, 'scene', 484, '', '', '', 'bg train_table_snow_morning', '', '', '', 's485', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s485', 'chapter_3', 3, 'sprite', 485, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's486', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s486', 'chapter_3', 3, 'dialogue', 486, 'taku', '顾天鹏', '好吧，是假的。我也饿了。', '', '', '', '', 's487', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s487', 'chapter_3', 3, 'dialogue', 487, 'ai', '星野爱', '看吧，我赢了。', '', '', '', '', 's488', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s488', 'chapter_3', 3, 'narration', 488, '', '', '星野爱像真的赢了什么比赛一样笑起来，把饼干掰成两半。', '', '', '', '', 's489', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s489', 'chapter_3', 3, 'dialogue', 489, 'taku', '顾天鹏', '这算哪门子胜利。', '', '', '', '', 's490', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s490', 'chapter_3', 3, 'dialogue', 490, 'ai', '星野爱', '早餐分配权的胜利。', '', '', '', '', 's507', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s491', 'chapter_3', 3, 'narration', 491, '', '', '顾天鹏试图保持平静，仿佛被戳破的不是谎言，而只是清晨车窗上的一层薄雾。', '', '', '', '', 's492', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s492', 'chapter_3', 3, 'narration', 492, '', '', '星野爱看着他，眼里写满了“你还要装到什么时候”。', '', '', '', '', 's493', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s493', 'chapter_3', 3, 'set', 493, '', '', '', '', '', 'ai_sprite_mode', 'true', 's494', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s494', 'chapter_3', 3, 'set', 494, '', '', '', '', '', 'event_cg_mode', 'false', 's495', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s495', 'chapter_3', 3, 'scene', 495, '', '', '', 'bg train_table_snow_morning', '', '', '', 's496', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s496', 'chapter_3', 3, 'sprite', 496, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's497', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s497', 'chapter_3', 3, 'dialogue', 497, 'taku', '顾天鹏', '是真的。', '', '', '', '', 's498', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s498', 'chapter_3', 3, 'narration', 498, '', '', '顾天鹏将她的手指移开，又若无其事地说。', '', '', '', '', 's499', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s499', 'chapter_3', 3, 'dialogue', 499, 'taku', '顾天鹏', '况且，能看破谎言的只有我一个，并且世界上只有我一个，你不行。', '', '', '', '', 's500', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s500', 'chapter_3', 3, 'dialogue', 500, 'ai', '星野爱', '哪有这种赖皮的能力嘛。', '', '', '', '', 's501', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s501', 'chapter_3', 3, 'narration', 501, '', '', '星野爱嘟着嘴。', '', '', '', '', 's502', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s502', 'chapter_3', 3, 'dialogue', 502, 'taku', '顾天鹏', '很神奇吧。', '', '', '', '', 's503', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s503', 'chapter_3', 3, 'dialogue', 503, 'ai', '星野爱', '没人会信啦。', '', '', '', '', 's504', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s504', 'chapter_3', 3, 'dialogue', 504, 'taku', '顾天鹏', '当我开玩笑也没问题。', '', '', '', '', 's505', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s505', 'chapter_3', 3, 'narration', 505, '', '', '她没有再追问那句“饿不饿”。半块饼干最终还是被放回包装袋里，清晨的亲近也随之轻轻合上。', '', '', '', '', 's506', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s506', 'chapter_3', 3, 'jump', 506, '', '', '', '', '', '', '', 's522', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s480', 'chapter_3', 3, 'menu', 480, '', '', '', '', '', '', '', 's507', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s507', 'chapter_3', 3, 'narration', 507, '', '', '片刻后，顾天鹏拿出昨天看过的旅行攻略，利用桌面竖着敲了敲，准备到站前再温习一遍。', '', '', '', '', 's508', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s508', 'chapter_3', 3, 'set', 508, '', '', '', '', '', 'ai_sprite_mode', 'false', 's509', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s509', 'chapter_3', 3, 'set', 509, '', '', '', '', '', 'event_cg_mode', 'true', 's510', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s510', 'chapter_3', 3, 'scene', 510, '', '', '', 'cg yuzawa_cracker_share', '', '', '', 's511', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s511', 'chapter_3', 3, 'narration', 511, '', '', '这时，旁边传来咔嚓一声，像是把什么东西掰断了一样。', '', '', '', '', 's512', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s512', 'chapter_3', 3, 'narration', 512, '', '', '顾天鹏疑惑着抬头，紧接着半块饼干递到他嘴边。', '', '', '', '', 's513', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s513', 'chapter_3', 3, 'dialogue', 513, 'ai', '星野爱', '给。', '', '', '', '', 's514', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s514', 'chapter_3', 3, 'dialogue', 514, 'taku', '顾天鹏', '谢谢。', '', '', '', '', 's515', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s515', 'chapter_3', 3, 'set', 515, '', '', '', '', '', 'ai_sprite_mode', 'true', 's516', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s516', 'chapter_3', 3, 'set', 516, '', '', '', '', '', 'event_cg_mode', 'false', 's517', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s517', 'chapter_3', 3, 'scene', 517, '', '', '', 'bg train_table_snow_morning', '', '', '', 's518', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s518', 'chapter_3', 3, 'sprite', 518, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's519', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s519', 'chapter_3', 3, 'narration', 519, '', '', '放弃了一口咬上去的打算，顾天鹏拿手接过。', '', '', '', '', 's520', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s520', 'chapter_3', 3, 'narration', 520, '', '', '两人吃完早餐，一起看了会儿攻略上的各种插画和文案。', '', '', '', '', 's521', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s521', 'chapter_3', 3, 'narration', 521, '', '', '因为纸张只能朝着一个方向，星野爱让他坐到自己旁边，和之前一样。', '', '', '', '', 's522', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s522', 'side_ch3_lie_game', 3, 'set', 522, '', '', '', '', '', 'ai_sprite_mode', 'true', 's523', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s523', 'side_ch3_lie_game', 3, 'set', 523, '', '', '', '', '', 'event_cg_mode', 'false', 's524', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s524', 'side_ch3_lie_game', 3, 'scene', 524, '', '', '', 'bg train_table_snow_morning', '', '', '', 's525', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s525', 'side_ch3_lie_game', 3, 'sprite', 525, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's526', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s526', 'side_ch3_lie_game', 3, 'narration', 526, '', '', '列车临近越后汤泽时，星野爱忽然把包装袋推到桌子正中央。', '', '', '', '', 's527', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s527', 'side_ch3_lie_game', 3, 'dialogue', 527, 'ai', '星野爱', '那我们来玩一个游戏。', '', '', '', '', 's528', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s528', 'side_ch3_lie_game', 3, 'dialogue', 528, 'taku', '顾天鹏', '游戏？', '', '', '', '', 's529', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s529', 'side_ch3_lie_game', 3, 'dialogue', 529, 'ai', '星野爱', '谎言裁判。你说三句话，我判断哪一句是假的。', '', '', '', '', 's530', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s530', 'side_ch3_lie_game', 3, 'dialogue', 530, 'taku', '顾天鹏', '如果你输了呢？', '', '', '', '', 's531', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s531', 'side_ch3_lie_game', 3, 'dialogue', 531, 'ai', '星野爱', '我承认顾天鹏是世界上最礼貌的十七岁少年。', '', '', '', '', 's532', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s532', 'side_ch3_lie_game', 3, 'dialogue', 532, 'taku', '顾天鹏', '这不是已经承认过了？', '', '', '', '', 's533', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s533', 'side_ch3_lie_game', 3, 'dialogue', 533, 'ai', '星野爱', '那就升级成最麻烦的十七岁少年。', '', '', '', '', 's534', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s534', 'side_ch3_lie_game', 3, 'narration', 534, '', '', '顾天鹏看着她一本正经的表情，终于还是被逗得叹了口气。', '', '', '', '', 's535', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s535', 'side_ch3_lie_game', 3, 'dialogue', 535, 'taku', '顾天鹏', '第一，我不饿。第二，我觉得你很吵。第三，我其实很期待接下来的旅馆。', '', '', '', '', 's536', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s536', 'side_ch3_lie_game', 3, 'narration', 536, '', '', '星野爱盯着他的眼睛，像真要把谎言从里面抓出来。', '', '', '', '', 's537', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s537', 'side_ch3_lie_game', 3, 'dialogue', 537, 'ai', '星野爱', '第一句是假的。第二句也是假的。第三句是真的。', '', '', '', '', 's538', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s538', 'side_ch3_lie_game', 3, 'dialogue', 538, 'taku', '顾天鹏', '规则里不是只有一句假话吗？', '', '', '', '', 's539', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s539', 'side_ch3_lie_game', 3, 'dialogue', 539, 'ai', '星野爱', '规则可以被最贪婪的裁判临时修改。', '', '', '', '', 's540', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s540', 'side_ch3_lie_game', 3, 'narration', 540, '', '', '她把饼干掰开，仍旧没有递到他嘴边，只是放到桌面中央。顾天鹏拿起属于自己的那半块，两个人隔着一只包装袋吃完了早饭。', '', '', '', '', 's541', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s541', 'side_ch3_lie_game', 3, 'narration', 541, '', '', '这不是原本会发生的亲近，却让他们多了一个谁也没写进攻略里的小游戏。', '', '', '', '', 's542', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s542', 'side_ch3_lie_game', 3, 'narration', 542, '', '', '到站以后，星野爱把空袋折成小方块，塞进外套口袋。', '', '', '', '', 's543', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s543', 'side_ch3_lie_game', 3, 'dialogue', 543, 'ai', '星野爱', '证物保留。以后你再撒谎，我就把这个拿出来。', '', '', '', '', 's544', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s544', 'side_ch3_lie_game', 3, 'dialogue', 544, 'taku', '顾天鹏', '那证物最好保管好。', '', '', '', '', 's545', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s545', 'side_ch3_lie_game', 3, 'dialogue', 545, 'ai', '星野爱', '当然。我可是裁判。', '', '', '', '', 's546', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s546', 'side_ch3_lie_game', 3, 'narration', 546, '', '', '他们拖着行李走下列车，清晨的雪光从站台尽头铺过来。旅馆窗外的雪很快亮得刺眼，新的一天没有章名，也没有提示，只是自然地继续。', '', '', '', '', 's547', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s547', 'side_ch3_lie_game', 3, 'set', 547, '', '', '', '', '', 'ai_sprite_outfit', 'stage', 's548', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s548', 'side_ch3_lie_game', 3, 'set', 548, '', '', '', '', '', 'ai_sprite_mode', 'true', 's549', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s549', 'side_ch3_lie_game', 3, 'set', 549, '', '', '', '', '', 'event_cg_mode', 'false', 's550', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s550', 'side_ch3_lie_game', 3, 'scene', 550, '', '', '', 'bg ryokan_room', '', '', '', 's551', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s551', 'side_ch3_lie_game', 3, 'sprite', 551, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's552', '');
