INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s555', 'chapter_4', 4, 'set', 555, '', '', '', '', '', 'event_cg_mode', 'false', 's556', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s556', 'chapter_4', 4, 'scene', 556, '', '', '', 'bg ryokan_room', '', '', '', 's557', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s557', 'chapter_4', 4, 'sprite', 557, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's558', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s558', 'chapter_4', 4, 'narration', 558, '', '', '从初冬漫步而来的春色', '', '', '', '', 's559', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s559', 'main_ryokan_morning', 4, 'dialogue', 559, 'taku', '顾天鹏', '登山？', '', '', '', '', 's560', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s560', 'main_ryokan_morning', 4, 'narration', 560, '', '', '顾天鹏说。', '', '', '', '', 's561', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s561', 'main_ryokan_morning', 4, 'narration', 561, '', '', '转头看去时，星野爱正目不转睛地望着他，眼里闪着期待的光。', '', '', '', '', 's562', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s562', 'main_ryokan_morning', 4, 'narration', 562, '', '', '她跪坐在榻榻米上，羊绒围巾搭着大腿。', '', '', '', '', 's563', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s563', 'main_ryokan_morning', 4, 'narration', 563, '', '', '清晨的阳光溜进屋子，光线绵延在她的侧脸，旋即拉出好看的虚影，消失在未沾染多少灰尘的地板之上。', '', '', '', '', 's564', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s564', 'main_ryokan_morning', 4, 'narration', 564, '', '', '金色的光柱旋转着近乎透明的颗粒，旭日东升时，少女连指尖都泛着神秘的色彩。', '', '', '', '', 's565', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s565', 'main_ryokan_morning', 4, 'dialogue', 565, 'ai', '星野爱', '可以吗？', '', '', '', '', 's566', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s566', 'main_ryokan_morning', 4, 'dialogue', 566, 'taku', '顾天鹏', '没问题。', '', '', '', '', 's567', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s567', 'main_ryokan_morning', 4, 'dialogue', 567, 'ai', '星野爱', '太好了！', '', '', '', '', 's568', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s568', 'main_ryokan_morning', 4, 'narration', 568, '', '', '星野爱笑着把围巾举过头，做出振臂高呼的动作。', '', '', '', '', 's569', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s569', 'main_ryokan_morning', 4, 'narration', 569, '', '', '面对这样的少女，顾天鹏总会产生亲切的好感——她从不吝啬自己的笑容。', '', '', '', '', 's570', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s570', 'main_ryokan_morning', 4, 'scene', 570, '', '', '', 'bg ryokan_room', '', '', '', 's571', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s571', 'main_ryokan_morning', 4, 'sprite', 571, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's572', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s572', 'main_ryokan_morning', 4, 'narration', 572, '', '', '一直到中午之前，顾天鹏继续看书，看《了不起的盖茨比》，把英语翻译过来。', '', '', '', '', 's573', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s573', 'main_ryokan_morning', 4, 'narration', 573, '', '', '翻译成中文，翻译成日语，最后碾碎了丢进思想的大海里。', '', '', '', '', 's574', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s574', 'main_ryokan_morning', 4, 'narration', 574, '', '', '这是一本无论看几遍都不会厌倦的书。', '', '', '', '', 's575', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s575', 'main_ryokan_morning', 4, 'narration', 575, '', '', '鲜活优美的文字，引人入胜的剧情，丝滑如抛光打磨后镜面一样的情节流畅程度，还有那个永远充满决心、生来便了不起的盖茨比。', '', '', '', '', 's576', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s576', 'main_ryokan_morning', 4, 'narration', 576, '', '', '每每翻开书页，顾天鹏总要再三阅读它的开篇，并且次次心怀澎湃。', '', '', '', '', 's577', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s577', 'main_ryokan_morning', 4, 'narration', 577, '', '', '“那就戴上金帽子吧，如果能让她心怡；如果能蹦高，蹦给她看又何妨，直到她大喊：‘情郎，戴金帽子蹦高的情郎，我一定要得到你！’”', '', '', '', '', 's578', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s578', 'main_ryokan_morning', 4, 'narration', 578, '', '', '为了充实自己，他也曾写下类似“计划表”的东西。', '', '', '', '', 's579', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s579', 'main_ryokan_morning', 4, 'narration', 579, '', '', '每天：蹲起一百次，伏地挺撑八十次，仰卧起坐一百次，长跑五公里。', '', '', '', '', 's580', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s580', 'main_ryokan_morning', 4, 'narration', 580, '', '', '长远：永远努力，永远礼貌。坚持看书，不喝酒，不吸烟。投资自己，为自己花钱。', '', '', '', '', 's581', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s581', 'main_ryokan_morning', 4, 'narration', 581, '', '', '至少学习三种球类运动。对母亲更好些——后来划掉，改成：平等地对待每一个人。', '', '', '', '', 's582', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s582', 'main_ryokan_morning', 4, 'narration', 582, '', '', '了不起的计划，即使在独自生活的今天，顾天鹏也从来没懈怠过半次。', '', '', '', '', 's583', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s583', 'main_ryokan_morning', 4, 'dialogue', 583, 'ai', '星野爱', '很深奥的书呢。', '', '', '', '', 's584', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s584', 'main_ryokan_morning', 4, 'narration', 584, '', '', '不知什么时候，围着围巾的星野爱跪坐到他身边，指尖触摸红唇，眼睛朝书页张望。', '', '', '', '', 's585', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s585', 'main_ryokan_morning', 4, 'dialogue', 585, 'taku', '顾天鹏', '伟大的杰作。', '', '', '', '', 's586', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s586', 'main_ryokan_morning', 4, 'narration', 586, '', '', '他干咳一声，从榻榻米上站起来。', '', '', '', '', 's587', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s587', 'main_ryokan_morning', 4, 'dialogue', 587, 'taku', '顾天鹏', '吃饭？', '', '', '', '', 's588', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s588', 'main_ryokan_morning', 4, 'dialogue', 588, 'ai', '星野爱', '嗯嗯。', '', '', '', '', 's589', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s589', 'main_ryokan_morning', 4, 'narration', 589, '', '', '星野爱古灵精怪地笑笑。', '', '', '', '', 's590', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s590', 'main_ryokan_morning', 4, 'dialogue', 590, 'ai', '星野爱', '难道你还想再看会儿？', '', '', '', '', 's591', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s591', 'main_ryokan_morning', 4, 'dialogue', 591, 'taku', '顾天鹏', '再看就一发不可收拾了。', '', '', '', '', 's592', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s592', 'main_ryokan_morning', 4, 'narration', 592, '', '', '星野爱也站起来。', '', '', '', '', 's593', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s593', 'main_ryokan_morning', 4, 'dialogue', 593, 'ai', '星野爱', '真有那么好看？', '', '', '', '', 's594', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s594', 'main_ryokan_morning', 4, 'dialogue', 594, 'taku', '顾天鹏', '毫无疑问。', '', '', '', '', 's595', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s595', 'main_ryokan_morning', 4, 'dialogue', 595, 'ai', '星野爱', '信你。', '', '', '', '', 's596', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s596', 'main_ryokan_morning', 4, 'narration', 596, '', '', '她换上迷人的笑容。', '', '', '', '', 's597', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s597', 'main_ryokan_morning', 4, 'dialogue', 597, 'ai', '星野爱', '回头也借我看看吧！', '', '', '', '', 's598', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s598', 'main_ryokan_morning', 4, 'narration', 598, '', '', '顾天鹏点头。', '', '', '', '', 's599', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s599', 'main_ryokan_morning', 4, 'dialogue', 599, 'taku', '顾天鹏', '当然可以。这本书，我恨不得全世界的人都去翻上几遍，如果行得通的话，让那些家伙全文背诵最好。', '', '', '', '', 's600', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s600', 'main_ryokan_morning', 4, 'dialogue', 600, 'ai', '星野爱', '哈哈，真有那么夸张嘛。', '', '', '', '', 's601', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s601', 'main_ryokan_morning', 4, 'narration', 601, '', '', '星野爱好笑似的开口。', '', '', '', '', 's602', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s602', 'main_ryokan_morning', 4, 'dialogue', 602, 'ai', '星野爱', '简直可以拿去做广告词了。', '', '', '', '', 's603', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s603', 'main_ryokan_morning', 4, 'dialogue', 603, 'taku', '顾天鹏', '代言费要多少好呢？', '', '', '', '', 's604', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s604', 'main_ryokan_morning', 4, 'dialogue', 604, 'ai', '星野爱', '一千万？', '', '', '', '', 's605', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s605', 'main_ryokan_morning', 4, 'dialogue', 605, 'taku', '顾天鹏', '够住好多好多个夜晚了。', '', '', '', '', 's606', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s606', 'main_ryokan_morning', 4, 'dialogue', 606, 'ai', '星野爱', '的确是呢。', '', '', '', '', 's607', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s607', 'main_ryokan_morning', 4, 'dialogue', 607, 'taku', '顾天鹏', '走吧。', '', '', '', '', 's608', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s608', 'main_ryokan_morning', 4, 'dialogue', 608, 'ai', '星野爱', '哦！', '', '', '', '', 's609', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s609', 'main_ryokan_morning', 4, 'set', 609, '', '', '', '', '', 'ai_sprite_mode', 'false', 's610', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s610', 'main_ryokan_morning', 4, 'set', 610, '', '', '', '', '', 'event_cg_mode', 'true', 's611', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s611', 'main_ryokan_morning', 4, 'scene', 611, '', '', '', 'cg ch4_ryokan_lunch', '', '', '', 's612', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s612', 'main_ryokan_morning', 4, 'narration', 612, '', '', '两人吃罢旅馆免费提供的鳗鱼盖浇饭、金枪鱼寿司，都没要上一瓶威士忌或是日本清酒，只是喝了两杯温热的开水。', '', '', '', '', 's613', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s613', 'main_ryokan_morning', 4, 'narration', 613, '', '', '除此之外，饭后甜点也免费提供。', '', '', '', '', 's614', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s614', 'main_ryokan_morning', 4, 'narration', 614, '', '', '负责管理甜点的和服女子告诉他们拿多少都行，不要浪费就好。', '', '', '', '', 's615', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s615', 'main_ryokan_morning', 4, 'narration', 615, '', '', '他们点头答应，但只取了一个巴掌大的甜甜圈，上面铺满了彩色的巧克力碎。', '', '', '', '', 's616', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s616', 'main_ryokan_morning', 4, 'narration', 616, '', '', '两人各掰了一半，但顾天鹏到最后也没吃完。', '', '', '', '', 's617', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s617', 'main_ryokan_morning', 4, 'set', 617, '', '', '', '', '', 'ai_sprite_mode', 'true', 's618', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s618', 'main_ryokan_morning', 4, 'set', 618, '', '', '', '', '', 'event_cg_mode', 'false', 's619', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s619', 'main_ryokan_morning', 4, 'scene', 619, '', '', '', 'bg ryokan_room', '', '', '', 's620', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s620', 'main_ryokan_morning', 4, 'sprite', 620, '', '', '', '', '[{"image": "heroine stage_neutral", "pos": "heroine_bust_center"}]', '', '', 's621', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s621', 'main_ryokan_morning', 4, 'narration', 621, '', '', '下午一点三十，他们准备出门。', '', '', '', '', 's622', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s622', 'main_ryokan_morning', 4, 'narration', 622, '', '', '顾天鹏将《了不起的盖茨比》收进包里，星野爱则摘下围巾，对他说换套衣服再出去好了。', '', '', '', '', 's623', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s623', 'main_ryokan_morning', 4, 'dialogue', 623, 'taku', '顾天鹏', '好的，那我先出去。', '', '', '', '', 's624', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s624', 'main_ryokan_morning', 4, 'narration', 624, '', '', '顾天鹏抬一下手说。', '', '', '', '', 's625', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s625', 'main_ryokan_morning', 4, 'dialogue', 625, 'ai', '星野爱', '不想偷看？', '', '', '', '', 's626', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s626', 'main_ryokan_morning', 4, 'dialogue', 626, 'taku', '顾天鹏', '能克制住。', '', '', '', '', 's627', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s627', 'main_ryokan_morning', 4, 'dialogue', 627, 'ai', '星野爱', '哦～', '', '', '', '', 's628', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s628', 'main_ryokan_morning', 4, 'narration', 628, '', '', '星野爱转了转食指，最后指向他。', '', '', '', '', 's629', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s629', 'main_ryokan_morning', 4, 'dialogue', 629, 'ai', '星野爱', '诚实！', '', '', '', '', 's630', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s630', 'main_ryokan_morning', 4, 'dialogue', 630, 'taku', '顾天鹏', '礼貌，诚实。', '', '', '', '', 's631', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s631', 'main_ryokan_morning', 4, 'narration', 631, '', '', '顾天鹏叹气说。', '', '', '', '', 's632', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s632', 'main_ryokan_morning', 4, 'dialogue', 632, 'taku', '顾天鹏', '我到底还有多少优点。', '', '', '', '', 's633', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s633', 'main_ryokan_morning', 4, 'dialogue', 633, 'ai', '星野爱', '很帅！', '', '', '', '', 's634', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s634', 'main_ryokan_morning', 4, 'dialogue', 634, 'taku', '顾天鹏', '谢谢。', '', '', '', '', 's635', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s635', 'main_ryokan_morning', 4, 'narration', 635, '', '', '顾天鹏走出去，门关上，他的声音从走廊传进来。', '', '', '', '', 's636', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s636', 'main_ryokan_morning', 4, 'dialogue', 636, 'taku', '顾天鹏', '在门口等你。', '', '', '', '', 's637', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s637', 'main_ryokan_morning', 4, 'dialogue', 637, 'ai', '星野爱', 'OK！', '', '', '', '', 's638', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s638', 'main_ryokan_morning', 4, 'set', 638, '', '', '', '', '', 'ai_sprite_mode', 'false', 's639', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s639', 'main_ryokan_morning', 4, 'set', 639, '', '', '', '', '', 'event_cg_mode', 'false', 's640', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s640', 'main_ryokan_morning', 4, 'scene', 640, '', '', '', 'bg ryokan_genkan', '', '', '', 's641', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s641', 'main_ryokan_morning', 4, 'narration', 641, '', '', '门庭处，顾天鹏换好出门的运动鞋，又把来时路上买来的暖宝宝贴在衣服里。', '', '', '', '', 's642', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s642', 'main_ryokan_morning', 4, 'narration', 642, '', '', '走到门外，世界一片苍茫。', '', '', '', '', 's643', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s643', 'main_ryokan_morning', 4, 'narration', 643, '', '', '暖和的阳光撒下来，新葱闪闪发亮，门檐的积雪化成水滴落下来，一下一下敲出冬天的礼歌。', '', '', '', '', 's644', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s644', 'main_ryokan_morning', 4, 'narration', 644, '', '', '极目远眺，六七岁的顽童在放风筝，脚踏木屐的妇人在不远的地方交谈，男人砍了几捆柴背回来。', '', '', '', '', 's645', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s645', 'main_ryokan_morning', 4, 'narration', 645, '', '', '山的轮廓，太阳的形状，树叶的低语，风的高呼。', '', '', '', '', 's646', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s646', 'main_ryokan_morning', 4, 'narration', 646, '', '', '竟然连风都变得有迹可循了。', '', '', '', '', 's647', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s647', 'main_ryokan_morning', 4, 'narration', 647, '', '', '他靠在木壁上，听见犬吠声融进微寒的空气里。', '', '', '', '', 's648', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s648', 'main_ryokan_morning', 4, 'narration', 648, '', '', '没过一会儿，身后传来空灵的声音。', '', '', '', '', 's649', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s649', 'main_ryokan_morning', 4, 'dialogue', 649, 'ai', '星野爱', '顾天鹏，走吧！', '', '', '', '', 's650', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s650', 'main_ryokan_morning', 4, 'dialogue', 650, 'taku', '顾天鹏', '哦。', '', '', '', '', 's651', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s651', 'main_ryokan_morning', 4, 'set', 651, '', '', '', '', '', 'event_cg_mode', 'true', 's652', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s652', 'main_ryokan_morning', 4, 'scene', 652, '', '', '', 'cg ch4_winter_outfit', '', '', '', 's653', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s653', 'main_ryokan_morning', 4, 'narration', 653, '', '', '他回头望去，看见上身黑色棉袄，下身深蓝牛仔裤，脚踩一双棕褐色长筒靴的星野爱站在淡黄色的灯光之下。', '', '', '', '', 's654', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s654', 'main_ryokan_morning', 4, 'narration', 654, '', '', '她一边整理附两只有小兔子玩偶的御寒手套，一边抬眼看过来。', '', '', '', '', 's655', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s655', 'main_ryokan_morning', 4, 'narration', 655, '', '', '头上没戴帽子，但用了类似的兔子发饰装点秀发。', '', '', '', '', 's656', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s656', 'main_ryokan_morning', 4, 'narration', 656, '', '', '此刻正将头发拨到后面，露出那令人着迷的白皙耳朵。', '', '', '', '', 's657', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s657', 'main_ryokan_morning', 4, 'narration', 657, '', '', '那是怎样曼妙的身姿，连一袭白衫的北国风光在她面前都黯然失色。', '', '', '', '', 's658', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s658', 'main_ryokan_morning', 4, 'narration', 658, '', '', '整理好手套，星野爱迈着可以说是欢愉的步伐走过来。', '', '', '', '', 's659', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s659', 'main_ryokan_morning', 4, 'narration', 659, '', '', '直到到了顾天鹏身前，她止住脚步，手在身后交叠，脑袋倾斜一个可爱的角度，脸上挂着纯净的、毫无瑕疵的微笑。', '', '', '', '', 's660', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s660', 'main_ryokan_morning', 4, 'set', 660, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's661', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s661', 'main_ryokan_morning', 4, 'set', 661, '', '', '', '', '', 'ai_sprite_mode', 'true', 's662', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s662', 'main_ryokan_morning', 4, 'set', 662, '', '', '', '', '', 'event_cg_mode', 'false', 's663', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s663', 'main_ryokan_morning', 4, 'scene', 663, '', '', '', 'bg ryokan_genkan', '', '', '', 's664', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s664', 'main_ryokan_morning', 4, 'sprite', 664, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's665', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s665', 'main_ryokan_morning', 4, 'dialogue', 665, 'ai', '星野爱', '有那么好看吗？盯了好久。', '', '', '', '', 's666', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s666', 'main_ryokan_morning', 4, 'dialogue', 666, 'taku', '顾天鹏', '抱歉。', '', '', '', '', 's667', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s667', 'main_ryokan_morning', 4, 'dialogue', 667, 'ai', '星野爱', '走啦。', '', '', '', '', 's668', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s668', 'main_ryokan_morning', 4, 'narration', 668, '', '', '顾天鹏点头，星野爱围好围巾、对着空气呼出口气，两人踩着积雪一起出了门。', '', '', '', '', 's669', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s669', 'main_ryokan_morning', 4, 'set', 669, '', '', '', '', '', 'ai_sprite_mode', 'false', 's670', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s670', 'main_ryokan_morning', 4, 'set', 670, '', '', '', '', '', 'event_cg_mode', 'true', 's671', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s671', 'main_ryokan_morning', 4, 'scene', 671, '', '', '', 'cg ch4_snow_walk', '', '', '', 's672', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s672', 'main_ryokan_morning', 4, 'narration', 672, '', '', '一路上，微风和煦，阳光温暖。', '', '', '', '', 's673', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s673', 'main_ryokan_morning', 4, 'narration', 673, '', '', '如泡沫般的云朵翻涌在湛蓝色的天空之上，呼吸到的空气都染上初冬的色彩。', '', '', '', '', 's674', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s674', 'main_ryokan_morning', 4, 'narration', 674, '', '', '好像春天近了。其实春天还远着。', '', '', '', '', 's675', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s675', 'main_ryokan_morning', 4, 'narration', 675, '', '', '是星野爱让他觉得春天快来了。', '', '', '', '', 's676', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s676', 'main_ryokan_morning', 4, 'narration', 676, '', '', '顾天鹏想，那是一种完完全全属于春天的笑容了。', '', '', '', '', 's677', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s677', 'main_ryokan_morning', 4, 'narration', 677, '', '', '即使在晴空之下，积雪也难以完全消融，二人的脚印从旅馆延伸，一直到了山脚下。', '', '', '', '', 's678', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s678', 'main_ryokan_morning', 4, 'set', 678, '', '', '', '', '', 'ai_sprite_mode', 'true', 's679', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s679', 'main_ryokan_morning', 4, 'set', 679, '', '', '', '', '', 'event_cg_mode', 'false', 's680', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s680', 'main_ryokan_morning', 4, 'scene', 680, '', '', '', 'bg forest_trail_left', '', '', '', 's681', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s681', 'main_ryokan_morning', 4, 'sprite', 681, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's682', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s682', 'main_ryokan_morning', 4, 'narration', 682, '', '', '登山有两条线路，一条稍急，一条稍缓。', '', '', '', '', 's683', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s683', 'main_ryokan_morning', 4, 'dialogue', 683, 'ai', '星野爱', '选哪边好呢？', '', '', '', '', 's684', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s685', 'main_ryokan_morning', 4, 'narration', 685, '', '', '顾天鹏先看路牌，又看了一眼雪地里被踩实的脚印。至少这条路能保证他们在天黑前回来。', '', '', '', '', 's686', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s686', 'main_ryokan_morning', 4, 'narration', 686, '', '', '星野爱左右看了看，最后把手套往上拽了拽。', '', '', '', '', 's687', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s687', 'main_ryokan_morning', 4, 'dialogue', 687, 'ai', '星野爱', '那就左边好了！', '', '', '', '', 's688', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s688', 'main_ryokan_morning', 4, 'dialogue', 688, 'taku', '顾天鹏', '那我走右边。', '', '', '', '', 's689', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s689', 'main_ryokan_morning', 4, 'narration', 689, '', '', '顾天鹏说。', '', '', '', '', 's690', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s690', 'main_ryokan_morning', 4, 'dialogue', 690, 'taku', '顾天鹏', '到时候在山顶汇合。', '', '', '', '', 's691', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s691', 'main_ryokan_morning', 4, 'narration', 691, '', '', '星野爱眯缝眼睛盯着他，发出一种奇妙的“嘁”的拟声。', '', '', '', '', 's692', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s692', 'main_ryokan_morning', 4, 'dialogue', 692, 'taku', '顾天鹏', '开玩笑的，那就左边吧。', '', '', '', '', 's702', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s693', 'main_ryokan_morning', 4, 'narration', 693, '', '', '顾天鹏顺着她的视线看向树与树之间。那里的雪面完整得像一张还没写字的纸。', '', '', '', '', 's694', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s694', 'main_ryokan_morning', 4, 'narration', 694, '', '', '他没有立刻否定，只把可能迷路这件事先放在心里。', '', '', '', '', 's695', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s695', 'main_ryokan_morning', 4, 'dialogue', 695, 'ai', '星野爱', '一点点就好。我们不走远。', '', '', '', '', 's696', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s696', 'main_ryokan_morning', 4, 'narration', 696, '', '', '他们往树影里踏了几步，脚下的雪发出很轻的碎裂声。新路确实被他们踩出来了，短得像一句还没说完的话。', '', '', '', '', 's697', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s697', 'main_ryokan_morning', 4, 'dialogue', 697, 'taku', '顾天鹏', '到这里。再往前就是迷路。', '', '', '', '', 's698', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s698', 'main_ryokan_morning', 4, 'dialogue', 698, 'ai', '星野爱', '冒险家撤退！', '', '', '', '', 's699', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s699', 'main_ryokan_morning', 4, 'narration', 699, '', '', '她朝没被踩乱的雪地敬了个不太标准的礼，然后沿着自己的脚印退回路牌前。', '', '', '', '', 's700', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s700', 'main_ryokan_morning', 4, 'narration', 700, '', '', '那段小小的偏离耗掉了一点时间，山道上的节奏也被打乱了。', '', '', '', '', 's701', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s701', 'main_ryokan_morning', 4, 'narration', 701, '', '', '他们还是回到左侧山道，只是原本轻快的脚步慢了些。', '', '', '', '', 's702', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s684', 'main_ryokan_morning', 4, 'menu', 684, '', '', '', '', '', '', '', 's702', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s702', 'main_ryokan_morning', 4, 'narration', 702, '', '', '脚印延伸向左面，路边的杂草被消融的雪水压弯了腰。', '', '', '', '', 's703', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s703', 'chapter_5', 5, 'set', 703, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's704', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s704', 'chapter_5', 5, 'set', 704, '', '', '', '', '', 'ai_sprite_mode', 'true', 's705', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s705', 'chapter_5', 5, 'set', 705, '', '', '', '', '', 'event_cg_mode', 'false', 's706', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s706', 'chapter_5', 5, 'scene', 706, '', '', '', 'bg forest_trail_left', '', '', '', 's707', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s707', 'chapter_5', 5, 'sprite', 707, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's708', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s708', 'chapter_5', 5, 'narration', 708, '', '', '她说，无法成为偶像', '', '', '', '', 's709', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s709', 'chapter_5', 5, 'narration', 709, '', '', '风凉浸浸的，白色的松树叶落下水来，摔进雪里，像是沉到大海里的一滴墨一样消失的无影无踪。', '', '', '', '', 's710', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s710', 'chapter_5', 5, 'dialogue', 710, 'ai', '星野爱', '真好啊，天气，这种时候决定出来登山真是太合适了！', '', '', '', '', 's711', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s711', 'chapter_5', 5, 'dialogue', 711, 'taku', '顾天鹏', '是啊，如果我一个人的话，估计会先去泡泡温泉吧。毕竟坐了那么久火车。', '', '', '', '', 's712', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s712', 'chapter_5', 5, 'dialogue', 712, 'ai', '星野爱', '让你一起出来真是抱歉。', '', '', '', '', 's713', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s713', 'chapter_5', 5, 'dialogue', 713, 'taku', '顾天鹏', '还好。', '', '', '', '', 's714', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s714', 'chapter_5', 5, 'dialogue', 714, 'ai', '星野爱', '我问你啊。', '', '', '', '', 's715', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s715', 'chapter_5', 5, 'narration', 715, '', '', '她背过身来，动作优雅、灵动到不可思议，就像是精心准备好的一样。', '', '', '', '', 's716', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s716', 'chapter_5', 5, 'narration', 716, '', '', '从树梢间倾泻下来的阳光，晃过她精致的侧脸，在她的黑色皮袄上来回跳跃。', '', '', '', '', 's717', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s717', 'chapter_5', 5, 'narration', 717, '', '', '她背着手，身子面向顾天鹏，一步一步向后退。', '', '', '', '', 's718', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s718', 'chapter_5', 5, 'dialogue', 718, 'ai', '星野爱', '你喜欢登山吗？', '', '', '', '', 's719', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s719', 'chapter_5', 5, 'dialogue', 719, 'taku', '顾天鹏', '喜欢看书，锻炼，听歌，出门倒是难得，登山更不用说，但不讨厌。', '', '', '', '', 's720', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s720', 'chapter_5', 5, 'dialogue', 720, 'ai', '星野爱', '喜欢看书，锻炼，听歌，难得出门。', '', '', '', '', 's721', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s721', 'chapter_5', 5, 'narration', 721, '', '', '星野爱鹦鹉学舌。', '', '', '', '', 's722', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s722', 'chapter_5', 5, 'dialogue', 722, 'ai', '星野爱', '怎么想到出门远足呢，到这里。', '', '', '', '', 's723', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s723', 'chapter_5', 5, 'dialogue', 723, 'taku', '顾天鹏', '放松。', '', '', '', '', 's724', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s724', 'chapter_5', 5, 'dialogue', 724, 'ai', '星野爱', '放松。', '', '', '', '', 's725', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s725', 'chapter_5', 5, 'narration', 725, '', '', '她又学了一句，眨了下眼睛。', '', '', '', '', 's726', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s726', 'chapter_5', 5, 'dialogue', 726, 'ai', '星野爱', '之前心情很不好？', '', '', '', '', 's727', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s727', 'chapter_5', 5, 'dialogue', 727, 'taku', '顾天鹏', '为什么这么说。', '', '', '', '', 's728', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s728', 'chapter_5', 5, 'dialogue', 728, 'ai', '星野爱', '不然放松什么。', '', '', '', '', 's729', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s729', 'chapter_5', 5, 'dialogue', 729, 'taku', '顾天鹏', '不用理由，想做就做了。', '', '', '', '', 's730', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s730', 'chapter_5', 5, 'dialogue', 730, 'ai', '星野爱', '这样啊。', '', '', '', '', 's731', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s731', 'chapter_5', 5, 'dialogue', 731, 'taku', '顾天鹏', '就这么简单。', '', '', '', '', 's732', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s732', 'chapter_5', 5, 'dialogue', 732, 'ai', '星野爱', '就这么简单啊。', '', '', '', '', 's733', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s733', 'chapter_5', 5, 'scene', 733, '', '', '', 'bg forest_trail_right', '', '', '', 's734', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s734', 'chapter_5', 5, 'sprite', 734, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's735', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s735', 'chapter_5', 5, 'narration', 735, '', '', '她没再说话，又转身朝前，一步一步踏出脚印，凝眸望向蔚蓝如海湾的天空。', '', '', '', '', 's736', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s736', 'chapter_5', 5, 'narration', 736, '', '', '长长的云朵延伸到很远的地方，如同铺出了一条登上仙境的道路。', '', '', '', '', 's737', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s737', 'chapter_5', 5, 'narration', 737, '', '', '走在身后，顾天鹏默然无语。', '', '', '', '', 's738', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s738', 'chapter_5', 5, 'narration', 738, '', '', '看着星野爱那头亮紫色的秀发、自信挺拔的身影、缓缓移动的身姿。', '', '', '', '', 's739', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s739', 'chapter_5', 5, 'narration', 739, '', '', '他感觉自己的目光像是被强大的黑洞引力吸引了一般，怎么也挪不开。', '', '', '', '', 's740', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s740', 'chapter_5', 5, 'narration', 740, '', '', '消融的雪发出清晰的声音，叮咚叮咚的。', '', '', '', '', 's741', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s741', 'chapter_5', 5, 'narration', 741, '', '', '消逝的时间像是被微风吹到树林里，再也回不来。', '', '', '', '', 's742', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s742', 'chapter_5', 5, 'narration', 742, '', '', '良久，顾天鹏打破沉默。', '', '', '', '', 's743', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s743', 'chapter_5', 5, 'dialogue', 743, 'taku', '顾天鹏', '你呢。', '', '', '', '', 's744', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s744', 'chapter_5', 5, 'dialogue', 744, 'ai', '星野爱', '什么？', '', '', '', '', 's745', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s745', 'chapter_5', 5, 'dialogue', 745, 'taku', '顾天鹏', '喜欢登山？', '', '', '', '', 's746', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s746', 'chapter_5', 5, 'dialogue', 746, 'ai', '星野爱', '不讨厌。', '', '', '', '', 's747', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s747', 'chapter_5', 5, 'dialogue', 747, 'taku', '顾天鹏', '具体来说喜欢什么。', '', '', '', '', 's748', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s748', 'chapter_5', 5, 'narration', 748, '', '', '沉吟片刻，星野爱扭动腰肢，露出美好的侧脸，灿烂的笑颜。', '', '', '', '', 's749', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s749', 'chapter_5', 5, 'narration', 749, '', '', '她把手放在动人的唇前。', '', '', '', '', 's750', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s750', 'chapter_5', 5, 'dialogue', 750, 'ai', '星野爱', '是秘密！', '', '', '', '', 's751', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s751', 'chapter_5', 5, 'dialogue', 751, 'taku', '顾天鹏', '又来？', '', '', '', '', 's752', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s752', 'chapter_5', 5, 'dialogue', 752, 'ai', '星野爱', '嘻嘻。', '', '', '', '', 's753', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s753', 'chapter_5', 5, 'narration', 753, '', '', '她刻意放慢步调，等顾天鹏和她并排。', '', '', '', '', 's754', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s754', 'chapter_5', 5, 'dialogue', 754, 'ai', '星野爱', '若隐若现的秘密，这就是女孩子！', '', '', '', '', 's755', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s755', 'chapter_5', 5, 'dialogue', 755, 'taku', '顾天鹏', '神秘。', '', '', '', '', 's756', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s756', 'chapter_5', 5, 'dialogue', 756, 'ai', '星野爱', '并且完美！', '', '', '', '', 's757', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s757', 'chapter_5', 5, 'dialogue', 757, 'taku', '顾天鹏', '和我想的不太一样。', '', '', '', '', 's758', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s758', 'chapter_5', 5, 'dialogue', 758, 'ai', '星野爱', '你怎么想？', '', '', '', '', 's759', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s759', 'chapter_5', 5, 'narration', 759, '', '', '她有些好奇。', '', '', '', '', 's760', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s760', 'chapter_5', 5, 'narration', 760, '', '', '顾天鹏望着前方，道路出奇的明亮。', '', '', '', '', 's761', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s761', 'chapter_5', 5, 'dialogue', 761, 'taku', '顾天鹏', 'Sugar and spice, and everything nice.', '', '', '', '', 's762', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s762', 'chapter_5', 5, 'dialogue', 762, 'ai', '星野爱', '说这话我听不懂。', '', '', '', '', 's763', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s763', 'chapter_5', 5, 'narration', 763, '', '', '她大概是鼓起嘴嘟囔。', '', '', '', '', 's764', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s764', 'chapter_5', 5, 'dialogue', 764, 'taku', '顾天鹏', '女孩子是由砂糖、香辛料和一切美好的东西组成的。', '', '', '', '', 's765', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s765', 'chapter_5', 5, 'narration', 765, '', '', '她把食指依附在脸颊上。', '', '', '', '', 's766', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s766', 'chapter_5', 5, 'dialogue', 766, 'ai', '星野爱', '嗯……感觉甜甜的。', '', '', '', '', 's767', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s767', 'chapter_5', 5, 'dialogue', 767, 'taku', '顾天鹏', '是的。', '', '', '', '', 's768', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s768', 'chapter_5', 5, 'dialogue', 768, 'ai', '星野爱', '可是少了点什么。', '', '', '', '', 's769', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s769', 'chapter_5', 5, 'dialogue', 769, 'taku', '顾天鹏', '少了点什么？', '', '', '', '', 's770', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s770', 'chapter_5', 5, 'dialogue', 770, 'ai', '星野爱', '大概，神秘？', '', '', '', '', 's771', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s771', 'chapter_5', 5, 'narration', 771, '', '', '她盯着耷拉的树梢，又转向顾天鹏。', '', '', '', '', 's772', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s772', 'chapter_5', 5, 'dialogue', 772, 'ai', '星野爱', '想不到贴切的了，该怎么形容？', '', '', '', '', 's773', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s773', 'chapter_5', 5, 'dialogue', 773, 'taku', '顾天鹏', '谎言？', '', '', '', '', 's774', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s774', 'chapter_5', 5, 'dialogue', 774, 'ai', '星野爱', '没错！', '', '', '', '', 's775', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s775', 'chapter_5', 5, 'dialogue', 775, 'ai', '星野爱', '是这种感觉，既神秘又危险的女孩子，一级棒！', '', '', '', '', 's776', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s776', 'chapter_5', 5, 'dialogue', 776, 'taku', '顾天鹏', '了不起。', '', '', '', '', 's777', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s777', 'chapter_5', 5, 'dialogue', 777, 'ai', '星野爱', '了不起的星野爱！', '', '', '', '', 's778', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s778', 'chapter_5', 5, 'dialogue', 778, 'taku', '顾天鹏', '璀璨的星野爱。', '', '', '', '', 's779', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s779', 'chapter_5', 5, 'dialogue', 779, 'ai', '星野爱', '完美的星野爱！', '', '', '', '', 's780', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s780', 'chapter_5', 5, 'dialogue', 780, 'taku', '顾天鹏', '再说下去就是自负了哦。', '', '', '', '', 's781', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s781', 'chapter_5', 5, 'narration', 781, '', '', '她笑着吐了下舌头。', '', '', '', '', 's782', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s782', 'chapter_5', 5, 'narration', 782, '', '', '顾天鹏有些愕然：身旁的少女连装糊涂都如此令人怦然心动。', '', '', '', '', 's783', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s783', 'chapter_5', 5, 'scene', 783, '', '', '', 'bg ch5_forest_midtrail', '', '', '', 's784', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s784', 'chapter_5', 5, 'sprite', 784, '', '', '', '', '[{"image": "heroine winter_shy", "pos": "heroine_winter_center"}]', '', '', 's785', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s785', 'chapter_5', 5, 'narration', 785, '', '', '寂静的松树林里，两人继续向前。', '', '', '', '', 's786', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s786', 'chapter_5', 5, 'narration', 786, '', '', '顾天鹏只顾爬山，手也未从兜里伸出来。', '', '', '', '', 's787', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s787', 'chapter_5', 5, 'narration', 787, '', '', '星野爱则时不时跑向前方，触碰偶然飞来红蜻蜓、不知名的小鸟，时不时绕回来，挑逗路边的野花、杂草。', '', '', '', '', 's788', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s788', 'chapter_5', 5, 'narration', 788, '', '', '埋进雪里的脚印纵横交错，忽浅忽深，不分彼此，唯有前行的方向明确。', '', '', '', '', 's789', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s789', 'chapter_5', 5, 'scene', 789, '', '', '', 'bg ch5_forest_clearing', '', '', '', 's790', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s790', 'chapter_5', 5, 'sprite', 790, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's791', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s791', 'chapter_5', 5, 'narration', 791, '', '', '再往前，道路逐渐开阔，鸟叫声愈发清晰。', '', '', '', '', 's792', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s792', 'chapter_5', 5, 'narration', 792, '', '', '运动鞋也好，长筒靴也罢，无论是哪一种，踩上积雪的时候，都会发出抚慰心弦的沙沙声。', '', '', '', '', 's793', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s793', 'chapter_5', 5, 'narration', 793, '', '', '直到积雪层变厚，阳光变得更加温暖，清风便从山腰处了无踪迹了。', '', '', '', '', 's794', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s794', 'chapter_5', 5, 'narration', 794, '', '', '呼出的白气升到太阳里，藏到飘渺的云端。', '', '', '', '', 's795', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s795', 'chapter_5', 5, 'narration', 795, '', '', '耳边唯有心跳和脚步声长存，除此之外就空无一物了，视野是清新的白。', '', '', '', '', 's796', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s796', 'chapter_5', 5, 'set', 796, '', '', '', '', '', 'ai_sprite_mode', 'true', 's797', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s797', 'chapter_5', 5, 'set', 797, '', '', '', '', '', 'event_cg_mode', 'false', 's798', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s798', 'chapter_5', 5, 'scene', 798, '', '', '', 'bg ch5_summit_sunset', '', '', '', 's799', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s799', 'chapter_5', 5, 'sprite', 799, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's800', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s800', 'chapter_5', 5, 'narration', 800, '', '', '登上山顶已近黄昏。', '', '', '', '', 's801', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s801', 'chapter_5', 5, 'narration', 801, '', '', '一路上，两个人停停歇歇，休息时便交谈。', '', '', '', '', 's802', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s802', 'chapter_5', 5, 'narration', 802, '', '', '从杉树叶聊到芭蕉，从无垠山脉聊到碧蓝之海。', '', '', '', '', 's803', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s803', 'chapter_5', 5, 'narration', 803, '', '', '聊了雪，聊了风，聊了鹿儿岛的樱花，聊了电视节目主持人的搞笑着装。', '', '', '', '', 's804', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s804', 'chapter_5', 5, 'narration', 804, '', '', '连几分熟的鸡蛋最好吃也聊，聊了很多很多，多到统计不完，多到文字写不下。', '', '', '', '', 's805', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s805', 'chapter_5', 5, 'dialogue', 805, 'ai', '星野爱', '是吧是吧！', '', '', '', '', 's806', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s806', 'chapter_5', 5, 'narration', 806, '', '', '站在山巅，星野爱微笑着说，那笑容很像是电影里的某个特写镜头。', '', '', '', '', 's807', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s807', 'chapter_5', 5, 'dialogue', 807, 'ai', '星野爱', '那个节目真的很不错呢！', '', '', '', '', 's808', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s808', 'chapter_5', 5, 'dialogue', 808, 'taku', '顾天鹏', '很难不赞同。', '', '', '', '', 's809', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s809', 'chapter_5', 5, 'dialogue', 809, 'ai', '星野爱', '绝对赞同！', '', '', '', '', 's810', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s810', 'chapter_5', 5, 'dialogue', 810, 'ai', '星野爱', '弘中绫香，田中美奈实啊什么的……你知道那个动作吧？超有名。', '', '', '', '', 's811', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s811', 'chapter_5', 5, 'set', 811, '', '', '', '', '', 'ai_sprite_mode', 'false', 's812', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s812', 'chapter_5', 5, 'set', 812, '', '', '', '', '', 'event_cg_mode', 'true', 's813', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s813', 'chapter_5', 5, 'scene', 813, '', '', '', 'cg ch5_summit_ai_sunset', '', '', '', 's814', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s814', 'chapter_5', 5, 'narration', 814, '', '', '她面朝顾天鹏，落了雪的木栏在她之后，橙黄色的落日在木栏之后。', '', '', '', '', 's815', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s815', 'chapter_5', 5, 'narration', 815, '', '', '她仿佛背靠着夕阳，歪了下脑袋，手指触及下巴。', '', '', '', '', 's816', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s816', 'chapter_5', 5, 'dialogue', 816, 'ai', '星野爱', '‘有点心机又如何呢？’。绝对，绝对听过吧！', '', '', '', '', 's817', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s817', 'chapter_5', 5, 'dialogue', 817, 'taku', '顾天鹏', '听过。', '', '', '', '', 's818', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s818', 'chapter_5', 5, 'set', 818, '', '', '', '', '', 'ai_sprite_mode', 'true', 's819', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s819', 'chapter_5', 5, 'set', 819, '', '', '', '', '', 'event_cg_mode', 'false', 's820', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s820', 'chapter_5', 5, 'scene', 820, '', '', '', 'bg ch5_summit_sunset', '', '', '', 's821', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s821', 'chapter_5', 5, 'sprite', 821, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's822', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s822', 'chapter_5', 5, 'narration', 822, '', '', '这之后，他们爬上铺了层薄雪的小土丘，站在很高的地方朝山下俯瞰。', '', '', '', '', 's823', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s823', 'chapter_5', 5, 'narration', 823, '', '', '温泉旅馆变成了一个黑点般大小的存在，其他房屋亦是如此，行人已经完全看不清。', '', '', '', '', 's824', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s824', 'chapter_5', 5, 'narration', 824, '', '', '日暮笼罩的雪地上，墨黑墨黑的松树星罗棋布。', '', '', '', '', 's825', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s825', 'chapter_5', 5, 'narration', 825, '', '', '当斜阳散发出最后的光辉，那一道道阴影便被无限地拉长。', '', '', '', '', 's826', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s826', 'chapter_5', 5, 'narration', 826, '', '', '看厌了风景，他们从土丘上下来，星野爱一屁股坐进雪里。', '', '', '', '', 's827', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s827', 'chapter_5', 5, 'dialogue', 827, 'taku', '顾天鹏', '小心感冒。', '', '', '', '', 's828', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s828', 'chapter_5', 5, 'dialogue', 828, 'ai', '星野爱', '就这一次！', '', '', '', '', 's829', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s829', 'chapter_5', 5, 'narration', 829, '', '', '她撒娇似的说，一边对顾天鹏温和一笑，一边拍了拍身旁的雪地，示意他也坐下。', '', '', '', '', 's830', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s830', 'chapter_5', 5, 'narration', 830, '', '', '顾天鹏犹豫一下，她又像是催促似的扇动着手掌。', '', '', '', '', 's831', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s831', 'chapter_5', 5, 'narration', 831, '', '', '顾天鹏叹了口气，坐到她身边。', '', '', '', '', 's832', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s832', 'chapter_5', 5, 'narration', 832, '', '', '雪化的不快，但起身之后一定会有潮湿的感觉。', '', '', '', '', 's833', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s833', 'chapter_5', 5, 'dialogue', 833, 'ai', '星野爱', '好轻松。', '', '', '', '', 's834', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s834', 'chapter_5', 5, 'dialogue', 834, 'taku', '顾天鹏', '的的确确很轻松。', '', '', '', '', 's835', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s835', 'chapter_5', 5, 'narration', 835, '', '', '落日西沉，晚霞攀上二人的正脸，闯进他们双眸之中。', '', '', '', '', 's836', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s836', 'chapter_5', 5, 'narration', 836, '', '', '过了一会儿，顾天鹏突然问。', '', '', '', '', 's837', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s837', 'chapter_5', 5, 'dialogue', 837, 'taku', '顾天鹏', '你想当偶像？', '', '', '', '', 's838', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s838', 'chapter_5', 5, 'dialogue', 838, 'ai', '星野爱', '嗯？', '', '', '', '', 's839', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s839', 'chapter_5', 5, 'dialogue', 839, 'taku', '顾天鹏', '想当偶像？', '', '', '', '', 's840', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s840', 'chapter_5', 5, 'dialogue', 840, 'ai', '星野爱', '嗯——', '', '', '', '', 's841', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s841', 'chapter_5', 5, 'narration', 841, '', '', '她扬起脸，最后一头栽进雪地里。', '', '', '', '', 's842', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s842', 'chapter_5', 5, 'set', 842, '', '', '', '', '', 'ai_sprite_mode', 'false', 's843', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s843', 'chapter_5', 5, 'set', 843, '', '', '', '', '', 'event_cg_mode', 'true', 's844', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s844', 'chapter_5', 5, 'scene', 844, '', '', '', 'cg ch5_snow_confession', '', '', '', 's845', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s845', 'chapter_5', 5, 'dialogue', 845, 'taku', '顾天鹏', '干嘛呢？', '', '', '', '', 's846', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s846', 'chapter_5', 5, 'dialogue', 846, 'ai', '星野爱', '舒服！', '', '', '', '', 's847', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s847', 'chapter_5', 5, 'dialogue', 847, 'taku', '顾天鹏', '不想回答问题？', '', '', '', '', 's848', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s848', 'chapter_5', 5, 'dialogue', 848, 'ai', '星野爱', '还在想嘛！', '', '', '', '', 's849', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s849', 'chapter_5', 5, 'dialogue', 849, 'taku', '顾天鹏', '好呢。', '', '', '', '', 's850', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s850', 'chapter_5', 5, 'narration', 850, '', '', '她把右手举高，眯起一边眼睛，从分开的指缝间观察绝美的黄昏。', '', '', '', '', 's851', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s851', 'chapter_5', 5, 'dialogue', 851, 'ai', '星野爱', '真漂亮！', '', '', '', '', 's852', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s852', 'chapter_5', 5, 'dialogue', 852, 'ai', '星野爱', '你也躺下来，怎么样？', '', '', '', '', 's853', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s853', 'chapter_5', 5, 'dialogue', 853, 'taku', '顾天鹏', '很冷吧。', '', '', '', '', 's854', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s854', 'chapter_5', 5, 'dialogue', 854, 'ai', '星野爱', '就这一次！', '', '', '', '', 's855', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s855', 'chapter_5', 5, 'narration', 855, '', '', '顾天鹏没办法似的呼出一口气。', '', '', '', '', 's856', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s856', 'chapter_5', 5, 'narration', 856, '', '', '两人的身体沉进雪地里，石灰色的云仿佛抬手便能抓进掌心。', '', '', '', '', 's857', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s857', 'chapter_5', 5, 'narration', 857, '', '', '他们默默无语，感受着时而飘过的一阵南风，风里全是雪和泥土的清香。', '', '', '', '', 's858', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s858', 'chapter_5', 5, 'dialogue', 858, 'taku', '顾天鹏', '其实想当偶像吧？', '', '', '', '', 's859', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s859', 'chapter_5', 5, 'dialogue', 859, 'ai', '星野爱', '不想。', '', '', '', '', 's860', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s860', 'chapter_5', 5, 'narration', 860, '', '', '星野爱这次没犹豫。', '', '', '', '', 's861', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s861', 'chapter_5', 5, 'narration', 861, '', '', '顾天鹏长长地嗯了一声。', '', '', '', '', 's862', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s862', 'chapter_5', 5, 'dialogue', 862, 'taku', '顾天鹏', '理由呢？', '', '', '', '', 's863', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s863', 'chapter_5', 5, 'dialogue', 863, 'ai', '星野爱', '我没兴趣。', '', '', '', '', 's864', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s864', 'chapter_5', 5, 'dialogue', 864, 'taku', '顾天鹏', '没兴趣啊……', '', '', '', '', 's865', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s865', 'chapter_5', 5, 'dialogue', 865, 'ai', '星野爱', '顾天鹏，我说过吧，我是孤儿这件事。', '', '', '', '', 's866', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s866', 'chapter_5', 5, 'dialogue', 866, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's867', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s867', 'chapter_5', 5, 'narration', 867, '', '', '顾天鹏沉默一下。', '', '', '', '', 's868', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s868', 'chapter_5', 5, 'dialogue', 868, 'taku', '顾天鹏', '抱歉。', '', '', '', '', 's869', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s869', 'chapter_5', 5, 'dialogue', 869, 'ai', '星野爱', '嗯嗯——', '', '', '', '', 's870', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s870', 'chapter_5', 5, 'narration', 870, '', '', '她抿着嘴唇，又说。', '', '', '', '', 's871', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s871', 'chapter_5', 5, 'dialogue', 871, 'ai', '星野爱', '顾天鹏，你觉得什么是偶像呢？', '', '', '', '', 's872', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s872', 'chapter_5', 5, 'dialogue', 872, 'taku', '顾天鹏', '舞蹈，唱功，演技，好看的身材，脸。', '', '', '', '', 's873', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s873', 'chapter_5', 5, 'dialogue', 873, 'ai', '星野爱', '太直白了吧！', '', '', '', '', 's874', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s874', 'chapter_5', 5, 'narration', 874, '', '', '她好像被逗笑了。', '', '', '', '', 's875', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s875', 'chapter_5', 5, 'dialogue', 875, 'taku', '顾天鹏', '文艺点：精神支柱？', '', '', '', '', 's876', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s876', 'chapter_5', 5, 'dialogue', 876, 'ai', '星野爱', '嗯……精神支柱。', '', '', '', '', 's877', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s877', 'chapter_5', 5, 'narration', 877, '', '', '她字斟句酌重复道。', '', '', '', '', 's878', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s878', 'chapter_5', 5, 'narration', 878, '', '', '顾天鹏侧过脸，星野爱仍目视上方。', '', '', '', '', 's879', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s879', 'chapter_5', 5, 'dialogue', 879, 'ai', '星野爱', '从小在孤儿院长大的我，记忆中，从没爱过别人，也从来没被别人爱过。', '', '', '', '', 's880', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s880', 'chapter_5', 5, 'narration', 880, '', '', '从夕阳吹来的晚风掠过雪地，拨动她的刘海，旋即钻进松树林中。', '', '', '', '', 's881', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s881', 'chapter_5', 5, 'narration', 881, '', '', '等风停歇，她自嘲似的扬起嘴角，露出前所未有的，近乎可以用凄美来形容的微笑。', '', '', '', '', 's882', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s882', 'chapter_5', 5, 'dialogue', 882, 'ai', '星野爱', '这样的我，怎么能够成为偶像？', '', '', '', '', 's883', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s884', 'chapter_5', 5, 'narration', 884, '', '', '顾天鹏几乎想立刻反驳。那不是出于安慰，而是因为他在她眼里看见了和舞台灯一样明亮的东西。', '', '', '', '', 's885', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s885', 'chapter_5', 5, 'dialogue', 885, 'taku', '顾天鹏', '能不能成为偶像，不该只由过去决定。', '', '', '', '', 's886', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s886', 'chapter_5', 5, 'narration', 886, '', '', '这句话像被雪地吸走一半，剩下一半却稳稳落到她身边。', '', '', '', '', 's887', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s887', 'chapter_5', 5, 'dialogue', 887, 'ai', '星野爱', '你说得好像很容易。', '', '', '', '', 's888', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s888', 'chapter_5', 5, 'dialogue', 888, 'taku', '顾天鹏', '不容易，所以才值得你去做。', '', '', '', '', 's889', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s889', 'chapter_5', 5, 'narration', 889, '', '', '她笑着点头，可那笑意没有在眼底停留太久。被安慰过后，有些话反而更难继续说下去。', '', '', '', '', 's890', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s890', 'chapter_5', 5, 'narration', 890, '', '', '山顶的风把沉默吹散，黄昏很快过去。', '', '', '', '', 's891', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s891', 'chapter_5', 5, 'jump', 891, '', '', '', '', '', '', '', 's3641', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s892', 'chapter_5', 5, 'narration', 892, '', '', '顾天鹏没有急着把自己的判断塞过去。', '', '', '', '', 's893', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s893', 'chapter_5', 5, 'narration', 893, '', '', '她说出这句话已经用了很大力气，轻率的鼓励也许会显得太薄。', '', '', '', '', 's894', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s894', 'chapter_5', 5, 'dialogue', 894, 'taku', '顾天鹏', '我听见了。', '', '', '', '', 's895', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s895', 'chapter_5', 5, 'dialogue', 895, 'ai', '星野爱', '只是听见？', '', '', '', '', 's896', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s896', 'chapter_5', 5, 'dialogue', 896, 'taku', '顾天鹏', '先听见，再回答。', '', '', '', '', 's897', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s897', 'chapter_5', 5, 'narration', 897, '', '', '星野爱低下眼睛，像是第一次允许这句话在空气里停留得久一点。', '', '', '', '', 's898', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s883', 'chapter_5', 5, 'menu', 883, '', '', '', '', '', '', '', 's898', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s898', 'chapter_6', 6, 'set', 898, '', '', '', '', '', 'ai_sprite_mode', 'false', 's899', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s899', 'chapter_6', 6, 'set', 899, '', '', '', '', '', 'event_cg_mode', 'true', 's900', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s900', 'chapter_6', 6, 'scene', 900, '', '', '', 'cg ch6_ryokan_terrace_ai', '', '', '', 's901', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s901', 'chapter_6', 6, 'narration', 901, '', '', '温泉、赏雪、约会', '', '', '', '', 's902', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s902', 'chapter_6', 6, 'narration', 902, '', '', '那天天黑的很快，太阳不经意就掉进了山脉的沟壑里。', '', '', '', '', 's903', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s903', 'chapter_6', 6, 'narration', 903, '', '', '黄昏远去，星星一股脑全跑了出来。', '', '', '', '', 's904', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s904', 'chapter_6', 6, 'narration', 904, '', '', '顾天鹏告诉她：这边是天琴座，那边是仙女座。', '', '', '', '', 's905', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s905', 'chapter_6', 6, 'narration', 905, '', '', '天空深蓝至极，如同将五千米下的太平洋翻转过来。风停了好久。', '', '', '', '', 's906', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s906', 'chapter_6', 6, 'dialogue', 906, 'ai', '星野爱', '需要向粉丝倾诉爱意的偶像……', '', '', '', '', 's907', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s907', 'chapter_6', 6, 'narration', 907, '', '', '望着夜空中最亮的那颗织女星，恍若隔世光景的微笑浮现在星野爱脸上。', '', '', '', '', 's908', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s908', 'chapter_6', 6, 'dialogue', 908, 'ai', '星野爱', '我怎么可能办得到嘛。', '', '', '', '', 's909', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s909', 'chapter_6', 6, 'set', 909, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's910', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s910', 'chapter_6', 6, 'set', 910, '', '', '', '', '', 'ai_sprite_mode', 'true', 's911', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s911', 'chapter_6', 6, 'set', 911, '', '', '', '', '', 'event_cg_mode', 'false', 's912', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s912', 'chapter_6', 6, 'scene', 912, '', '', '', 'bg ch6_ryokan_genkan_night_snow', '', '', '', 's913', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s913', 'chapter_6', 6, 'sprite', 913, '', '', '', '', '[{"image": "heroine winter_surprised", "pos": "heroine_winter_center"}]', '', '', 's914', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s914', 'chapter_6', 6, 'narration', 914, '', '', '回到旅馆已是夜里七点十分，店里灯光微黄，人影攒动。', '', '', '', '', 's915', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s915', 'chapter_6', 6, 'narration', 915, '', '', '回头看去，门外恰好飘起雪来，雪势不大，但用一晚上的时间，大概足以淹没白日的足迹了。', '', '', '', '', 's916', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s916', 'chapter_6', 6, 'narration', 916, '', '', '二人先在玄关处换鞋。', '', '', '', '', 's917', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s917', 'chapter_6', 6, 'dialogue', 917, 'ai', '星野爱', '……阿秋！', '', '', '', '', 's918', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s918', 'chapter_6', 6, 'dialogue', 918, 'taku', '顾天鹏', '果然要感冒了吧。', '', '', '', '', 's919', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s919', 'chapter_6', 6, 'dialogue', 919, 'ai', '星野爱', '唔……你绝对也快了！', '', '', '', '', 's920', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s920', 'chapter_6', 6, 'dialogue', 920, 'taku', '顾天鹏', '那也是托你的福。', '', '', '', '', 's921', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s921', 'chapter_6', 6, 'dialogue', 921, 'ai', '星野爱', '嘿嘿，就这一次！', '', '', '', '', 's922', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s923', 'chapter_6', 6, 'narration', 923, '', '', '顾天鹏从口袋里摸出没用完的暖宝宝，递到她手心里。', '', '', '', '', 's924', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s924', 'chapter_6', 6, 'narration', 924, '', '', '星野爱低头看了看，又抬头看他，笑意比旅馆灯光还要暖。', '', '', '', '', 's925', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s925', 'chapter_6', 6, 'dialogue', 925, 'ai', '星野爱', '这个我收下了。明天还你一个更暖的。', '', '', '', '', 's926', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s926', 'chapter_6', 6, 'dialogue', 926, 'taku', '顾天鹏', '暖宝宝还能升级？', '', '', '', '', 's927', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s927', 'chapter_6', 6, 'dialogue', 927, 'ai', '星野爱', '当然，星野爱限定版。', '', '', '', '', 's928', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s928', 'chapter_6', 6, 'narration', 928, '', '', '这个玩笑让玄关变得热闹，也把刚才山顶残留的沉重暂时推远了一点。', '', '', '', '', 's933', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s929', 'chapter_6', 6, 'narration', 929, '', '', '顾天鹏没有顺着她的玩笑走，而是把声音压得认真了些。', '', '', '', '', 's930', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s930', 'chapter_6', 6, 'dialogue', 930, 'taku', '顾天鹏', '先回房换衣服。感冒了，明天的计划全会泡汤。', '', '', '', '', 's931', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s931', 'chapter_6', 6, 'dialogue', 931, 'ai', '星野爱', '收到，临时监护人先生。', '', '', '', '', 's932', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s932', 'chapter_6', 6, 'narration', 932, '', '', '她朝他敬礼，转身时却真的加快了脚步。', '', '', '', '', 's933', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s922', 'chapter_6', 6, 'menu', 922, '', '', '', '', '', '', '', 's933', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s933', 'chapter_6', 6, 'set', 933, '', '', '', '', '', 'ai_sprite_outfit', 'stage', 's934', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s934', 'chapter_6', 6, 'set', 934, '', '', '', '', '', 'ai_sprite_mode', 'true', 's935', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s935', 'chapter_6', 6, 'set', 935, '', '', '', '', '', 'event_cg_mode', 'false', 's936', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s936', 'chapter_6', 6, 'scene', 936, '', '', '', 'bg ch6_room_fire_warm', '', '', '', 's937', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s937', 'chapter_6', 6, 'sprite', 937, '', '', '', '', '[{"image": "heroine stage_speak", "pos": "heroine_bust_center"}]', '', '', 's938', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s938', 'chapter_6', 6, 'narration', 938, '', '', '他们简单吃过晚饭，又要了一碟花生，半碟兰花豆，半碟葡萄，半碟青提，一瓶手打橙汁。', '', '', '', '', 's939', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s939', 'chapter_6', 6, 'dialogue', 939, 'taku', '顾天鹏', '可乐要不要？', '', '', '', '', 's940', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s940', 'chapter_6', 6, 'dialogue', 940, 'ai', '星野爱', '算了，我不大喜欢喝碳酸饮料。', '', '', '', '', 's941', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s941', 'chapter_6', 6, 'dialogue', 941, 'taku', '顾天鹏', '好。', '', '', '', '', 's942', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s942', 'chapter_6', 6, 'narration', 942, '', '', '拿着吃的回到房间，他们把湿了一半的衣服挂到火炉边上烤干。', '', '', '', '', 's943', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s943', 'chapter_6', 6, 'narration', 943, '', '', '柴烧了不到三分之一，亮红色的火星子不时会从里面冒出来。', '', '', '', '', 's944', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s944', 'chapter_6', 6, 'narration', 944, '', '', '关上窗户后，冷风像是野兽一样拼命想往屋子里钻。', '', '', '', '', 's945', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s945', 'chapter_6', 6, 'narration', 945, '', '', '除了幽咽的风声、炉壁发出的噼里啪啦的声响，此外便万籁俱寂了。', '', '', '', '', 's946', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s946', 'chapter_6', 6, 'narration', 946, '', '', '这个时候，葡萄咬碎时的噗嗤声音都分外清亮。', '', '', '', '', 's947', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s947', 'chapter_6', 6, 'dialogue', 947, 'ai', '星野爱', '去洗澡吗？', '', '', '', '', 's948', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s948', 'chapter_6', 6, 'narration', 948, '', '', '星野爱把围巾也挂到炉壁旁边。', '', '', '', '', 's949', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s949', 'chapter_6', 6, 'dialogue', 949, 'taku', '顾天鹏', '一会儿再去。', '', '', '', '', 's950', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s950', 'chapter_6', 6, 'dialogue', 950, 'ai', '星野爱', '尽快哦，小心真的感冒……阿秋！', '', '', '', '', 's951', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s951', 'chapter_6', 6, 'narration', 951, '', '', '燃烧的木柴突然地响了，顾天鹏盯着她，她露出一副可爱的笑容。', '', '', '', '', 's952', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s952', 'chapter_6', 6, 'dialogue', 952, 'ai', '星野爱', '我先去了！', '', '', '', '', 's953', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s953', 'chapter_6', 6, 'narration', 953, '', '', '说完便夹着白色的浴巾离开。', '', '', '', '', 's954', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s954', 'chapter_6', 6, 'set', 954, '', '', '', '', '', 'ai_sprite_mode', 'false', 's955', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s955', 'chapter_6', 6, 'scene', 955, '', '', '', 'bg ch6_room_fire_warm', '', '', '', 's956', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s956', 'chapter_6', 6, 'narration', 956, '', '', '没有其他人的屋子，顾天鹏将上衣脱下。', '', '', '', '', 's957', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s957', 'chapter_6', 6, 'narration', 957, '', '', '前去洗浴之前，他先做了一百个蹲起，又做了八十个俯卧撑。', '', '', '', '', 's958', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s958', 'chapter_6', 6, 'narration', 958, '', '', '仰卧起坐做到第七十二个的时候，门被哐当一下推开。', '', '', '', '', 's959', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s959', 'chapter_6', 6, 'dialogue', 959, 'ai', '星野爱', '顾天鹏，再晚点的话……', '', '', '', '', 's960', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s960', 'chapter_6', 6, 'narration', 960, '', '', '刚带上门的星野爱注意到正在锻炼的顾天鹏，声音一下子顿住。', '', '', '', '', 's961', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s961', 'chapter_6', 6, 'dialogue', 961, 'ai', '星野爱', '你、你在干嘛？', '', '', '', '', 's962', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s962', 'chapter_6', 6, 'dialogue', 962, 'taku', '顾天鹏', '加强身体素质的练习。', '', '', '', '', 's963', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s963', 'chapter_6', 6, 'narration', 963, '', '', '顾天鹏说着，仰卧起坐又做一个。', '', '', '', '', 's964', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s964', 'chapter_6', 6, 'dialogue', 964, 'ai', '星野爱', '这么晚了还做？', '', '', '', '', 's965', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s965', 'chapter_6', 6, 'dialogue', 965, 'taku', '顾天鹏', '每天都做。', '', '', '', '', 's966', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s966', 'chapter_6', 6, 'dialogue', 966, 'ai', '星野爱', '这样……', '', '', '', '', 's967', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s967', 'chapter_6', 6, 'narration', 967, '', '', '她嬉皮笑脸走过来。', '', '', '', '', 's968', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s968', 'chapter_6', 6, 'dialogue', 968, 'ai', '星野爱', '不过该说不说，身材不错嘛。', '', '', '', '', 's969', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s969', 'chapter_6', 6, 'dialogue', 969, 'taku', '顾天鹏', '谢谢。我听过最动听的夸奖。', '', '', '', '', 's970', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s970', 'chapter_6', 6, 'dialogue', 970, 'ai', '星野爱', '是吗？', '', '', '', '', 's971', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s971', 'chapter_6', 6, 'dialogue', 971, 'taku', '顾天鹏', '毫无疑问。', '', '', '', '', 's972', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s972', 'chapter_6', 6, 'narration', 972, '', '', '做完仰卧起坐，顾天鹏深吁一口气。', '', '', '', '', 's973', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s973', 'chapter_6', 6, 'narration', 973, '', '', '聚精会神的时候，他才仔细打量起已经进来小半会儿的星野爱。', '', '', '', '', 's974', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s974', 'chapter_6', 6, 'narration', 974, '', '', '她用毛巾包住长发，旅馆浴衣松松裹着身体，几缕蓝紫色的鬓发从其间晃荡出来。', '', '', '', '', 's975', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s975', 'chapter_6', 6, 'narration', 975, '', '', '他礼貌地别开视线，星野爱像是感应到他转头动作似的抬头瞥他一眼，然后浅浅地笑了下。', '', '', '', '', 's976', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s976', 'chapter_6', 6, 'dialogue', 976, 'ai', '星野爱', '再晚点浴场就要关咯。', '', '', '', '', 's977', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s977', 'chapter_6', 6, 'dialogue', 977, 'taku', '顾天鹏', '现在就去。', '', '', '', '', 's978', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s978', 'chapter_6', 6, 'set', 978, '', '', '', '', '', 'event_cg_mode', 'false', 's979', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s979', 'chapter_6', 6, 'scene', 979, '', '', '', 'bg ch6_onsen_night', '', '', '', 's980', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s980', 'chapter_6', 6, 'narration', 980, '', '', '露天的浴场，人数已不过三个，大概是来的太晚的缘故，顾天鹏想。', '', '', '', '', 's981', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s981', 'chapter_6', 6, 'narration', 981, '', '', '他脱下衣物钻进温泉，一边感受着水池带来的暖意，一边靠在光滑的桑拿石上仰望月亮。', '', '', '', '', 's982', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s982', 'chapter_6', 6, 'narration', 982, '', '', '下起雪的时候，云也似乎变多了。', '', '', '', '', 's983', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s983', 'chapter_6', 6, 'narration', 983, '', '', '在山顶上看见过的星星如今不剩几个，唯独皎洁的月光依旧皎洁，月影如街灯一般。', '', '', '', '', 's984', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s984', 'chapter_6', 6, 'narration', 984, '', '', '从温泉上来，他用毛巾擦干身体，换上旅馆提供的棉质大短裤。', '', '', '', '', 's985', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s985', 'chapter_6', 6, 'set', 985, '', '', '', '', '', 'event_cg_mode', 'true', 's986', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s986', 'chapter_6', 6, 'scene', 986, '', '', '', 'cg ch6_gatsby_reading_night', '', '', '', 's987', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s987', 'chapter_6', 6, 'narration', 987, '', '', '回到房间之后，星野爱已经吹好头发，问他能不能翻一下《了不起的盖茨比》。', '', '', '', '', 's988', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s988', 'chapter_6', 6, 'dialogue', 988, 'taku', '顾天鹏', '当然没问题。', '', '', '', '', 's989', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s989', 'chapter_6', 6, 'narration', 989, '', '', '顾天鹏将书拿出来递过去，星野爱便照着他写在文字边的日语翻译认真阅读起来。', '', '', '', '', 's990', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s990', 'chapter_6', 6, 'narration', 990, '', '', '这是一个爱的幻灭的故事。', '', '', '', '', 's991', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s991', 'chapter_6', 6, 'narration', 991, '', '', '因为在任何时代任何国家，都会有始终抱着爱的梦想并为之不惜一切的人，虽然他们寥若晨星……', '', '', '', '', 's992', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s992', 'chapter_6', 6, 'narration', 992, '', '', '无声的雪飞扬在窗户外面。', '', '', '', '', 's993', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s993', 'chapter_6', 6, 'set', 993, '', '', '', '', '', 'event_cg_mode', 'false', 's994', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s994', 'chapter_6', 6, 'scene', 994, '', '', '', 'bg ch6_room_fire_warm', '', '', '', 's995', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s995', 'chapter_6', 6, 'narration', 995, '', '', '灯灭之前，顾天鹏去刷了牙，洗完脸。', '', '', '', '', 's996', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s996', 'chapter_6', 6, 'narration', 996, '', '', '重新回来的时候，他看见星野爱已经趴在桌子上睡着了。', '', '', '', '', 's997', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s997', 'chapter_6', 6, 'narration', 997, '', '', '鼾声微弱，《了不起的盖茨比》压在她脸下面。', '', '', '', '', 's998', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s998', 'chapter_6', 6, 'narration', 998, '', '', '他轻轻放平对方的身体，给她盖好被褥，自己在另一头侧身入睡。', '', '', '', '', 's999', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s999', 'chapter_6', 6, 'set', 999, '', '', '', '', '', 'ai_sprite_outfit', 'stage', 's1000', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1000', 'chapter_6', 6, 'set', 1000, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1001', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1001', 'chapter_6', 6, 'set', 1001, '', '', '', '', '', 'event_cg_mode', 'false', 's1002', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1002', 'chapter_6', 6, 'scene', 1002, '', '', '', 'bg ryokan_room', '', '', '', 's1003', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1003', 'chapter_6', 6, 'sprite', 1003, '', '', '', '', '[{"image": "heroine stage_shy", "pos": "heroine_bust_center"}]', '', '', 's1004', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1004', 'chapter_6', 6, 'narration', 1004, '', '', '第二天醒来，月影被暖阳替代，雪不知何时已经停了。', '', '', '', '', 's1005', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1005', 'chapter_6', 6, 'narration', 1005, '', '', '顾天鹏穿上衣服，沿着不容易积雪的长道来回跑了十公里，之后又擦干汗水冲了个澡。', '', '', '', '', 's1006', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1006', 'chapter_6', 6, 'narration', 1006, '', '', '九点多的时候，星野爱总算醒来。', '', '', '', '', 's1007', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1007', 'chapter_6', 6, 'narration', 1007, '', '', '顾天鹏给她带了早餐：抹了蓝莓酱的两块吐司面包，一瓶知名产地的纯牛奶，两节香蕉，用刀切半的半个苹果。', '', '', '', '', 's1008', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1008', 'chapter_6', 6, 'dialogue', 1008, 'ai', '星野爱', '谢谢。', '', '', '', '', 's1009', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1009', 'chapter_6', 6, 'narration', 1009, '', '', '星野爱有些意外。', '', '', '', '', 's1010', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1010', 'chapter_6', 6, 'dialogue', 1010, 'taku', '顾天鹏', '没什么。', '', '', '', '', 's1011', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1011', 'chapter_6', 6, 'narration', 1011, '', '', '顾天鹏继续看书。', '', '', '', '', 's1012', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1012', 'chapter_6', 6, 'narration', 1012, '', '', '吃完早饭，星野爱提出出门赏雪，顾天鹏点头，合上书，他们换上冬装出发。', '', '', '', '', 's1013', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1013', 'chapter_6', 6, 'set', 1013, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's1014', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1014', 'chapter_6', 6, 'set', 1014, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1015', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1015', 'chapter_6', 6, 'set', 1015, '', '', '', '', '', 'event_cg_mode', 'false', 's1016', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1016', 'chapter_6', 6, 'scene', 1016, '', '', '', 'bg ch6_snow_village_bridge', '', '', '', 's1017', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1017', 'chapter_6', 6, 'sprite', 1017, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1018', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1018', 'chapter_6', 6, 'narration', 1018, '', '', '这一天，阳光不如昨天强烈，温度也稍微降了一些。', '', '', '', '', 's1019', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1019', 'chapter_6', 6, 'dialogue', 1019, 'ai', '星野爱', '哈~', '', '', '', '', 's1020', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1020', 'chapter_6', 6, 'dialogue', 1020, 'ai', '星野爱', '明明还是十一月。', '', '', '', '', 's1021', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1021', 'chapter_6', 6, 'dialogue', 1021, 'ai', '星野爱', '不过比冬天还冬天！', '', '', '', '', 's1022', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1022', 'chapter_6', 6, 'narration', 1022, '', '', '她望着刚刚吐出的一口白气，看样子似乎很开心。', '', '', '', '', 's1023', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1023', 'chapter_6', 6, 'dialogue', 1023, 'taku', '顾天鹏', '大概雪下了一夜吧。', '', '', '', '', 's1024', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1024', 'chapter_6', 6, 'dialogue', 1024, 'ai', '星野爱', '白天怎么不继续呢？', '', '', '', '', 's1025', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1025', 'chapter_6', 6, 'dialogue', 1025, 'taku', '顾天鹏', '那该会有多冷啊。', '', '', '', '', 's1026', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1026', 'chapter_6', 6, 'dialogue', 1026, 'ai', '星野爱', '管他呢！', '', '', '', '', 's1027', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1027', 'chapter_6', 6, 'set', 1027, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1028', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1028', 'chapter_6', 6, 'set', 1028, '', '', '', '', '', 'event_cg_mode', 'true', 's1029', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1029', 'chapter_6', 6, 'scene', 1029, '', '', '', 'cg ch6_snow_wish_ai', '', '', '', 's1030', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1030', 'chapter_6', 6, 'narration', 1030, '', '', '戴着手套的星野爱蹲下身子，双手捧起一股雪，然后猛地起身往天上使劲撒。', '', '', '', '', 's1031', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1031', 'chapter_6', 6, 'dialogue', 1031, 'ai', '星野爱', '彻彻底底的，彻彻底底的，下一场超大超大的雪吧！', '', '', '', '', 's1032', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1032', 'chapter_6', 6, 'set', 1032, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1033', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1033', 'chapter_6', 6, 'set', 1033, '', '', '', '', '', 'event_cg_mode', 'false', 's1034', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1034', 'chapter_6', 6, 'scene', 1034, '', '', '', 'bg ch6_snow_village_bridge', '', '', '', 's1035', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1035', 'chapter_6', 6, 'sprite', 1035, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's1036', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1036', 'chapter_6', 6, 'narration', 1036, '', '', '他们漫步在雪中，像是走进了克劳德·莫奈的油画里。', '', '', '', '', 's1037', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1037', 'chapter_6', 6, 'narration', 1037, '', '', '映入眼帘的皆是难以忘怀的特别景致：厚厚的积雪覆盖在房顶之上，十几米高树像是盛开的一朵巨大白花。', '', '', '', '', 's1038', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1038', 'chapter_6', 6, 'narration', 1038, '', '', '云朵丝丝缕缕，金色的阳光照向残破的木桥、孤零零的树墩，远处的炊烟冉冉而上。', '', '', '', '', 's1039', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1039', 'chapter_6', 6, 'narration', 1039, '', '', '看着不紧不慢的人影，一动不动的红色信箱，顾天鹏的身心也完全放松下来。', '', '', '', '', 's1040', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1040', 'chapter_6', 6, 'narration', 1040, '', '', '似乎不知不觉间，他远行的目的就已经达到了。', '', '', '', '', 's1041', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1041', 'chapter_6', 6, 'narration', 1041, '', '', '倘若天气更好些，又正好有阵暖暖的微风吹过，这种感觉便会更加清晰了。', '', '', '', '', 's1042', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1042', 'chapter_6', 6, 'set', 1042, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1043', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1043', 'chapter_6', 6, 'set', 1043, '', '', '', '', '', 'event_cg_mode', 'true', 's1044', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1044', 'chapter_6', 6, 'scene', 1044, '', '', '', 'bg ch6_soba_shop', '', '', '', 's1045', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1045', 'chapter_6', 6, 'narration', 1045, '', '', '中午的时候，他们走进那家旅行攻略提到过的店里，一起体验了一次手打荞麦面。', '', '', '', '', 's1046', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1046', 'chapter_6', 6, 'narration', 1046, '', '', '到了下午，他们又从温泉旅馆出发，乘上价格低廉的公交车，去草莓村吃了“越后姬”。', '', '', '', '', 's1047', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1047', 'chapter_6', 6, 'set', 1047, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1048', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1048', 'chapter_6', 6, 'set', 1048, '', '', '', '', '', 'event_cg_mode', 'false', 's1049', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1049', 'chapter_6', 6, 'scene', 1049, '', '', '', 'bg ch6_strawberry_greenhouse', '', '', '', 's1050', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1050', 'chapter_6', 6, 'sprite', 1050, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1051', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1051', 'chapter_6', 6, 'dialogue', 1051, 'ai', '星野爱', '哦~好吃！', '', '', '', '', 's1052', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1052', 'chapter_6', 6, 'narration', 1052, '', '', '在草莓村的时候，星野爱由衷地赞叹道。', '', '', '', '', 's1053', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1053', 'chapter_6', 6, 'dialogue', 1053, 'taku', '顾天鹏', '真的很不错，应该没人会不喜欢吃这个吧？', '', '', '', '', 's1054', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1054', 'chapter_6', 6, 'dialogue', 1054, 'ai', '星野爱', '多亏了你的攻略！', '', '', '', '', 's1055', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1055', 'chapter_6', 6, 'dialogue', 1055, 'taku', '顾天鹏', '多亏了卖给我旅行攻略的大叔。', '', '', '', '', 's1056', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1056', 'chapter_6', 6, 'dialogue', 1056, 'ai', '星野爱', '也是！', '', '', '', '', 's1057', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1057', 'chapter_6', 6, 'scene', 1057, '', '', '', 'bg ch6_onsen_street_moon', '', '', '', 's1058', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1058', 'chapter_6', 6, 'sprite', 1058, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's1059', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1059', 'chapter_6', 6, 'narration', 1059, '', '', '转回温泉旅馆，他们提前下了车，六点多的时候，月光皎白凄清。', '', '', '', '', 's1060', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1060', 'chapter_6', 6, 'dialogue', 1060, 'ai', '星野爱', '今天很开心。', '', '', '', '', 's1061', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1061', 'chapter_6', 6, 'narration', 1061, '', '', '月色之下，星野爱的身影融进夜幕里。', '', '', '', '', 's1062', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1062', 'chapter_6', 6, 'dialogue', 1062, 'taku', '顾天鹏', '我也是。', '', '', '', '', 's1063', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1063', 'chapter_6', 6, 'narration', 1063, '', '', '顾天鹏慢慢地跟在她身后。', '', '', '', '', 's1064', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1064', 'chapter_6', 6, 'narration', 1064, '', '', '远处的房屋犹如星星点点，空漠是唯美的克莱因蓝。', '', '', '', '', 's1065', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1065', 'chapter_6', 6, 'dialogue', 1065, 'ai', '星野爱', '明天要去哪好呢？', '', '', '', '', 's1066', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1066', 'chapter_6', 6, 'dialogue', 1066, 'taku', '顾天鹏', '放风筝，滑雪，看麋鹿。', '', '', '', '', 's1067', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1067', 'chapter_6', 6, 'dialogue', 1067, 'ai', '星野爱', '不错嘛。', '', '', '', '', 's1068', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1068', 'chapter_6', 6, 'dialogue', 1068, 'taku', '顾天鹏', '还有很多呢。', '', '', '', '', 's1069', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1069', 'chapter_6', 6, 'dialogue', 1069, 'ai', '星野爱', '全都要玩个遍！', '', '', '', '', 's1070', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1070', 'chapter_6', 6, 'set', 1070, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1071', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1071', 'chapter_6', 6, 'set', 1071, '', '', '', '', '', 'event_cg_mode', 'true', 's1072', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1072', 'chapter_6', 6, 'scene', 1072, '', '', '', 'cg ch6_moonlit_ai', '', '', '', 's1073', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1073', 'chapter_6', 6, 'narration', 1073, '', '', '她开心地大喊一声，窈窕的身影在夜色下绕动、旋转。', '', '', '', '', 's1074', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1074', 'chapter_6', 6, 'narration', 1074, '', '', '这一刻，连月色都相形失色。', '', '', '', '', 's1075', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1075', 'chapter_7', 7, 'set', 1075, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's1076', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1076', 'chapter_7', 7, 'set', 1076, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1077', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1077', 'chapter_7', 7, 'set', 1077, '', '', '', '', '', 'event_cg_mode', 'false', 's1078', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1078', 'chapter_7', 7, 'scene', 1078, '', '', '', 'bg ch7_ryokan_breakfast', '', '', '', 's1079', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1079', 'chapter_7', 7, 'sprite', 1079, '', '', '', '', '[{"image": "heroine winter_surprised", "pos": "heroine_winter_center"}]', '', '', 's1080', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1080', 'chapter_7', 7, 'narration', 1080, '', '', '你比任何人都适合成为偶像', '', '', '', '', 's1081', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1081', 'chapter_7', 7, 'narration', 1081, '', '', '十一月十一日那天，天气晴得温和。', '', '', '', '', 's1082', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1082', 'chapter_7', 7, 'narration', 1082, '', '', '明晃晃的光线从窗户外透进来。', '', '', '', '', 's1083', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1083', 'chapter_7', 7, 'narration', 1083, '', '', '小鸟在树梢上啁啾，又扑腾着翅膀飞走，飞得比山还高。', '', '', '', '', 's1084', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1084', 'chapter_7', 7, 'dialogue', 1084, 'taku', '顾天鹏', '这么早就出门？', '', '', '', '', 's1085', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1085', 'chapter_7', 7, 'dialogue', 1085, 'ai', '星野爱', '稍微锻炼一下。', '', '', '', '', 's1086', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1086', 'chapter_7', 7, 'dialogue', 1086, 'taku', '顾天鹏', '不吃早饭吗？', '', '', '', '', 's1087', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1087', 'chapter_7', 7, 'dialogue', 1087, 'ai', '星野爱', '回来再吃。', '', '', '', '', 's1088', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1088', 'chapter_7', 7, 'narration', 1088, '', '', '柔软的身体横坐在被褥上，星野爱用手支着榻榻米，漂亮的眼睛朝窗外望去。', '', '', '', '', 's1089', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1089', 'chapter_7', 7, 'dialogue', 1089, 'ai', '星野爱', '也是呢，锻炼的好天气！', '', '', '', '', 's1090', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1090', 'chapter_7', 7, 'dialogue', 1090, 'taku', '顾天鹏', '要不要一起？', '', '', '', '', 's1091', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1092', 'chapter_7', 7, 'narration', 1092, '', '', '顾天鹏把这句话说得比玩笑更认真一点。', '', '', '', '', 's1093', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1093', 'chapter_7', 7, 'narration', 1093, '', '', '如果她真的愿意，他大概会放慢速度，陪她在雪地里跑到太阳升起来。', '', '', '', '', 's1094', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1094', 'chapter_7', 7, 'dialogue', 1094, 'ai', '星野爱', '一起？在雪地？', '', '', '', '', 's1095', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1095', 'chapter_7', 7, 'narration', 1095, '', '', '星野爱掀开被角，脚尖刚碰到榻榻米就被冷意劝退。', '', '', '', '', 's1096', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1096', 'chapter_7', 7, 'dialogue', 1096, 'ai', '星野爱', '不行，还是很冷！我就算啦。', '', '', '', '', 's1097', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1097', 'chapter_7', 7, 'dialogue', 1097, 'taku', '顾天鹏', '那我替你把晨跑额度用掉。', '', '', '', '', 's1109', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1098', 'chapter_7', 7, 'narration', 1098, '', '', '顾天鹏自己也知道，这更像一句清晨的寒暄。她不答应，他也不会意外。', '', '', '', '', 's1099', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1099', 'chapter_7', 7, 'dialogue', 1099, 'ai', '星野爱', '一起？在雪地？虽然开了太阳不过应该还是很冷！我就算啦。', '', '', '', '', 's1100', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1100', 'chapter_7', 7, 'narration', 1100, '', '', '她立马抬手拒绝。', '', '', '', '', 's1101', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1101', 'chapter_7', 7, 'narration', 1101, '', '', '顾天鹏也没想她会答应，于是微微点头，星野爱则露出不失温度的笑容。', '', '', '', '', 's1102', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1102', 'chapter_7', 7, 'dialogue', 1102, 'taku', '顾天鹏', '那我尽量摔在显眼的地方咯。', '', '', '', '', 's1103', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1103', 'chapter_7', 7, 'dialogue', 1103, 'ai', '星野爱', '那一定要很显眼才行。', '', '', '', '', 's1104', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1104', 'chapter_7', 7, 'dialogue', 1104, 'taku', '顾天鹏', '第三十三盏路灯之下怎么样？', '', '', '', '', 's1105', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1105', 'chapter_7', 7, 'dialogue', 1105, 'ai', '星野爱', '哈？坏了的那个？一点也不显眼！', '', '', '', '', 's1106', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1106', 'chapter_7', 7, 'dialogue', 1106, 'taku', '顾天鹏', '等路灯全亮了，黑暗的地方反倒显眼了吧。', '', '', '', '', 's1107', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1107', 'chapter_7', 7, 'dialogue', 1107, 'ai', '星野爱', '是哦，好像。', '', '', '', '', 's1108', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1108', 'chapter_7', 7, 'narration', 1108, '', '', '玩笑被玩笑带走，晨跑也只是晨跑。等他真的出门时，清晨的空气里少了一点刚才差点出现的认真。', '', '', '', '', 's1109', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1091', 'chapter_7', 7, 'menu', 1091, '', '', '', '', '', '', '', 's1109', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1109', 'chapter_7', 7, 'dialogue', 1109, 'ai', '星野爱', '雪那么大，注意别脚滑了哦！', '', '', '', '', 's1110', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1110', 'chapter_7', 7, 'narration', 1110, '', '', '他离开之前，星野爱这么对他说。', '', '', '', '', 's1111', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1111', 'chapter_7', 7, 'dialogue', 1111, 'ai', '星野爱', '否则我还得一个人去外面找你，绝对很麻烦。', '', '', '', '', 's1112', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1112', 'chapter_7', 7, 'set', 1112, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1113', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1113', 'chapter_7', 7, 'set', 1113, '', '', '', '', '', 'event_cg_mode', 'false', 's1114', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1114', 'chapter_7', 7, 'scene', 1114, '', '', '', 'bg ch7_snowy_run_road', '', '', '', 's1115', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1115', 'chapter_7', 7, 'narration', 1115, '', '', '五公里的来回，身体完全热了起来。', '', '', '', '', 's1116', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1116', 'chapter_7', 7, 'narration', 1116, '', '', '跑完步，顾天鹏返回旅馆，像昨天一样冲了澡，擦拭身体，换上干净的衣服。', '', '', '', '', 's1117', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1117', 'chapter_7', 7, 'set', 1117, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's1118', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1118', 'chapter_7', 7, 'set', 1118, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1119', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1119', 'chapter_7', 7, 'set', 1119, '', '', '', '', '', 'event_cg_mode', 'false', 's1120', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1120', 'chapter_7', 7, 'scene', 1120, '', '', '', 'bg ch7_ryokan_breakfast', '', '', '', 's1121', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1121', 'chapter_7', 7, 'sprite', 1121, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1122', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1122', 'chapter_7', 7, 'narration', 1122, '', '', '他走进提供早餐的地方，头上戴着兔子发卡的星野爱坐在榻榻米上向他招手。', '', '', '', '', 's1123', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1123', 'chapter_7', 7, 'dialogue', 1123, 'ai', '星野爱', '顾天鹏，这边！', '', '', '', '', 's1124', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1124', 'chapter_7', 7, 'narration', 1124, '', '', '他点头，星野爱往旁边挪了一个屁股的空位，用手在上面拍了拍，示意他坐下来。', '', '', '', '', 's1125', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1125', 'chapter_7', 7, 'narration', 1125, '', '', '他走过去盘腿坐下。', '', '', '', '', 's1126', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1126', 'chapter_7', 7, 'dialogue', 1126, 'ai', '星野爱', '我看看……面包、蔬菜沙拉、牛奶、味噌汤，还有香蕉，苹果，橘子拿了两个，够不够吃？', '', '', '', '', 's1127', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1127', 'chapter_7', 7, 'dialogue', 1127, 'taku', '顾天鹏', '太多了吧？', '', '', '', '', 's1128', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1128', 'chapter_7', 7, 'narration', 1128, '', '', '顾天鹏望着桌上的那些东西。', '', '', '', '', 's1129', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1129', 'chapter_7', 7, 'dialogue', 1129, 'ai', '星野爱', '不多不多。', '', '', '', '', 's1130', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1130', 'chapter_7', 7, 'narration', 1130, '', '', '星野爱笑着拍了两下他的肩膀。', '', '', '', '', 's1131', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1131', 'chapter_7', 7, 'dialogue', 1131, 'ai', '星野爱', '刚刚锻炼完，又还是十七岁，不多吃点怎么长身体？', '', '', '', '', 's1132', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1132', 'chapter_7', 7, 'dialogue', 1132, 'taku', '顾天鹏', '都想那么周到了。', '', '', '', '', 's1133', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1133', 'chapter_7', 7, 'narration', 1133, '', '', '顾天鹏叹气说。', '', '', '', '', 's1134', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1134', 'chapter_7', 7, 'dialogue', 1134, 'taku', '顾天鹏', '唯独没想到有可能会浪费？', '', '', '', '', 's1135', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1135', 'chapter_7', 7, 'dialogue', 1135, 'ai', '星野爱', '没关系没关系，吃不完的就全交给我好了，我帮忙解决！', '', '', '', '', 's1136', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1136', 'chapter_7', 7, 'narration', 1136, '', '', '顾天鹏看向她，她只是好看的用微笑回应。', '', '', '', '', 's1137', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1137', 'chapter_7', 7, 'narration', 1137, '', '', '那笑容挥之不去，恬静的脸颊活像一道淡淡的虚影。', '', '', '', '', 's1138', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1138', 'chapter_7', 7, 'narration', 1138, '', '', '顾天鹏有种恍惚的错觉：仿佛那笑容要在时间上刻下鲜明的痕迹一样。', '', '', '', '', 's1139', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1139', 'chapter_7', 7, 'set', 1139, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1140', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1140', 'chapter_7', 7, 'set', 1140, '', '', '', '', '', 'event_cg_mode', 'false', 's1141', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1141', 'chapter_7', 7, 'scene', 1141, '', '', '', 'bg ch7_cafe', '', '', '', 's1142', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1142', 'chapter_7', 7, 'narration', 1142, '', '', '直到中午，阳光更灿烂了，树叶嫩绿，鸟叫叽喳，几处飘着炊烟。', '', '', '', '', 's1143', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1143', 'chapter_7', 7, 'narration', 1143, '', '', '他们吃完午饭，又去到附近的咖啡屋要了两杯热咖啡。', '', '', '', '', 's1144', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1144', 'chapter_7', 7, 'set', 1144, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1145', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1145', 'chapter_7', 7, 'set', 1145, '', '', '', '', '', 'event_cg_mode', 'false', 's1146', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1146', 'chapter_7', 7, 'scene', 1146, '', '', '', 'bg ch7_cafe', '', '', '', 's1147', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1147', 'chapter_7', 7, 'sprite', 1147, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's1148', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1148', 'chapter_7', 7, 'narration', 1148, '', '', '侍应生是位年轻的女子，年龄大概也就二十岁上下。', '', '', '', '', 's1149', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1149', 'chapter_7', 7, 'narration', 1149, '', '', '她不紧不慢地将茶托放低，把两杯热咖啡取下来。', '', '', '', '', 's1150', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1150', 'chapter_7', 7, 'dialogue', 1150, 'waitress', '侍应生', '需要加糖吗？', '', '', '', '', 's1151', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1151', 'chapter_7', 7, 'narration', 1151, '', '', '顾天鹏用眼神询问星野爱。', '', '', '', '', 's1152', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1152', 'chapter_7', 7, 'dialogue', 1152, 'ai', '星野爱', '要的！', '', '', '', '', 's1153', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1153', 'chapter_7', 7, 'dialogue', 1153, 'taku', '顾天鹏', '麻烦了。', '', '', '', '', 's1154', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1154', 'chapter_7', 7, 'narration', 1154, '', '', '顾天鹏对侍应生点头。', '', '', '', '', 's1155', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1155', 'chapter_7', 7, 'narration', 1155, '', '', '那侍应生点头，白炽灯下的小脸有些泛红，估计难得看到像顾天鹏这种长相绝佳的少年。', '', '', '', '', 's1156', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1156', 'chapter_7', 7, 'narration', 1156, '', '', '等砂糖、方糖之类的东西拿上来，星野爱道了声谢谢，顾天鹏也是。', '', '', '', '', 's1157', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1157', 'chapter_7', 7, 'narration', 1157, '', '', '侍应生离开，顾天鹏把砂糖加进咖啡搅拌，然后一点点地呷了几口。', '', '', '', '', 's1158', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1158', 'chapter_7', 7, 'narration', 1158, '', '', '星野爱则对着杯面上的拉花观察一会儿，对着冒出来的白烟轻轻吹气。', '', '', '', '', 's1159', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1159', 'chapter_7', 7, 'dialogue', 1159, 'ai', '星野爱', '哦！拍照拍照！', '', '', '', '', 's1160', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1160', 'chapter_7', 7, 'set', 1160, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1161', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1161', 'chapter_7', 7, 'set', 1161, '', '', '', '', '', 'event_cg_mode', 'false', 's1162', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1162', 'chapter_7', 7, 'scene', 1162, '', '', '', 'bg ch7_cafe', '', '', '', 's1163', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1163', 'chapter_7', 7, 'sprite', 1163, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1164', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1164', 'chapter_7', 7, 'narration', 1164, '', '', '这个时候，店里放起歌来，播的是 Elisa 的《Eppure Sentire》。', '', '', '', '', 's1165', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1165', 'chapter_7', 7, 'narration', 1165, '', '', '那音质听着不像是用现代的电子设备播放的，顾天鹏听了一会儿，感觉有点像唱片机。', '', '', '', '', 's1166', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1166', 'chapter_7', 7, 'narration', 1166, '', '', '他一边听歌一边啜口咖啡，面前的星野爱用手机咔嚓咔嚓连照三四张照片。', '', '', '', '', 's1167', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1167', 'chapter_7', 7, 'dialogue', 1167, 'ai', '星野爱', '完美！', '', '', '', '', 's1168', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1168', 'chapter_7', 7, 'dialogue', 1168, 'taku', '顾天鹏', '咖啡都要凉了。', '', '', '', '', 's1169', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1169', 'chapter_7', 7, 'dialogue', 1169, 'ai', '星野爱', '咦，不会吧。', '', '', '', '', 's1170', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1170', 'chapter_7', 7, 'narration', 1170, '', '', '她把手机摆在桌面，榉木桌一下子闯进镜头里，画面黑漆漆一片。', '', '', '', '', 's1171', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1171', 'chapter_7', 7, 'narration', 1171, '', '', '左下角刚拍好的那张照片有两杯咖啡，水仙花竖在一边。', '', '', '', '', 's1172', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1172', 'chapter_7', 7, 'narration', 1172, '', '', '她捧着杯子抿了一口，然后惊喜地抬起头，咽下咖啡。', '', '', '', '', 's1173', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1173', 'chapter_7', 7, 'dialogue', 1173, 'ai', '星野爱', '热着呢，而且味道很不错！', '', '', '', '', 's1174', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1174', 'chapter_7', 7, 'dialogue', 1174, 'taku', '顾天鹏', '我也挺喜欢的。', '', '', '', '', 's1175', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1175', 'chapter_7', 7, 'narration', 1175, '', '', '那天刻下的第二个笑容，顾天鹏想。', '', '', '', '', 's1176', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1176', 'chapter_7', 7, 'set', 1176, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1177', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1177', 'chapter_7', 7, 'set', 1177, '', '', '', '', '', 'event_cg_mode', 'false', 's1178', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1178', 'chapter_7', 7, 'scene', 1178, '', '', '', 'bg ch7_cafe_street', '', '', '', 's1179', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1179', 'chapter_7', 7, 'sprite', 1179, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1180', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1180', 'chapter_7', 7, 'narration', 1180, '', '', '从咖啡屋离开，对面是一家酒店，左面邻着烤肉店，右边是便利店，再边上则是转角。', '', '', '', '', 's1181', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1181', 'chapter_7', 7, 'narration', 1181, '', '', '白色的电线杆立在自动贩卖机前面，橘黄色的垃圾桶上有雪悄悄融化。', '', '', '', '', 's1182', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1182', 'chapter_7', 7, 'narration', 1182, '', '', '身后传来的歌曲变化到蒸汽波风格，两人在门口商量。', '', '', '', '', 's1183', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1183', 'chapter_7', 7, 'dialogue', 1183, 'taku', '顾天鹏', '放风筝？', '', '', '', '', 's1184', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1184', 'chapter_7', 7, 'dialogue', 1184, 'ai', '星野爱', '现在好像没什么风啊。', '', '', '', '', 's1185', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1185', 'chapter_7', 7, 'narration', 1185, '', '', '星野爱托起一只手，眼睛望向蓝天，像是在感应风的方向。', '', '', '', '', 's1186', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1186', 'chapter_7', 7, 'dialogue', 1186, 'taku', '顾天鹏', '那就去滑雪好了。', '', '', '', '', 's1187', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1187', 'chapter_7', 7, 'narration', 1187, '', '', '她摸着下巴思索着什么，随后跳到两个台阶之下，背过手，面朝顾天鹏，上半身稍稍前倾。', '', '', '', '', 's1188', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1188', 'chapter_7', 7, 'dialogue', 1188, 'ai', '星野爱', '去看麋鹿吧！', '', '', '', '', 's1189', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1189', 'chapter_7', 7, 'dialogue', 1189, 'taku', '顾天鹏', '现在？', '', '', '', '', 's1190', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1190', 'chapter_7', 7, 'dialogue', 1190, 'ai', '星野爱', '嗯！', '', '', '', '', 's1191', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1191', 'chapter_7', 7, 'dialogue', 1191, 'taku', '顾天鹏', '好。', '', '', '', '', 's1192', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1192', 'chapter_7', 7, 'set', 1192, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1193', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1193', 'chapter_7', 7, 'set', 1193, '', '', '', '', '', 'event_cg_mode', 'false', 's1194', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1194', 'chapter_7', 7, 'scene', 1194, '', '', '', 'bg ch7_deer_snowfield', '', '', '', 's1195', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1195', 'chapter_7', 7, 'narration', 1195, '', '', '于是他们去看了麋鹿，在一个超大超大的雪场。', '', '', '', '', 's1196', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1196', 'chapter_7', 7, 'narration', 1196, '', '', '那里连树都很少，阳光毫无遮拦地扑向大地，头上的云朵竟一片也没有。', '', '', '', '', 's1197', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1197', 'chapter_7', 7, 'narration', 1197, '', '', '远远望去时，棕褐色的干草从雪地里刺出来，像极了自然生长在那里的麋鹿角。', '', '', '', '', 's1198', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1198', 'chapter_7', 7, 'narration', 1198, '', '', '他们坐上观光车，工作人员为他们介绍起麋鹿的长相、种类，如何区分麋鹿的性别，又说了麋鹿的迁徙路线。', '', '', '', '', 's1199', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1199', 'chapter_7', 7, 'dialogue', 1199, 'snow_staff', '工作人员', '每年都要迁徙，脖子上的项圈是用来帮助观察和研究的……', '', '', '', '', 's1200', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1200', 'chapter_7', 7, 'set', 1200, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1201', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1201', 'chapter_7', 7, 'set', 1201, '', '', '', '', '', 'event_cg_mode', 'false', 's1202', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1202', 'chapter_7', 7, 'scene', 1202, '', '', '', 'bg ch7_souvenir_shop', '', '', '', 's1203', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1203', 'chapter_7', 7, 'sprite', 1203, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's1204', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1204', 'chapter_7', 7, 'narration', 1204, '', '', '下午四点，他们从雪场离开，公交车坐了三站便下。', '', '', '', '', 's1205', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1205', 'chapter_7', 7, 'narration', 1205, '', '', '路过一条没什么雪的大路时，星野爱指着附近的一家小店。', '', '', '', '', 's1206', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1206', 'chapter_7', 7, 'dialogue', 1206, 'ai', '星野爱', '这里有纪念品卖。', '', '', '', '', 's1207', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1207', 'chapter_7', 7, 'dialogue', 1207, 'taku', '顾天鹏', '纪念品？', '', '', '', '', 's1208', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1208', 'chapter_7', 7, 'dialogue', 1208, 'ai', '星野爱', '折扇，手帕之类的。', '', '', '', '', 's1209', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1209', 'chapter_7', 7, 'narration', 1209, '', '', '她扯着套在大拇指上的手套。', '', '', '', '', 's1210', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1210', 'chapter_7', 7, 'narration', 1210, '', '', '之后两人走进店里，收银员亲切地说了一声欢迎光临，他们开始挑选纪念品。', '', '', '', '', 's1211', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1211', 'chapter_7', 7, 'narration', 1211, '', '', '星野爱买了一个 Sankyo 的胡桃木质音乐盒，又买了一张印着兔子图案的粉色手帕。', '', '', '', '', 's1212', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1212', 'chapter_7', 7, 'narration', 1212, '', '', '从店里出来，她看到顾天鹏两手空空，一副对什么都不怎么感兴趣的样子。', '', '', '', '', 's1213', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1213', 'chapter_7', 7, 'narration', 1213, '', '', '她止住脚步，把手里的东西塞到顾天鹏手中。', '', '', '', '', 's1214', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1214', 'chapter_7', 7, 'dialogue', 1214, 'ai', '星野爱', '帮我拿一下，顾天鹏。', '', '', '', '', 's1215', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1215', 'chapter_7', 7, 'dialogue', 1215, 'taku', '顾天鹏', '东西忘拿了？', '', '', '', '', 's1216', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1216', 'chapter_7', 7, 'dialogue', 1216, 'ai', '星野爱', '一会儿就好！', '', '', '', '', 's1217', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1217', 'chapter_7', 7, 'narration', 1217, '', '', '她说完便折回店里，再次出来的时候，手里多了一个用来装纪念品的米白色纸袋。', '', '', '', '', 's1218', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1218', 'chapter_7', 7, 'dialogue', 1218, 'ai', '星野爱', '给。', '', '', '', '', 's1219', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1219', 'chapter_7', 7, 'narration', 1219, '', '', '她将挂在手指上的纸袋递到顾天鹏胸前。', '', '', '', '', 's1220', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1220', 'chapter_7', 7, 'narration', 1220, '', '', '顾天鹏一边把替她保管的东西还给她，一边接过纸袋，用眼神询问：什么东西？', '', '', '', '', 's1221', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1221', 'chapter_7', 7, 'dialogue', 1221, 'ai', '星野爱', '围巾。', '', '', '', '', 's1222', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1222', 'chapter_7', 7, 'dialogue', 1222, 'taku', '顾天鹏', '围巾？', '', '', '', '', 's1223', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1223', 'chapter_7', 7, 'dialogue', 1223, 'ai', '星野爱', '图案是男孩子用也不会害羞的，放心好啦！', '', '', '', '', 's1224', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1224', 'chapter_7', 7, 'dialogue', 1224, 'taku', '顾天鹏', '我倒不是想问这个……', '', '', '', '', 's1225', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1225', 'chapter_7', 7, 'dialogue', 1225, 'ai', '星野爱', '就当是谢礼收下，可以吧？', '', '', '', '', 's1226', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1226', 'chapter_7', 7, 'narration', 1226, '', '', '说完，也不等顾天鹏回应，星野爱已经背过身去。', '', '', '', '', 's1227', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1227', 'chapter_7', 7, 'narration', 1227, '', '', '她高举胳膊伸了个懒腰，露出短款棉袄下的白皙腰肢。', '', '', '', '', 's1228', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1228', 'chapter_7', 7, 'narration', 1228, '', '', '顾天鹏望着她的背影，她则用慵懒的声音呻吟一声。', '', '', '', '', 's1229', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1229', 'chapter_7', 7, 'dialogue', 1229, 'ai', '星野爱', '今天也很开心呢。', '', '', '', '', 's1230', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1230', 'chapter_7', 7, 'dialogue', 1230, 'taku', '顾天鹏', '谢谢，那我收下了。', '', '', '', '', 's1231', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1231', 'chapter_7', 7, 'set', 1231, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1232', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1232', 'chapter_7', 7, 'set', 1232, '', '', '', '', '', 'event_cg_mode', 'false', 's1233', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1233', 'chapter_7', 7, 'scene', 1233, '', '', '', 'bg ch7_souvenir_shop', '', '', '', 's1234', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1234', 'chapter_7', 7, 'sprite', 1234, '', '', '', '', '[{"image": "heroine winter_shy", "pos": "heroine_winter_center"}]', '', '', 's1235', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1235', 'chapter_7', 7, 'narration', 1235, '', '', '黄昏的那阵风吹的悠悠然，将星野爱的围巾和长发吹到下沉的落日里。', '', '', '', '', 's1236', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1236', 'chapter_7', 7, 'narration', 1236, '', '', '夕晖映照到她迷人的侧脸上，远方的山麓笼罩着淡淡的光影。', '', '', '', '', 's1237', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1237', 'chapter_7', 7, 'narration', 1237, '', '', '往后的时间，他们折回旅馆。', '', '', '', '', 's1238', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1238', 'chapter_7', 7, 'narration', 1238, '', '', '黑暗一点点吞噬了山脚，眼望远方，山巅却变得愈发清晰。', '', '', '', '', 's1239', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1239', 'chapter_7', 7, 'narration', 1239, '', '', '直到道路旁的灯光亮起，限速牌的标志折射着类似金属的白光。', '', '', '', '', 's1240', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1240', 'chapter_7', 7, 'narration', 1240, '', '', '有人骑着越野自行车从马路经过，车身是黑还是红，教人根本分不清了。', '', '', '', '', 's1241', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1241', 'chapter_7', 7, 'narration', 1241, '', '', '走在路上的时候，顾天鹏总感觉天空都是冰凉而透明的。', '', '', '', '', 's1242', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1242', 'chapter_7', 7, 'set', 1242, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1243', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1243', 'chapter_7', 7, 'set', 1243, '', '', '', '', '', 'event_cg_mode', 'false', 's1244', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1244', 'chapter_7', 7, 'scene', 1244, '', '', '', 'bg ch7_rainy_ryokan_room', '', '', '', 's1245', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1245', 'chapter_7', 7, 'narration', 1245, '', '', '到越后汤泽的第四天，十一月十二日。', '', '', '', '', 's1246', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1246', 'chapter_7', 7, 'narration', 1246, '', '', '那一天，白天下了些小雨，中午的时候大了一点，下午却突然停了下来。', '', '', '', '', 's1247', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1247', 'chapter_7', 7, 'narration', 1247, '', '', '透过窗户向外看，天空阴沉沉一片，云里好像搅拌了混凝土一样。', '', '', '', '', 's1248', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1248', 'chapter_7', 7, 'narration', 1248, '', '', '傍晚的时候，一道不可思议的光线仿佛从云端劈下来似的。', '', '', '', '', 's1249', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1249', 'chapter_7', 7, 'narration', 1249, '', '', '尽管见不到太阳，但顾天鹏想不到比拨云见日更加合适的词汇来形容了。', '', '', '', '', 's1250', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1250', 'chapter_7', 7, 'narration', 1250, '', '', '那天夜里，没有风，没有雨，雪也没飘落一颗。', '', '', '', '', 's1251', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1251', 'chapter_7', 7, 'narration', 1251, '', '', '听旅馆的几个女孩子聊起，某个私塾的轻音部学生要来附近登台演出。', '', '', '', '', 's1252', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1252', 'chapter_7', 7, 'narration', 1252, '', '', '因为白天没怎么出门而郁闷的星野爱，就向其中一个女孩子仔细打听了一下，之后便拉着顾天鹏一起过去看表演。', '', '', '', '', 's1253', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1253', 'chapter_7', 7, 'set', 1253, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1254', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1254', 'chapter_7', 7, 'set', 1254, '', '', '', '', '', 'event_cg_mode', 'false', 's1255', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1255', 'chapter_7', 7, 'scene', 1255, '', '', '', 'bg ch7_student_stage_night', '', '', '', 's1256', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1256', 'chapter_7', 7, 'sprite', 1256, '', '', '', '', '[{"image": "heroine winter_surprised", "pos": "heroine_winter_center"}]', '', '', 's1257', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1257', 'chapter_7', 7, 'dialogue', 1257, 'ai', '星野爱', '没开始吧？', '', '', '', '', 's1258', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1258', 'chapter_7', 7, 'dialogue', 1258, 'taku', '顾天鹏', '看样子没开始。', '', '', '', '', 's1259', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1259', 'chapter_7', 7, 'dialogue', 1259, 'ai', '星野爱', '太好了！', '', '', '', '', 's1260', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1260', 'chapter_7', 7, 'narration', 1260, '', '', '到了目的地的时候，由于跑得太急，星野爱这才呼出一口气。', '', '', '', '', 's1261', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1261', 'chapter_7', 7, 'narration', 1261, '', '', '附近的空地，有人把积雪扫去，在中间搭了木柴，点燃亮腾腾的篝火。', '', '', '', '', 's1262', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1262', 'chapter_7', 7, 'narration', 1262, '', '', '那群人又在后面立了块几米高的桦木板，盖上红幕，搭了平台和楼梯，造出一个不大不小、但却有模有样的舞台。', '', '', '', '', 's1263', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1263', 'chapter_7', 7, 'narration', 1263, '', '', '凭借可爱的相貌、甜美的笑容，星野爱一路道谢，拽着顾天鹏的手腕一直挤到第一排的位置。', '', '', '', '', 's1264', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1264', 'chapter_7', 7, 'set', 1264, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1265', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1265', 'chapter_7', 7, 'set', 1265, '', '', '', '', '', 'event_cg_mode', 'false', 's1266', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1266', 'chapter_7', 7, 'scene', 1266, '', '', '', 'bg ch7_band_soundcheck', '', '', '', 's1267', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1267', 'chapter_7', 7, 'sprite', 1267, '', '', '', '', '[{"image": "band_guitarist", "pos": "band_guitarist_stage"}]', '', '', 's1268', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1268', 'chapter_7', 7, 'sprite', 1268, '', '', '', '', '[{"image": "band_bassist", "pos": "band_bassist_stage"}]', '', '', 's1269', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1269', 'chapter_7', 7, 'sprite', 1269, '', '', '', '', '[{"image": "band_keyboardist", "pos": "band_keyboardist_stage"}]', '', '', 's1270', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1270', 'chapter_7', 7, 'sprite', 1270, '', '', '', '', '[{"image": "band_drummer", "pos": "band_drummer_stage"}]', '', '', 's1271', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1271', 'chapter_7', 7, 'narration', 1271, '', '', '过了一会儿，电吉他、架子鼓、贝斯、键盘，所有乐器通通就绪，接着是试音，然后试音结束。', '', '', '', '', 's1272', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1272', 'chapter_7', 7, 'narration', 1272, '', '', '众人望向台上，星野爱也紧盯着前方，几个个子不高的少女从右边楼梯上来。', '', '', '', '', 's1273', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1273', 'chapter_7', 7, 'narration', 1273, '', '', '当所有人都把注意力放在聚光灯之下的时候，唯独顾天鹏觑了一眼星野爱的侧脸。', '', '', '', '', 's1274', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1274', 'chapter_7', 7, 'narration', 1274, '', '', '那时，舞台的灯光照在她的脸颊，照上她精致的鼻尖。', '', '', '', '', 's1275', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1275', 'chapter_7', 7, 'narration', 1275, '', '', '她的双眸仿佛成了世间最亮的事物。', '', '', '', '', 's1276', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1276', 'chapter_7', 7, 'narration', 1276, '', '', '不需要任何妆容，她就已经是如此适合舞台的聚光灯了。', '', '', '', '', 's1277', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1277', 'chapter_7', 7, 'narration', 1277, '', '', '那是一幅怎样的画面，顾天鹏想了很久，但依旧找不到贴切的形容词。', '', '', '', '', 's1278', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1278', 'chapter_7', 7, 'narration', 1278, '', '', '呼之欲出的是一句话：', '', '', '', '', 's1279', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1279', 'chapter_7', 7, 'narration', 1279, '', '', '这位名叫星野爱的少女，就像是一个天生的偶像一样。', '', '', '', '', 's1280', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1280', 'chapter_7', 7, 'sprite', 1280, '', '', '', '', '[{"hide": "band_guitarist"}]', '', '', 's1281', '');
