INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1290', 'chapter_7', 7, 'sprite', 1290, '', '', '', '', '[{"image": "band_drummer", "pos": "band_drummer_stage"}]', '', '', 's1291', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1291', 'chapter_7', 7, 'narration', 1291, '', '', '他别过视线，舞台上，几个轻音少女互相对视一眼。', '', '', '', '', 's1292', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1292', 'chapter_7', 7, 'narration', 1292, '', '', '演出开始。', '', '', '', '', 's1293', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1293', 'chapter_7', 7, 'narration', 1293, '', '', '以架子鼓手互击鼓槌，喊出指令为先：', '', '', '', '', 's1294', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1294', 'chapter_7', 7, 'dialogue', 1294, 'band_drummer_girl', '鼓手少女', 'one! two! three! four! one! two! three!', '', '', '', '', 's1295', '');
