INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1304', 'chapter_7', 7, 'sprite', 1304, '', '', '', '', '[{"image": "band_keyboardist", "pos": "band_keyboardist_stage"}]', '', '', 's1305', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1305', 'chapter_7', 7, 'sprite', 1305, '', '', '', '', '[{"image": "band_drummer", "pos": "band_drummer_stage"}]', '', '', 's1306', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1306', 'chapter_7', 7, 'narration', 1306, '', '', '电吉他声紧随其后。', '', '', '', '', 's1307', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1307', 'chapter_7', 7, 'narration', 1307, '', '', '身兼电吉他手的褐色短发少女负责指挥，作为贝斯手的黑色长发少女则用快速的击掌声来打节奏。', '', '', '', '', 's1308', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1308', 'chapter_7', 7, 'narration', 1308, '', '', '几秒的前奏之后，两名少女同时用上手里的乐器开始表演，键盘手也几乎是同一时间开始演奏。', '', '', '', '', 's1309', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1309', 'chapter_7', 7, 'narration', 1309, '', '', '乐器声，主唱声，赞美声，应援声，心跳声，掌声。', '', '', '', '', 's1310', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1310', 'chapter_7', 7, 'narration', 1310, '', '', '夜晚的越后汤泽像是被赋予了无穷的生命力一般。篝火燃烧向黑色的天幕。', '', '', '', '', 's1311', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1311', 'chapter_7', 7, 'narration', 1311, '', '', '一曲终了，第二首歌不多时便接上，然后是第三曲。', '', '', '', '', 's1312', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1312', 'chapter_7', 7, 'narration', 1312, '', '', '直到演出落幕。', '', '', '', '', 's1313', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1313', 'chapter_7', 7, 'dialogue', 1313, 'band_bassist_girl', '贝斯手少女', '谢谢大家！', '', '', '', '', 's1314', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1314', 'chapter_7', 7, 'dialogue', 1314, 'audience', '观众', 'K-ON！！！！', '', '', '', '', 's1315', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1315', 'chapter_7', 7, 'dialogue', 1315, 'audience', '观众', '最喜欢了！！！', '', '', '', '', 's1316', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1316', 'chapter_7', 7, 'dialogue', 1316, 'audience', '观众', '喔！！', '', '', '', '', 's1317', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1317', 'chapter_7', 7, 'dialogue', 1317, 'audience', '观众', '最好的轻音！！', '', '', '', '', 's1318', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1318', 'chapter_7', 7, 'narration', 1318, '', '', '所有的声音，唯独心跳和掌声经久不息。', '', '', '', '', 's1319', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1319', 'chapter_7', 7, 'narration', 1319, '', '', '离场之前，贝斯手兼主唱的黑色长发少女对台下的观众微微鞠躬。', '', '', '', '', 's1320', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1320', 'chapter_7', 7, 'narration', 1320, '', '', '正当少女要迈开步子下台时，贝斯连接音箱的插线忽然将她绊倒。', '', '', '', '', 's1321', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1321', 'chapter_7', 7, 'dialogue', 1321, 'band_bassist_girl', '贝斯手少女', '啊？', '', '', '', '', 's1322', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1322', 'chapter_7', 7, 'dialogue', 1322, 'audience', '观众', '诶？', '', '', '', '', 's1323', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1323', 'chapter_7', 7, 'narration', 1323, '', '', '几个队友望着她，台下的观众全都愣在原地。', '', '', '', '', 's1324', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1324', 'chapter_7', 7, 'narration', 1324, '', '', '随后是一声盖过心跳的尖叫。', '', '', '', '', 's1325', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1325', 'chapter_7', 7, 'narration', 1325, '', '', '就连十几米外的松树都难以幸免，树梢上覆盖的积雪啪地一声落到地面。', '', '', '', '', 's1326', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1326', 'chapter_7', 7, 'sprite', 1326, '', '', '', '', '[{"hide": "band_guitarist"}]', '', '', 's1327', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1327', 'chapter_7', 7, 'sprite', 1327, '', '', '', '', '[{"hide": "band_bassist"}]', '', '', 's1328', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1328', 'chapter_7', 7, 'sprite', 1328, '', '', '', '', '[{"hide": "band_keyboardist"}]', '', '', 's1329', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1329', 'chapter_7', 7, 'sprite', 1329, '', '', '', '', '[{"hide": "band_drummer"}]', '', '', 's1330', '');
