INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1331', 'chapter_7', 7, 'set', 1331, '', '', '', '', '', 'event_cg_mode', 'false', 's1332', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1332', 'chapter_7', 7, 'scene', 1332, '', '', '', 'bg ch7_band_aftermath', '', '', '', 's1333', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1333', 'chapter_7', 7, 'narration', 1333, '', '', '九点四十的时候，表演正式结束，大家帮忙收整舞台，篝火用雪水熄灭。', '', '', '', '', 's1334', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1334', 'chapter_7', 7, 'narration', 1334, '', '', '返回旅馆的路上，人们聊起“蓝白碗”的事情，交谈氛围和谐融洽，大家都有说有笑的。', '', '', '', '', 's1335', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1335', 'chapter_7', 7, 'narration', 1335, '', '', '如同深海般的静谧夜色下，一头蓝紫色长发的星野爱落在人群后面，顾天鹏则跟在她旁边，手插进衣服里。', '', '', '', '', 's1336', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1336', 'chapter_7', 7, 'narration', 1336, '', '', '两人从大路走进小道，踏入雪地，路过村庄，村庄的家家户户亮着微黄的灯光。', '', '', '', '', 's1337', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1337', 'chapter_7', 7, 'narration', 1337, '', '', '他们就这样慢慢地把脚踩进雪里，像是要试探雪的深浅似的，留下一路的脚印。', '', '', '', '', 's1338', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1338', 'chapter_7', 7, 'set', 1338, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1339', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1339', 'chapter_7', 7, 'set', 1339, '', '', '', '', '', 'event_cg_mode', 'false', 's1340', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1340', 'chapter_7', 7, 'scene', 1340, '', '', '', 'bg ch7_village_moon_path', '', '', '', 's1341', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1341', 'chapter_7', 7, 'sprite', 1341, '', '', '', '', '[{"image": "heroine winter_shy", "pos": "heroine_winter_center"}]', '', '', 's1342', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1342', 'chapter_7', 7, 'dialogue', 1342, 'ai', '星野爱', '轻音部吗？', '', '', '', '', 's1343', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1343', 'chapter_7', 7, 'narration', 1343, '', '', '星野爱像是在自言自语一般。', '', '', '', '', 's1344', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1344', 'chapter_7', 7, 'narration', 1344, '', '', '她忽然向前跑了几步，抬起双臂保持平衡，眼睛望着深蓝色的雪地，试图走出一条长长的直线。', '', '', '', '', 's1345', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1345', 'chapter_7', 7, 'narration', 1345, '', '', '结果可想而知，东歪西倒。', '', '', '', '', 's1346', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1346', 'chapter_7', 7, 'dialogue', 1346, 'ai', '星野爱', '她们那样的人，或许才适合成为偶像吧？', '', '', '', '', 's1347', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1347', 'chapter_7', 7, 'narration', 1347, '', '', '她耳语一样地轻声说。', '', '', '', '', 's1348', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1348', 'chapter_7', 7, 'narration', 1348, '', '', '闻言，顾天鹏只是静静地抬眼望向她。', '', '', '', '', 's1349', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1349', 'chapter_7', 7, 'narration', 1349, '', '', '那天夜里，月光拨开重叠的云雾，忽然照在她的背上，把她的身影概括得如此清晰。', '', '', '', '', 's1350', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1350', 'chapter_7', 7, 'narration', 1350, '', '', '顾天鹏险些看得失神。', '', '', '', '', 's1351', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1351', 'chapter_7', 7, 'dialogue', 1351, 'taku', '顾天鹏', '怎么会呢。', '', '', '', '', 's1352', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1352', 'chapter_7', 7, 'dialogue', 1352, 'ai', '星野爱', '观众喜欢她们，她们也喜欢观众，这应该就足够证明了……', '', '', '', '', 's1353', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1353', 'chapter_7', 7, 'narration', 1353, '', '', '星野爱继续向前。', '', '', '', '', 's1354', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1354', 'chapter_7', 7, 'dialogue', 1354, 'taku', '顾天鹏', '喜欢还是不喜欢，光靠看是不行的吧？', '', '', '', '', 's1355', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1355', 'chapter_7', 7, 'dialogue', 1355, 'ai', '星野爱', '嗯……', '', '', '', '', 's1356', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1356', 'chapter_7', 7, 'narration', 1356, '', '', '她仿佛在思索着什么，半天没有回应。', '', '', '', '', 's1357', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1357', 'chapter_7', 7, 'narration', 1357, '', '', '夜色渐浓，所见一派冬日之色，路灯和皓月争相发出光亮。', '', '', '', '', 's1358', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1358', 'chapter_7', 7, 'narration', 1358, '', '', '良久，顾天鹏止步原地，望着蓝得发黑的天际线。', '', '', '', '', 's1359', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1359', 'chapter_7', 7, 'dialogue', 1359, 'taku', '顾天鹏', '我觉得，或许你比任何人都适合成为一名偶像。', '', '', '', '', 's1360', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1360', 'chapter_7', 7, 'narration', 1360, '', '', '在那条歪歪扭扭的直线上延伸的脚印，未到旅店便停了下来。', '', '', '', '', 's1361', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1361', 'chapter_7', 7, 'narration', 1361, '', '', '忽起的凉风吹过星野爱的侧脸。', '', '', '', '', 's1362', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1362', 'chapter_7', 7, 'dialogue', 1362, 'ai', '星野爱', '谢谢你能这么说，顾天鹏。', '', '', '', '', 's1363', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1363', 'chapter_7', 7, 'set', 1363, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1364', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1364', 'chapter_7', 7, 'set', 1364, '', '', '', '', '', 'event_cg_mode', 'false', 's1365', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1365', 'chapter_7', 7, 'scene', 1365, '', '', '', 'bg ch7_village_moon_path', '', '', '', 's1366', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1366', 'chapter_7', 7, 'sprite', 1366, '', '', '', '', '[{"image": "heroine winter_shy", "pos": "heroine_winter_center"}]', '', '', 's1367', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1367', 'chapter_7', 7, 'narration', 1367, '', '', '回过身的时候，少女刘海轻扬，澄澈的眼里闪烁着特别的光点。', '', '', '', '', 's1368', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1368', 'chapter_7', 7, 'dialogue', 1368, 'ai', '星野爱', '我真的，很高兴！', '', '', '', '', 's1369', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1369', 'chapter_7', 7, 'narration', 1369, '', '', '她笑了，大概是那天第三个笑容。', '', '', '', '', 's1370', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1370', 'chapter_7', 7, 'narration', 1370, '', '', '连顾天鹏都忘了：原来前两个笑是在昨天。', '', '', '', '', 's1371', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1371', 'chapter_8', 8, 'set', 1371, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's1372', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1372', 'chapter_8', 8, 'set', 1372, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1373', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1373', 'chapter_8', 8, 'set', 1373, '', '', '', '', '', 'event_cg_mode', 'true', 's1374', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1374', 'chapter_8', 8, 'scene', 1374, '', '', '', 'cg ch8_ryokan_breakfast_wave', '', '', '', 's1375', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1375', 'chapter_8', 8, 'narration', 1375, '', '', '最后一天的风筝', '', '', '', '', 's1376', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1376', 'chapter_8', 8, 'narration', 1376, '', '', '留在越后汤泽的最后一天，温柔的雪飘了整夜。', '', '', '', '', 's1377', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1377', 'chapter_8', 8, 'narration', 1377, '', '', '五点多时雪停下来，山野的树木如同披上了一件白色风衣。', '', '', '', '', 's1378', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1378', 'chapter_8', 8, 'narration', 1378, '', '', '坑坑洼洼的雪地像是被水泥匠仔细补满了一样，饱满得和加满驼绒的棉被无异。', '', '', '', '', 's1379', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1379', 'chapter_8', 8, 'narration', 1379, '', '', '白天，两人在旅馆各吃了一块三明治做早餐。', '', '', '', '', 's1380', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1380', 'chapter_8', 8, 'narration', 1380, '', '', '嘴干的时候，星野爱用吸管喝了瓶草莓味的牛奶，顾天鹏则喝干两杯水。', '', '', '', '', 's1381', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1381', 'chapter_8', 8, 'set', 1381, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1382', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1382', 'chapter_8', 8, 'set', 1382, '', '', '', '', '', 'event_cg_mode', 'false', 's1383', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1383', 'chapter_8', 8, 'scene', 1383, '', '', '', 'bg ch8_cafe', '', '', '', 's1384', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1384', 'chapter_8', 8, 'narration', 1384, '', '', '那之后，他们又到之前去过的咖啡屋喝了一杯咖啡，点了没吃过的甜点。', '', '', '', '', 's1385', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1385', 'chapter_8', 8, 'narration', 1385, '', '', '周围的顾客在轻声交谈，有人点了特产的清酒，玻璃杯碰在一起发出清脆的声音。', '', '', '', '', 's1386', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1386', 'chapter_8', 8, 'narration', 1386, '', '', '同样的座位，桌面上的水仙花叶嫩绿如初。屋内果然比室外要暖和。', '', '', '', '', 's1387', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1387', 'chapter_8', 8, 'set', 1387, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1388', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1388', 'chapter_8', 8, 'set', 1388, '', '', '', '', '', 'event_cg_mode', 'true', 's1389', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1389', 'chapter_8', 8, 'scene', 1389, '', '', '', 'cg ch8_cafe_photo', '', '', '', 's1390', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1390', 'chapter_8', 8, 'dialogue', 1390, 'ai', '星野爱', '拍照拍照！', '', '', '', '', 's1391', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1391', 'chapter_8', 8, 'narration', 1391, '', '', '说着，星野爱已经横着手机对准甜点。', '', '', '', '', 's1392', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1392', 'chapter_8', 8, 'dialogue', 1392, 'taku', '顾天鹏', '等等。', '', '', '', '', 's1393', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1393', 'chapter_8', 8, 'narration', 1393, '', '', '顾天鹏想要靠后一点，防止自己闯进镜头，结果没来得及。', '', '', '', '', 's1394', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1394', 'chapter_8', 8, 'scene', 1394, '', '', '', 'cg ch8_cafe_photo_alt', '', '', '', 's1395', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1395', 'chapter_8', 8, 'dialogue', 1395, 'ai', '星野爱', '咔嚓！', '', '', '', '', 's1396', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1396', 'chapter_8', 8, 'narration', 1396, '', '', '两杯咖啡、用柠檬片装饰的甜点、长长的水仙花、不明不暗的光线，还有少年好看的手指骨节，无一不被留进画面。', '', '', '', '', 's1397', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1397', 'chapter_8', 8, 'set', 1397, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1398', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1398', 'chapter_8', 8, 'set', 1398, '', '', '', '', '', 'event_cg_mode', 'false', 's1399', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1399', 'chapter_8', 8, 'scene', 1399, '', '', '', 'bg ch8_cafe_street', '', '', '', 's1400', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1400', 'chapter_8', 8, 'sprite', 1400, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1401', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1401', 'chapter_8', 8, 'narration', 1401, '', '', '出了咖啡屋，他们在附近的一家冒着白色烟气的店里买了一份章鱼小丸子，加了甜酱。', '', '', '', '', 's1402', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1402', 'chapter_8', 8, 'narration', 1402, '', '', '吃完之后，他们又去自动贩卖机买了两瓶矿泉水，把手里用来装小丸子的纸壳塞进垃圾桶里。', '', '', '', '', 's1403', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1403', 'chapter_8', 8, 'dialogue', 1403, 'ai', '星野爱', '……太好吃了吧。', '', '', '', '', 's1404', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1404', 'chapter_8', 8, 'narration', 1404, '', '', '嘴里的食物还没咽下去，星野爱如同仓鼠一般鼓着腮帮子不清不楚地说。', '', '', '', '', 's1405', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1405', 'chapter_8', 8, 'dialogue', 1405, 'taku', '顾天鹏', '接下来要干嘛？', '', '', '', '', 's1406', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1406', 'chapter_8', 8, 'narration', 1406, '', '', '顾天鹏靠在自动贩卖机边上问她。', '', '', '', '', 's1407', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1408', 'chapter_8', 8, 'narration', 1408, '', '', '顾天鹏把选择权交给她。最后一天这种词听起来有点寂寞，所以更应该由最贪婪的人来填满。', '', '', '', '', 's1409', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1409', 'chapter_8', 8, 'dialogue', 1409, 'ai', '星野爱', '嗯……还有什么没做过？今天全都要玩一遍！', '', '', '', '', 's1410', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1410', 'chapter_8', 8, 'dialogue', 1410, 'taku', '顾天鹏', '当然没问题。', '', '', '', '', 's1411', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1411', 'chapter_8', 8, 'narration', 1411, '', '', '关于接下来要到哪去的问题，星野爱决定边走边想，顾天鹏自然没有意见。', '', '', '', '', 's1419', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1412', 'chapter_8', 8, 'narration', 1412, '', '', '顾天鹏翻了翻攻略，把还没做过的项目在心里排成清单。', '', '', '', '', 's1413', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1413', 'chapter_8', 8, 'narration', 1413, '', '', '既然是最后一天，至少不要留下能被轻易弥补的空白。', '', '', '', '', 's1414', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1414', 'chapter_8', 8, 'dialogue', 1414, 'taku', '顾天鹏', '攻略上还剩风筝、滑雪和神社。按距离排，先去风筝店。', '', '', '', '', 's1415', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1415', 'chapter_8', 8, 'dialogue', 1415, 'ai', '星野爱', '听起来像任务清单。', '', '', '', '', 's1416', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1416', 'chapter_8', 8, 'dialogue', 1416, 'taku', '顾天鹏', '任务清单也可以很快乐。', '', '', '', '', 's1417', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1417', 'chapter_8', 8, 'dialogue', 1417, 'ai', '星野爱', '那就把快乐一项一项打勾！', '', '', '', '', 's1418', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1418', 'chapter_8', 8, 'jump', 1418, '', '', '', '', '', '', '', 's1475', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1407', 'chapter_8', 8, 'menu', 1407, '', '', '', '', '', '', '', 's1419', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1419', 'chapter_8', 8, 'narration', 1419, '', '', '望着眼前的少女，他总觉得对方身上带着一股与生俱来的亲和力。', '', '', '', '', 's1420', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1420', 'chapter_8', 8, 'narration', 1420, '', '', '那种奇妙的感觉，让人想要亲近她，喜欢她。说是吸引力也好。', '', '', '', '', 's1421', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1421', 'chapter_8', 8, 'set', 1421, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1422', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1422', 'chapter_8', 8, 'set', 1422, '', '', '', '', '', 'event_cg_mode', 'true', 's1423', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1423', 'chapter_8', 8, 'scene', 1423, '', '', '', 'cg ch8_takoyaki_ai', '', '', '', 's1424', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1424', 'chapter_8', 8, 'narration', 1424, '', '', '她把最后一颗小丸子塞进嘴里，热气和笑意一同漫出来。', '', '', '', '', 's1425', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1425', 'chapter_8', 8, 'narration', 1425, '', '', '顾天鹏甚至能从那副鼓起腮帮子的表情里，看出她准备把这一天也吃得干干净净。', '', '', '', '', 's1426', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1426', 'chapter_8', 8, 'set', 1426, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1427', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1427', 'chapter_8', 8, 'set', 1427, '', '', '', '', '', 'event_cg_mode', 'false', 's1428', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1428', 'chapter_8', 8, 'scene', 1428, '', '', '', 'bg ch8_takoyaki_vending', '', '', '', 's1429', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1429', 'chapter_8', 8, 'sprite', 1429, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's1430', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1430', 'chapter_8', 8, 'narration', 1430, '', '', '他们绕过拐角，踏上雪道。', '', '', '', '', 's1431', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1431', 'chapter_8', 8, 'narration', 1431, '', '', '夹杂着杉树叶和泥土芬芳的清风从左面呼啸而来，将星野爱的羊绒围巾吹得猎猎作响。', '', '', '', '', 's1432', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1432', 'chapter_8', 8, 'dialogue', 1432, 'taku', '顾天鹏', '起风了。', '', '', '', '', 's1433', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1433', 'chapter_8', 8, 'narration', 1433, '', '', '星野爱用双手按住飘飞的围巾，却只能任由发丝随风而舞。', '', '', '', '', 's1434', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1434', 'chapter_8', 8, 'narration', 1434, '', '', '分不清是洗发水的香气，还是身体自然的香味。', '', '', '', '', 's1435', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1435', 'chapter_8', 8, 'narration', 1435, '', '', '总之，那味道就像秋天，和掠过的风一起悄然远去了。', '', '', '', '', 's1436', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1436', 'chapter_8', 8, 'dialogue', 1436, 'ai', '星野爱', '起风了，那就去放风筝好了！', '', '', '', '', 's1437', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1437', 'chapter_8', 8, 'set', 1437, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1438', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1438', 'chapter_8', 8, 'set', 1438, '', '', '', '', '', 'event_cg_mode', 'false', 's1439', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1439', 'chapter_8', 8, 'scene', 1439, '', '', '', 'bg ch8_kite_field', '', '', '', 's1440', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1440', 'chapter_8', 8, 'sprite', 1440, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1441', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1441', 'chapter_8', 8, 'narration', 1441, '', '', '他们没吃午饭，午休的时候到了距离旅馆三四百米远的空地上。', '', '', '', '', 's1442', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1442', 'chapter_8', 8, 'narration', 1442, '', '', '那里雪不太厚，阳光都被常驻的北风吹斜了身体，树影笔直地在雪中延长。', '', '', '', '', 's1443', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1443', 'chapter_8', 8, 'narration', 1443, '', '', '远远望去，几个七八岁左右的孩子在放长绳盘上的玻璃线，身影在雪地上来回跑动。', '', '', '', '', 's1444', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1444', 'chapter_8', 8, 'narration', 1444, '', '', '天上飞着蝴蝶、鲤鱼、海豚，甚至连哆啦 A 梦都有。', '', '', '', '', 's1445', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1445', 'chapter_8', 8, 'narration', 1445, '', '', '两人看了一会儿，到附近的店里租了一只深海鱼图样的风筝，找了片空地开始放长引线。', '', '', '', '', 's1446', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1446', 'chapter_8', 8, 'dialogue', 1446, 'ai', '星野爱', '这个！就要这条大鱼！', '', '', '', '', 's1447', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1447', 'chapter_8', 8, 'dialogue', 1447, 'taku', '顾天鹏', '看起来确实很适合今天。', '', '', '', '', 's1448', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1448', 'chapter_8', 8, 'set', 1448, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1449', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1449', 'chapter_8', 8, 'set', 1449, '', '', '', '', '', 'event_cg_mode', 'true', 's1450', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1450', 'chapter_8', 8, 'scene', 1450, '', '', '', 'cg ch8_kite_run_ai', '', '', '', 's1451', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1451', 'chapter_8', 8, 'narration', 1451, '', '', '放风筝的过程还算顺利。', '', '', '', '', 's1452', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1452', 'chapter_8', 8, 'narration', 1452, '', '', '随着引线一点点伸出去，深海鱼飞到天边，几乎要和缥缈的云朵绕在一起。', '', '', '', '', 's1453', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1453', 'chapter_8', 8, 'narration', 1453, '', '', '蔚蓝色的天空仿佛化身为东京湾的海面。', '', '', '', '', 's1454', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1454', 'chapter_8', 8, 'narration', 1454, '', '', '当星野爱在下面欢快地奔跑时，深海鱼风筝便游移向前。', '', '', '', '', 's1455', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1455', 'chapter_8', 8, 'narration', 1455, '', '', '跑得累了，她把风筝交给顾天鹏，由顾天鹏带着大鱼继续徘徊在蓝天。', '', '', '', '', 's1456', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1456', 'chapter_8', 8, 'set', 1456, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1457', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1457', 'chapter_8', 8, 'set', 1457, '', '', '', '', '', 'event_cg_mode', 'false', 's1458', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1458', 'chapter_8', 8, 'scene', 1458, '', '', '', 'bg ch8_kite_field', '', '', '', 's1459', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1459', 'chapter_8', 8, 'sprite', 1459, '', '', '', '', '[{"image": "heroine winter_shy", "pos": "heroine_winter_center"}]', '', '', 's1460', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1460', 'chapter_8', 8, 'narration', 1460, '', '', '两人都累了，他们就到小山丘上，将风筝线绑到遮天蔽日的枫树下面，然后一起背靠着树干坐下。', '', '', '', '', 's1461', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1461', 'chapter_8', 8, 'narration', 1461, '', '', '风刮过雪地，压弯了青草。', '', '', '', '', 's1462', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1462', 'chapter_8', 8, 'narration', 1462, '', '', '耳边尽是风声，偶尔会有不知从何而起的犬吠声传来，那声音如同来自另一个世界。', '', '', '', '', 's1463', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1463', 'chapter_8', 8, 'dialogue', 1463, 'ai', '星野爱', '怎么玩都玩不够呢。', '', '', '', '', 's1464', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1464', 'chapter_8', 8, 'narration', 1464, '', '', '枫树下，星野爱抱着膝盖，望向一缕飘动的云彩。', '', '', '', '', 's1465', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1465', 'chapter_8', 8, 'dialogue', 1465, 'taku', '顾天鹏', '那么多事情，如果每件都想做一遍，时间好像突然就紧了。', '', '', '', '', 's1466', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1466', 'chapter_8', 8, 'dialogue', 1466, 'ai', '星野爱', '嗯……但是全都想要！', '', '', '', '', 's1467', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1467', 'chapter_8', 8, 'dialogue', 1467, 'taku', '顾天鹏', '太贪婪了吧？', '', '', '', '', 's1468', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1468', 'chapter_8', 8, 'dialogue', 1468, 'ai', '星野爱', '没错，独一无二的贪婪！', '', '', '', '', 's1469', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1469', 'chapter_8', 8, 'narration', 1469, '', '', '她也转向顾天鹏，用手在下巴处比出一个勾的手势，露出一张自信满满的可爱脸。', '', '', '', '', 's1470', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1470', 'chapter_8', 8, 'dialogue', 1470, 'ai', '星野爱', '别人做过的，别人没做过的。无论哪一个，我都想做一遍。', '', '', '', '', 's1471', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1471', 'chapter_8', 8, 'dialogue', 1471, 'taku', '顾天鹏', '的确像是你。', '', '', '', '', 's1472', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1472', 'chapter_8', 8, 'dialogue', 1472, 'ai', '星野爱', '我星野爱，就是这么贪得无厌！', '', '', '', '', 's1473', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1473', 'chapter_8', 8, 'narration', 1473, '', '', '风声大了些。看着她那张略显狡猾、却又颇为可爱的侧脸，顾天鹏若有所思。', '', '', '', '', 's1474', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1474', 'chapter_8', 8, 'narration', 1474, '', '', '其他人也许不确定，唯独他彻底了解：这句话并非谎言。', '', '', '', '', 's1475', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1475', 'side_ch8_checklist_day', 8, 'set', 1475, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's1476', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1476', 'side_ch8_checklist_day', 8, 'set', 1476, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1477', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1477', 'side_ch8_checklist_day', 8, 'set', 1477, '', '', '', '', '', 'event_cg_mode', 'false', 's1478', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1478', 'side_ch8_checklist_day', 8, 'scene', 1478, '', '', '', 'bg ch8_cafe_street', '', '', '', 's1479', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1479', 'side_ch8_checklist_day', 8, 'sprite', 1479, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1480', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1480', 'side_ch8_checklist_day', 8, 'narration', 1480, '', '', '为了让任务清单不像作业，星野爱临时发明了“快乐盖章制度”。', '', '', '', '', 's1481', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1481', 'side_ch8_checklist_day', 8, 'dialogue', 1481, 'ai', '星野爱', '完成一个地点，就在攻略上画一个星星。', '', '', '', '', 's1482', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1482', 'side_ch8_checklist_day', 8, 'dialogue', 1482, 'taku', '顾天鹏', '没有印章？', '', '', '', '', 's1483', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1483', 'side_ch8_checklist_day', 8, 'dialogue', 1483, 'ai', '星野爱', '星野爱本人就是印章。', '', '', '', '', 's1484', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1484', 'side_ch8_checklist_day', 8, 'narration', 1484, '', '', '她用圆珠笔在攻略页边画下第一个歪星星，旁边写着“章鱼小丸子合格”。', '', '', '', '', 's1485', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1485', 'side_ch8_checklist_day', 8, 'narration', 1485, '', '', '风筝店的老板听见他们讨论任务清单，笑着从抽屉里拿出一张旧明信片，说如果能把风筝放到屋顶那么高，就送给他们。', '', '', '', '', 's1486', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1486', 'side_ch8_checklist_day', 8, 'scene', 1486, '', '', '', 'bg ch8_kite_field', '', '', '', 's1487', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1487', 'side_ch8_checklist_day', 8, 'sprite', 1487, '', '', '', '', '[{"image": "heroine winter_speak", "pos": "heroine_winter_center"}]', '', '', 's1488', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1488', 'side_ch8_checklist_day', 8, 'narration', 1488, '', '', '于是他们没有在枫树下坐很久，而是像两个被任务驱动的笨拙旅行者，在雪地上一次次放线、收线、再放线。', '', '', '', '', 's1489', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1489', 'side_ch8_checklist_day', 8, 'dialogue', 1489, 'ai', '星野爱', '再高一点！就差一点点！', '', '', '', '', 's1490', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1490', 'side_ch8_checklist_day', 8, 'dialogue', 1490, 'taku', '顾天鹏', '风向不稳定。', '', '', '', '', 's1491', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1491', 'side_ch8_checklist_day', 8, 'dialogue', 1491, 'ai', '星野爱', '那就拜托你和风谈判。', '', '', '', '', 's1492', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1492', 'side_ch8_checklist_day', 8, 'narration', 1492, '', '', '深海鱼风筝终于越过屋顶时，星野爱高兴得差点踩进雪堆。老板把明信片递给她，她立刻在背面写下第二颗星。', '', '', '', '', 's1493', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1493', 'side_ch8_checklist_day', 8, 'dialogue', 1493, 'ai', '星野爱', '风筝合格。顾天鹏谈判能力普通。', '', '', '', '', 's1494', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1494', 'side_ch8_checklist_day', 8, 'dialogue', 1494, 'taku', '顾天鹏', '普通已经很不错了。', '', '', '', '', 's1495', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1495', 'side_ch8_checklist_day', 8, 'narration', 1495, '', '', '接着是滑雪。她摔了两次，第三次终于滑过一小段平缓雪坡。顾天鹏没有笑，只在她站稳时鼓了两下掌。', '', '', '', '', 's1496', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1496', 'side_ch8_checklist_day', 8, 'dialogue', 1496, 'ai', '星野爱', '这个也要盖章。', '', '', '', '', 's1497', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1497', 'side_ch8_checklist_day', 8, 'narration', 1497, '', '', '神社前的石阶被雪水打湿，他们赶在闭门前买下御守。星野爱把最后一颗星画在攻略角落，盯着那一页看了很久。', '', '', '', '', 's1498', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1498', 'side_ch8_checklist_day', 8, 'dialogue', 1498, 'ai', '星野爱', '任务完成。', '', '', '', '', 's1499', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1499', 'side_ch8_checklist_day', 8, 'dialogue', 1499, 'taku', '顾天鹏', '开心吗？', '', '', '', '', 's1500', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1500', 'side_ch8_checklist_day', 8, 'dialogue', 1500, 'ai', '星野爱', '开心。', '', '', '', '', 's1501', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1501', 'side_ch8_checklist_day', 8, 'narration', 1501, '', '', '她回答得很快，却又轻轻补了一句。', '', '', '', '', 's1502', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1502', 'side_ch8_checklist_day', 8, 'dialogue', 1502, 'ai', '星野爱', '只是有点像把一天折成了很多小格子。', '', '', '', '', 's1503', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1503', 'side_ch8_checklist_day', 8, 'narration', 1503, '', '', '这条路线没有枫树下慢慢发酵的闲聊，却多了一张写满星星的攻略明信片。等他们回过神来，黄昏已经从神社的屋檐落下。', '', '', '', '', 's1504', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1504', 'side_ch8_checklist_day', 8, 'jump', 1504, '', '', '', '', '', '', '', 's1523', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1505', 'ch8_after_kite_rest', 8, 'set', 1505, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1506', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1506', 'ch8_after_kite_rest', 8, 'set', 1506, '', '', '', '', '', 'event_cg_mode', 'false', 's1507', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1507', 'ch8_after_kite_rest', 8, 'scene', 1507, '', '', '', 'bg ch8_ski_slope', '', '', '', 's1508', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1508', 'ch8_after_kite_rest', 8, 'narration', 1508, '', '', '从枫树下离开，他们将租来的绳盘、风筝、玻璃线，全都收好还到店里。', '', '', '', '', 's1509', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1509', 'ch8_after_kite_rest', 8, 'narration', 1509, '', '', '下午的时候，他们去了专门的雪场滑雪，又尝了这里远近闻名的炸天妇罗。', '', '', '', '', 's1510', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1510', 'ch8_after_kite_rest', 8, 'narration', 1510, '', '', '雪道在黄昏前被余光照得发亮，连租来的滑雪板边缘都像镶着一圈淡金色。', '', '', '', '', 's1511', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1511', 'ch8_after_kite_rest', 8, 'set', 1511, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1512', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1512', 'ch8_after_kite_rest', 8, 'set', 1512, '', '', '', '', '', 'event_cg_mode', 'false', 's1513', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1513', 'ch8_after_kite_rest', 8, 'scene', 1513, '', '', '', 'bg ch8_shrine_dusk', '', '', '', 's1514', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1514', 'ch8_after_kite_rest', 8, 'sprite', 1514, '', '', '', '', '[{"image": "heroine winter_neutral", "pos": "heroine_winter_center"}]', '', '', 's1515', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1515', 'ch8_after_kite_rest', 8, 'narration', 1515, '', '', '赶在黄昏之前，两个人又跑到附近的神社逛了一圈。', '', '', '', '', 's1516', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1516', 'ch8_after_kite_rest', 8, 'narration', 1516, '', '', '那里游客不算太多，空气竟然比外面还要清新不少。', '', '', '', '', 's1517', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1517', 'ch8_after_kite_rest', 8, 'narration', 1517, '', '', '他们祈福之后，买了交通安全御守、健康御守、事业御守和恋爱御守，一共花了不到两千日元。', '', '', '', '', 's1518', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1518', 'ch8_after_kite_rest', 8, 'dialogue', 1518, 'taku', '顾天鹏', '不要随便买御守送人，也不要擅自拆开御守的香囊，否则愿望就不灵验了。', '', '', '', '', 's1519', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1519', 'ch8_after_kite_rest', 8, 'narration', 1519, '', '', '神社里的工作人员这样跟他们说。', '', '', '', '', 's1520', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1520', 'ch8_after_kite_rest', 8, 'narration', 1520, '', '', '两人略感新奇地点头，样子几乎完全同步。', '', '', '', '', 's1521', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1521', 'ch8_after_kite_rest', 8, 'narration', 1521, '', '', '走出神社，一只乌鸦飞到出口的红色柱子上，用黑色的瞳孔注视大地，三只蝴蝶围绕着道路两边的紫花纷飞。', '', '', '', '', 's1522', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1522', 'ch8_after_kite_rest', 8, 'narration', 1522, '', '', '薄暮时分，天空被落日的余晖浸染，连雪都发黄发亮。', '', '', '', '', 's1523', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1523', 'ch8_evening_after_tasks', 8, 'set', 1523, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1524', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1524', 'ch8_evening_after_tasks', 8, 'set', 1524, '', '', '', '', '', 'event_cg_mode', 'true', 's1525', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1525', 'ch8_evening_after_tasks', 8, 'scene', 1525, '', '', '', 'cg ch8_moonlit_smile', '', '', '', 's1526', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1526', 'ch8_evening_after_tasks', 8, 'dialogue', 1526, 'ai', '星野爱', '放风筝、滑雪、逛神社、吃你心心念念的炸天妇罗……', '', '', '', '', 's1527', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1527', 'ch8_evening_after_tasks', 8, 'narration', 1527, '', '', '回去旅馆的路上，星野爱掰着手指念道。', '', '', '', '', 's1528', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1528', 'ch8_evening_after_tasks', 8, 'dialogue', 1528, 'ai', '星野爱', '一样也没漏，这些都做完了！', '', '', '', '', 's1529', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1529', 'ch8_evening_after_tasks', 8, 'dialogue', 1529, 'taku', '顾天鹏', '话是这么说，不过也不完全是我心心念念，你也喜欢得不得了嘛。', '', '', '', '', 's1530', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1530', 'ch8_evening_after_tasks', 8, 'dialogue', 1530, 'ai', '星野爱', '不过，总感觉还差些什么。', '', '', '', '', 's1531', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1531', 'ch8_evening_after_tasks', 8, 'dialogue', 1531, 'taku', '顾天鹏', '差些什么？', '', '', '', '', 's1532', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1532', 'ch8_evening_after_tasks', 8, 'narration', 1532, '', '', '她低头沉思起来。', '', '', '', '', 's1533', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1533', 'ch8_evening_after_tasks', 8, 'narration', 1533, '', '', '夕阳在她思考的间隙偷偷溜走，淡淡的白色重新笼罩着大地。', '', '', '', '', 's1534', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1534', 'ch8_evening_after_tasks', 8, 'narration', 1534, '', '', '直到最后一颗雪球落下，夜幕深沉，山峦仿佛被困在冰冷的星空之中。', '', '', '', '', 's1535', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1535', 'ch8_evening_after_tasks', 8, 'set', 1535, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1536', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1536', 'ch8_evening_after_tasks', 8, 'set', 1536, '', '', '', '', '', 'event_cg_mode', 'false', 's1537', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1537', 'ch8_evening_after_tasks', 8, 'scene', 1537, '', '', '', 'bg ch8_ryokan_room_moon', '', '', '', 's1538', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1538', 'ch8_evening_after_tasks', 8, 'sprite', 1538, '', '', '', '', '[{"image": "heroine winter_shy", "pos": "heroine_winter_center"}]', '', '', 's1539', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1539', 'ch8_evening_after_tasks', 8, 'narration', 1539, '', '', '他们心满意足地返回旅馆，换了鞋。', '', '', '', '', 's1540', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1540', 'ch8_evening_after_tasks', 8, 'narration', 1540, '', '', '星野爱带着浴巾去女性温泉，顾天鹏则一如既往坚持锻炼。', '', '', '', '', 's1541', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1541', 'ch8_evening_after_tasks', 8, 'narration', 1541, '', '', '等顾天鹏也泡完温泉回来，星野爱已经在看他的《了不起的盖茨比》。', '', '', '', '', 's1542', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1542', 'ch8_evening_after_tasks', 8, 'dialogue', 1542, 'taku', '顾天鹏', '还有什么想做的？', '', '', '', '', 's1543', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1543', 'ch8_evening_after_tasks', 8, 'narration', 1543, '', '', '坐到榻榻米上，顾天鹏漾着笑意问她。', '', '', '', '', 's1544', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1544', 'ch8_evening_after_tasks', 8, 'dialogue', 1544, 'ai', '星野爱', '什么？', '', '', '', '', 's1545', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1545', 'ch8_evening_after_tasks', 8, 'dialogue', 1545, 'taku', '顾天鹏', '还有什么想做的没？要是还能想起什么的话，趁我们没睡着，估计还来得及。', '', '', '', '', 's1546', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1546', 'ch8_evening_after_tasks', 8, 'dialogue', 1546, 'ai', '星野爱', '嗯……凿冰抓鱼？', '', '', '', '', 's1547', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1547', 'ch8_evening_after_tasks', 8, 'dialogue', 1547, 'taku', '顾天鹏', '恐怕不太合理。', '', '', '', '', 's1548', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1548', 'ch8_evening_after_tasks', 8, 'dialogue', 1548, 'ai', '星野爱', '那就喝一次这里的清酒咯？', '', '', '', '', 's1549', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1549', 'ch8_evening_after_tasks', 8, 'dialogue', 1549, 'taku', '顾天鹏', '你不还是未成年吗？', '', '', '', '', 's1550', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1550', 'ch8_evening_after_tasks', 8, 'dialogue', 1550, 'ai', '星野爱', '做一个美梦好了！', '', '', '', '', 's1551', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1551', 'ch8_evening_after_tasks', 8, 'dialogue', 1551, 'taku', '顾天鹏', '今天晚上就可以。', '', '', '', '', 's1552', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1552', 'ch8_evening_after_tasks', 8, 'dialogue', 1552, 'ai', '星野爱', '希望是这样。', '', '', '', '', 's1553', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1553', 'ch8_evening_after_tasks', 8, 'narration', 1553, '', '', '她合上书，嘴角扬起一个好看的弧度。', '', '', '', '', 's1554', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1554', 'ch8_evening_after_tasks', 8, 'narration', 1554, '', '', '旅馆的房间里，炉壁的火光摇摇晃晃。百叶窗外，天空暗得深邃，山体却泛着可爱的白光。', '', '', '', '', 's1555', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1555', 'ch8_evening_after_tasks', 8, 'set', 1555, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1556', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1556', 'ch8_evening_after_tasks', 8, 'set', 1556, '', '', '', '', '', 'event_cg_mode', 'true', 's1557', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1557', 'ch8_evening_after_tasks', 8, 'scene', 1557, '', '', '', 'cg ch8_futon_talk_ai', '', '', '', 's1558', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1558', 'ch8_evening_after_tasks', 8, 'narration', 1558, '', '', '火和灯都熄灭之后，两人睡在床的两侧，背对着背。', '', '', '', '', 's1559', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1559', 'ch8_evening_after_tasks', 8, 'narration', 1559, '', '', '月光透过百叶窗的缝隙散射到地板，视野竟有些不可思议地亮了起来。', '', '', '', '', 's1560', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1560', 'ch8_evening_after_tasks', 8, 'dialogue', 1560, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1561', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1561', 'ch8_evening_after_tasks', 8, 'dialogue', 1561, 'taku', '顾天鹏', '我在。', '', '', '', '', 's1562', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1562', 'ch8_evening_after_tasks', 8, 'dialogue', 1562, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1563', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1563', 'ch8_evening_after_tasks', 8, 'dialogue', 1563, 'taku', '顾天鹏', '我在。', '', '', '', '', 's1564', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1564', 'ch8_evening_after_tasks', 8, 'dialogue', 1564, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1565', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1565', 'ch8_evening_after_tasks', 8, 'dialogue', 1565, 'taku', '顾天鹏', '是。', '', '', '', '', 's1566', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1566', 'ch8_evening_after_tasks', 8, 'dialogue', 1566, 'ai', '星野爱', '你要说我在。', '', '', '', '', 's1567', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1567', 'ch8_evening_after_tasks', 8, 'dialogue', 1567, 'taku', '顾天鹏', '我在。', '', '', '', '', 's1568', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1568', 'ch8_evening_after_tasks', 8, 'dialogue', 1568, 'ai', '星野爱', '我可以叫你顾天鹏吗？', '', '', '', '', 's1569', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1569', 'ch8_evening_after_tasks', 8, 'dialogue', 1569, 'taku', '顾天鹏', '没问题，我不在意这些。', '', '', '', '', 's1570', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1570', 'ch8_evening_after_tasks', 8, 'dialogue', 1570, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1571', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1571', 'ch8_evening_after_tasks', 8, 'dialogue', 1571, 'taku', '顾天鹏', '我在。', '', '', '', '', 's1572', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1572', 'ch8_evening_after_tasks', 8, 'narration', 1572, '', '', '安静了一会儿，星野爱的声音再次传来。', '', '', '', '', 's1573', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1573', 'ch8_evening_after_tasks', 8, 'dialogue', 1573, 'ai', '星野爱', '我其实不擅长记人的名字，你信吗？', '', '', '', '', 's1574', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1574', 'ch8_evening_after_tasks', 8, 'dialogue', 1574, 'taku', '顾天鹏', '这句话不是谎言。', '', '', '', '', 's1575', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1575', 'ch8_evening_after_tasks', 8, 'dialogue', 1575, 'ai', '星野爱', '但我还是记住了你。', '', '', '', '', 's1576', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1576', 'ch8_evening_after_tasks', 8, 'narration', 1576, '', '', '她好像转过身来了。', '', '', '', '', 's1577', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1577', 'ch8_evening_after_tasks', 8, 'dialogue', 1577, 'ai', '星野爱', '我记得你叫顾天鹏，全名叫做顾天鹏。虽然我一直用顾天鹏来叫你，但是我就是记得。', '', '', '', '', 's1578', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1578', 'ch8_evening_after_tasks', 8, 'narration', 1578, '', '', '顾天鹏望着洒落到地面的银辉。', '', '', '', '', 's1579', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1579', 'ch8_evening_after_tasks', 8, 'dialogue', 1579, 'taku', '顾天鹏', '谢谢，我也牢记着你的名字。', '', '', '', '', 's1580', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1580', 'ch8_evening_after_tasks', 8, 'dialogue', 1580, 'ai', '星野爱', '说。', '', '', '', '', 's1581', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1581', 'ch8_evening_after_tasks', 8, 'dialogue', 1581, 'taku', '顾天鹏', '星野爱。', '', '', '', '', 's1582', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1582', 'ch8_evening_after_tasks', 8, 'dialogue', 1582, 'ai', '星野爱', '你一直都叫我星野小姐。', '', '', '', '', 's1583', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1583', 'ch8_evening_after_tasks', 8, 'dialogue', 1583, 'taku', '顾天鹏', '但我就是记得。', '', '', '', '', 's1584', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1584', 'ch8_evening_after_tasks', 8, 'dialogue', 1584, 'ai', '星野爱', '谢谢。', '', '', '', '', 's1585', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1585', 'ch8_evening_after_tasks', 8, 'narration', 1585, '', '', '她似乎又转了个身。月光将百叶窗木栏投下来的阴影拉得老长。', '', '', '', '', 's1586', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1586', 'ch8_evening_after_tasks', 8, 'dialogue', 1586, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1587', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1587', 'ch8_evening_after_tasks', 8, 'dialogue', 1587, 'taku', '顾天鹏', '我在。', '', '', '', '', 's1588', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1588', 'ch8_evening_after_tasks', 8, 'dialogue', 1588, 'ai', '星野爱', '我对有才能的人，或许记得比较深。', '', '', '', '', 's1589', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1589', 'ch8_evening_after_tasks', 8, 'dialogue', 1589, 'taku', '顾天鹏', '不瞒你说，我也时常觉得自己是个才华横溢的人。', '', '', '', '', 's1590', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1590', 'ch8_evening_after_tasks', 8, 'dialogue', 1590, 'ai', '星野爱', '一点也不谦虚哦。', '', '', '', '', 's1591', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1591', 'ch8_evening_after_tasks', 8, 'dialogue', 1591, 'taku', '顾天鹏', '受你影响了。', '', '', '', '', 's1592', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1592', 'ch8_evening_after_tasks', 8, 'dialogue', 1592, 'ai', '星野爱', '你有什么才能？', '', '', '', '', 's1593', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1593', 'ch8_evening_after_tasks', 8, 'dialogue', 1593, 'taku', '顾天鹏', '长得帅。', '', '', '', '', 's1594', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1594', 'ch8_evening_after_tasks', 8, 'narration', 1594, '', '', '星野爱好听地笑了。', '', '', '', '', 's1595', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1595', 'ch8_evening_after_tasks', 8, 'dialogue', 1595, 'ai', '星野爱', '就算是这样，长相也算不上是个才能。', '', '', '', '', 's1596', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1596', 'ch8_evening_after_tasks', 8, 'dialogue', 1596, 'taku', '顾天鹏', '那我坚持锻炼，喜欢看书，为人礼貌，平等待人，从不懈怠，高中的时候成绩基本都是年级前五。这些算不算才能？', '', '', '', '', 's1597', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1597', 'ch8_evening_after_tasks', 8, 'dialogue', 1597, 'ai', '星野爱', '你原来这么厉害？', '', '', '', '', 's1598', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1598', 'ch8_evening_after_tasks', 8, 'dialogue', 1598, 'taku', '顾天鹏', '是。', '', '', '', '', 's1599', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1599', 'ch8_evening_after_tasks', 8, 'dialogue', 1599, 'ai', '星野爱', '了不起！', '', '', '', '', 's1600', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1600', 'ch8_evening_after_tasks', 8, 'dialogue', 1600, 'taku', '顾天鹏', '了不起的顾天鹏。', '', '', '', '', 's1601', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1601', 'ch8_evening_after_tasks', 8, 'dialogue', 1601, 'ai', '星野爱', '了不起的顾天鹏！这么厉害的顾天鹏，在我看来，还有更厉害的地方！', '', '', '', '', 's1602', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1602', 'ch8_evening_after_tasks', 8, 'dialogue', 1602, 'taku', '顾天鹏', '什么？', '', '', '', '', 's1603', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1603', 'ch8_evening_after_tasks', 8, 'dialogue', 1603, 'ai', '星野爱', '秘密！', '', '', '', '', 's1604', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1604', 'ch8_evening_after_tasks', 8, 'dialogue', 1604, 'taku', '顾天鹏', '我就知道。', '', '', '', '', 's1605', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1605', 'ch8_evening_after_tasks', 8, 'dialogue', 1605, 'ai', '星野爱', '嘻嘻。', '', '', '', '', 's1606', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1606', 'ch8_evening_after_tasks', 8, 'narration', 1606, '', '', '借着月色，他们漫无边际地说了又说，聊了又聊，仿佛真的要把一辈子的事情在今晚干完不可。', '', '', '', '', 's1607', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1607', 'ch8_evening_after_tasks', 8, 'dialogue', 1607, 'taku', '顾天鹏', '你喜欢什么？', '', '', '', '', 's1608', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1608', 'ch8_evening_after_tasks', 8, 'dialogue', 1608, 'ai', '星野爱', '秘密。', '', '', '', '', 's1609', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1609', 'ch8_evening_after_tasks', 8, 'dialogue', 1609, 'taku', '顾天鹏', '喜欢的书是什么？', '', '', '', '', 's1610', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1610', 'ch8_evening_after_tasks', 8, 'dialogue', 1610, 'ai', '星野爱', '这个也是秘密。', '', '', '', '', 's1611', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1611', 'ch8_evening_after_tasks', 8, 'dialogue', 1611, 'taku', '顾天鹏', '喜欢吃什么？', '', '', '', '', 's1612', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1612', 'ch8_evening_after_tasks', 8, 'dialogue', 1612, 'ai', '星野爱', '那个也是秘密。', '', '', '', '', 's1613', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1613', 'ch8_evening_after_tasks', 8, 'dialogue', 1613, 'taku', '顾天鹏', '谈过恋爱？', '', '', '', '', 's1614', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1614', 'ch8_evening_after_tasks', 8, 'dialogue', 1614, 'ai', '星野爱', '秘密。', '', '', '', '', 's1615', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1615', 'ch8_evening_after_tasks', 8, 'dialogue', 1615, 'taku', '顾天鹏', '喜欢的类型是什么？', '', '', '', '', 's1616', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1616', 'ch8_evening_after_tasks', 8, 'dialogue', 1616, 'ai', '星野爱', '秘密。', '', '', '', '', 's1617', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1617', 'ch8_evening_after_tasks', 8, 'dialogue', 1617, 'taku', '顾天鹏', '全是秘密？', '', '', '', '', 's1618', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1618', 'ch8_evening_after_tasks', 8, 'dialogue', 1618, 'ai', '星野爱', '全是秘密！', '', '', '', '', 's1619', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1619', 'ch8_evening_after_tasks', 8, 'narration', 1619, '', '', '星野爱笑着说，那笑声比歌声都要动听。', '', '', '', '', 's1620', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1620', 'ch8_evening_after_tasks', 8, 'dialogue', 1620, 'taku', '顾天鹏', '你会唱歌吗？', '', '', '', '', 's1621', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1621', 'ch8_evening_after_tasks', 8, 'dialogue', 1621, 'ai', '星野爱', '唱歌？', '', '', '', '', 's1622', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1622', 'ch8_evening_after_tasks', 8, 'dialogue', 1622, 'taku', '顾天鹏', '像昨天的那个轻音部那样。', '', '', '', '', 's1623', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1623', 'ch8_evening_after_tasks', 8, 'dialogue', 1623, 'ai', '星野爱', '唱不到那么好吧，我不怎么喜欢唱歌。', '', '', '', '', 's1624', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1624', 'ch8_evening_after_tasks', 8, 'dialogue', 1624, 'taku', '顾天鹏', '明明声音很好听。', '', '', '', '', 's1625', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1625', 'ch8_evening_after_tasks', 8, 'dialogue', 1625, 'ai', '星野爱', '你的夸奖我很受用。', '', '', '', '', 's1626', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1626', 'ch8_evening_after_tasks', 8, 'dialogue', 1626, 'taku', '顾天鹏', '可以唱一次吗？小声地唱一次。', '', '', '', '', 's1627', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1627', 'ch8_evening_after_tasks', 8, 'dialogue', 1627, 'ai', '星野爱', '不行哝。', '', '', '', '', 's1628', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1628', 'ch8_evening_after_tasks', 8, 'dialogue', 1628, 'taku', '顾天鹏', '可惜。', '', '', '', '', 's1629', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1629', 'ch8_evening_after_tasks', 8, 'dialogue', 1629, 'ai', '星野爱', '连歌声都是秘密！', '', '', '', '', 's1630', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1630', 'ch8_evening_after_tasks', 8, 'narration', 1630, '', '', '那时候，星星闪烁在天边，月亮一动不动。', '', '', '', '', 's1631', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1631', 'chapter_9', 9, 'set', 1631, '', '', '', '', '', 'ai_sprite_outfit', 'winter', 's1632', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1632', 'chapter_9', 9, 'set', 1632, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1633', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1633', 'chapter_9', 9, 'set', 1633, '', '', '', '', '', 'event_cg_mode', 'false', 's1634', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1634', 'chapter_9', 9, 'scene', 1634, '', '', '', 'bg ch9_yuzawa_last_night_room', '', '', '', 's1635', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1635', 'chapter_9', 9, 'narration', 1635, '', '', '冬天之后，是秋天', '', '', '', '', 's1636', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1636', 'chapter_9', 9, 'narration', 1636, '', '', '留在越后汤泽的最后一晚，月色浸透整片雪原。', '', '', '', '', 's1637', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1637', 'chapter_9', 9, 'narration', 1637, '', '', '旅馆屋内暖炉温热，榻榻米上铺着柔软的被褥，窗外落雪安静无声，连风都刻意放轻了脚步。', '', '', '', '', 's1638', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1638', 'chapter_9', 9, 'set', 1638, '', '', '', '', '', 'event_cg_mode', 'true', 's1639', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1639', 'chapter_9', 9, 'scene', 1639, '', '', '', 'cg ch9_futon_night_talk', '', '', '', 's1640', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1640', 'chapter_9', 9, 'narration', 1640, '', '', '两人隔着一点距离躺下，背对着背，在静谧的夜色里轻声闲谈。', '', '', '', '', 's1641', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1641', 'chapter_9', 9, 'narration', 1641, '', '', '从童年琐事聊到喜好偏爱，从心底的秘密说到未曾表露的心事。', '', '', '', '', 's1642', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1642', 'chapter_9', 9, 'narration', 1642, '', '', '星野爱活泼轻快的嗓音，在安静的房间里轻轻回荡。', '', '', '', '', 's1643', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1643', 'chapter_9', 9, 'narration', 1643, '', '', '她藏着无数不为人知的心事，自幼孤身一人长大，无家人相伴，无依靠可寻，一路独自撑着自己前行。', '', '', '', '', 's1644', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1644', 'chapter_9', 9, 'narration', 1644, '', '', '心中怀揣着成为偶像的憧憬，却被现实的诸多条条框框死死束缚。', '', '', '', '', 's1645', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1645', 'chapter_9', 9, 'narration', 1645, '', '', '看似开朗明媚、永远笑意盎然的外表之下，藏着旁人从未窥见的孤独与敏感。', '', '', '', '', 's1646', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1646', 'chapter_9', 9, 'narration', 1646, '', '', '顾天鹏静静听着，一言不发，却将她所说的每一句话，都牢牢记在了心底。', '', '', '', '', 's1647', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1647', 'chapter_9', 9, 'set', 1647, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1648', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1648', 'chapter_9', 9, 'set', 1648, '', '', '', '', '', 'event_cg_mode', 'false', 's1649', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1649', 'chapter_9', 9, 'scene', 1649, '', '', '', 'bg ch9_yuzawa_last_night_room', '', '', '', 's1650', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1650', 'chapter_9', 9, 'sprite', 1650, '', '', '', '', '[{"image": "heroine winter_shy", "pos": "heroine_winter_center"}]', '', '', 's1651', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1651', 'chapter_9', 9, 'dialogue', 1651, 'ai', '星野爱', '其实，我很少能这般放松。', '', '', '', '', 's1652', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1652', 'chapter_9', 9, 'narration', 1652, '', '', '黑暗中，星野爱的声音轻缓又柔和。', '', '', '', '', 's1653', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1653', 'chapter_9', 9, 'dialogue', 1653, 'ai', '星野爱', '可以肆无忌惮说话，不用伪装情绪，不用刻意迎合任何人…… 这般轻松自在的日子，真的太少了。', '', '', '', '', 's1654', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1654', 'chapter_9', 9, 'dialogue', 1654, 'taku', '顾天鹏', '在这里很放松吗？', '', '', '', '', 's1655', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1655', 'chapter_9', 9, 'dialogue', 1655, 'ai', '星野爱', '嗯。', '', '', '', '', 's1656', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1656', 'chapter_9', 9, 'narration', 1656, '', '', '她轻轻应声。', '', '', '', '', 's1657', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1657', 'chapter_9', 9, 'dialogue', 1657, 'ai', '星野爱', '和你在一起的时候，格外放松。', '', '', '', '', 's1658', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1658', 'chapter_9', 9, 'narration', 1658, '', '', '简短的一句话，悄然落进顾天鹏的心底。', '', '', '', '', 's1659', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1659', 'chapter_9', 9, 'narration', 1659, '', '', '一夜闲谈，直至深夜，倦意慢慢袭来，两人相继沉沉睡去。', '', '', '', '', 's1660', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1660', 'chapter_9', 9, 'set', 1660, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1661', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1661', 'chapter_9', 9, 'set', 1661, '', '', '', '', '', 'event_cg_mode', 'false', 's1662', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1662', 'chapter_9', 9, 'scene', 1662, '', '', '', 'bg ch9_train_autumn_window', '', '', '', 's1663', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1663', 'chapter_9', 9, 'narration', 1663, '', '', '次日破晓，天光微亮，皑皑白雪铺满山野，天地间一片洁白。', '', '', '', '', 's1664', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1664', 'chapter_9', 9, 'narration', 1664, '', '', '两人收拾好所有行李，告别待了数日的越后汤泽，搭乘列车启程离开。', '', '', '', '', 's1665', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1665', 'chapter_9', 9, 'narration', 1665, '', '', '列车一路前行，窗外的风景不断流转，雪白的雪景慢慢褪去，绿意与暖黄的色调渐渐铺满视野。', '', '', '', '', 's1666', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1666', 'chapter_9', 9, 'narration', 1666, '', '', '气温缓缓回升，凛冽的寒意消散，取而代之的，是独属于秋的温柔与慵懒。', '', '', '', '', 's1667', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1667', 'chapter_9', 9, 'narration', 1667, '', '', '路途漫漫，车厢内安静平和，星野爱戴着耳机，靠在窗边静静听歌，不自觉跟着旋律轻声哼唱。', '', '', '', '', 's1668', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1668', 'chapter_9', 9, 'narration', 1668, '', '', '细碎的歌声轻飘散开，落在一旁的顾天鹏耳中。', '', '', '', '', 's1669', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1669', 'chapter_9', 9, 'set', 1669, '', '', '', '', '', 'event_cg_mode', 'true', 's1670', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1670', 'chapter_9', 9, 'scene', 1670, '', '', '', 'cg ch9_train_humming', '', '', '', 's1671', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1671', 'chapter_9', 9, 'set', 1671, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1672', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1672', 'chapter_9', 9, 'set', 1672, '', '', '', '', '', 'event_cg_mode', 'false', 's1673', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1673', 'chapter_9', 9, 'scene', 1673, '', '', '', 'bg ch9_train_autumn_window', '', '', '', 's1674', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1674', 'chapter_9', 9, 'sprite', 1674, '', '', '', '', '[{"image": "heroine winter_surprised", "pos": "heroine_winter_center"}]', '', '', 's1675', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1675', 'chapter_9', 9, 'dialogue', 1675, 'taku', '顾天鹏', '这不是唱的挺好吗？', '', '', '', '', 's1676', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1676', 'chapter_9', 9, 'dialogue', 1676, 'ai', '星野爱', '……', '', '', '', '', 's1677', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1677', 'chapter_9', 9, 'narration', 1677, '', '', '星野爱摘下耳机盯着他。', '', '', '', '', 's1678', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1678', 'chapter_9', 9, 'dialogue', 1678, 'ai', '星野爱', '我唱出来了？', '', '', '', '', 's1679', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1679', 'chapter_9', 9, 'dialogue', 1679, 'taku', '顾天鹏', '估计是了。', '', '', '', '', 's1680', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1680', 'chapter_9', 9, 'dialogue', 1680, 'ai', '星野爱', '哇，一不小心就……', '', '', '', '', 's1681', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1681', 'chapter_9', 9, 'dialogue', 1681, 'taku', '顾天鹏', '挺好的。', '', '', '', '', 's1682', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1682', 'chapter_9', 9, 'set', 1682, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1683', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1683', 'chapter_9', 9, 'set', 1683, '', '', '', '', '', 'event_cg_mode', 'false', 's1684', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1684', 'chapter_9', 9, 'scene', 1684, '', '', '', 'bg ch9_karuizawa_bus_stop', '', '', '', 's1685', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1685', 'chapter_9', 9, 'narration', 1685, '', '', '火车到站停下，他们带着行李走出车厢，又七拐八拐到巴士站台，乘上下一班公交车，公交车六分钟便来。', '', '', '', '', 's1686', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1686', 'chapter_9', 9, 'narration', 1686, '', '', '车子朝他们预约好的一家林间旅馆所在的方向开去。', '', '', '', '', 's1687', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1687', 'chapter_9', 9, 'narration', 1687, '', '', '车身摇摇晃晃，翻越碓冰岭，路过高尔夫球场和网球场，绕进被浅间山、留夫山、離山和鼻曲山包围的轻井泽。', '', '', '', '', 's1688', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1688', 'chapter_9', 9, 'narration', 1688, '', '', '这里是东京的西北方，位于长野县的东南部。', '', '', '', '', 's1689', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1689', 'chapter_9', 9, 'narration', 1689, '', '', '一年四季，薄雾弥漫山林，落叶松和白桦树展示着墨绿墨绿的繁盛枝叶。', '', '', '', '', 's1690', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1690', 'chapter_9', 9, 'narration', 1690, '', '', '不远处，枫树则如同燃烧的大鸟挥动翅膀。', '', '', '', '', 's1691', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1691', 'chapter_9', 9, 'narration', 1691, '', '', '梧桐满地，连地面都色彩缤纷，景观宛若仙境。', '', '', '', '', 's1692', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1692', 'chapter_9', 9, 'narration', 1692, '', '', '他们在终点站下了车，但还要步行几百米才能到旅馆。', '', '', '', '', 's1693', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1693', 'chapter_9', 9, 'set', 1693, '', '', '', '', '', 'ai_sprite_outfit', 'karuizawa', 's1694', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1694', 'chapter_9', 9, 'set', 1694, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1695', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1695', 'chapter_9', 9, 'set', 1695, '', '', '', '', '', 'ai_sprite_position', 'left', 's1696', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1696', 'chapter_9', 9, 'set', 1696, '', '', '', '', '', 'event_cg_mode', 'false', 's1697', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1697', 'chapter_9', 9, 'scene', 1697, '', '', '', 'bg ch9_forest_inn_path', '', '', '', 's1698', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1698', 'chapter_9', 9, 'sprite', 1698, '', '', '', '', '[{"image": "heroine karuizawa_neutral", "pos": "heroine_karuizawa_left"}]', '', '', 's1699', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1699', 'chapter_9', 9, 'narration', 1699, '', '', '好在路途平缓，行李箱里也没装什么东西。', '', '', '', '', 's1700', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1700', 'chapter_9', 9, 'narration', 1700, '', '', '他们拖着行李漫步在由繁花落叶构成的特别大海之中。', '', '', '', '', 's1701', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1701', 'chapter_9', 9, 'narration', 1701, '', '', '一路上，阳光不时地从叶缝间洒落下来，跳上星野爱的牛仔外套，闪烁于她迷人的肩膀。', '', '', '', '', 's1702', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1702', 'chapter_9', 9, 'narration', 1702, '', '', '无论风的温度如何，光是看着她对一切事物都兴致盎然的身影，森林便显得温暖、充满生气了。', '', '', '', '', 's1703', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1703', 'chapter_9', 9, 'set', 1703, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1704', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1704', 'chapter_9', 9, 'set', 1704, '', '', '', '', '', 'event_cg_mode', 'true', 's1705', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1705', 'chapter_9', 9, 'scene', 1705, '', '', '', 'cg ch9_autumn_arrival', '', '', '', 's1706', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1706', 'chapter_9', 9, 'dialogue', 1706, 'ai', '星野爱', '秋天！', '', '', '', '', 's1707', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1707', 'chapter_9', 9, 'narration', 1707, '', '', '林间道上，星野爱停下脚步，望着漫天的树叶伸出双臂感叹。', '', '', '', '', 's1708', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1708', 'chapter_9', 9, 'dialogue', 1708, 'taku', '顾天鹏', '到秋天了。', '', '', '', '', 's1709', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1709', 'chapter_9', 9, 'narration', 1709, '', '', '顾天鹏在她身后说。', '', '', '', '', 's1710', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1710', 'chapter_9', 9, 'dialogue', 1710, 'ai', '星野爱', '诶，你说，我们是不是就像是从冬天穿越过来的一样！', '', '', '', '', 's1711', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1711', 'chapter_9', 9, 'dialogue', 1711, 'taku', '顾天鹏', '的确呢。', '', '', '', '', 's1712', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1712', 'chapter_9', 9, 'narration', 1712, '', '', '顾天鹏看着脚下的枫叶。', '', '', '', '', 's1713', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1713', 'chapter_9', 9, 'dialogue', 1713, 'taku', '顾天鹏', '从雪地一下子到了这里，很难想象。', '', '', '', '', 's1714', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1714', 'chapter_9', 9, 'narration', 1714, '', '', '火团似的小鸟鸣啭一声，混进枝头。', '', '', '', '', 's1715', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1715', 'chapter_9', 9, 'set', 1715, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1716', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1716', 'chapter_9', 9, 'set', 1716, '', '', '', '', '', 'ai_sprite_position', 'right', 's1717', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1717', 'chapter_9', 9, 'set', 1717, '', '', '', '', '', 'event_cg_mode', 'false', 's1718', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1718', 'chapter_9', 9, 'scene', 1718, '', '', '', 'bg ch9_forest_inn_path', '', '', '', 's1719', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1719', 'chapter_9', 9, 'sprite', 1719, '', '', '', '', '[{"image": "heroine karuizawa_speak", "pos": "heroine_karuizawa_right"}]', '', '', 's1720', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1720', 'chapter_9', 9, 'dialogue', 1720, 'ai', '星野爱', '原来冬天之后是秋天！', '', '', '', '', 's1721', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1721', 'chapter_9', 9, 'dialogue', 1721, 'taku', '顾天鹏', '是春天。', '', '', '', '', 's1722', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1722', 'chapter_9', 9, 'dialogue', 1722, 'ai', '星野爱', '是秋天！', '', '', '', '', 's1723', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1723', 'chapter_9', 9, 'dialogue', 1723, 'taku', '顾天鹏', '是是，是秋天。', '', '', '', '', 's1724', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1724', 'chapter_9', 9, 'set', 1724, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1725', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1725', 'chapter_9', 9, 'set', 1725, '', '', '', '', '', 'event_cg_mode', 'false', 's1726', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1726', 'chapter_9', 9, 'scene', 1726, '', '', '', 'bg ch9_forest_inn_path', '', '', '', 's1727', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1727', 'chapter_9', 9, 'narration', 1727, '', '', '飘到路面的树叶和夏末死去的知了干壳在脚底下发出异常清脆的声响。', '', '', '', '', 's1728', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1728', 'chapter_9', 9, 'narration', 1728, '', '', '他们一边拖着行李向前，一边踢飞脚下的松子或是快要碎裂的落叶。', '', '', '', '', 's1729', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1729', 'chapter_9', 9, 'narration', 1729, '', '', '直到旅馆清晰地出现在他们面前，他们办理好入住。', '', '', '', '', 's1730', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1730', 'chapter_9', 9, 'narration', 1730, '', '', '像在越后汤泽那样，他们将行李和未来几天的生活，全都安顿在这里。', '', '', '', '', 's1731', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1731', 'chapter_9', 9, 'set', 1731, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1732', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1732', 'chapter_9', 9, 'set', 1732, '', '', '', '', '', 'event_cg_mode', 'false', 's1733', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1733', 'chapter_9', 9, 'scene', 1733, '', '', '', 'bg ch9_bicycle_rental', '', '', '', 's1734', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1734', 'chapter_9', 9, 'set', 1734, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1735', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1735', 'chapter_9', 9, 'set', 1735, '', '', '', '', '', 'ai_sprite_position', 'left', 's1736', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1736', 'chapter_9', 9, 'sprite', 1736, '', '', '', '', '[{"image": "heroine karuizawa_speak", "pos": "heroine_karuizawa_left"}]', '', '', 's1737', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1737', 'chapter_9', 9, 'narration', 1737, '', '', '距离午餐之前的那段时间，他们从旅馆出来，步行到自行车出租店。', '', '', '', '', 's1738', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1738', 'chapter_9', 9, 'narration', 1738, '', '', '顾天鹏租了一辆黑色的越野，星野爱则选了一辆稍微休闲些的白色自行车。', '', '', '', '', 's1739', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1739', 'chapter_9', 9, 'set', 1739, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1740', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1740', 'chapter_9', 9, 'scene', 1740, '', '', '', 'bg ch9_autumn_cycling_lane', '', '', '', 's1741', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1741', 'chapter_9', 9, 'narration', 1741, '', '', '他们从店门口出发，骑上车，听着耳边穿过的风声，感受来自头顶的闪烁着的金色光线。', '', '', '', '', 's1742', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1742', 'chapter_9', 9, 'narration', 1742, '', '', '时而加速超越，时而减速并行。', '', '', '', '', 's1743', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1743', 'chapter_9', 9, 'set', 1743, '', '', '', '', '', 'event_cg_mode', 'true', 's1744', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1744', 'chapter_9', 9, 'scene', 1744, '', '', '', 'cg ch9_bicycle_ride', '', '', '', 's1745', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1745', 'chapter_9', 9, 'narration', 1745, '', '', '自行车的车铃声像是上低音号一样徜徉在车道上，飘进幽静的空谷中。', '', '', '', '', 's1746', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1746', 'chapter_9', 9, 'narration', 1746, '', '', '轮胎碾过地面，杂乱散落的树叶如同森林的精灵一般追逐在车身后。', '', '', '', '', 's1747', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1747', 'chapter_9', 9, 'narration', 1747, '', '', '视野所见，一派秋日之息。', '', '', '', '', 's1748', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1748', 'chapter_9', 9, 'narration', 1748, '', '', '果然冬天之后是秋天，顾天鹏突然想起她说的话。', '', '', '', '', 's1749', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1749', 'chapter_9', 9, 'set', 1749, '', '', '', '', '', 'event_cg_mode', 'false', 's1750', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1750', 'chapter_9', 9, 'scene', 1750, '', '', '', 'bg ch9_roadside_steps', '', '', '', 's1751', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1751', 'chapter_9', 9, 'narration', 1751, '', '', '骑得累了，他们把车停在路边。', '', '', '', '', 's1752', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1752', 'chapter_9', 9, 'narration', 1752, '', '', '顾天鹏随意地坐在阶梯旁的地面，星野爱则蹲在附近观察蚂蚁的洞穴。', '', '', '', '', 's1753', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1753', 'chapter_9', 9, 'set', 1753, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1754', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1754', 'chapter_9', 9, 'set', 1754, '', '', '', '', '', 'ai_sprite_position', 'far', 's1755', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1755', 'chapter_9', 9, 'sprite', 1755, '', '', '', '', '[{"image": "heroine karuizawa_neutral", "pos": "heroine_karuizawa_far"}]', '', '', 's1756', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1756', 'chapter_9', 9, 'dialogue', 1756, 'ai', '星野爱', '你喜欢什么季节？', '', '', '', '', 's1757', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1757', 'chapter_9', 9, 'narration', 1757, '', '', '星野爱突然若无其事地问他。', '', '', '', '', 's1758', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1759', 'chapter_9', 9, 'narration', 1759, '', '', '顾天鹏没有把答案藏太久。夏天这个词从舌尖落下时，连秋天的风都像停了一瞬。', '', '', '', '', 's1760', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1760', 'chapter_9', 9, 'dialogue', 1760, 'taku', '顾天鹏', '夏天。', '', '', '', '', 's1761', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1761', 'chapter_9', 9, 'dialogue', 1761, 'ai', '星野爱', '为什么？', '', '', '', '', 's1762', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1762', 'chapter_9', 9, 'dialogue', 1762, 'taku', '顾天鹏', '因为到了夏天，人会想把冬天没说完的话补上。', '', '', '', '', 's1763', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1763', 'chapter_9', 9, 'narration', 1763, '', '', '这个回答出口以后，顾天鹏自己也愣了一下。原来有些话并不是想好才说，只是被问到时刚好浮上来。', '', '', '', '', 's1764', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1764', 'chapter_9', 9, 'dialogue', 1764, 'ai', '星野爱', '听起来像秘密的一部分。', '', '', '', '', 's1765', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1765', 'chapter_9', 9, 'dialogue', 1765, 'taku', '顾天鹏', '那就先算一部分。', '', '', '', '', 's1766', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1766', 'chapter_9', 9, 'dialogue', 1766, 'ai', '星野爱', '我喜欢冬天。', '', '', '', '', 's1786', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1767', 'chapter_9', 9, 'narration', 1767, '', '', '顾天鹏决定只给出一半答案。秘密并不总是为了拒绝别人，有时只是为了让谈话继续往前走。', '', '', '', '', 's1768', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1768', 'chapter_9', 9, 'dialogue', 1768, 'taku', '顾天鹏', '夏天。', '', '', '', '', 's1769', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1769', 'chapter_9', 9, 'narration', 1769, '', '', '顾天鹏捡起红色的落叶，叶片一碰便碎裂开来。', '', '', '', '', 's1770', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1770', 'chapter_9', 9, 'dialogue', 1770, 'ai', '星野爱', '为什么？', '', '', '', '', 's1771', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1771', 'chapter_9', 9, 'dialogue', 1771, 'taku', '顾天鹏', '秘密。', '', '', '', '', 's1772', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1772', 'chapter_9', 9, 'narration', 1772, '', '', '星野爱回头望他。', '', '', '', '', 's1773', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1773', 'chapter_9', 9, 'dialogue', 1773, 'taku', '顾天鹏', '我不能有秘密？', '', '', '', '', 's1774', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1774', 'chapter_9', 9, 'dialogue', 1774, 'ai', '星野爱', '当然可以。', '', '', '', '', 's1775', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1775', 'chapter_9', 9, 'narration', 1775, '', '', '星野爱笑了。', '', '', '', '', 's1776', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1776', 'chapter_9', 9, 'dialogue', 1776, 'ai', '星野爱', '我喜欢冬天。', '', '', '', '', 's1777', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1777', 'chapter_9', 9, 'dialogue', 1777, 'taku', '顾天鹏', '理由是秘密。', '', '', '', '', 's1778', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1778', 'chapter_9', 9, 'narration', 1778, '', '', '秘密换来了秘密，谈话也停在安全的地方。', '', '', '', '', 's1779', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1779', 'chapter_9', 9, 'narration', 1779, '', '', '可她没有立刻走开，只是又捡起一片带孔的叶子，像还想把话题往前推一点。', '', '', '', '', 's1780', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1780', 'chapter_9', 9, 'narration', 1780, '', '', '顾天鹏把那片叶子接过来，夹进随身带着的书里。星野爱没有阻止，只是眯起眼睛。', '', '', '', '', 's1781', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1781', 'chapter_9', 9, 'dialogue', 1781, 'ai', '星野爱', '那这片叶子就是保证金。', '', '', '', '', 's1782', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1782', 'chapter_9', 9, 'dialogue', 1782, 'taku', '顾天鹏', '保证什么？', '', '', '', '', 's1783', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1783', 'chapter_9', 9, 'dialogue', 1783, 'ai', '星野爱', '保证有一天，你要把夏天的理由说出来。我也会把冬天的理由说出来。', '', '', '', '', 's1784', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1784', 'chapter_9', 9, 'narration', 1784, '', '', '这不是轻易说出口的约定。它太轻，也太绕，像两个人把真正的问题藏进叶脉里，故意让它晚一点发芽。', '', '', '', '', 's1785', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1785', 'chapter_9', 9, 'jump', 1785, '', '', '', '', '', '', '', 's3611', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1758', 'chapter_9', 9, 'menu', 1758, '', '', '', '', '', '', '', 's1786', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1786', 'chapter_9', 9, 'narration', 1786, '', '', '星野爱摇头，直起身子，也不管地面脏不脏，径自在顾天鹏身边坐下。', '', '', '', '', 's1787', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1787', 'chapter_9', 9, 'narration', 1787, '', '', '她拾起一片红绿各半、满是孔洞的树叶。', '', '', '', '', 's1788', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1788', 'chapter_9', 9, 'dialogue', 1788, 'ai', '星野爱', '我喜欢那几天，在越后汤泽的那几天。', '', '', '', '', 's1789', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1789', 'chapter_9', 9, 'dialogue', 1789, 'taku', '顾天鹏', '因为雪？', '', '', '', '', 's1790', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1790', 'chapter_9', 9, 'narration', 1790, '', '', '她摇了摇头。', '', '', '', '', 's1791', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1791', 'chapter_9', 9, 'dialogue', 1791, 'taku', '顾天鹏', '因为麋鹿？', '', '', '', '', 's1792', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1792', 'chapter_9', 9, 'narration', 1792, '', '', '她还是否认。', '', '', '', '', 's1793', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1793', 'chapter_9', 9, 'dialogue', 1793, 'taku', '顾天鹏', '猜不到。', '', '', '', '', 's1794', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1794', 'chapter_9', 9, 'narration', 1794, '', '', '顾天鹏投降。', '', '', '', '', 's1795', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1795', 'chapter_9', 9, 'set', 1795, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1796', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1796', 'chapter_9', 9, 'set', 1796, '', '', '', '', '', 'event_cg_mode', 'true', 's1797', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1797', 'chapter_9', 9, 'scene', 1797, '', '', '', 'cg ch9_leaf_sunlight', '', '', '', 's1798', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1798', 'chapter_9', 9, 'narration', 1798, '', '', '星野爱把树叶伸向天空，微弱的阳光透过缝隙和小孔洒落下来。', '', '', '', '', 's1799', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1799', 'chapter_9', 9, 'narration', 1799, '', '', '她眯起眼睛望向光源。', '', '', '', '', 's1800', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1800', 'chapter_9', 9, 'dialogue', 1800, 'ai', '星野爱', '我觉得那几天很开心，很幸福！', '', '', '', '', 's1801', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1801', 'chapter_9', 9, 'dialogue', 1801, 'taku', '顾天鹏', '有多幸福？', '', '', '', '', 's1802', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1802', 'chapter_9', 9, 'dialogue', 1802, 'ai', '星野爱', '就像整个人都睡进了蜜糖里一样。又像是飘上了蓝天，钻进了最喜欢的那朵白色的云彩里面。', '', '', '', '', 's1803', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1803', 'chapter_9', 9, 'dialogue', 1803, 'taku', '顾天鹏', '果然喜欢甜食？', '', '', '', '', 's1804', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1804', 'chapter_9', 9, 'dialogue', 1804, 'ai', '星野爱', '笨蛋吗？', '', '', '', '', 's1805', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1805', 'chapter_9', 9, 'dialogue', 1805, 'taku', '顾天鹏', '开玩笑的。', '', '', '', '', 's1806', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1806', 'chapter_9', 9, 'dialogue', 1806, 'ai', '星野爱', '我知道。', '', '', '', '', 's1807', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1807', 'chapter_9', 9, 'narration', 1807, '', '', '树底下，他们静静地坐在那里，望着缓缓偏移的树影。', '', '', '', '', 's1808', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1808', 'chapter_9', 9, 'dialogue', 1808, 'ai', '星野爱', '从未有过的感觉。', '', '', '', '', 's1809', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1809', 'chapter_9', 9, 'narration', 1809, '', '', '良久，星野爱开口，语气带着几分茫然。', '', '', '', '', 's1810', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1810', 'chapter_9', 9, 'dialogue', 1810, 'ai', '星野爱', '我也描述不清了，为什么会很开心，很幸福。一想到冬天，我就想到鸟居，想到神社，想到炸天妇罗，想到滑雪和打雪仗，想到草莓村，想到温泉，想到月色，想到咖啡屋…… 你也记得那支水仙花吧？总之，就好像有电流划过身体一样，很喜欢，很幸福，可我却说不清缘由。', '', '', '', '', 's1811', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1811', 'chapter_9', 9, 'narration', 1811, '', '', '突如其来的一阵强风席卷而来，吹得满地树叶漫天飞舞。', '', '', '', '', 's1812', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1812', 'chapter_9', 9, 'narration', 1812, '', '', '星野爱抬手遮挡，片刻之后风便停歇。', '', '', '', '', 's1813', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1813', 'chapter_9', 9, 'set', 1813, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1814', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1814', 'chapter_9', 9, 'set', 1814, '', '', '', '', '', 'ai_sprite_position', 'near', 's1815', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1815', 'chapter_9', 9, 'set', 1815, '', '', '', '', '', 'event_cg_mode', 'false', 's1816', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1816', 'chapter_9', 9, 'scene', 1816, '', '', '', 'bg ch9_roadside_steps', '', '', '', 's1817', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1817', 'chapter_9', 9, 'sprite', 1817, '', '', '', '', '[{"image": "heroine karuizawa_shy", "pos": "heroine_karuizawa_near"}]', '', '', 's1818', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1818', 'chapter_9', 9, 'dialogue', 1818, 'ai', '星野爱', '但我连喜欢的理由是什么都不知道。', '', '', '', '', 's1819', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1819', 'chapter_9', 9, 'dialogue', 1819, 'taku', '顾天鹏', '那都不要紧。', '', '', '', '', 's1820', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1820', 'chapter_9', 9, 'narration', 1820, '', '', '她扭过头，看见穿过云层、穿过繁茂枝叶、穿过山间薄雾的日光，尽数落在少年的脸庞上，明亮又耀眼。', '', '', '', '', 's1821', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1821', 'chapter_9', 9, 'narration', 1821, '', '', '她心中早有察觉，却依旧忍不住心头一动。', '', '', '', '', 's1822', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1822', 'chapter_9', 9, 'dialogue', 1822, 'ai', '星野爱', '不要紧？', '', '', '', '', 's1823', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1823', 'chapter_9', 9, 'dialogue', 1823, 'taku', '顾天鹏', '你还会喜欢上秋天，还会喜欢上夏天，还会喜欢上春天。', '', '', '', '', 's1824', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1824', 'chapter_9', 9, 'dialogue', 1824, 'ai', '星野爱', '喜欢的太多了吧？', '', '', '', '', 's1825', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1825', 'chapter_9', 9, 'dialogue', 1825, 'taku', '顾天鹏', '你不是星野爱吗？', '', '', '', '', 's1826', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1826', 'chapter_9', 9, 'narration', 1826, '', '', '星野爱望着他。', '', '', '', '', 's1827', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1827', 'chapter_9', 9, 'dialogue', 1827, 'taku', '顾天鹏', '你是世界上最最贪婪的少女，多喜欢一点怎么了？', '', '', '', '', 's1828', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1828', 'chapter_9', 9, 'dialogue', 1828, 'ai', '星野爱', '我……', '', '', '', '', 's1829', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1829', 'chapter_9', 9, 'dialogue', 1829, 'taku', '顾天鹏', '了不起的、贪婪的星野爱，不是吗？', '', '', '', '', 's1830', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1830', 'chapter_9', 9, 'dialogue', 1830, 'ai', '星野爱', '也是。', '', '', '', '', 's1831', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1831', 'chapter_9', 9, 'narration', 1831, '', '', '星野爱的脸上绽放出前所未有的灿烂笑容。', '', '', '', '', 's1832', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1832', 'chapter_9', 9, 'narration', 1832, '', '', '树影斑驳，偶尔有行人驱车路过，清脆的车铃声在林间回荡不休。', '', '', '', '', 's1833', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1833', 'chapter_9', 9, 'dialogue', 1833, 'ai', '星野爱', '我想，我在越后汤泽喜欢上了冬天！', '', '', '', '', 's1834', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1834', 'chapter_9', 9, 'dialogue', 1834, 'taku', '顾天鹏', '其实是秋天。', '', '', '', '', 's1835', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1835', 'chapter_9', 9, 'dialogue', 1835, 'ai', '星野爱', '冬天！', '', '', '', '', 's1836', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1836', 'chapter_9', 9, 'dialogue', 1836, 'taku', '顾天鹏', '冬天。', '', '', '', '', 's1837', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1837', 'chapter_9', 9, 'set', 1837, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1838', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1838', 'chapter_9', 9, 'set', 1838, '', '', '', '', '', 'event_cg_mode', 'true', 's1839', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1839', 'chapter_9', 9, 'scene', 1839, '', '', '', 'cg ch9_autumn_promise', '', '', '', 's1840', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1840', 'chapter_9', 9, 'narration', 1840, '', '', '星野爱也站起身，抬手拂开耳边散落的长发，余风轻轻撩动她的发梢。', '', '', '', '', 's1841', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1841', 'chapter_9', 9, 'narration', 1841, '', '', '在顾天鹏眼中，此刻的她，宛若自林间仙境走来的花灵。', '', '', '', '', 's1842', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1842', 'chapter_9', 9, 'dialogue', 1842, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1843', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1843', 'chapter_9', 9, 'narration', 1843, '', '', '她笑意盈盈，眉眼弯起，笑容比樱花烂漫，比梧桐温柔。', '', '', '', '', 's1844', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1844', 'chapter_9', 9, 'dialogue', 1844, 'ai', '星野爱', '接下来，我想在这个地方，在轻井泽，喜欢上秋天。', '', '', '', '', 's1845', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1845', 'chapter_9', 9, 'dialogue', 1845, 'taku', '顾天鹏', '你可是星野爱，喜欢便是了。', '', '', '', '', 's1846', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1846', 'chapter_9', 9, 'narration', 1846, '', '', '她微微侧头，眼眸亮如星辰。', '', '', '', '', 's1847', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1847', 'chapter_9', 9, 'dialogue', 1847, 'ai', '星野爱', '可以吗？', '', '', '', '', 's1848', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1848', 'chapter_9', 9, 'narration', 1848, '', '', '风声在林间喧嚣，树叶却只是轻轻颤动，隐约能听见彼此沉稳的心跳声。', '', '', '', '', 's1849', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1849', 'chapter_9', 9, 'narration', 1849, '', '', '顾天鹏回过神，扬起笑容。', '', '', '', '', 's1850', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1850', 'chapter_9', 9, 'set', 1850, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1851', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1851', 'chapter_9', 9, 'set', 1851, '', '', '', '', '', 'ai_sprite_position', 'right', 's1852', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1852', 'chapter_9', 9, 'set', 1852, '', '', '', '', '', 'event_cg_mode', 'false', 's1853', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1853', 'chapter_9', 9, 'scene', 1853, '', '', '', 'bg ch9_roadside_steps', '', '', '', 's1854', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1854', 'chapter_9', 9, 'sprite', 1854, '', '', '', '', '[{"image": "heroine karuizawa_speak", "pos": "heroine_karuizawa_right"}]', '', '', 's1855', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1855', 'chapter_9', 9, 'dialogue', 1855, 'taku', '顾天鹏', '可以，请在轻井泽喜欢上秋天。', '', '', '', '', 's1856', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1856', 'chapter_9', 9, 'dialogue', 1856, 'ai', '星野爱', '要怎么做？', '', '', '', '', 's1857', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1857', 'chapter_9', 9, 'dialogue', 1857, 'taku', '顾天鹏', '逛街、漫步河边、泛舟、在不冷不热的天气里吃上一口冰淇淋、尝一次世间难得的苹果派，这些都可以。', '', '', '', '', 's1858', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1858', 'chapter_9', 9, 'dialogue', 1858, 'ai', '星野爱', '还不够。', '', '', '', '', 's1859', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1859', 'chapter_9', 9, 'dialogue', 1859, 'taku', '顾天鹏', '钓鱼、逛书店、路过教堂，站在西式建筑前坦然说出：我喜欢这里，喜欢轻井泽的秋天。', '', '', '', '', 's1860', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1860', 'chapter_9', 9, 'dialogue', 1860, 'ai', '星野爱', '还不够！', '', '', '', '', 's1861', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1861', 'chapter_9', 9, 'dialogue', 1861, 'taku', '顾天鹏', '还有很多很多有趣的事。', '', '', '', '', 's1862', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1862', 'chapter_9', 9, 'narration', 1862, '', '', '顾天鹏柔声说道。', '', '', '', '', 's1863', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1863', 'chapter_9', 9, 'narration', 1863, '', '', '星野爱笑意更深。', '', '', '', '', 's1864', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1864', 'chapter_9', 9, 'dialogue', 1864, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1865', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1865', 'chapter_9', 9, 'narration', 1865, '', '', '她背着手，身上淡淡的香气随着微风飘至少年身前，语气满是雀跃。', '', '', '', '', 's1866', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1866', 'chapter_9', 9, 'dialogue', 1866, 'ai', '星野爱', '请，让我喜欢上轻井泽的秋天。', '', '', '', '', 's1867', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1867', 'chapter_9', 9, 'dialogue', 1867, 'taku', '顾天鹏', '嗯，在冬天之后，喜欢上秋天。', '', '', '', '', 's1868', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1868', 'chapter_9', 9, 'narration', 1868, '', '', '顾天鹏轻笑出声。', '', '', '', '', 's1869', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1869', 'chapter_9', 9, 'dialogue', 1869, 'taku', '顾天鹏', '听起来怪怪的。', '', '', '', '', 's1870', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1870', 'chapter_9', 9, 'dialogue', 1870, 'ai', '星野爱', '不会。', '', '', '', '', 's1871', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1871', 'chapter_9', 9, 'narration', 1871, '', '', '星野爱笃定地摇头，眼底盛满温柔。', '', '', '', '', 's1872', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1872', 'chapter_9', 9, 'dialogue', 1872, 'ai', '星野爱', '因为冬天之后，是秋天。', '', '', '', '', 's1873', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1873', 'chapter_10', 10, 'set', 1873, '', '', '', '', '', 'ai_sprite_outfit', 'karuizawa', 's1874', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1874', 'chapter_10', 10, 'set', 1874, '', '', '', '', '', 'ai_sprite_position', 'center', 's1875', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1875', 'chapter_10', 10, 'set', 1875, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1876', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1876', 'chapter_10', 10, 'set', 1876, '', '', '', '', '', 'event_cg_mode', 'false', 's1877', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1877', 'chapter_10', 10, 'scene', 1877, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's1878', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1878', 'chapter_10', 10, 'narration', 1878, '', '', '祝你生日快乐', '', '', '', '', 's1879', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1879', 'chapter_10', 10, 'narration', 1879, '', '', '离开林间小道以后，旧轻井泽的街面在他们眼前缓缓铺开。', '', '', '', '', 's1880', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1880', 'chapter_10', 10, 'narration', 1880, '', '', '西式木屋、石板路、玻璃橱窗和一排排被秋色染亮的树冠，像是从某本旅行手账里翻出来的插画。', '', '', '', '', 's1881', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1881', 'chapter_10', 10, 'narration', 1881, '', '', '空气里有烘烤面包的香气，也有甜点、咖啡、烤鱼和热油交错在一起的味道。', '', '', '', '', 's1882', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1882', 'chapter_10', 10, 'narration', 1882, '', '', '顾天鹏还没来得及确认方向，星野爱已经被整条街夺走了注意力。', '', '', '', '', 's1883', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1883', 'chapter_10', 10, 'set', 1883, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1884', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1884', 'chapter_10', 10, 'set', 1884, '', '', '', '', '', 'ai_sprite_position', 'left', 's1885', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1885', 'chapter_10', 10, 'sprite', 1885, '', '', '', '', '[{"image": "heroine karuizawa_speak", "pos": "heroine_karuizawa_left"}]', '', '', 's1886', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1886', 'chapter_10', 10, 'dialogue', 1886, 'ai', '星野爱', '那边好香！', '', '', '', '', 's1887', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1887', 'chapter_10', 10, 'narration', 1887, '', '', '她指向街角冒着白烟的小摊。', '', '', '', '', 's1888', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1888', 'chapter_10', 10, 'dialogue', 1888, 'ai', '星野爱', '还有那家！那个看起来也很好吃！', '', '', '', '', 's1889', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1889', 'chapter_10', 10, 'dialogue', 1889, 'taku', '顾天鹏', '你刚才不是说要在轻井泽喜欢上秋天吗？', '', '', '', '', 's1890', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1890', 'chapter_10', 10, 'dialogue', 1890, 'ai', '星野爱', '吃东西当然也是喜欢秋天的一部分！', '', '', '', '', 's1891', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1891', 'chapter_10', 10, 'dialogue', 1891, 'taku', '顾天鹏', '这句话听起来很有说服力。', '', '', '', '', 's1892', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1892', 'chapter_10', 10, 'narration', 1892, '', '', '星野爱东张西望，眼睛像被橱窗里的糖果点亮。', '', '', '', '', 's1893', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1893', 'chapter_10', 10, 'dialogue', 1893, 'ai', '星野爱', '顾天鹏，我们先选哪一个？', '', '', '', '', 's1894', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1894', 'chapter_10', 10, 'dialogue', 1894, 'taku', '顾天鹏', '你先别把整条街都吃掉。', '', '', '', '', 's1895', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1895', 'chapter_10', 10, 'dialogue', 1895, 'ai', '星野爱', '我很克制的。', '', '', '', '', 's1896', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1896', 'chapter_10', 10, 'narration', 1896, '', '', '她说这话时，视线已经飘到斜对面的甜品店门口。', '', '', '', '', 's1897', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1897', 'chapter_10', 10, 'dialogue', 1897, 'taku', '顾天鹏', '那就先去那里？', '', '', '', '', 's1898', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1898', 'chapter_10', 10, 'dialogue', 1898, 'ai', '星野爱', '嗯，就那里！', '', '', '', '', 's1899', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1899', 'chapter_10', 10, 'set', 1899, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1900', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1900', 'chapter_10', 10, 'set', 1900, '', '', '', '', '', 'ai_sprite_position', 'right', 's1901', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1901', 'chapter_10', 10, 'set', 1901, '', '', '', '', '', 'event_cg_mode', 'false', 's1902', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1902', 'chapter_10', 10, 'scene', 1902, '', '', '', 'bg ch10_ice_cream_shop', '', '', '', 's1903', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1903', 'chapter_10', 10, 'sprite', 1903, '', '', '', '', '[{"image": "heroine karuizawa_speak", "pos": "heroine_karuizawa_right"}]', '', '', 's1904', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1904', 'chapter_10', 10, 'narration', 1904, '', '', '甜品店有两层，二楼露台摆着小圆桌，能看见街道尽头被山色托起的天空。', '', '', '', '', 's1905', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1905', 'chapter_10', 10, 'narration', 1905, '', '', '一楼的玻璃柜里陈列着各式蛋糕和冰淇淋，连空气都像被奶油和咖啡香浸软了。', '', '', '', '', 's1906', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1906', 'chapter_10', 10, 'dialogue', 1906, 'waitress', '侍应生', '欢迎光临。', '', '', '', '', 's1907', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1907', 'chapter_10', 10, 'dialogue', 1907, 'ai', '星野爱', '我要这个，咖啡果冻摩卡冰淇淋！', '', '', '', '', 's1908', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1908', 'chapter_10', 10, 'dialogue', 1908, 'taku', '顾天鹏', '你选得真快。', '', '', '', '', 's1909', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1909', 'chapter_10', 10, 'dialogue', 1909, 'ai', '星野爱', '美味的东西要趁它还没逃走之前抓住。', '', '', '', '', 's1910', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1910', 'chapter_10', 10, 'dialogue', 1910, 'taku', '顾天鹏', '冰淇淋不会逃走。', '', '', '', '', 's1911', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1911', 'chapter_10', 10, 'dialogue', 1911, 'ai', '星野爱', '但会融化。', '', '', '', '', 's1912', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1912', 'chapter_10', 10, 'narration', 1912, '', '', '她一本正经，仿佛刚说出了某种人生哲理。', '', '', '', '', 's1913', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1913', 'chapter_10', 10, 'set', 1913, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1914', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1914', 'chapter_10', 10, 'set', 1914, '', '', '', '', '', 'event_cg_mode', 'true', 's1915', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1915', 'chapter_10', 10, 'scene', 1915, '', '', '', 'cg ch10_ice_cream_walk', '', '', '', 's1916', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1916', 'chapter_10', 10, 'narration', 1916, '', '', '两人各自拿着一杯摩卡冰淇淋，沿着旧轻井泽的街道慢慢往前。', '', '', '', '', 's1917', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1917', 'chapter_10', 10, 'narration', 1917, '', '', '冰冷的甜味在舌尖散开，咖啡果冻微微发苦，反倒让奶油的香气变得更加鲜明。', '', '', '', '', 's1918', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1918', 'chapter_10', 10, 'narration', 1918, '', '', '星野爱小口小口吃着，像是在认真研究秋天到底是什么味道。', '', '', '', '', 's1919', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1919', 'chapter_10', 10, 'dialogue', 1919, 'ai', '星野爱', '这个也很幸福。', '', '', '', '', 's1920', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1920', 'chapter_10', 10, 'dialogue', 1920, 'taku', '顾天鹏', '你今天已经喜欢上好多东西了。', '', '', '', '', 's1921', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1921', 'chapter_10', 10, 'dialogue', 1921, 'ai', '星野爱', '不行吗？', '', '', '', '', 's1922', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1922', 'chapter_10', 10, 'dialogue', 1922, 'taku', '顾天鹏', '当然可以。', '', '', '', '', 's1923', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1923', 'chapter_10', 10, 'narration', 1923, '', '', '她满意地点头，发丝和围巾被街边的风轻轻拂起。', '', '', '', '', 's1924', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1924', 'chapter_10', 10, 'set', 1924, '', '', '', '', '', 'event_cg_mode', 'false', 's1925', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1925', 'chapter_10', 10, 'scene', 1925, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's1926', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1926', 'chapter_10', 10, 'narration', 1926, '', '', '他们继续沿着街道往前，路过橱窗、木质招牌和开在转角处的小花店。', '', '', '', '', 's1927', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1927', 'chapter_10', 10, 'narration', 1927, '', '', '旧轻井泽的秋天并不只在树上，也落在玻璃窗的反光里，落在行人慢慢放缓的步伐里。', '', '', '', '', 's1928', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1928', 'chapter_10', 10, 'set', 1928, '', '', '', '', '', 'event_cg_mode', 'false', 's1929', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1929', 'chapter_10', 10, 'scene', 1929, '', '', '', 'bg ch10_white_church_wedding', '', '', '', 's1930', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1930', 'chapter_10', 10, 'narration', 1930, '', '', '后来，他们在街道尽头附近看见一座白色教堂。', '', '', '', '', 's1931', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1931', 'chapter_10', 10, 'narration', 1931, '', '', '教堂前似乎刚办完婚礼，亲友们围在草坪边鼓掌，彩带和气球一起升向蓝天。', '', '', '', '', 's1932', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1932', 'chapter_10', 10, 'narration', 1932, '', '', '白鸽从屋檐上掠起，翅膀擦过阳光，木管乐器的声音混进风里。', '', '', '', '', 's1933', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1933', 'chapter_10', 10, 'narration', 1933, '', '', '星野爱停下脚步，手里的冰淇淋被她忘在一边。', '', '', '', '', 's1934', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1934', 'chapter_10', 10, 'set', 1934, '', '', '', '', '', 'ai_sprite_mode', 'true', 's1935', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1935', 'chapter_10', 10, 'set', 1935, '', '', '', '', '', 'ai_sprite_position', 'near', 's1936', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1936', 'chapter_10', 10, 'sprite', 1936, '', '', '', '', '[{"image": "heroine karuizawa_shy", "pos": "heroine_karuizawa_near"}]', '', '', 's1937', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1937', 'chapter_10', 10, 'dialogue', 1937, 'ai', '星野爱', '真好啊。', '', '', '', '', 's1938', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1938', 'chapter_10', 10, 'dialogue', 1938, 'taku', '顾天鹏', '光是站在旁边看，好像也会被分到一点快乐。', '', '', '', '', 's1939', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1939', 'chapter_10', 10, 'dialogue', 1939, 'ai', '星野爱', '快乐会传给别人吗？', '', '', '', '', 's1940', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1940', 'chapter_10', 10, 'dialogue', 1940, 'taku', '顾天鹏', '我觉得会。', '', '', '', '', 's1941', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1941', 'chapter_10', 10, 'dialogue', 1941, 'ai', '星野爱', '那难过呢？', '', '', '', '', 's1942', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1942', 'chapter_10', 10, 'dialogue', 1942, 'taku', '顾天鹏', '大概也会。', '', '', '', '', 's1943', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1943', 'chapter_10', 10, 'narration', 1943, '', '', '星野爱望着被簇拥的新娘，目光温柔得不像是在看陌生人。', '', '', '', '', 's1944', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1944', 'chapter_10', 10, 'dialogue', 1944, 'ai', '星野爱', '恋爱以后会有婚礼，婚礼以后，会有属于两个人的孩子吧。', '', '', '', '', 's1945', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1945', 'chapter_10', 10, 'narration', 1945, '', '', '她像是在说很遥远的事，又像是在试探某扇不愿打开的门。', '', '', '', '', 's1946', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1946', 'chapter_10', 10, 'dialogue', 1946, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's1947', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1947', 'chapter_10', 10, 'dialogue', 1947, 'taku', '顾天鹏', '嗯？', '', '', '', '', 's1948', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1948', 'chapter_10', 10, 'dialogue', 1948, 'ai', '星野爱', '孩子也会幸福吗？', '', '', '', '', 's1949', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1950', 'chapter_10', 10, 'narration', 1950, '', '', '顾天鹏知道这个问题不能用玩笑接住。', '', '', '', '', 's1951', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1951', 'chapter_10', 10, 'narration', 1951, '', '', '哪怕答案轻得没有分量，他也必须把它说得足够认真。', '', '', '', '', 's1952', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1952', 'chapter_10', 10, 'dialogue', 1952, 'taku', '顾天鹏', '会的。', '', '', '', '', 's1953', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1953', 'chapter_10', 10, 'narration', 1953, '', '', '话一出口，顾天鹏才发现自己的回答轻得像羽毛。', '', '', '', '', 's1954', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1954', 'chapter_10', 10, 'narration', 1954, '', '', '答案太快，像一张没有展开的纸。星野爱收下了它，却没有把真正的问题继续递出来。', '', '', '', '', 's1955', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1955', 'chapter_10', 10, 'narration', 1955, '', '', '他们在教堂前多站了一会儿，才把那阵掌声和阴影一起留在身后。', '', '', '', '', 's1956', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1956', 'chapter_10', 10, 'jump', 1956, '', '', '', '', '', '', '', 's3654', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1957', 'chapter_10', 10, 'narration', 1957, '', '', '顾天鹏差点直接回答，却又在最后一刻停住。', '', '', '', '', 's1958', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1958', 'chapter_10', 10, 'narration', 1958, '', '', '有些问题表面上只要一个答案，真正需要的却是有人愿意追问。', '', '', '', '', 's1959', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1959', 'chapter_10', 10, 'dialogue', 1959, 'taku', '顾天鹏', '为什么突然这么想？', '', '', '', '', 's1960', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1960', 'chapter_10', 10, 'dialogue', 1960, 'ai', '星野爱', '因为我不知道。', '', '', '', '', 's1961', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1961', 'chapter_10', 10, 'narration', 1961, '', '', '她没有看他，指尖轻轻攥住外套袖口。', '', '', '', '', 's1962', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1962', 'chapter_10', 10, 'dialogue', 1962, 'ai', '星野爱', '我不知道幸福这种东西，会不会也需要有人先教。', '', '', '', '', 's1963', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1963', 'chapter_10', 10, 'dialogue', 1963, 'taku', '顾天鹏', '会的。至少不该由孩子来承担大人的空白。', '', '', '', '', 's1964', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1964', 'chapter_10', 10, 'narration', 1964, '', '', '这一次，答案不是直接落下去的，而是绕过她真正害怕的地方，慢慢放到她手边。', '', '', '', '', 's1971', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1965', 'chapter_10', 10, 'narration', 1965, '', '', '顾天鹏看着白色教堂前被风吹起的彩带，忽然没有立刻回答。', '', '', '', '', 's1966', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1966', 'chapter_10', 10, 'dialogue', 1966, 'taku', '顾天鹏', '我不知道一句话能不能回答这个。', '', '', '', '', 's1967', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1967', 'chapter_10', 10, 'dialogue', 1967, 'ai', '星野爱', '那要怎么办？', '', '', '', '', 's1968', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1968', 'chapter_10', 10, 'dialogue', 1968, 'taku', '顾天鹏', '以后再确认。等你真的想知道的时候，我陪你一起看。', '', '', '', '', 's1969', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1969', 'chapter_10', 10, 'narration', 1969, '', '', '星野爱眨了眨眼，像是第一次听见有人把未来说得这么笨拙。', '', '', '', '', 's1970', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1970', 'chapter_10', 10, 'jump', 1970, '', '', '', '', '', '', '', 's3683', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1949', 'chapter_10', 10, 'menu', 1949, '', '', '', '', '', '', '', 's1971', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1971', 'chapter_10', 10, 'dialogue', 1971, 'ai', '星野爱', '可是，我好像没有那样觉得过。', '', '', '', '', 's1972', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1972', 'chapter_10', 10, 'narration', 1972, '', '', '周围的掌声仍在继续，然而顾天鹏却听见有什么细小的东西在她眼底碎开。', '', '', '', '', 's1973', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1973', 'chapter_10', 10, 'narration', 1973, '', '', '那不是谎言，也不是玩笑。', '', '', '', '', 's1974', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1974', 'chapter_10', 10, 'dialogue', 1974, 'ai', '星野爱', '啊。', '', '', '', '', 's1975', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1975', 'chapter_10', 10, 'narration', 1975, '', '', '下一秒，星野爱重新笑起来，笑容明亮得近乎匆忙。', '', '', '', '', 's1976', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1976', 'chapter_10', 10, 'dialogue', 1976, 'ai', '星野爱', '刚才那个是玩笑，别露出这种表情嘛。', '', '', '', '', 's1977', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1977', 'chapter_10', 10, 'dialogue', 1977, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's1978', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1978', 'chapter_10', 10, 'narration', 1978, '', '', '顾天鹏没有拆穿她，也不知道该如何安慰。', '', '', '', '', 's1979', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1979', 'chapter_10', 10, 'set', 1979, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1980', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1980', 'chapter_10', 10, 'scene', 1980, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's1981', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1981', 'chapter_10', 10, 'narration', 1981, '', '', '他们离开教堂时，街上的风突然变得有些吵。', '', '', '', '', 's1982', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1982', 'chapter_10', 10, 'narration', 1982, '', '', '边上经过了什么店，橱窗里摆着什么颜色的餐盘，谁也没有认真记住。', '', '', '', '', 's1983', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1983', 'chapter_10', 10, 'set', 1983, '', '', '', '', '', 'ai_sprite_mode', 'false', 's1984', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1984', 'chapter_10', 10, 'set', 1984, '', '', '', '', '', 'event_cg_mode', 'false', 's1985', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1985', 'chapter_10', 10, 'scene', 1985, '', '', '', 'bg ch10_lunch_restaurant', '', '', '', 's1986', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1986', 'chapter_10', 10, 'narration', 1986, '', '', '午饭是在一家气派的西式餐厅里解决的。', '', '', '', '', 's1987', '');
