INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1994', 'chapter_10', 10, 'narration', 1994, '', '', '她托着脸，语气轻快，眼底却还残留着一点散不去的雾。', '', '', '', '', 's1995', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1995', 'chapter_10', 10, 'dialogue', 1995, 'taku', '顾天鹏', '好。', '', '', '', '', 's1996', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1996', 'chapter_10', 10, 'dialogue', 1996, 'ai', '星野爱', '答应得这么快？', '', '', '', '', 's1997', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s1997', 'chapter_10', 10, 'dialogue', 1997, 'taku', '顾天鹏', '你不是想喜欢上轻井泽的秋天吗？蛋糕应该也算。', '', '', '', '', 's1998', '');
