INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2003', 'chapter_10', 10, 'narration', 2003, '', '', '午饭之后，下午的阳光变得更轻，街上的影子被树叶筛成细碎的形状。', '', '', '', '', 's2004', '');
