INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2009', 'chapter_10', 10, 'sprite', 2009, '', '', '', '', '[{"image": "heroine karuizawa_surprised", "pos": "heroine_karuizawa_right"}]', '', '', 's2010', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2010', 'chapter_10', 10, 'narration', 2010, '', '', '下午，他们走进一家小小的蛋糕店。', '', '', '', '', 's2011', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2011', 'chapter_10', 10, 'narration', 2011, '', '', '店员把巧克力奶油蛋糕放进蓝色礼盒，又用红丝带扎成规整的蝴蝶结。', '', '', '', '', 's2012', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2012', 'chapter_10', 10, 'dialogue', 2012, 'waitress', '侍应生', '需要配蜡烛吗？', '', '', '', '', 's2013', '');
