INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2015', 'chapter_10', 10, 'narration', 2015, '', '', '星野爱几乎立刻抢答。', '', '', '', '', 's2016', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2016', 'chapter_10', 10, 'dialogue', 2016, 'taku', '顾天鹏', '这么坚定？', '', '', '', '', 's2017', '');
