INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2021', 'chapter_10', 10, 'set', 2021, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2022', '');
