INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2023', 'chapter_10', 10, 'narration', 2023, '', '', '傍晚，他们沿着林间路返回旅馆。', '', '', '', '', 's2024', '');
