INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2025', 'chapter_10', 10, 'narration', 2025, '', '', '风开始变凉，树叶在脚边翻滚，旧轻井泽热闹的声音被一点点丢在身后。', '', '', '', '', 's2026', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2026', 'chapter_10', 10, 'set', 2026, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2027', '');
