INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2030', 'chapter_10', 10, 'narration', 2030, '', '', '回到房间后，两人打开电视看了一会儿棒球赛。', '', '', '', '', 's2031', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2031', 'chapter_10', 10, 'narration', 2031, '', '', '屏幕里的观众欢呼雀跃，比分却变化得毫无道理。', '', '', '', '', 's2032', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2032', 'chapter_10', 10, 'dialogue', 2032, 'taku', '顾天鹏', '刚才还领先。', '', '', '', '', 's2033', '');
