INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2035', 'chapter_10', 10, 'dialogue', 2035, 'ai', '星野爱', '也可能只是我们没有看懂。', '', '', '', '', 's2036', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2036', 'chapter_10', 10, 'narration', 2036, '', '', '他们对视一眼，同时失去继续看的兴致。', '', '', '', '', 's2037', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2037', 'chapter_10', 10, 'narration', 2037, '', '', '电视被关掉以后，房间忽然安静下来，窗外的竹林被灯光照出一小片柔和的轮廓。', '', '', '', '', 's2038', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2038', 'chapter_10', 10, 'set', 2038, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2039', '');
