INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2040', 'chapter_10', 10, 'scene', 2040, '', '', '', 'cg ch10_birthday_cake_candles', '', '', '', 's2041', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2041', 'chapter_10', 10, 'narration', 2041, '', '', '七点左右，他们拆开礼盒，把蛋糕放在矮桌中央。', '', '', '', '', 's2042', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2042', 'chapter_10', 10, 'narration', 2042, '', '', '蓝色盒子、红色丝带、塑料刀叉和一把细小的蜡烛，全部散在桌面上。', '', '', '', '', 's2043', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2043', 'chapter_10', 10, 'narration', 2043, '', '', '顾天鹏数了十六根蜡烛，一根一根插进巧克力奶油里。', '', '', '', '', 's2044', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2044', 'chapter_10', 10, 'narration', 2044, '', '', '火柴燃起，橘色的小火苗在房间里晃动。', '', '', '', '', 's2045', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2045', 'chapter_10', 10, 'dialogue', 2045, 'taku', '顾天鹏', '祝你生日快乐。', '', '', '', '', 's2046', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2046', 'chapter_10', 10, 'dialogue', 2046, 'ai', '星野爱', '今天才不是我的生日。', '', '', '', '', 's2047', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2047', 'chapter_10', 10, 'narration', 2047, '', '', '星野爱笑了。', '', '', '', '', 's2048', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2048', 'chapter_10', 10, 'narration', 2048, '', '', '不是白天教堂前那种仓促的笑，而是柔软、明亮，像被烛光慢慢照出来的笑。', '', '', '', '', 's2049', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2049', 'chapter_10', 10, 'narration', 2049, '', '', '蜡烛烧到一半，门缝里钻进一阵晚风，十六点火光几乎同时熄灭。', '', '', '', '', 's2050', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2050', 'chapter_10', 10, 'dialogue', 2050, 'taku', '顾天鹏', '我再点一次。', '', '', '', '', 's2051', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2051', 'chapter_10', 10, 'dialogue', 2051, 'ai', '星野爱', '不用了。', '', '', '', '', 's2052', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2052', 'chapter_10', 10, 'narration', 2052, '', '', '她伸手按住顾天鹏的手背，动作很轻。', '', '', '', '', 's2053', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2053', 'chapter_10', 10, 'dialogue', 2053, 'ai', '星野爱', '这样就很好。', '', '', '', '', 's2054', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2054', 'chapter_10', 10, 'narration', 2054, '', '', '两人切下一小块蛋糕，又把它分成两半。', '', '', '', '', 's2055', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2055', 'chapter_10', 10, 'narration', 2055, '', '', '甜味比下午的冰淇淋更浓，却没有人吃得太快。', '', '', '', '', 's2056', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2056', 'chapter_10', 10, 'scene', 2056, '', '', '', 'cg ch10_night_cake_still', '', '', '', 's2057', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2057', 'chapter_10', 10, 'narration', 2057, '', '', '睡觉以前，蛋糕还剩下大半，安静地停在桌上。', '', '', '', '', 's2058', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2058', 'chapter_10', 10, 'narration', 2058, '', '', '熄灭的蜡烛歪在奶油里，红丝带落在一旁，像一条被夜色收起的小路。', '', '', '', '', 's2059', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2059', 'chapter_10', 10, 'narration', 2059, '', '', '那幅画面没有掌声，没有音乐，也没有生日歌。', '', '', '', '', 's2060', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2060', 'chapter_10', 10, 'narration', 2060, '', '', '但顾天鹏想，星野爱或许会记得。', '', '', '', '', 's2061', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2061', 'chapter_10', 10, 'narration', 2061, '', '', '至少，他会记得。', '', '', '', '', 's2062', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2062', 'chapter_11', 11, 'set', 2062, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2063', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2063', 'chapter_11', 11, 'set', 2063, '', '', '', '', '', 'ai_sprite_position', 'center', 's2064', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2064', 'chapter_11', 11, 'set', 2064, '', '', '', '', '', 'ai_sprite_outfit', 'autumn', 's2065', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2065', 'chapter_11', 11, 'set', 2065, '', '', '', '', '', 'event_cg_mode', 'false', 's2066', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2066', 'chapter_11', 11, 'scene', 2066, '', '', '', 'bg ch11_birch_morning_run', '', '', '', 's2067', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2067', 'chapter_11', 11, 'narration', 2067, '', '', '所有的一切，请记得真切', '', '', '', '', 's2068', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2068', 'chapter_11', 11, 'narration', 2068, '', '', '第二天，顾天鹏醒得很早。', '', '', '', '', 's2069', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2069', 'chapter_11', 11, 'narration', 2069, '', '', '旅馆外的林道还浸在清晨的蓝色里，桦木和落叶松一路向前延伸，薄雾贴着地面缓缓散开。', '', '', '', '', 's2070', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2070', 'chapter_11', 11, 'narration', 2070, '', '', '他沿着平坦的小路跑了几个来回。脚下的落叶被踩出轻响，呼吸在微凉的空气里变得清楚。', '', '', '', '', 's2071', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2071', 'chapter_11', 11, 'narration', 2071, '', '', '跑到第五公里时，天色终于亮起来。远处的山影被晨光镀上一层淡金色。', '', '', '', '', 's2072', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2072', 'chapter_11', 11, 'narration', 2072, '', '', '这种疲惫并不轻松，却让人确认自己还在一步一步向前。', '', '', '', '', 's2073', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2073', 'chapter_11', 11, 'set', 2073, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2074', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2074', 'chapter_11', 11, 'set', 2074, '', '', '', '', '', 'ai_sprite_position', 'right', 's2075', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2075', 'chapter_11', 11, 'set', 2075, '', '', '', '', '', 'event_cg_mode', 'false', 's2076', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2076', 'chapter_11', 11, 'scene', 2076, '', '', '', 'bg ch11_inn_morning_room', '', '', '', 's2077', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2077', 'chapter_11', 11, 'sprite', 2077, '', '', '', '', '[{"image": "heroine autumn_neutral", "pos": "heroine_autumn_right"}]', '', '', 's2078', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2078', 'chapter_11', 11, 'narration', 2078, '', '', '回到房间时，星野爱已经洗好头，正坐在窗边吹干长发。', '', '', '', '', 's2079', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2079', 'chapter_11', 11, 'narration', 2079, '', '', '粉色发圈放在矮桌上，吹风机的热风把她的发梢吹得轻轻晃动。', '', '', '', '', 's2080', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2080', 'chapter_11', 11, 'dialogue', 2080, 'ai', '星野爱', '又去锻炼了？', '', '', '', '', 's2081', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2081', 'chapter_11', 11, 'dialogue', 2081, 'taku', '顾天鹏', '嗯，趁你还没醒。', '', '', '', '', 's2082', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2082', 'chapter_11', 11, 'dialogue', 2082, 'ai', '星野爱', '每天跑不累吗？', '', '', '', '', 's2083', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2083', 'chapter_11', 11, 'dialogue', 2083, 'taku', '顾天鹏', '会累。', '', '', '', '', 's2084', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2084', 'chapter_11', 11, 'narration', 2084, '', '', '顾天鹏把外套挂到一边，忍不住笑了笑。', '', '', '', '', 's2085', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2085', 'chapter_11', 11, 'dialogue', 2085, 'taku', '顾天鹏', '不过我喜欢那种坚持下来的感觉。', '', '', '', '', 's2086', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2086', 'chapter_11', 11, 'dialogue', 2086, 'ai', '星野爱', '真厉害。', '', '', '', '', 's2087', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2087', 'chapter_11', 11, 'dialogue', 2087, 'taku', '顾天鹏', '和你一样。', '', '', '', '', 's2088', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2088', 'chapter_11', 11, 'dialogue', 2088, 'ai', '星野爱', '我？', '', '', '', '', 's2089', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2089', 'chapter_11', 11, 'dialogue', 2089, 'taku', '顾天鹏', '你也一直在努力。', '', '', '', '', 's2090', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2090', 'chapter_11', 11, 'narration', 2090, '', '', '星野爱没有立刻回答，只是把吹风机放下，将头发一点一点拢起。', '', '', '', '', 's2091', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2091', 'chapter_11', 11, 'narration', 2091, '', '', '她用粉色发圈扎好发尾，回头看向他。', '', '', '', '', 's2092', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2092', 'chapter_11', 11, 'dialogue', 2092, 'ai', '星野爱', '欢迎回来。', '', '', '', '', 's2093', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2093', 'chapter_11', 11, 'dialogue', 2093, 'taku', '顾天鹏', '我回来了。', '', '', '', '', 's2094', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2094', 'chapter_11', 11, 'set', 2094, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2095', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2095', 'chapter_11', 11, 'scene', 2095, '', '', '', 'bg ch11_inn_morning_room', '', '', '', 's2096', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2096', 'chapter_11', 11, 'narration', 2096, '', '', '洗漱、换衣服、确认背包里的零钱和相机以后，两人骑上旅馆租来的自行车，沿着林间路慢慢驶向旧轻井泽。', '', '', '', '', 's2097', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2097', 'chapter_11', 11, 'narration', 2097, '', '', '路边的树影一段明一段暗，像有人把秋天剪成了长长的胶片。', '', '', '', '', 's2098', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2098', 'chapter_11', 11, 'set', 2098, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2099', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2099', 'chapter_11', 11, 'set', 2099, '', '', '', '', '', 'ai_sprite_position', 'left', 's2100', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2100', 'chapter_11', 11, 'scene', 2100, '', '', '', 'bg ch11_breakfast_cafe', '', '', '', 's2101', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2101', 'chapter_11', 11, 'sprite', 2101, '', '', '', '', '[{"image": "heroine autumn_speak", "pos": "heroine_autumn_left"}]', '', '', 's2102', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2102', 'chapter_11', 11, 'narration', 2102, '', '', '早餐是在一间带露台的咖啡馆里解决的。', '', '', '', '', 's2103', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2103', 'chapter_11', 11, 'narration', 2103, '', '', '木头被阳光烘出温柔的香味，桌上摆着咖啡、鸡蛋三明治和刚切开的水果。', '', '', '', '', 's2104', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2104', 'chapter_11', 11, 'dialogue', 2104, 'ai', '星野爱', '这里的咖啡味道好温柔。', '', '', '', '', 's2105', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2105', 'chapter_11', 11, 'dialogue', 2105, 'taku', '顾天鹏', '咖啡也能温柔吗？', '', '', '', '', 's2106', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2106', 'chapter_11', 11, 'dialogue', 2106, 'ai', '星野爱', '能啊。现在这杯就是。', '', '', '', '', 's2107', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2107', 'chapter_11', 11, 'dialogue', 2107, 'taku', '顾天鹏', '那三明治呢？', '', '', '', '', 's2108', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2108', 'chapter_11', 11, 'dialogue', 2108, 'ai', '星野爱', '三明治是可靠。', '', '', '', '', 's2109', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2109', 'chapter_11', 11, 'narration', 2109, '', '', '她煞有介事地点头，像是在给早餐写人物设定。', '', '', '', '', 's2110', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2110', 'chapter_11', 11, 'dialogue', 2110, 'taku', '顾天鹏', '听起来我输给了三明治。', '', '', '', '', 's2111', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2111', 'chapter_11', 11, 'dialogue', 2111, 'ai', '星野爱', '顾天鹏也很可靠。', '', '', '', '', 's2112', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2112', 'chapter_11', 11, 'narration', 2112, '', '', '她补得很快，补完又捧起咖啡杯，把笑意藏进升起的白雾里。', '', '', '', '', 's2113', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2113', 'chapter_11', 11, 'set', 2113, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2114', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2114', 'chapter_11', 11, 'scene', 2114, '', '', '', 'bg ch11_outlet_plaza', '', '', '', 's2115', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2115', 'chapter_11', 11, 'narration', 2115, '', '', '上午快结束时，他们从旧轻井泽的街道转向奥特莱斯。', '', '', '', '', 's2116', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2116', 'chapter_11', 11, 'narration', 2116, '', '', '广场上排列着明亮的橱窗，衣服、鞋子、餐厅和甜品店散在一条条步道两侧。', '', '', '', '', 's2117', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2117', 'chapter_11', 11, 'narration', 2117, '', '', '星野爱原本只是漫无目的地看，直到一件浅黄色 T 恤把她的脚步轻轻拽住。', '', '', '', '', 's2118', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2118', 'chapter_11', 11, 'set', 2118, '', '', '', '', '', 'event_cg_mode', 'true', 's2119', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2119', 'chapter_11', 11, 'scene', 2119, '', '', '', 'cg ch11_tshirt_tryon', '', '', '', 's2120', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2120', 'chapter_11', 11, 'narration', 2120, '', '', '试衣间外，星野爱换上那件印着小海豚的 T 恤，推开门时眼神有些得意。', '', '', '', '', 's2121', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2121', 'chapter_11', 11, 'dialogue', 2121, 'ai', '星野爱', '怎么样？', '', '', '', '', 's2122', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2122', 'chapter_11', 11, 'dialogue', 2122, 'taku', '顾天鹏', '很好看。', '', '', '', '', 's2123', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2123', 'chapter_11', 11, 'dialogue', 2123, 'ai', '星野爱', '衣服好看还是人好看？', '', '', '', '', 's2124', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2124', 'chapter_11', 11, 'dialogue', 2124, 'taku', '顾天鹏', '人更好看。', '', '', '', '', 's2125', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2125', 'chapter_11', 11, 'dialogue', 2125, 'ai', '星野爱', '谎言。', '', '', '', '', 's2126', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2126', 'chapter_11', 11, 'dialogue', 2126, 'taku', '顾天鹏', '这是事实。', '', '', '', '', 's2127', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2127', 'chapter_11', 11, 'dialogue', 2127, 'ai', '星野爱', '顾天鹏同学太礼貌了，礼貌到很可疑。', '', '', '', '', 's2128', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2128', 'chapter_11', 11, 'dialogue', 2128, 'taku', '顾天鹏', '那就当成不太可疑的事实。', '', '', '', '', 's2129', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2129', 'chapter_11', 11, 'narration', 2129, '', '', '星野爱低头看了看衣摆，唇角弯起。', '', '', '', '', 's2130', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2130', 'chapter_11', 11, 'dialogue', 2130, 'ai', '星野爱', '就算是谎言，我也不讨厌。', '', '', '', '', 's2131', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2131', 'chapter_11', 11, 'set', 2131, '', '', '', '', '', 'event_cg_mode', 'false', 's2132', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2132', 'chapter_11', 11, 'set', 2132, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2133', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2133', 'chapter_11', 11, 'set', 2133, '', '', '', '', '', 'ai_sprite_position', 'far', 's2134', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2134', 'chapter_11', 11, 'scene', 2134, '', '', '', 'bg ch11_outlet_plaza', '', '', '', 's2135', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2135', 'chapter_11', 11, 'sprite', 2135, '', '', '', '', '[{"image": "heroine autumn_neutral", "pos": "heroine_autumn_far"}]', '', '', 's2136', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2136', 'chapter_11', 11, 'narration', 2136, '', '', '最后，那件衣服并没有被买下。', '', '', '', '', 's2137', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2137', 'chapter_11', 11, 'dialogue', 2137, 'ai', '星野爱', '现在拿着袋子到处走太麻烦，而且这又不是夏天。', '', '', '', '', 's2138', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2138', 'chapter_11', 11, 'dialogue', 2138, 'taku', '顾天鹏', '那就夏天再来。', '', '', '', '', 's2139', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2139', 'chapter_11', 11, 'dialogue', 2139, 'ai', '星野爱', '夏天吗？', '', '', '', '', 's2140', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2140', 'chapter_11', 11, 'narration', 2140, '', '', '她重复了一遍这个词，像是在舌尖确认它的温度。', '', '', '', '', 's2141', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2141', 'chapter_11', 11, 'dialogue', 2141, 'taku', '顾天鹏', '到时候再买也不迟。', '', '', '', '', 's2142', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2142', 'chapter_11', 11, 'dialogue', 2142, 'ai', '星野爱', '嗯。', '', '', '', '', 's2143', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2143', 'chapter_11', 11, 'narration', 2143, '', '', '星野爱点点头，却又多看了一眼身后的橱窗。', '', '', '', '', 's2144', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2144', 'chapter_11', 11, 'set', 2144, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2145', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2145', 'chapter_11', 11, 'scene', 2145, '', '', '', 'bg ch11_riverside_meadow', '', '', '', 's2146', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2146', 'chapter_11', 11, 'narration', 2146, '', '', '离开奥特莱斯以后，城市的轮廓渐渐退开。', '', '', '', '', 's2147', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2147', 'chapter_11', 11, 'narration', 2147, '', '', '他们沿着河岸慢慢走，草地在风里起伏，细小的白花铺得到处都是。', '', '', '', '', 's2148', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2148', 'chapter_11', 11, 'narration', 2148, '', '', '午前的阳光比早晨明亮，河水却仍旧清澈得像刚醒来。', '', '', '', '', 's2149', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2149', 'chapter_11', 11, 'set', 2149, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2150', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2150', 'chapter_11', 11, 'set', 2150, '', '', '', '', '', 'ai_sprite_position', 'left', 's2151', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2151', 'chapter_11', 11, 'scene', 2151, '', '', '', 'bg ch11_flower_stand', '', '', '', 's2152', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2152', 'chapter_11', 11, 'sprite', 2152, '', '', '', '', '[{"image": "heroine autumn_speak", "pos": "heroine_autumn_left"}]', '', '', 's2153', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2153', 'chapter_11', 11, 'narration', 2153, '', '', '草地旁有个小小的花摊，木桶里插着几枝向日葵。', '', '', '', '', 's2154', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2154', 'chapter_11', 11, 'dialogue', 2154, 'flower_child', '卖花的孩子', '哥哥姐姐，要买花吗？', '', '', '', '', 's2155', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2155', 'chapter_11', 11, 'dialogue', 2155, 'ai', '星野爱', '向日葵！', '', '', '', '', 's2156', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2156', 'chapter_11', 11, 'narration', 2156, '', '', '星野爱几乎立刻停下脚步。', '', '', '', '', 's2157', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2157', 'chapter_11', 11, 'dialogue', 2157, 'taku', '顾天鹏', '你喜欢这个？', '', '', '', '', 's2158', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2158', 'chapter_11', 11, 'dialogue', 2158, 'ai', '星野爱', '刚才那家咖啡馆的高玻璃瓶里也插着一枝。放在桌上一定很好看。', '', '', '', '', 's2159', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2159', 'chapter_11', 11, 'dialogue', 2159, 'flower_child', '卖花的孩子', '漂亮姐姐和帅气哥哥，一人一枝会更好看。', '', '', '', '', 's2160', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2160', 'chapter_11', 11, 'dialogue', 2160, 'taku', '顾天鹏', '这孩子很会做生意。', '', '', '', '', 's2161', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2161', 'chapter_11', 11, 'dialogue', 2161, 'ai', '星野爱', '买一朵吧。', '', '', '', '', 's2162', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2163', 'chapter_11', 11, 'narration', 2163, '', '', '顾天鹏点头，没有把好意变成负担。她说一朵，那就让那一朵被好好记住。', '', '', '', '', 's2164', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2164', 'chapter_11', 11, 'dialogue', 2164, 'taku', '顾天鹏', '只买一朵？', '', '', '', '', 's2165', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2165', 'chapter_11', 11, 'dialogue', 2165, 'ai', '星野爱', '向日葵看起来很重，拿多了会累。大概八十克。', '', '', '', '', 's2166', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2166', 'chapter_11', 11, 'dialogue', 2166, 'taku', '顾天鹏', '你连这个都能估出来？', '', '', '', '', 's2167', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2167', 'chapter_11', 11, 'dialogue', 2167, 'ai', '星野爱', '当然是气势。', '', '', '', '', 's2168', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2168', 'chapter_11', 11, 'narration', 2168, '', '', '最后，卖花的孩子把那枝最亮的向日葵递给星野爱，又认真提醒她不要让花瓣碰到地面。', '', '', '', '', 's2177', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2169', 'chapter_11', 11, 'narration', 2169, '', '', '顾天鹏看着桶里的向日葵，忽然觉得如果只有她拿着花，这幅画会少掉一处呼应。', '', '', '', '', 's2170', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2170', 'chapter_11', 11, 'narration', 2170, '', '', '他决定多买一枝，哪怕最后还是会被她笑太夸张。', '', '', '', '', 's2171', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2171', 'chapter_11', 11, 'dialogue', 2171, 'taku', '顾天鹏', '两枝吧。', '', '', '', '', 's2172', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2172', 'chapter_11', 11, 'dialogue', 2172, 'ai', '星野爱', '向日葵看起来很重哦。', '', '', '', '', 's2173', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2173', 'chapter_11', 11, 'dialogue', 2173, 'taku', '顾天鹏', '大概八十克？', '', '', '', '', 's2174', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2174', 'chapter_11', 11, 'dialogue', 2174, 'ai', '星野爱', '你怎么偷学我的气势估算法。', '', '', '', '', 's2175', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2175', 'chapter_11', 11, 'narration', 2175, '', '', '最后，卖花的孩子把两枝向日葵递给他们，只收了一枝的钱，说另一枝算作“气势折扣”。', '', '', '', '', 's2176', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2176', 'chapter_11', 11, 'jump', 2176, '', '', '', '', '', '', '', 's2208', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2162', 'chapter_11', 11, 'menu', 2162, '', '', '', '', '', '', '', 's2177', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2177', 'chapter_11', 11, 'set', 2177, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2178', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2178', 'chapter_11', 11, 'set', 2178, '', '', '', '', '', 'ai_sprite_position', 'right', 's2179', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2179', 'chapter_11', 11, 'scene', 2179, '', '', '', 'bg ch11_riverside_meadow', '', '', '', 's2180', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2180', 'chapter_11', 11, 'sprite', 2180, '', '', '', '', '[{"image": "heroine autumn_speak", "pos": "heroine_autumn_right"}]', '', '', 's2181', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2181', 'chapter_11', 11, 'narration', 2181, '', '', '星野爱举着向日葵，在草地上轻轻转了半圈。', '', '', '', '', 's2182', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2182', 'chapter_11', 11, 'dialogue', 2182, 'ai', '星野爱', '有点像魔法棒。', '', '', '', '', 's2183', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2183', 'chapter_11', 11, 'dialogue', 2183, 'taku', '顾天鹏', '会施什么魔法？', '', '', '', '', 's2184', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2184', 'chapter_11', 11, 'dialogue', 2184, 'ai', '星野爱', '让轻井泽的秋天变得更好吃、更好看、更幸福。', '', '', '', '', 's2185', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2185', 'chapter_11', 11, 'dialogue', 2185, 'taku', '顾天鹏', '听起来已经成功了。', '', '', '', '', 's2186', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2186', 'chapter_11', 11, 'narration', 2186, '', '', '向日葵在风里微微晃动。她走在前面，偶尔回头，像是确认顾天鹏有没有跟上。', '', '', '', '', 's2187', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2187', 'chapter_11', 11, 'set', 2187, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2188', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2188', 'chapter_11', 11, 'set', 2188, '', '', '', '', '', 'event_cg_mode', 'true', 's2189', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2189', 'chapter_11', 11, 'scene', 2189, '', '', '', 'cg ch11_sunflower_language', '', '', '', 's2190', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2190', 'chapter_11', 11, 'narration', 2190, '', '', '快走到草地尽头时，星野爱忽然转过身，把向日葵藏到背后。', '', '', '', '', 's2191', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2191', 'chapter_11', 11, 'dialogue', 2191, 'ai', '星野爱', '顾天鹏，你知道向日葵的花语吗？', '', '', '', '', 's2192', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2192', 'chapter_11', 11, 'dialogue', 2192, 'taku', '顾天鹏', '知道。', '', '', '', '', 's2193', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2193', 'chapter_11', 11, 'dialogue', 2193, 'ai', '星野爱', '这种时候应该说不知道。', '', '', '', '', 's2194', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2194', 'chapter_11', 11, 'dialogue', 2194, 'taku', '顾天鹏', '那我不知道。', '', '', '', '', 's2195', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2195', 'chapter_11', 11, 'narration', 2195, '', '', '她满意地点头，发丝被河风吹起，白色的小花从她脚边掠过。', '', '', '', '', 's2196', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2196', 'chapter_11', 11, 'dialogue', 2196, 'ai', '星野爱', '向日葵是沉默的爱，是没能说出口的爱，也是没有回音也会继续朝向太阳的爱。', '', '', '', '', 's2197', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2197', 'chapter_11', 11, 'narration', 2197, '', '', '那句话落下以后，周围的一切都变得格外真切。', '', '', '', '', 's2198', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2198', 'chapter_11', 11, 'narration', 2198, '', '', '风、草、河水、远山、她手里的花，像是终于在同一幅画里找到了自己的位置。', '', '', '', '', 's2199', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2199', 'chapter_11', 11, 'dialogue', 2199, 'taku', '顾天鹏', '各种各样的爱呢。', '', '', '', '', 's2200', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2200', 'chapter_11', 11, 'dialogue', 2200, 'ai', '星野爱', '是吧。', '', '', '', '', 's2201', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2201', 'chapter_11', 11, 'dialogue', 2201, 'taku', '顾天鹏', '你也叫爱。', '', '', '', '', 's2202', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2202', 'chapter_11', 11, 'dialogue', 2202, 'ai', '星野爱', '没错，星野爱。', '', '', '', '', 's2203', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2203', 'chapter_11', 11, 'narration', 2203, '', '', '顾天鹏望着她，声音轻得几乎被风带走。', '', '', '', '', 's2204', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2204', 'chapter_11', 11, 'dialogue', 2204, 'taku', '顾天鹏', '那有没有一种，名字叫星野的爱。', '', '', '', '', 's2205', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2205', 'chapter_11', 11, 'dialogue', 2205, 'ai', '星野爱', '什么？', '', '', '', '', 's2206', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2206', 'chapter_11', 11, 'dialogue', 2206, 'taku', '顾天鹏', '没什么。走吧。', '', '', '', '', 's2207', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2207', 'chapter_11', 11, 'dialogue', 2207, 'ai', '星野爱', '哦。', '', '', '', '', 's2208', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2208', 'side_ch11_two_sunflowers', 11, 'set', 2208, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2209', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2209', 'side_ch11_two_sunflowers', 11, 'set', 2209, '', '', '', '', '', 'ai_sprite_position', 'right', 's2210', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2210', 'side_ch11_two_sunflowers', 11, 'set', 2210, '', '', '', '', '', 'event_cg_mode', 'false', 's2211', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2211', 'side_ch11_two_sunflowers', 11, 'scene', 2211, '', '', '', 'bg ch11_riverside_meadow', '', '', '', 's2212', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2212', 'side_ch11_two_sunflowers', 11, 'sprite', 2212, '', '', '', '', '[{"image": "heroine autumn_speak", "pos": "heroine_autumn_right"}]', '', '', 's2213', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2213', 'side_ch11_two_sunflowers', 11, 'narration', 2213, '', '', '两枝向日葵让河岸变得像一个临时舞台。星野爱把其中一枝举到顾天鹏面前，认真调整高度。', '', '', '', '', 's2214', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2214', 'side_ch11_two_sunflowers', 11, 'dialogue', 2214, 'ai', '星野爱', '不行，你拿得太端正了。花不是奖状。', '', '', '', '', 's2215', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2215', 'side_ch11_two_sunflowers', 11, 'dialogue', 2215, 'taku', '顾天鹏', '那应该怎么拿？', '', '', '', '', 's2216', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2216', 'side_ch11_two_sunflowers', 11, 'dialogue', 2216, 'ai', '星野爱', '像这样。', '', '', '', '', 's2217', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2217', 'side_ch11_two_sunflowers', 11, 'narration', 2217, '', '', '她把自己的那枝斜斜搭在肩上，金色花瓣贴近脸颊，整个人明亮得像秋天刚刚被点燃。', '', '', '', '', 's2218', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2218', 'side_ch11_two_sunflowers', 11, 'narration', 2218, '', '', '卖花的孩子在后面追上来，手里拿着一张小小的卡片。', '', '', '', '', 's2219', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2219', 'side_ch11_two_sunflowers', 11, 'dialogue', 2219, 'flower_child', '卖花的孩子', '姐姐，刚才忘记给你们这个了。写花语的小卡。', '', '', '', '', 's2220', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2220', 'side_ch11_two_sunflowers', 11, 'dialogue', 2220, 'ai', '星野爱', '花语？', '', '', '', '', 's2221', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2221', 'side_ch11_two_sunflowers', 11, 'narration', 2221, '', '', '星野爱接过卡片，却没有马上读。她把卡片夹进顾天鹏那枝向日葵的叶片里，像把秘密暂时寄存在他手上。', '', '', '', '', 's2222', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2222', 'side_ch11_two_sunflowers', 11, 'dialogue', 2222, 'ai', '星野爱', '先不看。等今天结束再拆。', '', '', '', '', 's2223', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2223', 'side_ch11_two_sunflowers', 11, 'dialogue', 2223, 'taku', '顾天鹏', '为什么？', '', '', '', '', 's2224', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2224', 'side_ch11_two_sunflowers', 11, 'dialogue', 2224, 'ai', '星野爱', '如果现在知道答案，路上的想象就会少很多。', '', '', '', '', 's2225', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2225', 'side_ch11_two_sunflowers', 11, 'narration', 2225, '', '', '他们沿着河岸继续走。每经过一处玻璃窗，星野爱都要确认两枝花在倒影里是不是对称；每经过一阵风，她又会用手护住花瓣，像护住某种容易被吹跑的玩笑。', '', '', '', '', 's2226', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2226', 'side_ch11_two_sunflowers', 11, 'narration', 2226, '', '', '途中有位推着轮椅的老人停下来，看着他们手里的向日葵笑了笑。星野爱犹豫片刻，把自己那枝递过去。', '', '', '', '', 's2227', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2227', 'side_ch11_two_sunflowers', 11, 'dialogue', 2227, 'ai', '星野爱', '要不要看一下？只借给您一分钟。', '', '', '', '', 's2228', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2228', 'side_ch11_two_sunflowers', 11, 'narration', 2228, '', '', '老人接过花，放在膝上看了很久。临走前，她把花还给星野爱，说年轻人拿着太阳走路的样子很好。', '', '', '', '', 's2229', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2229', 'side_ch11_two_sunflowers', 11, 'narration', 2229, '', '', '星野爱听完这句话，难得没有马上接玩笑。', '', '', '', '', 's2230', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2230', 'side_ch11_two_sunflowers', 11, 'dialogue', 2230, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's2231', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2231', 'side_ch11_two_sunflowers', 11, 'dialogue', 2231, 'taku', '顾天鹏', '嗯？', '', '', '', '', 's2232', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2232', 'side_ch11_two_sunflowers', 11, 'dialogue', 2232, 'ai', '星野爱', '如果花语是很沉重的东西，我们就晚点再知道吧。', '', '', '', '', 's2233', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2233', 'side_ch11_two_sunflowers', 11, 'narration', 2233, '', '', '于是关于花语的谈话没有在草地尽头自然发生。它被夹在叶片里，随着两枝向日葵一起，走向了另一个午后。', '', '', '', '', 's2234', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2234', 'side_ch11_two_sunflowers', 11, 'jump', 2234, '', '', '', '', '', '', '', 's2235', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2235', 'ch11_after_flower_language', 11, 'set', 2235, '', '', '', '', '', 'event_cg_mode', 'false', 's2236', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2236', 'ch11_after_flower_language', 11, 'set', 2236, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2237', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2237', 'ch11_after_flower_language', 11, 'set', 2237, '', '', '', '', '', 'ai_sprite_position', 'near', 's2238', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2238', 'ch11_after_flower_language', 11, 'scene', 2238, '', '', '', 'bg ch11_street_food_tomatoes', '', '', '', 's2239', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2239', 'ch11_after_flower_language', 11, 'sprite', 2239, '', '', '', '', '[{"image": "heroine autumn_speak", "pos": "heroine_autumn_near"}]', '', '', 's2240', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2240', 'ch11_after_flower_language', 11, 'narration', 2240, '', '', '中午，他们在街边吃了可丽饼、冷面和一小盒水果番茄。', '', '', '', '', 's2241', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2241', 'ch11_after_flower_language', 11, 'narration', 2241, '', '', '星野爱把番茄含在嘴里，腮帮子鼓起一点，还要努力发表评价。', '', '', '', '', 's2242', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2242', 'ch11_after_flower_language', 11, 'dialogue', 2242, 'ai', '星野爱', '这个很甜。', '', '', '', '', 's2243', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2243', 'ch11_after_flower_language', 11, 'dialogue', 2243, 'taku', '顾天鹏', '先咽下去再说话。', '', '', '', '', 's2244', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2244', 'ch11_after_flower_language', 11, 'dialogue', 2244, 'ai', '星野爱', '可是现在说才准确。', '', '', '', '', 's2245', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2245', 'ch11_after_flower_language', 11, 'dialogue', 2245, 'taku', '顾天鹏', '食评也要注意安全。', '', '', '', '', 's2246', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2246', 'ch11_after_flower_language', 11, 'narration', 2246, '', '', '她咽下番茄，认真想了想。', '', '', '', '', 's2247', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2247', 'ch11_after_flower_language', 11, 'dialogue', 2247, 'ai', '星野爱', '下午去云场池吧。', '', '', '', '', 's2248', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2248', 'ch11_after_flower_language', 11, 'dialogue', 2248, 'taku', '顾天鹏', '想看水？', '', '', '', '', 's2249', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2249', 'ch11_after_flower_language', 11, 'dialogue', 2249, 'ai', '星野爱', '想看秋天倒在水里的样子。', '', '', '', '', 's2250', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2250', 'ch11_after_flower_language', 11, 'dialogue', 2250, 'taku', '顾天鹏', '这个说法不错。', '', '', '', '', 's2251', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2251', 'ch11_after_flower_language', 11, 'dialogue', 2251, 'ai', '星野爱', '那就决定了。', '', '', '', '', 's2252', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2252', 'ch11_after_flower_language', 11, 'set', 2252, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2253', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2253', 'ch11_after_flower_language', 11, 'set', 2253, '', '', '', '', '', 'ai_sprite_position', 'center', 's2254', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2254', 'ch11_after_flower_language', 11, 'scene', 2254, '', '', '', 'bg ch11_kumoba_pond_path', '', '', '', 's2255', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2255', 'ch11_after_flower_language', 11, 'narration', 2255, '', '', '通往云场池的小路安静地伸向树影深处。', '', '', '', '', 's2256', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2256', 'ch11_after_flower_language', 11, 'narration', 2256, '', '', '水面在远处闪着光，红叶像一封封还没拆开的信，等着他们继续往前。', '', '', '', '', 's2257', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2257', 'ch11_after_flower_language', 11, 'narration', 2257, '', '', '向日葵在他们身侧随着脚步轻轻晃动，顾天鹏忽然觉得今天发生的一切，都应该被好好记住。', '', '', '', '', 's2258', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2258', 'ch11_after_flower_language', 11, 'narration', 2258, '', '', '不需要被解释，只要真切地存在过，就已经足够。', '', '', '', '', 's2259', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2259', 'chapter_12', 12, 'set', 2259, '', '', '', '', '', 'ai_sprite_outfit', 'ch12_hat', 's2260', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2260', 'chapter_12', 12, 'set', 2260, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2261', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2261', 'chapter_12', 12, 'set', 2261, '', '', '', '', '', 'ai_sprite_position', 'right', 's2262', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2262', 'chapter_12', 12, 'scene', 2262, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's2263', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2263', 'chapter_12', 12, 'sprite', 2263, '', '', '', '', '[{"image": "heroine ch12_hat", "pos": "heroine_ch12_ch13_right"}]', '', '', 's2264', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2264', 'chapter_12', 12, 'narration', 2264, '', '', '从画里走进另一幅画里', '', '', '', '', 's2265', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2265', 'chapter_12', 12, 'narration', 2265, '', '', '去云场池的路上，他们又被旧街旁一间小小的饰品店拦住。', '', '', '', '', 's2266', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2266', 'chapter_12', 12, 'narration', 2266, '', '', '木门开着，架子上摆满帽子、手链和细碎的银色饰物，阳光落进去，像把一整盒糖纸都撒开。', '', '', '', '', 's2267', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2267', 'chapter_12', 12, 'dialogue', 2267, 'ai', '星野爱', '顾天鹏，你看这个。', '', '', '', '', 's2268', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2268', 'chapter_12', 12, 'narration', 2268, '', '', '星野爱把橘色渔夫帽扣到头上，转过身时裙摆轻轻扬起。', '', '', '', '', 's2269', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2269', 'chapter_12', 12, 'dialogue', 2269, 'ai', '星野爱', '怎么样？是不是很有秋天的感觉？', '', '', '', '', 's2270', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2270', 'chapter_12', 12, 'dialogue', 2270, 'taku', '顾天鹏', '像把一小片枫叶戴在头上。', '', '', '', '', 's2271', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2271', 'chapter_12', 12, 'dialogue', 2271, 'ai', '星野爱', '这算夸奖吗？', '', '', '', '', 's2272', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2272', 'chapter_12', 12, 'dialogue', 2272, 'taku', '顾天鹏', '是。很适合你。', '', '', '', '', 's2273', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2273', 'chapter_12', 12, 'dialogue', 2273, 'ai', '星野爱', '那就合格。', '', '', '', '', 's2274', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2274', 'chapter_12', 12, 'narration', 2274, '', '', '她笑着把帽檐往下一压，又挑出一顶黑色帽子，隔着半步比到顾天鹏头顶。', '', '', '', '', 's2275', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2275', 'chapter_12', 12, 'dialogue', 2275, 'ai', '星野爱', '你也试试。', '', '', '', '', 's2276', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2276', 'chapter_12', 12, 'dialogue', 2276, 'taku', '顾天鹏', '我只是陪你看。', '', '', '', '', 's2277', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2277', 'chapter_12', 12, 'dialogue', 2277, 'ai', '星野爱', '陪看也要有参与感。', '', '', '', '', 's2278', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2278', 'chapter_12', 12, 'narration', 2278, '', '', '顾天鹏只好低头让她比划。她认真到像在给一幅画寻找最后一笔阴影。', '', '', '', '', 's2279', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2279', 'chapter_12', 12, 'dialogue', 2279, 'shop_owner', '饰品店老板娘', '你们两个站在一起真好看。要不要看看手链？', '', '', '', '', 's2280', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2280', 'chapter_12', 12, 'narration', 2280, '', '', '老板娘取出一对细银手链，坠子是小小的心形，价钱不贵，却被擦得很亮。', '', '', '', '', 's2281', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2281', 'chapter_12', 12, 'dialogue', 2281, 'shop_owner', '饰品店老板娘', '不买也没关系，就当给今天留个纪念。', '', '', '', '', 's2282', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2283', 'chapter_12', 12, 'narration', 2283, '', '', '顾天鹏把视线落到那对细银手链上。心形坠子太直白，直白到反而让人不知道该怎么开口。', '', '', '', '', 's2284', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2284', 'chapter_12', 12, 'dialogue', 2284, 'ai', '星野爱', '会不会太像恋爱纪念品了？', '', '', '', '', 's2285', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2285', 'chapter_12', 12, 'dialogue', 2285, 'taku', '顾天鹏', '所以才要认真看完再放回去。', '', '', '', '', 's2286', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2286', 'chapter_12', 12, 'narration', 2286, '', '', '星野爱把其中一条扣在手腕上比了比，银色坠子在灯下晃了一下，又被她小心解开。', '', '', '', '', 's2287', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2287', 'chapter_12', 12, 'dialogue', 2287, 'ai', '星野爱', '谢谢您。但我们只试一下。', '', '', '', '', 's2288', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2288', 'chapter_12', 12, 'narration', 2288, '', '', '她把手链放回托盘，动作轻得像怕惊动那一点银光。', '', '', '', '', 's2289', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2289', 'chapter_12', 12, 'narration', 2289, '', '', '那一点直白的银光让两个人都安静了一会儿。最后他们还是决定把纪念留在试戴的一瞬。', '', '', '', '', 's2290', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2290', 'chapter_12', 12, 'jump', 2290, '', '', '', '', '', '', '', 's3698', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2291', 'chapter_12', 12, 'narration', 2291, '', '', '顾天鹏没有伸手去碰那对手链。', '', '', '', '', 's2292', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2292', 'chapter_12', 12, 'narration', 2292, '', '', '有些纪念一旦买下来，反而会变得太像纪念品。', '', '', '', '', 's2293', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2293', 'chapter_12', 12, 'dialogue', 2293, 'ai', '星野爱', '谢谢您。', '', '', '', '', 's2294', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2282', 'chapter_12', 12, 'menu', 2282, '', '', '', '', '', '', '', 's2294', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2294', 'chapter_12', 12, 'dialogue', 2294, 'taku', '顾天鹏', '但我们收下的话，会像是把纪念偷走了。', '', '', '', '', 's2295', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2295', 'chapter_12', 12, 'narration', 2295, '', '', '星野爱跟着点头。', '', '', '', '', 's2296', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2296', 'chapter_12', 12, 'dialogue', 2296, 'ai', '星野爱', '所以我们只偷走试帽子的快乐。', '', '', '', '', 's2297', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2297', 'chapter_12', 12, 'dialogue', 2297, 'shop_owner', '饰品店老板娘', '那就多偷一点。', '', '', '', '', 's2298', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2298', 'chapter_12', 12, 'narration', 2298, '', '', '离开店时，橘色帽子重新回到架上。可顾天鹏总觉得，那抹颜色已经悄悄留在了她的笑里。', '', '', '', '', 's2299', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2299', 'chapter_12', 12, 'set', 2299, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2300', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2300', 'chapter_12', 12, 'set', 2300, '', '', '', '', '', 'ai_sprite_position', 'left', 's2301', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2301', 'chapter_12', 12, 'set', 2301, '', '', '', '', '', 'ai_sprite_outfit', 'ch12_sunflower', 's2302', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2302', 'chapter_12', 12, 'scene', 2302, '', '', '', 'bg ch12_kumoba_pond', '', '', '', 's2303', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2303', 'chapter_12', 12, 'sprite', 2303, '', '', '', '', '[{"image": "heroine ch12_sunflower", "pos": "heroine_ch12_ch13_left"}]', '', '', 's2304', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2304', 'chapter_12', 12, 'narration', 2304, '', '', '云场池比照片里更安静。', '', '', '', '', 's2305', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2305', 'chapter_12', 12, 'narration', 2305, '', '', '水把天空、枫叶和远山一并收了进去，连风经过时都像是在放轻脚步。', '', '', '', '', 's2306', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2306', 'chapter_12', 12, 'dialogue', 2306, 'ai', '星野爱', '真的像秋天掉进水里了。', '', '', '', '', 's2307', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2307', 'chapter_12', 12, 'dialogue', 2307, 'taku', '顾天鹏', '捞得起来吗？', '', '', '', '', 's2308', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2308', 'chapter_12', 12, 'dialogue', 2308, 'ai', '星野爱', '捞不起来。捞起来就不是这幅画了。', '', '', '', '', 's2309', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2309', 'chapter_12', 12, 'narration', 2309, '', '', '她抱着向日葵站在岸边，紫色长发被光照出柔软的亮边。', '', '', '', '', 's2310', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2310', 'chapter_12', 12, 'narration', 2310, '', '', '顾天鹏看着她，忽然明白为什么有人会在旅途中一次次停下脚步。', '', '', '', '', 's2311', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2311', 'chapter_12', 12, 'dialogue', 2311, 'taku', '顾天鹏', '想拍照吗？', '', '', '', '', 's2312', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2312', 'chapter_12', 12, 'dialogue', 2312, 'ai', '星野爱', '想，但又觉得不拍也可以。', '', '', '', '', 's2313', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2313', 'chapter_12', 12, 'dialogue', 2313, 'taku', '顾天鹏', '为什么？', '', '', '', '', 's2314', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2314', 'chapter_12', 12, 'dialogue', 2314, 'ai', '星野爱', '因为现在太完整了。相机会把它切成一小块。', '', '', '', '', 's2315', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2315', 'chapter_12', 12, 'narration', 2315, '', '', '她顿了顿，又把视线投向水面。', '', '', '', '', 's2316', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2316', 'chapter_12', 12, 'dialogue', 2316, 'ai', '星野爱', '可是如果不拍，又怕以后想不起来。人类真的很麻烦。', '', '', '', '', 's2317', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2317', 'chapter_12', 12, 'dialogue', 2317, 'taku', '顾天鹏', '那就记两份。一份交给相机，一份交给我们自己。', '', '', '', '', 's2318', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2318', 'chapter_12', 12, 'dialogue', 2318, 'ai', '星野爱', '顾天鹏偶尔也会说漂亮话。', '', '', '', '', 's2319', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2319', 'chapter_12', 12, 'dialogue', 2319, 'taku', '顾天鹏', '这句不是谎言。', '', '', '', '', 's2320', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2320', 'chapter_12', 12, 'dialogue', 2320, 'ai', '星野爱', '我知道。', '', '', '', '', 's2321', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2321', 'chapter_12', 12, 'narration', 2321, '', '', '两个人沿着池边慢慢走。鸟声、落叶声和远处不知名的水声混在一起，像一段没有歌词的歌。', '', '', '', '', 's2322', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2322', 'chapter_12', 12, 'dialogue', 2322, 'ai', '星野爱', '如果每天都这么开心，会不会有一天就分辨不出开心了？', '', '', '', '', 's2323', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2323', 'chapter_12', 12, 'dialogue', 2323, 'taku', '顾天鹏', '不会。', '', '', '', '', 's2324', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2324', 'chapter_12', 12, 'dialogue', 2324, 'ai', '星野爱', '答得好快。', '', '', '', '', 's2325', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2325', 'chapter_12', 12, 'dialogue', 2325, 'taku', '顾天鹏', '因为你现在问这个问题的时候，还是很开心。', '', '', '', '', 's2326', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2326', 'chapter_12', 12, 'dialogue', 2326, 'ai', '星野爱', '被发现了。', '', '', '', '', 's2327', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2327', 'chapter_12', 12, 'narration', 2327, '', '', '她低头笑了笑，向日葵的花盘在胸前轻轻晃动。', '', '', '', '', 's2328', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2328', 'chapter_12', 12, 'dialogue', 2328, 'ai', '星野爱', '那今天就继续开心下去。', '', '', '', '', 's2329', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2329', 'chapter_12', 12, 'dialogue', 2329, 'taku', '顾天鹏', '去哪？', '', '', '', '', 's2330', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2330', 'chapter_12', 12, 'dialogue', 2330, 'ai', '星野爱', '往前。只要还在画里，去哪都可以。', '', '', '', '', 's2331', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2331', 'chapter_12', 12, 'set', 2331, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2332', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2332', 'chapter_12', 12, 'scene', 2332, '', '', '', 'bg ch13_miharashidai_sunset', '', '', '', 's2333', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2333', 'chapter_12', 12, 'narration', 2333, '', '', '他们穿过别墅间的小路，又踏上铺着落叶的木栈道。', '', '', '', '', 's2334', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2334', 'chapter_12', 12, 'narration', 2334, '', '', '等见晴台出现在眼前时，太阳已经贴近山线，云层被烧成橙红和深紫。', '', '', '', '', 's2335', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2335', 'chapter_12', 12, 'narration', 2335, '', '', '顾天鹏停在栏杆前，忽然有种错觉。', '', '', '', '', 's2336', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2336', 'chapter_12', 12, 'narration', 2336, '', '', '他们像是刚从一幅金色的画里走出，又被傍晚推入另一幅更大的画中。', '', '', '', '', 's2337', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2337', 'chapter_13', 13, 'set', 2337, '', '', '', '', '', 'ai_sprite_outfit', 'ch13_smile', 's2338', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2338', 'chapter_13', 13, 'set', 2338, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2339', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2339', 'chapter_13', 13, 'set', 2339, '', '', '', '', '', 'ai_sprite_position', 'near', 's2340', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2340', 'chapter_13', 13, 'sprite', 2340, '', '', '', '', '[{"image": "heroine ch13_smile", "pos": "heroine_ch12_ch13_near"}]', '', '', 's2341', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2341', 'chapter_13', 13, 'narration', 2341, '', '', '请永远微笑着', '', '', '', '', 's2342', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2342', 'chapter_13', 13, 'narration', 2342, '', '', '大树下有一架藤木秋千。星野爱走过去，坐下时手里还握着那枝向日葵。', '', '', '', '', 's2343', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2343', 'chapter_13', 13, 'dialogue', 2343, 'ai', '星野爱', '这里好安静。', '', '', '', '', 's2344', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2344', 'chapter_13', 13, 'dialogue', 2344, 'taku', '顾天鹏', '刚才一路上你可不安静。', '', '', '', '', 's2345', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2345', 'chapter_13', 13, 'dialogue', 2345, 'ai', '星野爱', '那是为了不让秋天寂寞。', '', '', '', '', 's2346', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2346', 'chapter_13', 13, 'narration', 2346, '', '', '她轻轻晃动秋千，裙摆与落叶一起摇起来。', '', '', '', '', 's2347', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2347', 'chapter_13', 13, 'narration', 2347, '', '', '顾天鹏退到树旁，想把她、夕阳、向日葵和那片夸张得不像真实的天空一起记住。', '', '', '', '', 's2348', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2348', 'chapter_13', 13, 'dialogue', 2348, 'ai', '星野爱', '你躲那么远做什么？', '', '', '', '', 's2349', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2349', 'chapter_13', 13, 'dialogue', 2349, 'taku', '顾天鹏', '看画要退远一点。', '', '', '', '', 's2350', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2350', 'chapter_13', 13, 'dialogue', 2350, 'ai', '星野爱', '那我现在是画吗？', '', '', '', '', 's2351', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2351', 'chapter_13', 13, 'dialogue', 2351, 'taku', '顾天鹏', '是。', '', '', '', '', 's2352', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2352', 'chapter_13', 13, 'dialogue', 2352, 'ai', '星野爱', '会不会太贵？', '', '', '', '', 's2353', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2353', 'chapter_13', 13, 'dialogue', 2353, 'taku', '顾天鹏', '买不起。', '', '', '', '', 's2354', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2354', 'chapter_13', 13, 'dialogue', 2354, 'ai', '星野爱', '那只能免费展览了。', '', '', '', '', 's2355', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2355', 'chapter_13', 13, 'narration', 2355, '', '', '她笑起来。那笑容没有舞台灯，也没有镜头，却比任何一次表演都更让人移不开眼。', '', '', '', '', 's2356', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2356', 'chapter_13', 13, 'dialogue', 2356, 'taku', '顾天鹏', '你现在笑得很好看。', '', '', '', '', 's2357', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2357', 'chapter_13', 13, 'dialogue', 2357, 'ai', '星野爱', '又开始夸人了。', '', '', '', '', 's2358', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2358', 'chapter_13', 13, 'dialogue', 2358, 'taku', '顾天鹏', '这次不是漂亮话。', '', '', '', '', 's2359', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2359', 'chapter_13', 13, 'dialogue', 2359, 'ai', '星野爱', '嗯。', '', '', '', '', 's2360', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2360', 'chapter_13', 13, 'narration', 2360, '', '', '星野爱把向日葵举到眼前，金色花瓣挡住她半张脸。', '', '', '', '', 's2361', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2361', 'chapter_13', 13, 'dialogue', 2361, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's2362', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2362', 'chapter_13', 13, 'dialogue', 2362, 'taku', '顾天鹏', '怎么了？', '', '', '', '', 's2363', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2363', 'chapter_13', 13, 'dialogue', 2363, 'ai', '星野爱', '以后也请你这样笑着。', '', '', '', '', 's2364', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2364', 'chapter_13', 13, 'dialogue', 2364, 'taku', '顾天鹏', '我？', '', '', '', '', 's2365', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2365', 'chapter_13', 13, 'dialogue', 2365, 'ai', '星野爱', '嗯。不要总是露出好像把一切都看穿的表情。那样很累。', '', '', '', '', 's2366', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2366', 'chapter_13', 13, 'dialogue', 2366, 'taku', '顾天鹏', '我会尽量。', '', '', '', '', 's2367', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2367', 'chapter_13', 13, 'dialogue', 2367, 'ai', '星野爱', '不是尽量，是约定。', '', '', '', '', 's2368', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2368', 'chapter_13', 13, 'dialogue', 2368, 'taku', '顾天鹏', '好，约定。', '', '', '', '', 's2369', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2369', 'chapter_13', 13, 'narration', 2369, '', '', '风从山那边吹来，藤条发出很轻的声响。她看着他，像是终于把一句话从很深的地方拿出来。', '', '', '', '', 's2370', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2370', 'chapter_13', 13, 'dialogue', 2370, 'ai', '星野爱', '如果有一天，我又变得很难看懂。', '', '', '', '', 's2371', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2371', 'chapter_13', 13, 'dialogue', 2371, 'taku', '顾天鹏', '我会慢慢看。', '', '', '', '', 's2372', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2372', 'chapter_13', 13, 'dialogue', 2372, 'ai', '星野爱', '如果我笑得很假呢？', '', '', '', '', 's2373', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2373', 'chapter_13', 13, 'dialogue', 2373, 'taku', '顾天鹏', '那我就等到你不用假笑。', '', '', '', '', 's2374', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2374', 'chapter_13', 13, 'dialogue', 2374, 'ai', '星野爱', '你这个人，真的很狡猾。', '', '', '', '', 's2375', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2375', 'chapter_13', 13, 'narration', 2375, '', '', '她低下头，肩膀却忽然轻轻一颤。', '', '', '', '', 's2376', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2376', 'chapter_13', 13, 'set', 2376, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2377', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2377', 'chapter_13', 13, 'set', 2377, '', '', '', '', '', 'ai_sprite_position', 'near', 's2378', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2378', 'chapter_13', 13, 'set', 2378, '', '', '', '', '', 'ai_sprite_outfit', 'ch13_teary', 's2379', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2379', 'chapter_13', 13, 'sprite', 2379, '', '', '', '', '[{"image": "heroine ch13_teary", "pos": "heroine_ch12_ch13_near"}]', '', '', 's2380', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2380', 'chapter_13', 13, 'narration', 2380, '', '', '夕阳最后一点光落进她眼里，像快要熄灭的星。', '', '', '', '', 's2381', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2381', 'chapter_13', 13, 'dialogue', 2381, 'taku', '顾天鹏', '爱？', '', '', '', '', 's2382', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2382', 'chapter_13', 13, 'dialogue', 2382, 'ai', '星野爱', '对不起。', '', '', '', '', 's2383', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2383', 'chapter_13', 13, 'dialogue', 2383, 'taku', '顾天鹏', '为什么道歉？', '', '', '', '', 's2384', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2384', 'chapter_13', 13, 'dialogue', 2384, 'ai', '星野爱', '不知道。', '', '', '', '', 's2385', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2385', 'chapter_13', 13, 'narration', 2385, '', '', '她试着笑，可那笑意刚到唇边就碎掉了。', '', '', '', '', 's2386', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2386', 'chapter_13', 13, 'dialogue', 2386, 'ai', '星野爱', '我只是突然觉得，今天太好了。好到像是不该属于我。', '', '', '', '', 's2387', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2387', 'chapter_13', 13, 'dialogue', 2387, 'taku', '顾天鹏', '没有这种事。', '', '', '', '', 's2388', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2388', 'chapter_13', 13, 'dialogue', 2388, 'ai', '星野爱', '可是我会害怕。', '', '', '', '', 's2389', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2389', 'chapter_13', 13, 'dialogue', 2389, 'taku', '顾天鹏', '害怕什么？', '', '', '', '', 's2390', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2390', 'chapter_13', 13, 'dialogue', 2390, 'ai', '星野爱', '害怕有一天，连这么好的事都会被我弄脏。', '', '', '', '', 's2391', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2392', 'chapter_13', 13, 'narration', 2392, '', '', '顾天鹏没有再让夕阳夹在两人之间。', '', '', '', '', 's2393', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2393', 'chapter_13', 13, 'narration', 2393, '', '', '他走到秋千旁，坐在她伸手就能碰到的位置。', '', '', '', '', 's2394', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2394', 'chapter_13', 13, 'narration', 2394, '', '', '坐下以后，他才把水瓶递过去，像是把沉默也放在她能握住的地方。', '', '', '', '', 's2395', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2395', 'chapter_13', 13, 'narration', 2395, '', '', '她一开始有些僵硬，像是不知道该不该允许这份靠近。顾天鹏没有继续逼近，只把水递到她手边。', '', '', '', '', 's2396', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2396', 'chapter_13', 13, 'jump', 2396, '', '', '', '', '', '', '', 's3668', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2397', 'chapter_13', 13, 'narration', 2397, '', '', '顾天鹏先把水瓶递过去。', '', '', '', '', 's2398', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2398', 'chapter_13', 13, 'narration', 2398, '', '', '他不确定怎样的距离才不会让她更难过，只能先给她一个能握住的东西。', '', '', '', '', 's2399', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2399', 'chapter_13', 13, 'narration', 2399, '', '', '星野爱接住水以后，他才在秋千旁坐下，把剩下的距离慢慢补上。', '', '', '', '', 's2406', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2400', 'chapter_13', 13, 'narration', 2400, '', '', '顾天鹏没有立刻靠近，只把向日葵放到秋千旁。', '', '', '', '', 's2401', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2401', 'chapter_13', 13, 'narration', 2401, '', '', '金色花瓣在夕阳里亮了一瞬，像替他说了一句过分直白的话。', '', '', '', '', 's2402', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2402', 'chapter_13', 13, 'dialogue', 2402, 'ai', '星野爱', '你这是在把太阳交给我吗？', '', '', '', '', 's2403', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2403', 'chapter_13', 13, 'dialogue', 2403, 'taku', '顾天鹏', '太重的话，就放在中间。', '', '', '', '', 's2404', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2404', 'chapter_13', 13, 'narration', 2404, '', '', '星野爱低头看着那枝花，眼泪终于没有急着落下来。', '', '', '', '', 's2405', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2405', 'chapter_13', 13, 'jump', 2405, '', '', '', '', '', '', '', 's3712', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2391', 'chapter_13', 13, 'menu', 2391, '', '', '', '', '', '', '', 's2406', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2406', 'chapter_13', 13, 'dialogue', 2406, 'taku', '顾天鹏', '那就不要一个人拿着。', '', '', '', '', 's2407', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2407', 'chapter_13', 13, 'dialogue', 2407, 'ai', '星野爱', '什么？', '', '', '', '', 's2408', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2408', 'chapter_13', 13, 'dialogue', 2408, 'taku', '顾天鹏', '害怕也好，开心也好，向日葵也好。重的时候，就分我一半。', '', '', '', '', 's2409', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2409', 'chapter_13', 13, 'narration', 2409, '', '', '星野爱握紧瓶身，眼泪终于落下来。', '', '', '', '', 's2410', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2410', 'chapter_13', 13, 'dialogue', 2410, 'ai', '星野爱', '对不起。', '', '', '', '', 's2411', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2411', 'chapter_13', 13, 'dialogue', 2411, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's2412', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2412', 'chapter_13', 13, 'dialogue', 2412, 'ai', '星野爱', '对不起……', '', '', '', '', 's2413', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2413', 'chapter_13', 13, 'narration', 2413, '', '', '他没有说没关系。', '', '', '', '', 's2414', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2414', 'chapter_13', 13, 'narration', 2414, '', '', '因为那句话太轻，接不住她此刻的难过。', '', '', '', '', 's2415', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2415', 'chapter_13', 13, 'narration', 2415, '', '', '于是顾天鹏只是坐在她身边，陪她看见晴台的夕阳一点点暗下去。', '', '', '', '', 's2416', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2416', 'chapter_13', 13, 'narration', 2416, '', '', '山风安静，树影安静，连那枝向日葵也垂下头。', '', '', '', '', 's2417', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2417', 'chapter_13', 13, 'narration', 2417, '', '', '只有心跳声在黑暗里变得分外清楚。', '', '', '', '', 's2418', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2418', 'chapter_14', 14, 'set', 2418, '', '', '', '', '', 'ai_sprite_outfit', 'ch14_quiet', 's2419', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2419', 'chapter_14', 14, 'set', 2419, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2420', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2420', 'chapter_14', 14, 'set', 2420, '', '', '', '', '', 'ai_sprite_position', 'right', 's2421', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2421', 'chapter_14', 14, 'set', 2421, '', '', '', '', '', 'event_cg_mode', 'false', 's2422', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2422', 'chapter_14', 14, 'scene', 2422, '', '', '', 'bg ch14_roadside_bench_night', '', '', '', 's2423', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2423', 'chapter_14', 14, 'sprite', 2423, '', '', '', '', '[{"image": "heroine ch14_quiet", "pos": "heroine_ch12_ch13_right"}]', '', '', 's2424', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2424', 'chapter_14', 14, 'narration', 2424, '', '', '从明天开始', '', '', '', '', 's2425', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2425', 'chapter_14', 14, 'narration', 2425, '', '', '后来，他们在路边的长椅上坐了很久。', '', '', '', '', 's2426', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2426', 'chapter_14', 14, 'narration', 2426, '', '', '谁也没有先开口，像是两个人都在看时间一点点流过去。', '', '', '', '', 's2427', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2427', 'chapter_14', 14, 'narration', 2427, '', '', '山路上隔很久才会有车经过，车灯把他们的脸照亮，又像潮水一样退开，只剩轮胎声在夜里滚远。', '', '', '', '', 's2428', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2428', 'chapter_14', 14, 'narration', 2428, '', '', '云层很薄，月亮从后面慢慢露出来。头顶的路灯响过两声，忽然不再闪烁。', '', '', '', '', 's2429', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2429', 'chapter_14', 14, 'narration', 2429, '', '', '一些像萤火虫的小虫在光里乱飞，轨迹没有任何规律。', '', '', '', '', 's2430', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2430', 'chapter_14', 14, 'dialogue', 2430, 'ai', '星野爱', '抱歉。', '', '', '', '', 's2431', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2431', 'chapter_14', 14, 'dialogue', 2431, 'taku', '顾天鹏', '喝口水？', '', '', '', '', 's2432', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2432', 'chapter_14', 14, 'dialogue', 2432, 'ai', '星野爱', '嗯。', '', '', '', '', 's2433', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2433', 'chapter_14', 14, 'narration', 2433, '', '', '星野爱只喝了一小口，又把瓶子和向日葵都抱在怀里。', '', '', '', '', 's2434', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2434', 'chapter_14', 14, 'dialogue', 2434, 'ai', '星野爱', '吓到你了？', '', '', '', '', 's2435', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2435', 'chapter_14', 14, 'dialogue', 2435, 'taku', '顾天鹏', '没有。', '', '', '', '', 's2436', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2436', 'chapter_14', 14, 'dialogue', 2436, 'ai', '星野爱', '那就好。', '', '', '', '', 's2437', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2437', 'chapter_14', 14, 'dialogue', 2437, 'taku', '顾天鹏', '你怎么了？', '', '', '', '', 's2438', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2438', 'chapter_14', 14, 'dialogue', 2438, 'ai', '星野爱', '对不起……我只是太高兴了。', '', '', '', '', 's2439', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2439', 'chapter_14', 14, 'dialogue', 2439, 'taku', '顾天鹏', '高兴的时候可不会道歉。', '', '', '', '', 's2440', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2440', 'chapter_14', 14, 'dialogue', 2440, 'ai', '星野爱', '也是呢。', '', '', '', '', 's2441', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2441', 'chapter_14', 14, 'narration', 2441, '', '', '她笑了一下，笑意浅得像浮在水面上。', '', '', '', '', 's2442', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2442', 'chapter_14', 14, 'dialogue', 2442, 'ai', '星野爱', '刚才你走开的时候，这里好安静。', '', '', '', '', 's2443', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2443', 'chapter_14', 14, 'narration', 2443, '', '', '她把瓶盖拧松，又下意识拧紧。', '', '', '', '', 's2444', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2444', 'chapter_14', 14, 'dialogue', 2444, 'ai', '星野爱', '人也没有，猫也没有，乌鸦也没有。车没有，风也听不见。什么都好，乱七八糟的声音也可以，总该有一点什么吧。', '', '', '', '', 's2445', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2445', 'chapter_14', 14, 'dialogue', 2445, 'taku', '顾天鹏', '没人喜欢那种感觉。', '', '', '', '', 's2446', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2446', 'chapter_14', 14, 'dialogue', 2446, 'ai', '星野爱', '嗯。就好像被丢掉了一样。', '', '', '', '', 's2447', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2447', 'chapter_14', 14, 'dialogue', 2447, 'taku', '顾天鹏', '大概是这种感觉。', '', '', '', '', 's2448', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2448', 'chapter_14', 14, 'dialogue', 2448, 'ai', '星野爱', '太讨厌了。', '', '', '', '', 's2449', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2449', 'chapter_14', 14, 'narration', 2449, '', '', '月亮又被薄云遮住，路灯把两个人的影子拖得很长。', '', '', '', '', 's2450', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2450', 'chapter_14', 14, 'dialogue', 2450, 'ai', '星野爱', '但仔细想想，好像又没什么。只是很黑，很安静而已。', '', '', '', '', 's2451', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2451', 'chapter_14', 14, 'narration', 2451, '', '', '她本来像是准备笑。可她看见顾天鹏坐在旁边，用很柔和的眼神望着自己，那点坚强便怎么也挂不住了。', '', '', '', '', 's2452', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2452', 'chapter_14', 14, 'dialogue', 2452, 'ai', '星野爱', '可是……可是……', '', '', '', '', 's2453', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2453', 'chapter_14', 14, 'narration', 2453, '', '', '眼泪从她眼角滑下来。她来不及放下花，只能用手背去擦。', '', '', '', '', 's2454', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2454', 'chapter_14', 14, 'dialogue', 2454, 'taku', '顾天鹏', '怎么哭了。', '', '', '', '', 's2455', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2455', 'chapter_14', 14, 'dialogue', 2455, 'ai', '星野爱', '没有。', '', '', '', '', 's2456', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2456', 'chapter_14', 14, 'dialogue', 2456, 'taku', '顾天鹏', '谎言。', '', '', '', '', 's2457', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2457', 'chapter_14', 14, 'dialogue', 2457, 'ai', '星野爱', '对不起。', '', '', '', '', 's2458', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2458', 'chapter_14', 14, 'dialogue', 2458, 'taku', '顾天鹏', '那就笑好了。', '', '', '', '', 's2459', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2459', 'chapter_14', 14, 'dialogue', 2459, 'ai', '星野爱', '怎么可能笑得出来啊。', '', '', '', '', 's2460', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2460', 'chapter_14', 14, 'dialogue', 2460, 'taku', '顾天鹏', '没关系。', '', '', '', '', 's2461', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2461', 'chapter_14', 14, 'narration', 2461, '', '', '他说得很慢，像是把每个字都放在她能听清的位置。', '', '', '', '', 's2462', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2462', 'chapter_14', 14, 'dialogue', 2462, 'taku', '顾天鹏', '没关系的。', '', '', '', '', 's2463', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2463', 'chapter_14', 14, 'dialogue', 2463, 'ai', '星野爱', '顾天鹏……', '', '', '', '', 's2464', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2464', 'chapter_14', 14, 'dialogue', 2464, 'taku', '顾天鹏', '我在。', '', '', '', '', 's2465', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2465', 'chapter_14', 14, 'narration', 2465, '', '', '那天晚上，向日葵的花瓣浸上眼泪，变得像纸一样轻。', '', '', '', '', 's2466', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2466', 'chapter_14', 14, 'narration', 2466, '', '', '后来他们又安静地坐了一会儿。路灯稳定地亮着，车声偶尔从山路尽头传来。', '', '', '', '', 's2467', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2467', 'chapter_14', 14, 'dialogue', 2467, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's2468', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2468', 'chapter_14', 14, 'dialogue', 2468, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's2469', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2469', 'chapter_14', 14, 'dialogue', 2469, 'ai', '星野爱', '我刚才是不是很麻烦？', '', '', '', '', 's2470', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2470', 'chapter_14', 14, 'dialogue', 2470, 'taku', '顾天鹏', '没有。', '', '', '', '', 's2471', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2471', 'chapter_14', 14, 'dialogue', 2471, 'ai', '星野爱', '你回答得太快了。', '', '', '', '', 's2472', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2472', 'chapter_14', 14, 'dialogue', 2472, 'taku', '顾天鹏', '因为是真的。', '', '', '', '', 's2473', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2473', 'chapter_14', 14, 'narration', 2473, '', '', '星野爱低头看着花，花瓣在夜风里轻轻发抖。', '', '', '', '', 's2474', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2474', 'chapter_14', 14, 'dialogue', 2474, 'ai', '星野爱', '从明天开始，我会变得正常一点。', '', '', '', '', 's2475', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2475', 'chapter_14', 14, 'dialogue', 2475, 'taku', '顾天鹏', '正常一点？', '', '', '', '', 's2476', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2476', 'chapter_14', 14, 'dialogue', 2476, 'ai', '星野爱', '比如不突然哭，不突然道歉，不突然把很重的话丢给别人。', '', '', '', '', 's2477', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2477', 'chapter_14', 14, 'dialogue', 2477, 'taku', '顾天鹏', '那计划清单会不会太严格。', '', '', '', '', 's2478', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2478', 'chapter_14', 14, 'dialogue', 2478, 'ai', '星野爱', '严格一点才像计划。', '', '', '', '', 's2479', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2479', 'chapter_14', 14, 'dialogue', 2479, 'taku', '顾天鹏', '那我也从明天开始。', '', '', '', '', 's2480', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2480', 'chapter_14', 14, 'dialogue', 2480, 'ai', '星野爱', '开始什么？', '', '', '', '', 's2481', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2482', 'chapter_14', 14, 'narration', 2482, '', '', '顾天鹏决定用一个不太讲道理的答案，把她过分认真的清单揉皱。', '', '', '', '', 's2483', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2483', 'chapter_14', 14, 'dialogue', 2483, 'taku', '顾天鹏', '开始把你的计划打乱。', '', '', '', '', 's2484', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2484', 'chapter_14', 14, 'narration', 2484, '', '', '她愣了一下，随即笑出一点很轻的声音。', '', '', '', '', 's2485', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2485', 'chapter_14', 14, 'dialogue', 2485, 'ai', '星野爱', '你好坏。', '', '', '', '', 's2486', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2486', 'chapter_14', 14, 'dialogue', 2486, 'taku', '顾天鹏', '这句也不是谎言。', '', '', '', '', 's2487', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2487', 'chapter_14', 14, 'narration', 2487, '', '', '她确实笑了，可笑过以后，那张清单没有被任何人真正接住。', '', '', '', '', 's2488', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2488', 'chapter_14', 14, 'narration', 2488, '', '', '夜色把他们的沉默拉得很长。第二天清晨，她把告别写进信里，没有叫醒他。', '', '', '', '', 's2489', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2489', 'chapter_14', 14, 'jump', 2489, '', '', '', '', '', '', '', 's3742', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2490', 'chapter_14', 14, 'narration', 2490, '', '', '顾天鹏看着她，忽然觉得这份计划不该只被拿来否定。', '', '', '', '', 's2491', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2491', 'chapter_14', 14, 'narration', 2491, '', '', '如果她需要一张清单，那他至少可以陪她把明天写得不那么孤单。', '', '', '', '', 's2492', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2492', 'chapter_14', 14, 'dialogue', 2492, 'taku', '顾天鹏', '开始陪你把计划写完。', '', '', '', '', 's2493', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2493', 'chapter_14', 14, 'narration', 2493, '', '', '她愣了一下，像是不太习惯有人认真对待这种笨拙的约定。', '', '', '', '', 's2494', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2494', 'chapter_14', 14, 'dialogue', 2494, 'ai', '星野爱', '那第一条是什么？', '', '', '', '', 's2495', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2495', 'chapter_14', 14, 'dialogue', 2495, 'taku', '顾天鹏', '明天也不要一个人逞强。', '', '', '', '', 's2496', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2496', 'chapter_14', 14, 'dialogue', 2496, 'ai', '星野爱', '这条好难。', '', '', '', '', 's2497', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2497', 'chapter_14', 14, 'dialogue', 2497, 'taku', '顾天鹏', '所以写在最前面。', '', '', '', '', 's2505', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2498', 'chapter_14', 14, 'narration', 2498, '', '', '顾天鹏没有急着替她否定计划，也没有急着把计划补完。', '', '', '', '', 's2499', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2499', 'chapter_14', 14, 'dialogue', 2499, 'taku', '顾天鹏', '那就从明天开始。', '', '', '', '', 's2500', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2500', 'chapter_14', 14, 'dialogue', 2500, 'ai', '星野爱', '开始什么？', '', '', '', '', 's2501', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2501', 'chapter_14', 14, 'dialogue', 2501, 'taku', '顾天鹏', '开始慢慢来。', '', '', '', '', 's2502', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2502', 'chapter_14', 14, 'narration', 2502, '', '', '星野爱望着他，像是听见了一句不像约定的约定。', '', '', '', '', 's2503', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2503', 'chapter_14', 14, 'narration', 2503, '', '', '他们没有再继续列清单，只是坐到路灯把影子拉得很长。', '', '', '', '', 's2504', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2504', 'chapter_14', 14, 'jump', 2504, '', '', '', '', '', '', '', 's3727', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2481', 'chapter_14', 14, 'menu', 2481, '', '', '', '', '', '', '', 's2505', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2505', 'chapter_14', 14, 'narration', 2505, '', '', '沉默又回到他们之间。可这一次，沉默没有那么锋利。', '', '', '', '', 's2506', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2506', 'chapter_14', 14, 'dialogue', 2506, 'ai', '星野爱', '明天还有没有没做完的事？', '', '', '', '', 's2507', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2507', 'chapter_14', 14, 'dialogue', 2507, 'taku', '顾天鹏', '有。', '', '', '', '', 's2508', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2508', 'chapter_14', 14, 'dialogue', 2508, 'ai', '星野爱', '那就明天再做。', '', '', '', '', 's2509', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2509', 'chapter_14', 14, 'dialogue', 2509, 'taku', '顾天鹏', '好。', '', '', '', '', 's2510', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2510', 'chapter_14', 14, 'narration', 2510, '', '', '她闭上眼睛，像是在把这句话藏起来。', '', '', '', '', 's2511', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2511', 'chapter_14', 14, 'dialogue', 2511, 'ai', '星野爱', '从明天开始。', '', '', '', '', 's2512', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2512', 'chapter_14', 14, 'set', 2512, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2513', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2513', 'chapter_14', 14, 'scene', 2513, '', '', '', 'bg ch11_birch_morning_run', '', '', '', 's2514', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2514', 'chapter_14', 14, 'narration', 2514, '', '', '第二天早上，顾天鹏照常出门跑步。', '', '', '', '', 's2515', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2515', 'chapter_14', 14, 'narration', 2515, '', '', '桦树林里晨光很淡，鞋底踩过潮湿的路面，空气冷得让人一下子清醒。', '', '', '', '', 's2516', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2516', 'chapter_14', 14, 'narration', 2516, '', '', '等他回到旅馆时，星野爱已经洗好头发，坐在房间里等他。', '', '', '', '', 's2517', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2517', 'chapter_14', 14, 'dialogue', 2517, 'taku', '顾天鹏', '我回来了。', '', '', '', '', 's2518', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2518', 'chapter_14', 14, 'dialogue', 2518, 'ai', '星野爱', '欢迎回来～', '', '', '', '', 's2519', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2519', 'chapter_14', 14, 'scene', 2519, '', '', '', 'bg ch11_inn_morning_room', '', '', '', 's2520', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2520', 'chapter_14', 14, 'narration', 2520, '', '', '天气很好，两支向日葵被放在桌上。', '', '', '', '', 's2521', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2521', 'chapter_14', 14, 'narration', 2521, '', '', '他们上午几乎什么都没做，只是吃过早餐，又把前一天没完成的计划重新摊开。', '', '', '', '', 's2522', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2522', 'chapter_14', 14, 'dialogue', 2522, 'ai', '星野爱', '六点叫你起床，七点吃饭，八点出门。', '', '', '', '', 's2523', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2523', 'chapter_14', 14, 'dialogue', 2523, 'taku', '顾天鹏', '我通常醒得比六点早。', '', '', '', '', 's2524', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2524', 'chapter_14', 14, 'dialogue', 2524, 'ai', '星野爱', '那就谁先醒，谁叫另一个人。', '', '', '', '', 's2525', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2525', 'chapter_14', 14, 'narration', 2525, '', '', '她低头写得很认真，把上午、下午、晚上都塞进清单里，最后甚至写到十点回旅馆睡觉。', '', '', '', '', 's2526', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2526', 'chapter_14', 14, 'dialogue', 2526, 'ai', '星野爱', '大功告成！', '', '', '', '', 's2527', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2527', 'chapter_14', 14, 'dialogue', 2527, 'taku', '顾天鹏', '排得太满了吧。', '', '', '', '', 's2528', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2528', 'chapter_14', 14, 'dialogue', 2528, 'ai', '星野爱', '因为想做的事情太多了。', '', '', '', '', 's2529', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2529', 'chapter_14', 14, 'scene', 2529, '', '', '', 'bg ch11_breakfast_cafe', '', '', '', 's2530', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2530', 'chapter_14', 14, 'narration', 2530, '', '', '中午过后，他们先把午饭吃完，又按照清单坐公交去白丝瀑布。', '', '', '', '', 's2531', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2531', 'chapter_14', 14, 'scene', 2531, '', '', '', 'bg ch11_riverside_meadow', '', '', '', 's2532', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2532', 'chapter_14', 14, 'narration', 2532, '', '', '瀑布附近有老人卖烤鱼。两个人各买了一条，坐在湿润的石头上，一边吃一边看白色水流从高处落下来。', '', '', '', '', 's2533', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2533', 'chapter_14', 14, 'narration', 2533, '', '', '水声一直在耳边响，偶尔混进鸟叫。风从水边吹来，清爽得让人想闭上眼睡一会儿。', '', '', '', '', 's2534', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2534', 'chapter_14', 14, 'dialogue', 2534, 'ai', '星野爱', '感觉这里的空气有安眠药。', '', '', '', '', 's2535', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2535', 'chapter_14', 14, 'dialogue', 2535, 'taku', '顾天鹏', '这句听起来不是谎言。', '', '', '', '', 's2536', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2536', 'chapter_14', 14, 'dialogue', 2536, 'ai', '星野爱', '因为我现在真的好困。', '', '', '', '', 's2537', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2537', 'chapter_14', 14, 'scene', 2537, '', '', '', 'bg ch11_outlet_plaza', '', '', '', 's2538', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2538', 'chapter_14', 14, 'narration', 2538, '', '', '两点多，他们离开瀑布，去了轻井泽千住博美术馆。', '', '', '', '', 's2539', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2539', 'chapter_14', 14, 'narration', 2539, '', '', '去美术馆的路上，红灯迟迟不变。车一辆辆驶过，有人把一群小鸭子引到人行道旁，松鼠钻进松林，割草机的声音从远处传来。', '', '', '', '', 's2540', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2540', 'chapter_14', 14, 'narration', 2540, '', '', '美术馆里到处都是清新的绿色和白色，像走进一片被整理得非常干净的森林。', '', '', '', '', 's2541', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2541', 'chapter_14', 14, 'narration', 2541, '', '', '他们把画一幅一幅看过去：瀑布、淡水湖、黑色的山、夜色里的小镇。大约一个小时以后才出来。', '', '', '', '', 's2542', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2542', 'chapter_14', 14, 'dialogue', 2542, 'ai', '星野爱', '好想拍照。', '', '', '', '', 's2543', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2543', 'chapter_14', 14, 'dialogue', 2543, 'taku', '顾天鹏', '拍照？', '', '', '', '', 's2544', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2544', 'chapter_14', 14, 'dialogue', 2544, 'ai', '星野爱', '拍我们两个。', '', '', '', '', 's2545', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2545', 'chapter_14', 14, 'dialogue', 2545, 'taku', '顾天鹏', '那不是随时都行吗。', '', '', '', '', 's2546', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2546', 'chapter_14', 14, 'dialogue', 2546, 'ai', '星野爱', '去用拍贴机吧。', '', '', '', '', 's2547', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2547', 'chapter_14', 14, 'narration', 2547, '', '', '拍贴机藏在一个不起眼的小房间里。照片最后只打印出一张。', '', '', '', '', 's2548', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2548', 'chapter_14', 14, 'dialogue', 2548, 'ai', '星野爱', '你表情也太淡了吧？', '', '', '', '', 's2549', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2549', 'chapter_14', 14, 'dialogue', 2549, 'taku', '顾天鹏', '我都这样。', '', '', '', '', 's2550', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2550', 'chapter_14', 14, 'dialogue', 2550, 'ai', '星野爱', '笑一下嘛。', '', '', '', '', 's2551', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2551', 'chapter_14', 14, 'dialogue', 2551, 'taku', '顾天鹏', '尽量。', '', '', '', '', 's2552', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2552', 'chapter_14', 14, 'narration', 2552, '', '', '照片里，星野爱靠得很近，对着镜头比了耶。顾天鹏脸上也有一点很淡的笑。', '', '', '', '', 's2553', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2553', 'chapter_14', 14, 'dialogue', 2553, 'ai', '星野爱', '还行吧～', '', '', '', '', 's2554', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2554', 'chapter_14', 14, 'dialogue', 2554, 'taku', '顾天鹏', '脸拍进去就可以了。', '', '', '', '', 's2555', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2555', 'chapter_14', 14, 'scene', 2555, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's2556', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2556', 'chapter_14', 14, 'narration', 2556, '', '', '之后他们继续照着清单走。', '', '', '', '', 's2557', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2557', 'chapter_14', 14, 'narration', 2557, '', '', '他们租了鱼竿，在清澈的小河边扔石头，去尝新出的甜点，站在人群里看街头艺人表演。', '', '', '', '', 's2558', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2558', 'chapter_14', 14, 'scene', 2558, '', '', '', 'bg ch7_souvenir_shop', '', '', '', 's2559', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2559', 'chapter_14', 14, 'narration', 2559, '', '', '傍晚前，他们又一起走进书店。', '', '', '', '', 's2560', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2560', 'chapter_14', 14, 'dialogue', 2560, 'ai', '星野爱', '顾天鹏喜欢什么书？', '', '', '', '', 's2561', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2561', 'chapter_14', 14, 'dialogue', 2561, 'taku', '顾天鹏', '秘密。', '', '', '', '', 's2562', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2562', 'chapter_14', 14, 'dialogue', 2562, 'ai', '星野爱', '我知道……《了不起的盖茨比》？', '', '', '', '', 's2563', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2563', 'chapter_14', 14, 'dialogue', 2563, 'taku', '顾天鹏', '那本最喜欢。', '', '', '', '', 's2564', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2564', 'chapter_14', 14, 'dialogue', 2564, 'ai', '星野爱', '还有别的？', '', '', '', '', 's2565', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2565', 'chapter_14', 14, 'dialogue', 2565, 'taku', '顾天鹏', '有。', '', '', '', '', 's2566', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2566', 'chapter_14', 14, 'dialogue', 2566, 'ai', '星野爱', '说嘛。', '', '', '', '', 's2567', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2567', 'chapter_14', 14, 'dialogue', 2567, 'taku', '顾天鹏', '秘密。', '', '', '', '', 's2568', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2568', 'chapter_14', 14, 'dialogue', 2568, 'ai', '星野爱', '我喜欢《小王子》。', '', '', '', '', 's2569', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2569', 'chapter_14', 14, 'narration', 2569, '', '', '顾天鹏看了她一眼，认真列了许多作家的名字，最后才说自己最喜欢的还是菲茨杰拉德。', '', '', '', '', 's2570', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2570', 'chapter_14', 14, 'dialogue', 2570, 'ai', '星野爱', '你这样会让人觉得看书很没劲。', '', '', '', '', 's2571', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2571', 'chapter_14', 14, 'dialogue', 2571, 'taku', '顾天鹏', '那就先看简单一点的。', '', '', '', '', 's2572', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2572', 'chapter_14', 14, 'dialogue', 2572, 'ai', '星野爱', '比如小王子？', '', '', '', '', 's2573', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2573', 'chapter_14', 14, 'dialogue', 2573, 'taku', '顾天鹏', '比如小王子。', '', '', '', '', 's2574', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2574', 'chapter_14', 14, 'scene', 2574, '', '', '', 'bg ch13_miharashidai_sunset', '', '', '', 's2575', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2575', 'chapter_14', 14, 'narration', 2575, '', '', '太阳快落山时，他们走过一座桥。', '', '', '', '', 's2576', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2576', 'chapter_14', 14, 'narration', 2576, '', '', '风向变了。橘黄色的光把影子拉成几个，又在桥中央重新交叠到一起。', '', '', '', '', 's2577', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2577', 'chapter_14', 14, 'narration', 2577, '', '', '星野爱走在前面，像孩子一样踩着地上的影子。到桥中间时，她忽然停下。', '', '', '', '', 's2578', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2578', 'chapter_14', 14, 'narration', 2578, '', '', '她穿着白色长裙，外面披着淡蓝色牛仔外套。风把长发吹起来，让她看上去轻得像刚出现的云。', '', '', '', '', 's2579', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2579', 'chapter_14', 14, 'dialogue', 2579, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's2580', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2580', 'chapter_14', 14, 'dialogue', 2580, 'taku', '顾天鹏', '嗯？', '', '', '', '', 's2581', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2581', 'chapter_14', 14, 'dialogue', 2581, 'ai', '星野爱', '谢谢。', '', '', '', '', 's2582', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2582', 'chapter_14', 14, 'dialogue', 2582, 'taku', '顾天鹏', '突然道什么谢。', '', '', '', '', 's2583', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2583', 'chapter_14', 14, 'narration', 2583, '', '', '她没有回答，只是像在听风。', '', '', '', '', 's2584', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2584', 'chapter_14', 14, 'scene', 2584, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's2585', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2585', 'chapter_14', 14, 'narration', 2585, '', '', '晚上十点多，他们回到旅馆。', '', '', '', '', 's2586', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2586', 'chapter_14', 14, 'narration', 2586, '', '', '星野爱把下午拍的照片压在一支向日葵下面。', '', '', '', '', 's2587', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2587', 'chapter_14', 14, 'narration', 2587, '', '', '他们洗过澡，没有立刻睡，只是坐在台灯旁边看天色暗下去，直到竹林外再没有一点光。', '', '', '', '', 's2588', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2588', 'chapter_14', 14, 'dialogue', 2588, 'ai', '星野爱', '计划清单上面的事情还没做完呢。', '', '', '', '', 's2589', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2589', 'chapter_14', 14, 'dialogue', 2589, 'taku', '顾天鹏', '那明天再做好了。', '', '', '', '', 's2590', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2590', 'chapter_14', 14, 'narration', 2590, '', '', '星野爱点点头，把《了不起的盖茨比》拿出来翻。', '', '', '', '', 's2591', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2591', 'chapter_14', 14, 'narration', 2591, '', '', '她翻到很晚，顾天鹏先睡着了。', '', '', '', '', 's2592', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2592', 'chapter_14', 14, 'set', 2592, '', '', '', '', '', 'ai_sprite_mode', 'true', 's2593', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2593', 'chapter_14', 14, 'set', 2593, '', '', '', '', '', 'ai_sprite_position', 'center', 's2594', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2594', 'chapter_14', 14, 'set', 2594, '', '', '', '', '', 'ai_sprite_outfit', 'ch14_departure', 's2595', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2595', 'chapter_14', 14, 'sprite', 2595, '', '', '', '', '[{"image": "heroine ch14_departure", "pos": "heroine_ch12_ch13_center"}]', '', '', 's2596', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2596', 'chapter_14', 14, 'narration', 2596, '', '', '清晨，星野爱只带着行李箱离开。', '', '', '', '', 's2597', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2597', 'chapter_14', 14, 'narration', 2597, '', '', '台灯关着，书还摆在桌上。', '', '', '', '', 's2598', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2598', 'chapter_14', 14, 'narration', 2598, '', '', '她没有叫醒顾天鹏。门轻轻合上，房间重新安静下来。', '', '', '', '', 's2599', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2599', 'chapter_15', 15, 'set', 2599, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2600', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2600', 'chapter_15', 15, 'set', 2600, '', '', '', '', '', 'event_cg_mode', 'true', 's2601', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2601', 'chapter_15', 15, 'scene', 2601, '', '', '', 'cg ch15_empty_room_letter', '', '', '', 's2602', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2602', 'chapter_15', 15, 'narration', 2602, '', '', '没有你的明日和信', '', '', '', '', 's2603', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2603', 'chapter_15', 15, 'narration', 2603, '', '', '顾天鹏记不清自己发现星野爱离开的准确时间，只记得大概是凌晨五点四十左右。', '', '', '', '', 's2604', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2604', 'chapter_15', 15, 'narration', 2604, '', '', '醒来以后，房间静得不像有人住过。旁边的床单还有褶皱，行李箱却只剩下他自己的那个。', '', '', '', '', 's2605', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2605', 'chapter_15', 15, 'narration', 2605, '', '', '玻璃门外传来鸟叫，竹林顶端浮着灰色的云，好像随时会下雨。', '', '', '', '', 's2606', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2606', 'chapter_15', 15, 'dialogue', 2606, 'taku', '顾天鹏', '……爱？', '', '', '', '', 's2607', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2607', 'chapter_15', 15, 'narration', 2607, '', '', '没有回应。', '', '', '', '', 's2608', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2608', 'chapter_15', 15, 'narration', 2608, '', '', '他站了一会儿，还是像往常一样换鞋去桦树林里跑步。', '', '', '', '', 's2609', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2609', 'chapter_15', 15, 'set', 2609, '', '', '', '', '', 'event_cg_mode', 'false', 's2610', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2610', 'chapter_15', 15, 'scene', 2610, '', '', '', 'bg ch11_birch_morning_run', '', '', '', 's2611', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2611', 'chapter_15', 15, 'narration', 2611, '', '', '那天他跑了很久，肯定不止五公里。', '', '', '', '', 's2612', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2612', 'chapter_15', 15, 'narration', 2612, '', '', '六点四十多，雨忽然落下来。一开始只有几滴，很快就把白茫茫的清晨全部涂湿。', '', '', '', '', 's2613', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2613', 'chapter_15', 15, 'narration', 2613, '', '', '顾天鹏小跑回旅馆，头发只湿了一点。', '', '', '', '', 's2614', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2614', 'chapter_15', 15, 'scene', 2614, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's2615', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2615', 'chapter_15', 15, 'narration', 2615, '', '', '推开门时，他下意识说了一句我回来了。', '', '', '', '', 's2616', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2616', 'chapter_15', 15, 'narration', 2616, '', '', '房间里没有人洗好头发等他，也没有人笑着说欢迎回来。', '', '', '', '', 's2617', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2617', 'chapter_15', 15, 'narration', 2617, '', '', '他觉得自己有点蠢，洗澡时打开手机，用歌声盖住淋浴声和外面的雨声。', '', '', '', '', 's2618', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2618', 'chapter_15', 15, 'narration', 2618, '', '', '洗完以后，雨下得更大，竹林在风里摇晃，窗玻璃上满是被吹斜的水痕。', '', '', '', '', 's2619', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2619', 'chapter_15', 15, 'narration', 2619, '', '', '顾天鹏喝了一杯水，喉咙才像重新恢复了说话的能力。', '', '', '', '', 's2620', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2620', 'chapter_15', 15, 'narration', 2620, '', '', '他坐到桌边，看见蛋糕、刀叉、没有拆封的手套、烧黑半截的蜡烛、倒在墙影里的两支向日葵，以及压在花茎下反光的照片。', '', '', '', '', 's2621', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2621', 'chapter_15', 15, 'narration', 2621, '', '', '所有东西都像照片一样被定格住了。', '', '', '', '', 's2622', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2622', 'chapter_15', 15, 'narration', 2622, '', '', '雨停了半个小时左右，他把玻璃门打开，风立刻灌进房间。', '', '', '', '', 's2623', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2623', 'chapter_15', 15, 'narration', 2623, '', '', '桌边的《了不起的盖茨比》被吹得翻页。顾天鹏过去想把书收好，却看见里面夹着一张折起来的信纸。', '', '', '', '', 's2624', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2624', 'chapter_15', 15, 'narration', 2624, '', '', '他拿起信，坐到床边，从头开始读。', '', '', '', '', 's2625', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2625', 'chapter_15', 15, 'dialogue', 2625, 'ai_letter', '星野爱的信', '对不起，我说谎了。', '', '', '', '', 's2626', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2626', 'chapter_15', 15, 'narration', 2626, '', '', '星野爱的字迹并不好看，却每一笔都尽量写清楚。', '', '', '', '', 's2627', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2627', 'chapter_15', 15, 'narration', 2627, '', '', '读到这里，风有点大。他把玻璃门重新关严，又去倒了一杯水。', '', '', '', '', 's2628', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2628', 'chapter_15', 15, 'dialogue', 2628, 'ai_letter', '星野爱的信', '说好的明天继续把计划清单里的事情做完，我却不辞而别了。非常抱歉。', '', '', '', '', 's2629', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2629', 'chapter_15', 15, 'dialogue', 2629, 'ai_letter', '星野爱的信', '我是在台灯旁边写这封信的。窗外没下雨，天黑得吓人，风声很大。', '', '', '', '', 's2630', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2630', 'chapter_15', 15, 'dialogue', 2630, 'ai_letter', '星野爱的信', '我还是更喜欢下午三点、有太阳的时候写信。你肯定忘了这句话吧？可是你说过喜欢夏天在桥边吹风散步，我帮你记着。', '', '', '', '', 's2631', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2631', 'chapter_15', 15, 'dialogue', 2631, 'ai_letter', '星野爱的信', '谢谢你陪我过生日，陪我看麋鹿、吃可丽饼、看斯巴鲁、去瀑布、美术馆、书店，还有那座桥。', '', '', '', '', 's2632', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2632', 'chapter_15', 15, 'dialogue', 2632, 'ai_letter', '星野爱的信', '还有好多好多，一张纸大概写不完。既然是离开，各种东西我就不带了。向日葵也留在这里，果然很重。', '', '', '', '', 's2633', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2633', 'chapter_15', 15, 'dialogue', 2633, 'ai_letter', '星野爱的信', '照片我想拿，可是只有一张。还是留给你吧。看到照片就会想起在一起，然后又分开，那多难受啊。麻烦你帮我难受好了。', '', '', '', '', 's2634', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2634', 'chapter_15', 15, 'dialogue', 2634, 'ai_letter', '星野爱的信', '顾天鹏，对不起，这次我想写你的全名。我会牢记你的全名。', '', '', '', '', 's2635', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2635', 'chapter_15', 15, 'dialogue', 2635, 'ai_letter', '星野爱的信', '你很帅，是个很好的人。相比之下，我觉得自己实在很恶劣，不过我不讨厌这样的自己。星野爱就是这样，可爱，贪婪，独一无二。', '', '', '', '', 's2636', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2636', 'chapter_15', 15, 'dialogue', 2636, 'ai_letter', '星野爱的信', '我要回东京了。东京其实也不远，说不定你读到这里的时候，我正晒着太阳看东京湾。', '', '', '', '', 's2637', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2637', 'chapter_15', 15, 'dialogue', 2637, 'ai_letter', '星野爱的信', '最后还有一件事。你说只要是说出来的话都能识破。那你猜猜，写在信里的有多少是谎言？', '', '', '', '', 's2638', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2638', 'chapter_15', 15, 'dialogue', 2638, 'ai_letter', '星野爱的信', '世界上最贪婪的少女，星野爱。', '', '', '', '', 's2639', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2639', 'chapter_15', 15, 'narration', 2639, '', '', '信写得很长，字又小又挤。顾天鹏读完以后，又从头读了一遍。', '', '', '', '', 's2640', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2640', 'chapter_15', 15, 'narration', 2640, '', '', '第二遍读完，他把杯子里的水全部喝光，喉咙却还是很干。', '', '', '', '', 's2641', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2641', 'chapter_15', 15, 'narration', 2641, '', '', '雨又下起来，风小了一些，竹林没有刚才那样混乱。', '', '', '', '', 's2642', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2642', 'chapter_15', 15, 'narration', 2642, '', '', '他坐到台灯旁读第三遍。读完后把信翻到背面，总觉得后面还应该写着什么，可那里什么都没有。', '', '', '', '', 's2643', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2643', 'chapter_15', 15, 'narration', 2643, '', '', '信纸干净得像她离开时那样决绝。吹风机放在旁边，上面还残留一点她洗过头发后的香气。', '', '', '', '', 's2644', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2644', 'chapter_15', 15, 'narration', 2644, '', '', '顾天鹏把信折好，夹回书里。', '', '', '', '', 's2645', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2645', 'chapter_15', 15, 'narration', 2645, '', '', '书自动弹到星野爱昨晚翻到的那一页，右上角用铅笔写着一行很小的字。', '', '', '', '', 's2646', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2646', 'chapter_15', 15, 'dialogue', 2646, 'ai_letter', '星野爱的信', '书太难懂了，想看简单一点的，小王子。', '', '', '', '', 's2647', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2647', 'chapter_15', 15, 'narration', 2647, '', '', '后面画了一个简略的哭脸，连句号也没有。', '', '', '', '', 's2648', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2648', 'chapter_15', 15, 'narration', 2648, '', '', '他想象她深夜坐在台灯下写信的样子，却猜不出那时她究竟是开心还是难过。', '', '', '', '', 's2649', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2649', 'chapter_15', 15, 'narration', 2649, '', '', '他把蛋糕、刀叉、蜡烛和手套都收起来丢到外面的垃圾桶。', '', '', '', '', 's2650', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2650', 'chapter_15', 15, 'narration', 2650, '', '', '回来以后，他拿起向日葵，仍旧觉得这花无论如何也不止八十克。', '', '', '', '', 's2651', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2651', 'chapter_15', 15, 'narration', 2651, '', '', '照片在花茎下面泛着白光。他捏起来看，好像时间又回到他们刚从美术馆出来的下午。', '', '', '', '', 's2652', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2652', 'chapter_15', 15, 'narration', 2652, '', '', '可那是不可能的。', '', '', '', '', 's2653', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2653', 'chapter_15', 15, 'narration', 2653, '', '', '他把和星野爱有关的东西都塞进抽屉，中午去外面吃了饭。', '', '', '', '', 's2654', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2654', 'chapter_15', 15, 'narration', 2654, '', '', '街上有零星几个行人，听不清对话声，只听见雨敲在伞面上。', '', '', '', '', 's2655', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2655', 'chapter_15', 15, 'narration', 2655, '', '', '回到旅馆后，他看了一会儿棒球赛。观众的喝彩声越来越远，他睡了一觉，醒来时已经接近傍晚。', '', '', '', '', 's2656', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2656', 'chapter_15', 15, 'narration', 2656, '', '', '雨停了，门檐上还在滴水。隔着玻璃，声音显得很遥远。', '', '', '', '', 's2657', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2657', 'chapter_15', 15, 'narration', 2657, '', '', '手机里播到一首熟悉的歌，他想起星野爱在火车上唱过的那几句。', '', '', '', '', 's2658', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2658', 'chapter_15', 15, 'narration', 2658, '', '', '她现在在做什么呢。大概已经到家了吧。东京一点也不小，分别之后，也许再也见不到了。', '', '', '', '', 's2659', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2659', 'chapter_15', 15, 'narration', 2659, '', '', '旅途中她总说自己贪婪，离开时却什么都没有带走。', '', '', '', '', 's2660', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2660', 'chapter_15', 15, 'narration', 2660, '', '', '这点的确太恶劣了，顾天鹏想。', '', '', '', '', 's2661', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2661', 'chapter_15', 15, 'narration', 2661, '', '', '她可爱、热情、纯粹，却又充满谎言，好像说谎就是她活下去的本能。', '', '', '', '', 's2662', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2662', 'chapter_15', 15, 'narration', 2662, '', '', '她没有待在阴影里。她本身就像一片巨大的阴影。', '', '', '', '', 's2663', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2663', 'chapter_15', 15, 'narration', 2663, '', '', '无论从哪个角度看，她都彻彻底底，是需要被人拯救的。', '', '', '', '', 's2664', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2664', 'chapter_15', 15, 'narration', 2664, '', '', '那天傍晚没有晚霞，竹林湿透了，夜幕一点点降下来。', '', '', '', '', 's2665', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2665', 'chapter_16', 16, 'set', 2665, '', '', '', '', '', 'event_cg_mode', 'false', 's2666', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2666', 'chapter_16', 16, 'set', 2666, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2667', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2667', 'chapter_16', 16, 'scene', 2667, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's2668', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2668', 'chapter_16', 16, 'narration', 2668, '', '', '如果能再相见', '', '', '', '', 's2669', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2669', 'chapter_16', 16, 'narration', 2669, '', '', '后面的几天，顾天鹏没有立刻回东京。', '', '', '', '', 's2670', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2670', 'chapter_16', 16, 'narration', 2670, '', '', '他仍然按照原来的计划留在轻井泽，准备等春天来临后再回去找工作。', '', '', '', '', 's2671', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2671', 'chapter_16', 16, 'narration', 2671, '', '', '星野爱离开得很突然，连联系方式都没有留下。', '', '', '', '', 's2672', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2672', 'chapter_16', 16, 'narration', 2672, '', '', '说到底，他不过是她在火车上偶然遇到的人。相遇和分别本来就是旅途中常有的事。', '', '', '', '', 's2673', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2673', 'chapter_16', 16, 'narration', 2673, '', '', '即使如此，他还是花了不少时间，才慢慢适应从两个人出门变成一个人旅行。', '', '', '', '', 's2674', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2674', 'chapter_16', 16, 'narration', 2674, '', '', '十一月十九日晚上，顾天鹏坐在台灯边翻书。', '', '', '', '', 's2675', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2675', 'chapter_16', 16, 'narration', 2675, '', '', '门外的竹叶停在灯光和黑暗的交界处，窗外传来不知名动物的叫声，安静得像在提醒人不要说话。', '', '', '', '', 's2676', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2676', 'chapter_16', 16, 'narration', 2676, '', '', '他合上书，关紧窗户，锻炼、洗澡，然后倒在床上睡着。', '', '', '', '', 's2677', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2677', 'chapter_16', 16, 'scene', 2677, '', '', '', 'bg ch11_birch_morning_run', '', '', '', 's2678', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2678', 'chapter_16', 16, 'narration', 2678, '', '', '十一月二十日，他八点起床。', '', '', '', '', 's2679', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2679', 'chapter_16', 16, 'narration', 2679, '', '', '刷牙、用湿毛巾让自己清醒以后，他到旅馆外面跑步。', '', '', '', '', 's2680', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2680', 'chapter_16', 16, 'narration', 2680, '', '', '晨曦从林间一点点爬上来，树干上的白光亮得有些不真实。', '', '', '', '', 's2681', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2681', 'chapter_16', 16, 'narration', 2681, '', '', '几辆自行车从车道上驶过，车铃声却没有第一天抵达轻井泽时那样悦耳。', '', '', '', '', 's2682', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2682', 'chapter_16', 16, 'narration', 2682, '', '', '两个穿运动服的女生也在跑步，其中一个手机外放着熟悉的歌。', '', '', '', '', 's2683', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2683', 'chapter_16', 16, 'narration', 2683, '', '', '鸟叫声从高处传来，像布谷鸟，又像斑鸠或乌鸦。无论他跑多远，那声音都没有停下。', '', '', '', '', 's2684', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2684', 'chapter_16', 16, 'scene', 2684, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's2685', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2685', 'chapter_16', 16, 'narration', 2685, '', '', '回到旅馆，他洗澡换衣服，然后去了书店。', '', '', '', '', 's2686', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2686', 'chapter_16', 16, 'scene', 2686, '', '', '', 'bg ch7_souvenir_shop', '', '', '', 's2687', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2687', 'chapter_16', 16, 'narration', 2687, '', '', '书店里，一个母亲带着孩子挑书，有人推着新到的书往仓库送。', '', '', '', '', 's2688', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2688', 'chapter_16', 16, 'narration', 2688, '', '', '顾天鹏从留着胡茬的大叔身边走过，去文学读物区找出《源氏物语》。', '', '', '', '', 's2689', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2689', 'chapter_16', 16, 'narration', 2689, '', '', '他一看就看到中午。', '', '', '', '', 's2690', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2690', 'chapter_16', 16, 'narration', 2690, '', '', '离开时，两个少女在讨论要不要买《小王子》和《月亮与六便士》，说这样可以交换着看。', '', '', '', '', 's2691', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2691', 'chapter_16', 16, 'narration', 2691, '', '', '顾天鹏下意识看了她们一眼，然后转身离开。', '', '', '', '', 's2692', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2692', 'chapter_16', 16, 'scene', 2692, '', '', '', 'bg ch7_cafe', '', '', '', 's2693', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2693', 'chapter_16', 16, 'narration', 2693, '', '', '中午十二点，他在外面的店里吃午餐。', '', '', '', '', 's2694', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2694', 'chapter_16', 16, 'narration', 2694, '', '', '咖喱鸡翅盖浇饭的味道不怎么样，拿铁也很普通。也许只是他没什么胃口，最后勉强才吃完。', '', '', '', '', 's2695', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2695', 'chapter_16', 16, 'scene', 2695, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's2696', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2696', 'chapter_16', 16, 'narration', 2696, '', '', '走出店外时还不到一点，头顶的阳光却已经消失。', '', '', '', '', 's2697', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2697', 'chapter_16', 16, 'narration', 2697, '', '', '周围算不上暗沉，也不像要下雨，只是视野里的一切都显得脏兮兮的。', '', '', '', '', 's2698', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2698', 'chapter_16', 16, 'narration', 2698, '', '', '他漫无目的地走，在两个十字路口右转，不知不觉来到和星野爱最后一起走过的那座石桥。', '', '', '', '', 's2699', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2699', 'chapter_16', 16, 'narration', 2699, '', '', '路灯没有亮，地上没有影子，风连桥边的小旗帜都吹不动。桥下的水机械地流着，小草被压进泥土里。', '', '', '', '', 's2700', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2700', 'chapter_16', 16, 'narration', 2700, '', '', '每一处景致看起来都像死物。', '', '', '', '', 's2701', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2701', 'chapter_16', 16, 'narration', 2701, '', '', '想不到要去哪里，他绕到附近的宠物店逗了一会儿猫。', '', '', '', '', 's2702', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2702', 'chapter_16', 16, 'narration', 2702, '', '', '年轻的店员给他介绍各种猫的品种，又问他是不是来旅游，要待多久，以后有没有兴趣常来。', '', '', '', '', 's2703', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2703', 'chapter_16', 16, 'narration', 2703, '', '', '顾天鹏简单回答完，离开店里。', '', '', '', '', 's2704', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2704', 'chapter_16', 16, 'narration', 2704, '', '', '站在街边，他看见女人提着购物袋交谈，学生聊着游戏和美妆产品，老人散步，小孩追逐。', '', '', '', '', 's2705', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2705', 'chapter_16', 16, 'narration', 2705, '', '', '不知哪家店里传来轻柔的音乐，像飘在云上一样。', '', '', '', '', 's2706', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2706', 'chapter_16', 16, 'narration', 2706, '', '', '他忽然觉得这些事物都在按照某种既定程序运行。', '', '', '', '', 's2707', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2707', 'chapter_16', 16, 'narration', 2707, '', '', '恍惚间，他仿佛看见穿着裙子的星野爱回过身，对他笑了一下。', '', '', '', '', 's2708', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2708', 'chapter_16', 16, 'narration', 2708, '', '', '那笑容很快远去。', '', '', '', '', 's2709', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2709', 'chapter_16', 16, 'dialogue', 2709, 'taku', '顾天鹏', '这到底算什么。', '', '', '', '', 's2710', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2710', 'chapter_16', 16, 'scene', 2710, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's2711', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2711', 'chapter_16', 16, 'narration', 2711, '', '', '晚上，顾天鹏在便利店吃了关东煮，又买了一瓶 MAX 咖啡。咖啡味道倒是不错。', '', '', '', '', 's2712', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2712', 'chapter_16', 16, 'narration', 2712, '', '', '回到旅馆后，他看新闻和天气预报。', '', '', '', '', 's2713', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2713', 'chapter_16', 16, 'narration', 2713, '', '', '东京基本是晴天，轻井泽却要连阴三天。', '', '', '', '', 's2714', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2714', 'chapter_16', 16, 'narration', 2714, '', '', '关上电视，外面的天色暗下来。他把灯打开，从包里翻出《了不起的盖茨比》。', '', '', '', '', 's2715', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2715', 'chapter_16', 16, 'narration', 2715, '', '', '他没有看书，只是又一次展开夹在里面的信。', '', '', '', '', 's2716', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2716', 'chapter_16', 16, 'narration', 2716, '', '', '那封信他已经读过很多遍，可每次读完，都觉得差了点什么。', '', '', '', '', 's2717', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2717', 'chapter_16', 16, 'narration', 2717, '', '', '它结束得太干脆，像有人突然剪断电话线。每句话后面似乎都应该还有一段长长的回忆，可那里什么都没有。', '', '', '', '', 's2718', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2718', 'chapter_16', 16, 'narration', 2718, '', '', '这次读完，顾天鹏提起笔，像只有把想法写下来才能平静。', '', '', '', '', 's2719', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2719', 'chapter_16', 16, 'narration', 2719, '', '', '他看着暮色里的竹林，最后埋头写下一句。', '', '', '', '', 's2720', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2720', 'chapter_16', 16, 'dialogue', 2720, 'taku', '顾天鹏', '你好，星野爱，我会牢记你的名字。', '', '', '', '', 's2721', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2721', 'chapter_16', 16, 'narration', 2721, '', '', '这句话后面，本该写夕阳、月色、秋天的枫叶、冬天的白雪。', '', '', '', '', 's2722', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2722', 'chapter_16', 16, 'narration', 2722, '', '', '但他最后什么都没有继续写。', '', '', '', '', 's2723', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2723', 'chapter_16', 16, 'narration', 2723, '', '', '没有她的地址，这只是一封寄不出去的信。', '', '', '', '', 's2724', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2724', 'chapter_16', 16, 'set', 2724, '', '', '', '', '', 'event_cg_mode', 'true', 's2725', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2725', 'chapter_16', 16, 'scene', 2725, '', '', '', 'cg ch16_photo_desk_night', '', '', '', 's2726', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2726', 'chapter_16', 16, 'narration', 2726, '', '', '顾天鹏把写了字的纸揉成一团，又把所有关于星野爱的东西收在一起：信、向日葵，以及那些轻得不像证据的回忆。', '', '', '', '', 's2727', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2727', 'chapter_16', 16, 'narration', 2727, '', '', '他把能丢的东西都丢掉。', '', '', '', '', 's2728', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2728', 'chapter_16', 16, 'narration', 2728, '', '', '照片其实也该丢。带着它继续旅行，总会让人难过。', '', '', '', '', 's2729', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2729', 'chapter_16', 16, 'narration', 2729, '', '', '要是难过，就和出门旅行的目的背道而驰了。', '', '', '', '', 's2730', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2730', 'chapter_16', 16, 'narration', 2730, '', '', '他拿着照片犹豫很久，最后还是把它摆回桌面。', '', '', '', '', 's2731', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2731', 'chapter_16', 16, 'narration', 2731, '', '', '十点多，他关掉台灯。', '', '', '', '', 's2732', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2732', 'chapter_16', 16, 'narration', 2732, '', '', '残留的微光让照片亮了一会儿，像有月色打在上面。', '', '', '', '', 's2733', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2733', 'chapter_16', 16, 'narration', 2733, '', '', '但今晚连月亮都没有。', '', '', '', '', 's2734', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2734', 'chapter_16', 16, 'narration', 2734, '', '', '第二天一大早，他把垃圾篓里的东西全部扔到外面。', '', '', '', '', 's2735', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2735', 'chapter_16', 16, 'set', 2735, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2736', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2736', 'chapter_16', 16, 'set', 2736, '', '', '', '', '', 'ai_sprite_position', 'center', 's2737', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2737', 'chapter_16', 16, 'set', 2737, '', '', '', '', '', 'event_cg_mode', 'false', 's2738', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2739', 'chapter_16', 16, 'set', 2739, '', '', '', '', '', 'story_route', 'main_continue', 's2740', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2740', 'chapter_16', 16, 'jump', 2740, '', '', '', '', '', '', '', 's2745', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2741', 'chapter_16', 16, 'set', 2741, '', '', '', '', '', 'story_route', 'main_search', 's2742', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2742', 'chapter_16', 16, 'jump', 2742, '', '', '', '', '', '', '', 's3537', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2743', 'chapter_16', 16, 'set', 2743, '', '', '', '', '', 'story_route', 'side_memory', 's2744', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2744', 'chapter_16', 16, 'jump', 2744, '', '', '', '', '', '', '', 's3575', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2738', 'chapter_16', 16, 'menu', 2738, '', '', '', '', '', '', '', 's2745', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2745', 'chapter_17', 17, 'set', 2745, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2746', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2746', 'chapter_17', 17, 'set', 2746, '', '', '', '', '', 'event_cg_mode', 'false', 's2747', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2747', 'chapter_17', 17, 'scene', 2747, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's2748', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2748', 'chapter_17', 17, 'narration', 2748, '', '', '后来', '', '', '', '', 's2749', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2749', 'chapter_17', 17, 'narration', 2749, '', '', '扔掉垃圾以后，顾天鹏继续留在轻井泽。', '', '', '', '', 's2750', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2750', 'chapter_17', 17, 'narration', 2750, '', '', '白天出门看书，下午去宠物店逗猫。天气好的时候，他就沿着街道走到黄昏，再坐进咖啡店听歌。', '', '', '', '', 's2751', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2751', 'chapter_17', 17, 'narration', 2751, '', '', '一个人的旅途逐渐变得轻松。空落落的感觉偶尔还会出现，却一天比一天淡。', '', '', '', '', 's2752', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2752', 'chapter_17', 17, 'narration', 2752, '', '', '他会对运输垃圾的大叔说辛苦了，也会在绿色信箱旁看见有人取信。', '', '', '', '', 's2753', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2753', 'chapter_17', 17, 'narration', 2753, '', '', '那些微小的动静把旅途重新填起来。不是热闹，只是说明世界还在正常运转。', '', '', '', '', 's2754', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2754', 'chapter_17', 17, 'narration', 2754, '', '', '十一月二十六日，天气好转后的第三天，他晨跑以后去小餐馆吃了芝士披萨和纳豆。', '', '', '', '', 's2755', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2755', 'chapter_17', 17, 'narration', 2755, '', '', '原本打算去便利店买 MAX 咖啡，经过宠物店时，柜台里的少女使劲朝他挥手。', '', '', '', '', 's2756', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2756', 'chapter_17', 17, 'scene', 2756, '', '', '', 'bg ch17_pet_shop', '', '', '', 's2757', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2757', 'chapter_17', 17, 'sprite', 2757, '', '', '', '', '[{"image": "yuki petshop", "pos": "cast_single_center"}]', '', '', 's2758', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2758', 'chapter_17', 17, 'narration', 2758, '', '', '十一月二十六日，开太阳的第三天，他经过宠物店时，被看店的少女叫住。', '', '', '', '', 's2759', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2759', 'chapter_17', 17, 'dialogue', 2759, 'yuki', '小仓友希', '顾天鹏！', '', '', '', '', 's2760', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2760', 'chapter_17', 17, 'dialogue', 2760, 'taku', '顾天鹏', '下午好，小仓小姐。', '', '', '', '', 's2761', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2761', 'chapter_17', 17, 'dialogue', 2761, 'yuki', '小仓友希', '叫友希小姐也没问题。进来坐吗？', '', '', '', '', 's2762', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2762', 'chapter_17', 17, 'set', 2762, '', '', '', '', '', 'event_cg_mode', 'true', 's2763', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2763', 'chapter_17', 17, 'scene', 2763, '', '', '', 'cg ch17_yuki_coffee_cat', '', '', '', 's2764', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2764', 'chapter_17', 17, 'narration', 2764, '', '', '她留着及肩的黑发，红色连帽卫衣配黑色百褶裙，脚上是一双运动鞋。', '', '', '', '', 's2765', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2765', 'chapter_17', 17, 'narration', 2765, '', '', '她看起来活泼，又像随时能把人拉进自己的节奏。', '', '', '', '', 's2766', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2766', 'chapter_17', 17, 'narration', 2766, '', '', '小仓友希把一只半梦半醒的橘黄色胖猫抱给他，又跑去小房间里泡咖啡。', '', '', '', '', 's2767', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2767', 'chapter_17', 17, 'dialogue', 2767, 'yuki', '小仓友希', '今天很早嘛。', '', '', '', '', 's2768', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2768', 'chapter_17', 17, 'dialogue', 2768, 'taku', '顾天鹏', '不是被你喊进来的吗？', '', '', '', '', 's2769', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2769', 'chapter_17', 17, 'dialogue', 2769, 'yuki', '小仓友希', '原来准备去哪？', '', '', '', '', 's2770', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2770', 'chapter_17', 17, 'dialogue', 2770, 'taku', '顾天鹏', '买咖啡。', '', '', '', '', 's2771', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2771', 'chapter_17', 17, 'dialogue', 2771, 'yuki', '小仓友希', '本地的咖啡豆，我自己泡的。要不要喝？', '', '', '', '', 's2772', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2772', 'chapter_17', 17, 'dialogue', 2772, 'taku', '顾天鹏', '谢谢。', '', '', '', '', 's2773', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2773', 'chapter_17', 17, 'dialogue', 2773, 'yuki', '小仓友希', '杯子是新的，牛奶和砂糖自己加。', '', '', '', '', 's2774', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2774', 'chapter_17', 17, 'dialogue', 2774, 'yuki', '小仓友希', '想听什么歌？', '', '', '', '', 's2775', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2775', 'chapter_17', 17, 'dialogue', 2775, 'taku', '顾天鹏', '《五百英里》。', '', '', '', '', 's2776', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2776', 'chapter_17', 17, 'narration', 2776, '', '', '店里的音乐换成民谣，猫在他怀里低低叫了两声。', '', '', '', '', 's2777', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2777', 'chapter_17', 17, 'dialogue', 2777, 'yuki', '小仓友希', '你喜欢民谣？', '', '', '', '', 's2778', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2778', 'chapter_17', 17, 'dialogue', 2778, 'taku', '顾天鹏', '不讨厌。', '', '', '', '', 's2779', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2779', 'chapter_17', 17, 'dialogue', 2779, 'yuki', '小仓友希', '那《Love Story》呢？', '', '', '', '', 's2780', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2780', 'chapter_17', 17, 'dialogue', 2780, 'taku', '顾天鹏', '听过。', '', '', '', '', 's2781', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2781', 'chapter_17', 17, 'dialogue', 2781, 'yuki', '小仓友希', '我很喜欢，一会儿有这首。', '', '', '', '', 's2782', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2782', 'chapter_17', 17, 'narration', 2782, '', '', '门框上的铃铛响了几声，有两个小女孩进来挑猫粮。小仓友希笑着招呼她们，回头又继续和顾天鹏说话。', '', '', '', '', 's2783', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2783', 'chapter_17', 17, 'dialogue', 2783, 'yuki', '小仓友希', '今天又是运动、看书、欣赏风景？', '', '', '', '', 's2784', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2784', 'chapter_17', 17, 'dialogue', 2784, 'taku', '顾天鹏', '差不多。', '', '', '', '', 's2785', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2785', 'chapter_17', 17, 'dialogue', 2785, 'yuki', '小仓友希', '这才叫旅行。看了什么书？', '', '', '', '', 's2786', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2786', 'chapter_17', 17, 'dialogue', 2786, 'taku', '顾天鹏', '《小王子》。', '', '', '', '', 's2787', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2787', 'chapter_17', 17, 'dialogue', 2787, 'yuki', '小仓友希', '小孩子看的？', '', '', '', '', 's2788', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2788', 'chapter_17', 17, 'dialogue', 2788, 'taku', '顾天鹏', '开篇就请孩子们原谅把书献给一个大人。', '', '', '', '', 's2789', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2789', 'chapter_17', 17, 'dialogue', 2789, 'yuki', '小仓友希', '那应该看漫画才对。', '', '', '', '', 's2790', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2790', 'chapter_17', 17, 'dialogue', 2790, 'taku', '顾天鹏', '也看过。', '', '', '', '', 's2791', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2791', 'chapter_17', 17, 'dialogue', 2791, 'yuki', '小仓友希', '那种色色的漫画？', '', '', '', '', 's2792', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2792', 'chapter_17', 17, 'dialogue', 2792, 'taku', '顾天鹏', '色色的漫画？', '', '', '', '', 's2793', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2793', 'chapter_17', 17, 'dialogue', 2793, 'yuki', '小仓友希', '你犹豫一秒就是看过。', '', '', '', '', 's2794', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2794', 'chapter_17', 17, 'dialogue', 2794, 'taku', '顾天鹏', '这算什么定律。', '', '', '', '', 's2795', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2795', 'chapter_17', 17, 'dialogue', 2795, 'yuki', '小仓友希', '一秒定律。', '', '', '', '', 's2796', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2796', 'chapter_17', 17, 'narration', 2796, '', '', '顾天鹏笑了笑，侧身喝了一口咖啡。没加糖，味道有点苦。', '', '', '', '', 's2797', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2797', 'chapter_17', 17, 'narration', 2797, '', '', '店内的歌换成了另一首。他完全没听过歌词，只觉得猫的呼吸声比音乐更容易让人安心。', '', '', '', '', 's2798', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2798', 'chapter_17', 17, 'dialogue', 2798, 'yuki', '小仓友希', '之前和你一起的那个漂亮女孩子呢？', '', '', '', '', 's2799', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2799', 'chapter_17', 17, 'dialogue', 2799, 'taku', '顾天鹏', '她回东京了。', '', '', '', '', 's2800', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2800', 'chapter_17', 17, 'dialogue', 2800, 'yuki', '小仓友希', '你们原来不是一起的吗？', '', '', '', '', 's2801', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2801', 'chapter_17', 17, 'dialogue', 2801, 'taku', '顾天鹏', '只是偶然遇到的。', '', '', '', '', 's2802', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2802', 'chapter_17', 17, 'narration', 2802, '', '', '说出这句话时，他有种在谈几年前事情的错觉。', '', '', '', '', 's2803', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2803', 'chapter_17', 17, 'narration', 2803, '', '', '白裙子、兔子发饰、蓝紫色长发，还有那双摄人心魄的眼睛忽然清晰起来。', '', '', '', '', 's2804', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2804', 'chapter_17', 17, 'dialogue', 2804, 'yuki', '小仓友希', '我还以为你们是情侣。毕竟你也挺帅的。', '', '', '', '', 's2805', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2805', 'chapter_17', 17, 'dialogue', 2805, 'taku', '顾天鹏', '谢谢。其实我也不是想让你夸我。', '', '', '', '', 's2806', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2806', 'chapter_17', 17, 'dialogue', 2806, 'yuki', '小仓友希', '笨蛋。', '', '', '', '', 's2807', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2807', 'chapter_17', 17, 'narration', 2807, '', '', '店里来了寄养猫的客人。小仓友希把白色长毛猫抱进洗澡间，忙了很久才出来。', '', '', '', '', 's2808', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2808', 'chapter_17', 17, 'dialogue', 2808, 'yuki', '小仓友希', '累死了。', '', '', '', '', 's2809', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2809', 'chapter_17', 17, 'narration', 2809, '', '', '顾天鹏从口袋里拿出纸巾递给她。', '', '', '', '', 's2810', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2810', 'chapter_17', 17, 'dialogue', 2810, 'taku', '顾天鹏', '擦汗？', '', '', '', '', 's2811', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2811', 'chapter_17', 17, 'dialogue', 2811, 'yuki', '小仓友希', '谢谢。', '', '', '', '', 's2812', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2812', 'chapter_17', 17, 'narration', 2812, '', '', '他们又听了几首歌。小仓友希若无其事地问他家在哪里，准备在轻井泽待多久。', '', '', '', '', 's2813', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2813', 'chapter_17', 17, 'dialogue', 2813, 'taku', '顾天鹏', '差不多到春天。', '', '', '', '', 's2814', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2814', 'chapter_17', 17, 'dialogue', 2814, 'yuki', '小仓友希', '春天啊。那你要不要来我这里打工？每天来几个小时，有工资。', '', '', '', '', 's2815', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2815', 'chapter_17', 17, 'dialogue', 2815, 'taku', '顾天鹏', '有多少？', '', '', '', '', 's2816', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2816', 'chapter_17', 17, 'dialogue', 2816, 'yuki', '小仓友希', '一般人时薪一千。', '', '', '', '', 's2817', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2817', 'chapter_17', 17, 'dialogue', 2817, 'taku', '顾天鹏', '那我呢？', '', '', '', '', 's2818', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2818', 'chapter_17', 17, 'dialogue', 2818, 'yuki', '小仓友希', '你这么帅，给两千。', '', '', '', '', 's2819', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2819', 'chapter_17', 17, 'dialogue', 2819, 'taku', '顾天鹏', '这是包养？', '', '', '', '', 's2820', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2820', 'chapter_17', 17, 'dialogue', 2820, 'yuki', '小仓友希', '这算吗？', '', '', '', '', 's2821', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2821', 'chapter_17', 17, 'dialogue', 2821, 'taku', '顾天鹏', '我哪知道。', '', '', '', '', 's2822', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2822', 'chapter_17', 17, 'dialogue', 2822, 'yuki', '小仓友希', '那就算。要是过意不去，就站在门口替我发传单揽客。', '', '', '', '', 's2823', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2823', 'chapter_17', 17, 'dialogue', 2823, 'taku', '顾天鹏', '你当我是吉祥物？', '', '', '', '', 's2824', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2824', 'chapter_17', 17, 'dialogue', 2824, 'yuki', '小仓友希', '不错的想法嘛。', '', '', '', '', 's2825', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2825', 'chapter_17', 17, 'narration', 2825, '', '', '他们一直坐到下午四点。顾天鹏把怀里的猫放回软垫，小仓友希跳下椅子，说要送他到门口。', '', '', '', '', 's2826', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2826', 'chapter_17', 17, 'dialogue', 2826, 'taku', '顾天鹏', '不用。', '', '', '', '', 's2827', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2827', 'chapter_17', 17, 'dialogue', 2827, 'yuki', '小仓友希', '那明天来吗？', '', '', '', '', 's2828', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2828', 'chapter_17', 17, 'narration', 2828, '', '', '她问得可怜兮兮，像店里的猫全都替她站在同一边。', '', '', '', '', 's2829', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2829', 'chapter_17', 17, 'dialogue', 2829, 'taku', '顾天鹏', '你开的工资那么多，没法拒绝。', '', '', '', '', 's2830', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2830', 'chapter_17', 17, 'dialogue', 2830, 'yuki', '小仓友希', '说定了！', '', '', '', '', 's2831', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2832', 'chapter_17', 17, 'narration', 2832, '', '', '顾天鹏看着店里安静的灯光和趴在笼子里的猫。', '', '', '', '', 's2833', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2833', 'chapter_17', 17, 'dialogue', 2833, 'taku', '顾天鹏', '你开的工资那么高，没法拒绝。', '', '', '', '', 's2834', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2834', 'chapter_17', 17, 'dialogue', 2834, 'yuki', '小仓友希', '说定了！', '', '', '', '', 's2835', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2835', 'chapter_17', 17, 'jump', 2835, '', '', '', '', '', '', '', 's2839', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2836', 'chapter_17', 17, 'narration', 2836, '', '', '顾天鹏摇了摇头。', '', '', '', '', 's2837', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2837', 'chapter_17', 17, 'dialogue', 2837, 'taku', '顾天鹏', '算了。旅途里认识的人，还是停在旅途里比较好。', '', '', '', '', 's2838', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2838', 'chapter_17', 17, 'jump', 2838, '', '', '', '', '', '', '', 's3477', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2831', 'chapter_17', 17, 'menu', 2831, '', '', '', '', '', '', '', 's2839', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2839', 'chapter_18', 18, 'set', 2839, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2840', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2840', 'chapter_18', 18, 'set', 2840, '', '', '', '', '', 'event_cg_mode', 'false', 's2841', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2841', 'chapter_18', 18, 'scene', 2841, '', '', '', 'bg ch18_pet_shop_rain', '', '', '', 's2842', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2842', 'chapter_18', 18, 'sprite', 2842, '', '', '', '', '[{"image": "yuki petshop", "pos": "cast_single_center"}]', '', '', 's2843', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2843', 'chapter_18', 18, 'narration', 2843, '', '', '双人成行', '', '', '', '', 's2844', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2844', 'chapter_18', 18, 'narration', 2844, '', '', '十一月二十九日晚上八点，顾天鹏结束宠物店兼职，准备离开。', '', '', '', '', 's2845', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2845', 'chapter_18', 18, 'dialogue', 2845, 'yuki', '小仓友希', '顾天鹏！明天……能不能陪我出去走走？店可以先不开。', '', '', '', '', 's2846', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2846', 'chapter_18', 18, 'narration', 2846, '', '', '她像下了很大决心才问出口。', '', '', '', '', 's2847', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2847', 'chapter_18', 18, 'narration', 2847, '', '', '店里的小动物大多睡了，只有几只猫不安分地叫了两声。', '', '', '', '', 's2848', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2848', 'chapter_18', 18, 'dialogue', 2848, 'taku', '顾天鹏', '最近不太想和别人一起出门，抱歉。', '', '', '', '', 's2849', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2849', 'chapter_18', 18, 'narration', 2849, '', '', '小仓友希怔怔看着他。门关上的瞬间，黑暗从缝隙里渗进店内。', '', '', '', '', 's2850', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2850', 'chapter_18', 18, 'narration', 2850, '', '', '十二月四日，外面下着大雨。顾天鹏收起伞，又一次走进宠物店。', '', '', '', '', 's2851', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2851', 'chapter_18', 18, 'dialogue', 2851, 'yuki', '小仓友希', '来啦。外面雨很大？', '', '', '', '', 's2852', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2852', 'chapter_18', 18, 'dialogue', 2852, 'taku', '顾天鹏', '本来都打算不来了。', '', '', '', '', 's2853', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2853', 'chapter_18', 18, 'dialogue', 2853, 'yuki', '小仓友希', '真是辛苦你咯。', '', '', '', '', 's2854', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2854', 'chapter_18', 18, 'narration', 2854, '', '', '猫粮、笼子、洗澡间和柜台的活大多由顾天鹏做完。小仓友希把时薪两千円说得理直气壮。', '', '', '', '', 's2855', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2855', 'chapter_18', 18, 'dialogue', 2855, 'yuki', '小仓友希', '大部分活不是我在干吗？', '', '', '', '', 's2856', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2856', 'chapter_18', 18, 'dialogue', 2856, 'taku', '顾天鹏', '不是我吗？', '', '', '', '', 's2857', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2857', 'chapter_18', 18, 'dialogue', 2857, 'yuki', '小仓友希', '时薪两千没白给。', '', '', '', '', 's2858', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2858', 'chapter_18', 18, 'narration', 2858, '', '', '两个人都放松地笑了一下。橱窗外雨声不停，店里反而显得更亮。', '', '', '', '', 's2859', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2859', 'chapter_18', 18, 'dialogue', 2859, 'yuki', '小仓友希', '那个，明天能一起吃个饭吗？真的只是吃饭。', '', '', '', '', 's2860', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2860', 'chapter_18', 18, 'dialogue', 2860, 'taku', '顾天鹏', '我知道。', '', '', '', '', 's2861', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2861', 'chapter_18', 18, 'dialogue', 2861, 'yuki', '小仓友希', '所以呢，可以吗？', '', '', '', '', 's2862', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2862', 'chapter_18', 18, 'narration', 2862, '', '', '顾天鹏有些犹豫。小仓友希没好气地看着他。', '', '', '', '', 's2863', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2863', 'chapter_18', 18, 'dialogue', 2863, 'yuki', '小仓友希', '婆婆妈妈的，你是没走出失恋的阴影？', '', '', '', '', 's2864', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2864', 'chapter_18', 18, 'dialogue', 2864, 'taku', '顾天鹏', '啥？', '', '', '', '', 's2865', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2865', 'chapter_18', 18, 'dialogue', 2865, 'yuki', '小仓友希', '是不是被女明星甩了，一直不好意思承认？', '', '', '', '', 's2866', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2866', 'chapter_18', 18, 'dialogue', 2866, 'taku', '顾天鹏', '一点也没猜对。', '', '', '', '', 's2867', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2867', 'chapter_18', 18, 'dialogue', 2867, 'yuki', '小仓友希', '那女孩子叫什么？和你一起的那位超级无敌美少女。', '', '', '', '', 's2868', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2868', 'chapter_18', 18, 'dialogue', 2868, 'taku', '顾天鹏', '星野爱。', '', '', '', '', 's2869', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2869', 'chapter_18', 18, 'dialogue', 2869, 'yuki', '小仓友希', '星野爱……名字也很漂亮。', '', '', '', '', 's2870', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2870', 'chapter_18', 18, 'dialogue', 2870, 'yuki', '小仓友希', '这趟出门就是为了她吧？', '', '', '', '', 's2871', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2871', 'chapter_18', 18, 'dialogue', 2871, 'taku', '顾天鹏', '不是。', '', '', '', '', 's2872', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2872', 'chapter_18', 18, 'dialogue', 2872, 'yuki', '小仓友希', '谎言？', '', '', '', '', 's2873', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2873', 'chapter_18', 18, 'dialogue', 2873, 'taku', '顾天鹏', '不是所有话都需要那么判断。', '', '', '', '', 's2874', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2874', 'chapter_18', 18, 'dialogue', 2874, 'yuki', '小仓友希', '那就是更像真的谎言。', '', '', '', '', 's2875', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2875', 'chapter_18', 18, 'narration', 2875, '', '', '顾天鹏没有继续解释。', '', '', '', '', 's2876', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2876', 'chapter_18', 18, 'scene', 2876, '', '', '', 'bg ch18_ice_cream_shop', '', '', '', 's2877', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2877', 'chapter_18', 18, 'sprite', 2877, '', '', '', '', '[{"image": "yuki tissue", "pos": "cast_single_center"}]', '', '', 's2878', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2878', 'chapter_18', 18, 'narration', 2878, '', '', '第二天，他们先去了冰淇淋店。小仓友希点了一份咖啡果冻摩卡冰淇淋，吃得像在完成限时挑战。', '', '', '', '', 's2879', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2879', 'chapter_18', 18, 'dialogue', 2879, 'yuki', '小仓友希', '我想吃冰淇淋。', '', '', '', '', 's2880', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2880', 'chapter_18', 18, 'dialogue', 2880, 'taku', '顾天鹏', '等会儿还要吃饭。', '', '', '', '', 's2881', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2881', 'chapter_18', 18, 'dialogue', 2881, 'yuki', '小仓友希', '吃冰淇淋和吃饭不是一回事。', '', '', '', '', 's2882', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2882', 'chapter_18', 18, 'dialogue', 2882, 'taku', '顾天鹏', '我就不要了。', '', '', '', '', 's2883', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2883', 'chapter_18', 18, 'dialogue', 2883, 'yuki', '小仓友希', '你不喜欢？', '', '', '', '', 's2884', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2884', 'chapter_18', 18, 'dialogue', 2884, 'taku', '顾天鹏', '只是后面还要吃饭。', '', '', '', '', 's2885', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2885', 'chapter_18', 18, 'scene', 2885, '', '', '', 'bg ch10_lunch_restaurant', '', '', '', 's2886', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2886', 'chapter_18', 18, 'sprite', 2886, '', '', '', '', '[{"image": "yuki tissue", "pos": "cast_single_center"}]', '', '', 's2887', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2887', 'chapter_18', 18, 'narration', 2887, '', '', '之后两人走进一家西式餐厅。小仓友希一口气点了很多东西，连服务员都忍不住提醒。', '', '', '', '', 's2888', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2888', 'chapter_18', 18, 'dialogue', 2888, 'taku', '顾天鹏', '点这么多没问题？', '', '', '', '', 's2889', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2889', 'chapter_18', 18, 'dialogue', 2889, 'yuki', '小仓友希', '没问题。', '', '', '', '', 's2890', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2890', 'chapter_18', 18, 'narration', 2890, '', '', '她赌气似的又勾上一个餐后点心。', '', '', '', '', 's2891', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2891', 'chapter_18', 18, 'narration', 2891, '', '', '顾天鹏看着菜单上被她划出来的一串菜名，忽然觉得这顿饭不像吃饭，更像她在和某种看不见的东西较劲。', '', '', '', '', 's2892', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2892', 'chapter_18', 18, 'narration', 2892, '', '', '服务员端上来的盘子几乎摆满桌面。小仓友希吃得很快，偶尔抬头看他一眼，又装作什么都没发生地去切牛排。', '', '', '', '', 's2893', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2893', 'chapter_18', 18, 'dialogue', 2893, 'taku', '顾天鹏', '慢点也没关系。', '', '', '', '', 's2894', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2894', 'chapter_18', 18, 'dialogue', 2894, 'yuki', '小仓友希', '我没有急。', '', '', '', '', 's2895', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2895', 'chapter_18', 18, 'dialogue', 2895, 'taku', '顾天鹏', '谎言。', '', '', '', '', 's2896', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2896', 'chapter_18', 18, 'dialogue', 2896, 'yuki', '小仓友希', '这招不是只有你和她之间才能用吗？', '', '', '', '', 's2897', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2897', 'chapter_18', 18, 'narration', 2897, '', '', '顾天鹏没有回答。小仓友希把叉子戳进餐后点心里，像终于抓到可以出气的东西。', '', '', '', '', 's2898', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2898', 'chapter_19', 19, 'set', 2898, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2899', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2899', 'chapter_19', 19, 'set', 2899, '', '', '', '', '', 'event_cg_mode', 'false', 's2900', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2900', 'chapter_19', 19, 'scene', 2900, '', '', '', 'bg ch7_cafe', '', '', '', 's2901', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2901', 'chapter_19', 19, 'sprite', 2901, '', '', '', '', '[{"image": "yuki tissue", "pos": "cast_single_center"}]', '', '', 's2902', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2902', 'chapter_19', 19, 'narration', 2902, '', '', '再见', '', '', '', '', 's2903', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2903', 'chapter_19', 19, 'narration', 2903, '', '', '吃完饭后，外面下了一层薄薄的雨。', '', '', '', '', 's2904', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2904', 'chapter_19', 19, 'dialogue', 2904, 'yuki', '小仓友希', '难得出来，再多陪我一会儿？', '', '', '', '', 's2905', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2905', 'chapter_19', 19, 'dialogue', 2905, 'taku', '顾天鹏', '下次吧。今天下雨，我想早点回去。', '', '', '', '', 's2906', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2906', 'chapter_19', 19, 'narration', 2906, '', '', '小仓友希的表情有点失落。她看见顾天鹏望着雨帘，像在看某个并不在这里的人。', '', '', '', '', 's2907', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2907', 'chapter_19', 19, 'narration', 2907, '', '', '他说的那句下次很快被雨声淹没。她抬头看他侧脸的时候，忽然明白自己没法挤进那道视线。', '', '', '', '', 's2908', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2908', 'chapter_19', 19, 'narration', 2908, '', '', '平安夜那天，天气晴。两人坐进一间精致咖啡屋。', '', '', '', '', 's2909', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2909', 'chapter_19', 19, 'dialogue', 2909, 'yuki', '小仓友希', '我要甜甜的。', '', '', '', '', 's2910', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2910', 'chapter_19', 19, 'dialogue', 2910, 'taku', '顾天鹏', '牛奶就好。', '', '', '', '', 's2911', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2911', 'chapter_19', 19, 'narration', 2911, '', '', '小仓友希凑过来看他手里的书。', '', '', '', '', 's2912', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2912', 'chapter_19', 19, 'dialogue', 2912, 'yuki', '小仓友希', '这本好看吗？', '', '', '', '', 's2913', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2913', 'chapter_19', 19, 'dialogue', 2913, 'taku', '顾天鹏', '还挺喜欢。', '', '', '', '', 's2914', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2914', 'chapter_19', 19, 'dialogue', 2914, 'yuki', '小仓友希', '下次借漫画来看吧。', '', '', '', '', 's2915', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2915', 'chapter_19', 19, 'dialogue', 2915, 'taku', '顾天鹏', '色色的漫画？', '', '', '', '', 's2916', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2916', 'chapter_19', 19, 'dialogue', 2916, 'yuki', '小仓友希', '色色的漫画。', '', '', '', '', 's2917', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2917', 'chapter_19', 19, 'narration', 2917, '', '', '她笑起来，阳光正好落在她脸上。', '', '', '', '', 's2918', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2918', 'chapter_19', 19, 'dialogue', 2918, 'yuki', '小仓友希', '晚上和我一起去看电影吧？', '', '', '', '', 's2919', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2919', 'chapter_19', 19, 'dialogue', 2919, 'taku', '顾天鹏', '算了。', '', '', '', '', 's2920', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2920', 'chapter_19', 19, 'dialogue', 2920, 'yuki', '小仓友希', '又是算了。别逼我求你，好吗？', '', '', '', '', 's2921', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2921', 'chapter_19', 19, 'narration', 2921, '', '', '如果是在遇到星野爱之前，顾天鹏或许会答应。可现在他不太喜欢那种相处之后又注定分开的感觉。', '', '', '', '', 's2922', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2922', 'chapter_19', 19, 'dialogue', 2922, 'taku', '顾天鹏', '不行。', '', '', '', '', 's2923', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2923', 'chapter_19', 19, 'dialogue', 2923, 'yuki', '小仓友希', '行。', '', '', '', '', 's2924', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2924', 'chapter_19', 19, 'dialogue', 2924, 'taku', '顾天鹏', '你完全不听别人讲话。', '', '', '', '', 's2925', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2925', 'chapter_19', 19, 'dialogue', 2925, 'yuki', '小仓友希', '我不管。', '', '', '', '', 's2926', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2926', 'chapter_19', 19, 'narration', 2926, '', '', '最后他还是被小仓友希拖去了电影院。', '', '', '', '', 's2927', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2927', 'chapter_19', 19, 'scene', 2927, '', '', '', 'bg ch19_cinema_lobby', '', '', '', 's2928', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2928', 'chapter_19', 19, 'sprite', 2928, '', '', '', '', '[{"image": "yuki tissue", "pos": "cast_single_center"}]', '', '', 's2929', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2929', 'chapter_19', 19, 'narration', 2929, '', '', '影院大厅里有圣诞装饰，外面的冬夜被玻璃门隔开。', '', '', '', '', 's2930', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2930', 'chapter_19', 19, 'set', 2930, '', '', '', '', '', 'event_cg_mode', 'true', 's2931', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2931', 'chapter_19', 19, 'scene', 2931, '', '', '', 'cg ch19_yuki_movie_tears', '', '', '', 's2932', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2932', 'chapter_19', 19, 'narration', 2932, '', '', '电影很感人，她哭得一塌糊涂。后来他们吃了街边小吃、烤番薯，还去游乐厅抓娃娃，结果一个也没抓到。', '', '', '', '', 's2933', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2933', 'chapter_19', 19, 'dialogue', 2933, 'yuki', '小仓友希', '呜呜……', '', '', '', '', 's2934', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2934', 'chapter_19', 19, 'dialogue', 2934, 'taku', '顾天鹏', '还要纸吗？', '', '', '', '', 's2935', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2935', 'chapter_19', 19, 'dialogue', 2935, 'yuki', '小仓友希', '谢谢。', '', '', '', '', 's2936', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2936', 'chapter_19', 19, 'narration', 2936, '', '', '她哭得毫不遮掩，走出电影院以后又立刻恢复精神，像刚才痛哭的人不是她。', '', '', '', '', 's2937', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2937', 'chapter_19', 19, 'dialogue', 2937, 'yuki', '小仓友希', '今天很开心。', '', '', '', '', 's2938', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2938', 'chapter_19', 19, 'narration', 2938, '', '', '十点多，顾天鹏把她送到家门口。月色和灯光落在她脸上，像一段快要消失的记忆。', '', '', '', '', 's2939', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2939', 'chapter_19', 19, 'dialogue', 2939, 'yuki', '小仓友希', '虽然很过分，这一段回忆，勉强就让我占据吧。', '', '', '', '', 's2940', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2940', 'chapter_19', 19, 'narration', 2940, '', '', '十二月三十一日，一年的最后一天，晴。', '', '', '', '', 's2941', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2941', 'chapter_19', 19, 'dialogue', 2941, 'yuki', '小仓友希', '准备什么时候回东京？', '', '', '', '', 's2942', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2942', 'chapter_19', 19, 'dialogue', 2942, 'taku', '顾天鹏', '明天晚上。', '', '', '', '', 's2943', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2943', 'chapter_19', 19, 'narration', 2943, '', '', '小仓友希没有立刻说话。她把手插进口袋，像在确认里面是否还装着能留下他的借口。', '', '', '', '', 's2944', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2944', 'chapter_19', 19, 'dialogue', 2944, 'yuki', '小仓友希', '那今天算是最后一天？', '', '', '', '', 's2945', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2945', 'chapter_19', 19, 'dialogue', 2945, 'taku', '顾天鹏', '轻井泽的最后一天。', '', '', '', '', 's2946', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2946', 'chapter_19', 19, 'dialogue', 2946, 'yuki', '小仓友希', '说得真冷淡。', '', '', '', '', 's2947', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2947', 'chapter_19', 19, 'dialogue', 2947, 'taku', '顾天鹏', '事实就是这样。', '', '', '', '', 's2948', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2948', 'chapter_19', 19, 'dialogue', 2948, 'yuki', '小仓友希', '事实有时候也很讨厌。', '', '', '', '', 's2949', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2949', 'chapter_19', 19, 'narration', 2949, '', '', '两个人在晴朗的一年末站了很久。雪没有落下来，风也不算冷，可分别的轮廓已经提前出现在那里。', '', '', '', '', 's2950', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2950', 'chapter_20', 20, 'set', 2950, '', '', '', '', '', 'ai_sprite_mode', 'false', 's2951', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2951', 'chapter_20', 20, 'set', 2951, '', '', '', '', '', 'event_cg_mode', 'false', 's2952', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2952', 'chapter_20', 20, 'scene', 2952, '', '', '', 'bg ch17_pet_shop', '', '', '', 's2953', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2953', 'chapter_20', 20, 'sprite', 2953, '', '', '', '', '[{"image": "yuki petshop", "pos": "cast_single_center"}]', '', '', 's2954', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2954', 'chapter_20', 20, 'narration', 2954, '', '', '四月是你的谎言', '', '', '', '', 's2955', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2955', 'chapter_20', 20, 'dialogue', 2955, 'yuki', '小仓友希', '不是说好了春天回去吗？', '', '', '', '', 's2956', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2956', 'chapter_20', 20, 'dialogue', 2956, 'taku', '顾天鹏', '我还是想早点回去。', '', '', '', '', 's2957', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2957', 'chapter_20', 20, 'dialogue', 2957, 'yuki', '小仓友希', '理由呢？', '', '', '', '', 's2958', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2958', 'chapter_20', 20, 'dialogue', 2958, 'taku', '顾天鹏', '说不清。', '', '', '', '', 's2959', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2959', 'chapter_20', 20, 'dialogue', 2959, 'yuki', '小仓友希', '哪有什么说不清的。', '', '', '', '', 's2960', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2960', 'chapter_20', 20, 'dialogue', 2960, 'taku', '顾天鹏', '那就当是秘密好了。', '', '', '', '', 's2961', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2961', 'chapter_20', 20, 'dialogue', 2961, 'yuki', '小仓友希', '就不能晚点？一月底，二月中旬也行啊。', '', '', '', '', 's2962', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2962', 'chapter_20', 20, 'dialogue', 2962, 'taku', '顾天鹏', '原本有这个打算，后来改变主意了。', '', '', '', '', 's2963', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2963', 'chapter_20', 20, 'narration', 2963, '', '', '小仓友希抱着杯子，替他把电话和 LINE 加进手机。她家在东京也开了一家店。', '', '', '', '', 's2964', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2964', 'chapter_20', 20, 'dialogue', 2964, 'yuki', '小仓友希', '回去找工作的时候，打上面的电话。', '', '', '', '', 's2965', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2965', 'chapter_20', 20, 'dialogue', 2965, 'taku', '顾天鹏', '宠物店？', '', '', '', '', 's2966', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2966', 'chapter_20', 20, 'dialogue', 2966, 'yuki', '小仓友希', '星巴克。', '', '', '', '', 's2967', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2967', 'chapter_20', 20, 'dialogue', 2967, 'taku', '顾天鹏', '你家到底多有钱？', '', '', '', '', 's2968', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2968', 'chapter_20', 20, 'dialogue', 2968, 'yuki', '小仓友希', '一点点。', '', '', '', '', 's2969', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2969', 'chapter_20', 20, 'narration', 2969, '', '', '她还翻出了面包店、健身房、游泳馆、家庭电话和高中班主任的联系方式。', '', '', '', '', 's2970', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2970', 'chapter_20', 20, 'dialogue', 2970, 'yuki', '小仓友希', '你是外星人吗？怎么连朋友都没有？', '', '', '', '', 's2971', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2971', 'chapter_20', 20, 'dialogue', 2971, 'taku', '顾天鹏', '只是不喜欢乱交朋友。', '', '', '', '', 's2972', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2972', 'chapter_20', 20, 'dialogue', 2972, 'yuki', '小仓友希', '居然连星野爱的联系方式也没有。', '', '', '', '', 's2973', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2973', 'chapter_20', 20, 'narration', 2973, '', '', '顾天鹏被咖啡呛了一下。', '', '', '', '', 's2974', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2974', 'chapter_20', 20, 'scene', 2974, '', '', '', 'bg ch20_karuizawa_station_winter', '', '', '', 's2975', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2975', 'chapter_20', 20, 'narration', 2975, '', '', '车站灯光亮起来时，轻井泽的冬天像被提前装进行李。', '', '', '', '', 's2976', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2976', 'chapter_20', 20, 'set', 2976, '', '', '', '', '', 'event_cg_mode', 'true', 's2977', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2977', 'chapter_20', 20, 'scene', 2977, '', '', '', 'cg ch20_yuki_station_gift', '', '', '', 's2978', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2978', 'chapter_20', 20, 'narration', 2978, '', '', '离开轻井泽那天，小仓友希送他到车站，还把一盒游戏塞进他手里。', '', '', '', '', 's2979', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2979', 'chapter_20', 20, 'dialogue', 2979, 'yuki', '小仓友希', '礼物！双人成行。等你有朋友一起玩的时候再拆。', '', '', '', '', 's2980', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2980', 'chapter_20', 20, 'narration', 2980, '', '', '冬天过去。电话里，小仓友希常常讲起轻井泽：石之教堂的婚礼、跑到街上的野猪、宠物店旁新开的咖啡屋。', '', '', '', '', 's2981', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2981', 'chapter_20', 20, 'narration', 2981, '', '', '她讲很多，顾天鹏听很多。电话挂断前，她说下次再来，就不用喝自己泡的难喝咖啡了。', '', '', '', '', 's2982', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2982', 'chapter_20', 20, 'dialogue', 2982, 'yuki', '小仓友希', '到时候我们去旁边新开的那家坐。', '', '', '', '', 's2983', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2983', 'chapter_20', 20, 'dialogue', 2983, 'taku', '顾天鹏', '是。', '', '', '', '', 's2984', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2984', 'chapter_20', 20, 'narration', 2984, '', '', '顾天鹏回东京后开始按部就班生活：跑步、读书、准备工作，偶尔去小仓友希介绍的咖啡店试班。', '', '', '', '', 's2985', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2985', 'chapter_20', 20, 'narration', 2985, '', '', '冬天的轻井泽被电话线留在另一端。星野爱的名字则像夹在书页里的照片，不碰也知道还在那里。', '', '', '', '', 's2986', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2986', 'chapter_20', 20, 'narration', 2986, '', '', '三月末的某天，小仓友希又打来电话，问他是不是已经把她忘了。顾天鹏说没有。', '', '', '', '', 's2987', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2987', 'chapter_20', 20, 'dialogue', 2987, 'yuki', '小仓友希', '那你说说第几次给你打电话了？', '', '', '', '', 's2988', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2988', 'chapter_20', 20, 'dialogue', 2988, 'taku', '顾天鹏', '不知道。', '', '', '', '', 's2989', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2989', 'chapter_20', 20, 'dialogue', 2989, 'yuki', '小仓友希', '所以才需要纪念日。', '', '', '', '', 's2990', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2990', 'chapter_20', 20, 'scene', 2990, '', '', '', 'bg ch20_sakura_slope', '', '', '', 's2991', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2991', 'chapter_20', 20, 'narration', 2991, '', '', '四月一日，顾天鹏从涩谷站下车，春日阳光比想象中还明媚。', '', '', '', '', 's2992', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2992', 'chapter_20', 20, 'narration', 2992, '', '', '高中制服的女生牵手经过，上班族提着黑色公文包匆匆走远，骑自行车的男生消失在拐角。', '', '', '', '', 's2993', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2993', 'chapter_20', 20, 'narration', 2993, '', '', '他扯了扯胸口的领结，一阵温暖的风从身后吹来，把他的衣角轻轻掀起。', '', '', '', '', 's2994', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2994', 'chapter_20', 20, 'narration', 2994, '', '', '粉色樱花沿着道路盛开，风吹过居民楼和坡道。', '', '', '', '', 's2995', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2995', 'chapter_20', 20, 'set', 2995, '', '', '', '', '', 'event_cg_mode', 'true', 's2996', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2996', 'chapter_20', 20, 'scene', 2996, '', '', '', 'cg ch20_sakura_reunion', '', '', '', 's2997', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2997', 'chapter_20', 20, 'narration', 2997, '', '', '他站在坡道下方抬头，看见那位少女站在坡道上。', '', '', '', '', 's2998', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2998', 'chapter_20', 20, 'narration', 2998, '', '', '清风拂过她的长发和裙角，世间一切美好仿佛都成了她的陪衬。', '', '', '', '', 's2999', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s2999', 'chapter_20', 20, 'narration', 2999, '', '', '那一天是四月的伊始。星野爱站在坡道上方，顾天鹏站在坡道下面，中间是樱花雨。', '', '', '', '', 's3000', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3000', 'chapter_21', 21, 'set', 3000, '', '', '', '', '', 'event_cg_mode', 'false', 's3001', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3001', 'chapter_21', 21, 'set', 3001, '', '', '', '', '', 'ai_sprite_mode', 'true', 's3002', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3002', 'chapter_21', 21, 'set', 3002, '', '', '', '', '', 'ai_sprite_outfit', 'ch20_spring', 's3003', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3003', 'chapter_21', 21, 'set', 3003, '', '', '', '', '', 'ai_sprite_position', 'right', 's3004', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3004', 'chapter_21', 21, 'scene', 3004, '', '', '', 'bg ch20_sakura_slope', '', '', '', 's3005', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3005', 'chapter_21', 21, 'sprite', 3005, '', '', '', '', '[{"image": "heroine ch20_spring", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3006', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3006', 'chapter_21', 21, 'narration', 3006, '', '', '电车驶过', '', '', '', '', 's3007', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3007', 'chapter_21', 21, 'dialogue', 3007, 'ai', '星野爱', '顾……天鹏？', '', '', '', '', 's3008', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3008', 'chapter_21', 21, 'narration', 3008, '', '', '风把她的头发吹到嘴边。她像第一次见面那样抬手拨开刘海。', '', '', '', '', 's3009', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3009', 'chapter_21', 21, 'dialogue', 3009, 'taku', '顾天鹏', '好久不见。', '', '', '', '', 's3010', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3010', 'chapter_21', 21, 'dialogue', 3010, 'ai', '星野爱', '嗯，好久不见！', '', '', '', '', 's3011', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3011', 'chapter_21', 21, 'narration', 3011, '', '', '那笑容太久违。顾天鹏差点忘了记忆里也曾经有过这样心动又真切的画面。', '', '', '', '', 's3012', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3012', 'chapter_21', 21, 'narration', 3012, '', '', '八点多，两个人沿着居民区散步，穿过铁道，路过公园。', '', '', '', '', 's3013', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3013', 'chapter_21', 21, 'narration', 3013, '', '', '公园里有不专业的棒球队在比赛，远处两个孩子玩滑梯和跷跷板，一个少女在树旁荡秋千。', '', '', '', '', 's3014', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3014', 'chapter_21', 21, 'dialogue', 3014, 'ai', '星野爱', '什么时候到东京的？', '', '', '', '', 's3015', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3015', 'chapter_21', 21, 'dialogue', 3015, 'taku', '顾天鹏', '年初就回来了。', '', '', '', '', 's3016', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3016', 'chapter_21', 21, 'dialogue', 3016, 'ai', '星野爱', '我还以为是最近。那怎么改变主意了？', '', '', '', '', 's3017', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3017', 'chapter_21', 21, 'dialogue', 3017, 'taku', '顾天鹏', '说不清。', '', '', '', '', 's3018', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3018', 'chapter_21', 21, 'narration', 3018, '', '', '他们在咖啡馆坐下。轻井泽提前离开的原因仍旧被她藏成秘密。', '', '', '', '', 's3019', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3019', 'chapter_21', 21, 'dialogue', 3019, 'ai', '星野爱', '之前相处得很开心呢。轻井泽也好，越后汤泽也是，真想一直玩下去。', '', '', '', '', 's3020', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3020', 'chapter_21', 21, 'dialogue', 3020, 'taku', '顾天鹏', '那为什么提前离开？', '', '', '', '', 's3021', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3021', 'chapter_21', 21, 'dialogue', 3021, 'ai', '星野爱', '说不定我和你一样，喜欢东京多一点。', '', '', '', '', 's3022', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3022', 'chapter_21', 21, 'dialogue', 3022, 'taku', '顾天鹏', '谎言。', '', '', '', '', 's3023', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3023', 'chapter_21', 21, 'dialogue', 3023, 'ai', '星野爱', '哈，又来？', '', '', '', '', 's3024', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3024', 'chapter_21', 21, 'dialogue', 3024, 'taku', '顾天鹏', '讨厌我？', '', '', '', '', 's3025', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3025', 'chapter_21', 21, 'dialogue', 3025, 'ai', '星野爱', '绝对不是！', '', '', '', '', 's3026', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3026', 'chapter_21', 21, 'dialogue', 3026, 'taku', '顾天鹏', '那到底是什么？', '', '', '', '', 's3027', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3027', 'chapter_21', 21, 'dialogue', 3027, 'ai', '星野爱', '秘密！早点习惯。', '', '', '', '', 's3028', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3028', 'chapter_21', 21, 'narration', 3028, '', '', '顾天鹏没有继续逼问。她的秘密像春天路边的阴影，看得见，却不能踩得太用力。', '', '', '', '', 's3029', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3029', 'chapter_21', 21, 'dialogue', 3029, 'ai', '星野爱', '你呢？刚才说找工作。', '', '', '', '', 's3030', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3030', 'chapter_21', 21, 'dialogue', 3030, 'taku', '顾天鹏', '还没有，不过可以有。', '', '', '', '', 's3031', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3031', 'chapter_21', 21, 'dialogue', 3031, 'ai', '星野爱', '你说的话太难懂了。', '', '', '', '', 's3032', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3032', 'chapter_21', 21, 'dialogue', 3032, 'taku', '顾天鹏', '可能吧。', '', '', '', '', 's3033', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3033', 'chapter_21', 21, 'dialogue', 3033, 'taku', '顾天鹏', '之前拍的那张照片，我又打印了一份。这样你也能留着。', '', '', '', '', 's3034', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3034', 'chapter_21', 21, 'dialogue', 3034, 'ai', '星野爱', '想得真周到。谢谢！', '', '', '', '', 's3035', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3036', 'chapter_21', 21, 'narration', 3036, '', '', '顾天鹏把自己的手机拿出来。', '', '', '', '', 's3037', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3037', 'chapter_21', 21, 'dialogue', 3037, 'ai', '星野爱', '上次离开得太匆忙，忘记要你联系方式了。在车上我还一直犯愁呢。', '', '', '', '', 's3038', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3038', 'chapter_21', 21, 'dialogue', 3038, 'taku', '顾天鹏', '可以。', '', '', '', '', 's3039', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3039', 'chapter_21', 21, 'narration', 3039, '', '', '两个人交换了 LINE。', '', '', '', '', 's3040', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3040', 'chapter_21', 21, 'set', 3040, '', '', '', '', '', 'event_cg_mode', 'true', 's3041', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3041', 'chapter_21', 21, 'scene', 3041, '', '', '', 'cg ch21_ai_photo_contact', '', '', '', 's3042', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3042', 'chapter_21', 21, 'narration', 3042, '', '', '顾天鹏注意到她手机已经换了。手机壳、牌子都和旅行时不一样。', '', '', '', '', 's3043', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3043', 'chapter_21', 21, 'narration', 3043, '', '', '他没有问为什么。春天的重逢已经足够脆弱，没必要马上把每个缺口都挖开。', '', '', '', '', 's3047', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3044', 'chapter_21', 21, 'narration', 3044, '', '', '顾天鹏把照片推过去，却没有拿出手机。', '', '', '', '', 's3045', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3045', 'chapter_21', 21, 'narration', 3045, '', '', '之后他们仍然会偶尔想起这天，只是没有任何一句消息能穿过春天。', '', '', '', '', 's3046', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3046', 'chapter_21', 21, 'jump', 3046, '', '', '', '', '', '', '', 's3484', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3035', 'chapter_21', 21, 'menu', 3035, '', '', '', '', '', '', '', 's3047', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3047', 'chapter_21', 21, 'set', 3047, '', '', '', '', '', 'event_cg_mode', 'false', 's3048', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3048', 'chapter_21', 21, 'scene', 3048, '', '', '', 'bg ch20_sakura_slope', '', '', '', 's3049', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3049', 'chapter_21', 21, 'sprite', 3049, '', '', '', '', '[{"image": "heroine ch20_spring", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3050', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3050', 'chapter_21', 21, 'narration', 3050, '', '', '他们继续往前走。没有人提出目的地，也没有人急着停下来。', '', '', '', '', 's3051', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3051', 'chapter_21', 21, 'narration', 3051, '', '', '沥青路旁的树还没完全长满叶子，春风像刚刚醒来。', '', '', '', '', 's3052', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3052', 'chapter_21', 21, 'dialogue', 3052, 'ai', '星野爱', '不是什么非说不可的事。', '', '', '', '', 's3053', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3053', 'chapter_21', 21, 'dialogue', 3053, 'taku', '顾天鹏', '我想听。', '', '', '', '', 's3054', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3054', 'chapter_21', 21, 'set', 3054, '', '', '', '', '', 'ai_sprite_outfit', 'ch21_secret', 's3055', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3055', 'chapter_21', 21, 'sprite', 3055, '', '', '', '', '[{"image": "heroine ch21_secret", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3056', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3056', 'chapter_21', 21, 'dialogue', 3056, 'ai', '星野爱', '那就不告诉你～', '', '', '', '', 's3057', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3057', 'chapter_21', 21, 'dialogue', 3057, 'taku', '顾天鹏', '这也太过分了吧？', '', '', '', '', 's3058', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3058', 'chapter_21', 21, 'dialogue', 3058, 'ai', '星野爱', '还好啦。只告诉你也行。', '', '', '', '', 's3059', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3059', 'chapter_21', 21, 'dialogue', 3059, 'taku', '顾天鹏', '那告诉我。', '', '', '', '', 's3060', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3060', 'chapter_21', 21, 'dialogue', 3060, 'ai', '星野爱', '为什么？你有什么特殊的？', '', '', '', '', 's3061', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3061', 'chapter_21', 21, 'dialogue', 3061, 'taku', '顾天鹏', '长得帅。', '', '', '', '', 's3062', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3062', 'chapter_21', 21, 'dialogue', 3062, 'ai', '星野爱', '这个不算。', '', '', '', '', 's3063', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3063', 'chapter_21', 21, 'narration', 3063, '', '', '他们走到电车轨道前。黄黑色栏杆落下，信号声叮叮响起。', '', '', '', '', 's3064', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3064', 'chapter_21', 21, 'narration', 3064, '', '', '轰隆隆的电车驶过，遮住了两人的视线。', '', '', '', '', 's3065', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3065', 'chapter_21', 21, 'dialogue', 3065, 'ai', '星野爱', '我决定，要成为偶像了。', '', '', '', '', 's3066', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3066', 'chapter_21', 21, 'narration', 3066, '', '', '她说这句话时，声音很轻，却像被电车驶过后的风完整留下来。', '', '', '', '', 's3067', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3067', 'chapter_22', 22, 'set', 3067, '', '', '', '', '', 'ai_sprite_mode', 'true', 's3068', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3068', 'chapter_22', 22, 'set', 3068, '', '', '', '', '', 'ai_sprite_outfit', 'ch20_spring', 's3069', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3069', 'chapter_22', 22, 'set', 3069, '', '', '', '', '', 'ai_sprite_position', 'right', 's3070', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3070', 'chapter_22', 22, 'scene', 3070, '', '', '', 'bg ch20_sakura_slope', '', '', '', 's3071', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3071', 'chapter_22', 22, 'sprite', 3071, '', '', '', '', '[{"image": "heroine ch20_spring", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3072', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3072', 'chapter_22', 22, 'narration', 3072, '', '', 'KIA', '', '', '', '', 's3073', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3073', 'chapter_22', 22, 'dialogue', 3073, 'taku', '顾天鹏', '恭喜。', '', '', '', '', 's3074', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3074', 'chapter_22', 22, 'dialogue', 3074, 'ai', '星野爱', '谢谢。', '', '', '', '', 's3075', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3075', 'chapter_22', 22, 'narration', 3075, '', '', '她没有表现得特别高兴，只是认真地跨过轨道。', '', '', '', '', 's3076', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3076', 'chapter_22', 22, 'narration', 3076, '', '', '顾天鹏落后她一米多。经过家居量贩店时，她回头瞥了一眼，又放慢脚步等他到身边。', '', '', '', '', 's3077', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3077', 'chapter_22', 22, 'dialogue', 3077, 'ai', '星野爱', '我其实有点担心。担心自己做不好。', '', '', '', '', 's3078', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3078', 'chapter_22', 22, 'dialogue', 3078, 'taku', '顾天鹏', '这点最不用担心。你可是星野爱。', '', '', '', '', 's3079', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3079', 'chapter_22', 22, 'dialogue', 3079, 'ai', '星野爱', '可我不够善良，没什么朋友。', '', '', '', '', 's3080', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3080', 'chapter_22', 22, 'dialogue', 3080, 'taku', '顾天鹏', '有一个就不少。', '', '', '', '', 's3081', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3081', 'chapter_22', 22, 'dialogue', 3081, 'ai', '星野爱', '我讨厌别人，从来没喜欢过谁，没爱过谁。', '', '', '', '', 's3082', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3082', 'chapter_22', 22, 'dialogue', 3082, 'taku', '顾天鹏', '只是现在。', '', '', '', '', 's3083', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3083', 'chapter_22', 22, 'dialogue', 3083, 'ai', '星野爱', '我撒谎成性。', '', '', '', '', 's3084', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3084', 'chapter_22', 22, 'dialogue', 3084, 'taku', '顾天鹏', '否则就不是星野爱了。', '', '', '', '', 's3085', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3085', 'chapter_22', 22, 'narration', 3085, '', '', '树影在她脸上摇晃。她静静看着他，像有某种难以置信的东西在眼里发芽。', '', '', '', '', 's3086', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3086', 'chapter_22', 22, 'dialogue', 3086, 'ai', '星野爱', '顾天鹏，你讨厌谎言吗？', '', '', '', '', 's3087', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3087', 'chapter_22', 22, 'dialogue', 3087, 'taku', '顾天鹏', '不讨厌。', '', '', '', '', 's3088', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3088', 'chapter_22', 22, 'dialogue', 3088, 'ai', '星野爱', '即便是谎言，也会在某一天变成事实吗？', '', '', '', '', 's3089', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3089', 'chapter_22', 22, 'dialogue', 3089, 'taku', '顾天鹏', '或许吧。', '', '', '', '', 's3090', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3090', 'chapter_22', 22, 'dialogue', 3090, 'ai', '星野爱', '或许……', '', '', '', '', 's3091', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3091', 'chapter_22', 22, 'narration', 3091, '', '', '她低头思考。四月的风带着泥土和树叶的味道从两人之间经过。', '', '', '', '', 's3092', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3092', 'chapter_22', 22, 'narration', 3092, '', '', '午餐前分别时，星野爱站在涩谷街头向他挥手。', '', '', '', '', 's3093', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3093', 'chapter_22', 22, 'dialogue', 3093, 'ai', '星野爱', '顾天鹏，遇到你，今天很开心。', '', '', '', '', 's3094', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3094', 'chapter_22', 22, 'dialogue', 3094, 'taku', '顾天鹏', '我也一样。', '', '', '', '', 's3095', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3095', 'chapter_22', 22, 'dialogue', 3095, 'ai', '星野爱', '这次我先联系你。', '', '', '', '', 's3096', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3096', 'chapter_22', 22, 'dialogue', 3096, 'taku', '顾天鹏', '我等着你。', '', '', '', '', 's3097', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3097', 'chapter_22', 22, 'scene', 3097, '', '', '', 'bg ch22_shibuya_spring', '', '', '', 's3098', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3098', 'chapter_22', 22, 'narration', 3098, '', '', '涩谷街头人流和车流交叠，春光落在玻璃幕墙上。', '', '', '', '', 's3099', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3099', 'chapter_22', 22, 'narration', 3099, '', '', '午餐前他们分开。顾天鹏接到小仓友希的电话，又赶去她家在东京开的咖啡店。', '', '', '', '', 's3100', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3100', 'chapter_22', 22, 'sprite', 3100, '', '', '', '', '[{"image": "yuki phone", "pos": "cast_single_center"}]', '', '', 's3101', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3101', 'chapter_22', 22, 'dialogue', 3101, 'yuki', '小仓友希', '你早上怎么不接电话？', '', '', '', '', 's3102', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3102', 'chapter_22', 22, 'dialogue', 3102, 'taku', '顾天鹏', '各种各样的事情。', '', '', '', '', 's3103', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3103', 'chapter_22', 22, 'dialogue', 3103, 'yuki', '小仓友希', '约会是吧？', '', '', '', '', 's3104', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3104', 'chapter_22', 22, 'dialogue', 3104, 'taku', '顾天鹏', '没有。', '', '', '', '', 's3105', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3105', 'chapter_22', 22, 'dialogue', 3105, 'yuki', '小仓友希', '快点去店里啦。找工作哪有你这种态度。', '', '', '', '', 's3106', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3106', 'chapter_22', 22, 'scene', 3106, '', '', '', 'bg ch23_tokyo_cafe_day', '', '', '', 's3107', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3107', 'chapter_22', 22, 'sprite', 3107, '', '', '', '', '[{"image": "koizumi tray", "pos": "cast_left"}]', '', '', 's3108', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3108', 'chapter_22', 22, 'sprite', 3108, '', '', '', '', '[{"image": "maki teach", "pos": "cast_right"}]', '', '', 's3109', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3109', 'chapter_22', 22, 'narration', 3109, '', '', '店里装修明亮整齐，柜台前有两个女生和一个男生。', '', '', '', '', 's3110', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3110', 'chapter_22', 22, 'narration', 3110, '', '', '靠近门口的位置，有两个女生在聊偶像组合和自己喜欢的成员。顾天鹏从她们身旁走过，径直走向柜台。', '', '', '', '', 's3111', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3111', 'chapter_22', 22, 'narration', 3111, '', '', '她们把喜欢的偶像用奇怪的缩写称呼，笑得很认真。顾天鹏听着那些词，第一次觉得偶像离自己的生活并不遥远。', '', '', '', '', 's3112', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3112', 'chapter_22', 22, 'dialogue', 3112, 'koizumi', '小泉花海', '友希姐姐跟我们说过了。顾天鹏，对吧。', '', '', '', '', 's3113', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3113', 'chapter_22', 22, 'dialogue', 3113, 'taku', '顾天鹏', '我是。', '', '', '', '', 's3114', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3114', 'chapter_22', 22, 'dialogue', 3114, 'koizumi', '小泉花海', '那个，你就是顾天鹏吗？', '', '', '', '', 's3115', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3115', 'chapter_22', 22, 'sprite', 3115, '', '', '', '', '[{"image": "maki movie", "pos": "cast_right"}]', '', '', 's3116', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3116', 'chapter_22', 22, 'dialogue', 3116, 'maki', '寺本真姬', '这么帅，肯定错不了啦。', '', '', '', '', 's3117', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3117', 'chapter_23', 23, 'set', 3117, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3118', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3118', 'chapter_23', 23, 'set', 3118, '', '', '', '', '', 'event_cg_mode', 'false', 's3119', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3119', 'chapter_23', 23, 'scene', 3119, '', '', '', 'bg ch23_tokyo_cafe_day', '', '', '', 's3120', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3120', 'chapter_23', 23, 'sprite', 3120, '', '', '', '', '[{"image": "koizumi tray", "pos": "cast_left"}]', '', '', 's3121', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3121', 'chapter_23', 23, 'sprite', 3121, '', '', '', '', '[{"image": "maki teach", "pos": "cast_right"}]', '', '', 's3122', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3122', 'chapter_23', 23, 'sprite', 3122, '', '', '', '', '[{"image": "nishida cafe", "pos": "cast_far_right"}]', '', '', 's3123', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3123', 'chapter_23', 23, 'narration', 3123, '', '', '已读', '', '', '', '', 's3124', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3124', 'chapter_23', 23, 'narration', 3124, '', '', '洗完杯子的男生走过来，把顾天鹏误当成客人。小泉花海慌慌张张地解释。', '', '', '', '', 's3125', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3125', 'chapter_23', 23, 'dialogue', 3125, 'nishida', '西田秀树', '你好，请问喝点什么？', '', '', '', '', 's3126', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3126', 'chapter_23', 23, 'sprite', 3126, '', '', '', '', '[{"image": "koizumi reach", "pos": "cast_left"}]', '', '', 's3127', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3127', 'chapter_23', 23, 'dialogue', 3127, 'koizumi', '小泉花海', '他不是客人啦。', '', '', '', '', 's3128', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3128', 'chapter_23', 23, 'narration', 3128, '', '', '小仓友希打电话过来，确认他已经到店，又隔着电话把他交给这里的人。', '', '', '', '', 's3129', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3129', 'chapter_23', 23, 'sprite', 3129, '', '', '', '', '[{"hide": "koizumi"}]', '', '', 's3130', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3130', 'chapter_23', 23, 'sprite', 3130, '', '', '', '', '[{"image": "yuki phone", "pos": "cast_left"}]', '', '', 's3131', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3131', 'chapter_23', 23, 'dialogue', 3131, 'yuki', '小仓友希', '好好教他，别让他偷懒。', '', '', '', '', 's3132', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3132', 'chapter_23', 23, 'sprite', 3132, '', '', '', '', '[{"image": "maki movie", "pos": "cast_right"}]', '', '', 's3133', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3133', 'chapter_23', 23, 'dialogue', 3133, 'maki', '寺本真姬', '我认真的啊。', '', '', '', '', 's3134', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3134', 'chapter_23', 23, 'narration', 3134, '', '', '电话挂断后，寺本真姬又打了回去，隔着线路和小仓友希吵了几句。', '', '', '', '', 's3135', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3135', 'chapter_23', 23, 'dialogue', 3135, 'maki', '寺本真姬', '为什么你不来东京店里？', '', '', '', '', 's3136', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3136', 'chapter_23', 23, 'dialogue', 3136, 'yuki', '小仓友希', '因为那边交给你们也没问题嘛。', '', '', '', '', 's3137', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3137', 'chapter_23', 23, 'dialogue', 3137, 'maki', '寺本真姬', '你真会使唤人。', '', '', '', '', 's3138', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3138', 'chapter_23', 23, 'sprite', 3138, '', '', '', '', '[{"hide": "yuki"}]', '', '', 's3139', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3139', 'chapter_23', 23, 'sprite', 3139, '', '', '', '', '[{"image": "koizumi reach", "pos": "cast_left"}]', '', '', 's3140', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3140', 'chapter_23', 23, 'sprite', 3140, '', '', '', '', '[{"image": "maki teach", "pos": "cast_right"}]', '', '', 's3141', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3141', 'chapter_23', 23, 'narration', 3141, '', '', '寺本真姬坚持要教咖啡流程，小泉花海则把简单的活交给顾天鹏。', '', '', '', '', 's3142', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3142', 'chapter_23', 23, 'narration', 3142, '', '', '小泉花海每次拜托他把东西放到上层架子时，都会先犹豫很久。她明明工作认真，却总担心自己显得没用。', '', '', '', '', 's3143', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3143', 'chapter_23', 23, 'narration', 3143, '', '', '顾天鹏没有点破，只把事情做好，再让她继续负责自己能做的部分。', '', '', '', '', 's3144', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3144', 'chapter_23', 23, 'narration', 3144, '', '', '傍晚离店前，店员们对他挥手。小泉花海低着头说辛苦了。', '', '', '', '', 's3145', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3145', 'chapter_23', 23, 'dialogue', 3145, 'koizumi', '小泉花海', '友希姐姐说让你早点回去休息。', '', '', '', '', 's3146', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3146', 'chapter_23', 23, 'dialogue', 3146, 'taku', '顾天鹏', '你们晚点才下班？', '', '', '', '', 's3147', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3147', 'chapter_23', 23, 'dialogue', 3147, 'koizumi', '小泉花海', '嗯。', '', '', '', '', 's3148', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3148', 'chapter_23', 23, 'dialogue', 3148, 'taku', '顾天鹏', '那我也晚点吧。', '', '', '', '', 's3149', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3149', 'chapter_23', 23, 'dialogue', 3149, 'koizumi', '小泉花海', '不行。友希姐姐说了，就听她的吧。', '', '', '', '', 's3150', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3150', 'chapter_23', 23, 'narration', 3150, '', '', '她难得露出坚毅的眼神。顾天鹏只好点头。', '', '', '', '', 's3151', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3151', 'chapter_23', 23, 'narration', 3151, '', '', '傍晚，他买了一本《周刊少年 Jump》，回家做饭、锻炼、洗澡。', '', '', '', '', 's3152', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3152', 'chapter_23', 23, 'narration', 3152, '', '', '九点多，手机显示有一条未读消息。', '', '', '', '', 's3153', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3153', 'chapter_23', 23, 'dialogue', 3153, 'ai_letter', '星野爱的信', '顾天鹏，后天有没有空？能不能陪我出来。', '', '', '', '', 's3154', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3154', 'chapter_24', 24, 'scene', 3154, '', '', '', 'bg ch30_apartment_phone', '', '', '', 's3155', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3155', 'chapter_24', 24, 'narration', 3155, '', '', '联络、工作、日常', '', '', '', '', 's3156', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3156', 'chapter_24', 24, 'narration', 3156, '', '', '顾天鹏回了具体时间。消息很快显示已读。', '', '', '', '', 's3157', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3157', 'chapter_24', 24, 'dialogue', 3157, 'ai_letter', '星野爱的信', '回了！！你决定就行！！', '', '', '', '', 's3158', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3158', 'chapter_24', 24, 'narration', 3158, '', '', '她又连着发来两个感叹号和一个兔子表情，好像单靠文字不够表达自己确实看见了回复。', '', '', '', '', 's3159', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3159', 'chapter_24', 24, 'narration', 3159, '', '', '星野爱问起他的工作，他也把排班大致告诉她。', '', '', '', '', 's3160', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3160', 'chapter_24', 24, 'dialogue', 3160, 'ai_letter', '星野爱的信', '工作怎么样？', '', '', '', '', 's3161', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3161', 'chapter_24', 24, 'dialogue', 3161, 'taku', '顾天鹏', '还在学。', '', '', '', '', 's3162', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3162', 'chapter_24', 24, 'dialogue', 3162, 'ai_letter', '星野爱的信', '咖啡店听起来好可靠。', '', '', '', '', 's3163', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3163', 'chapter_24', 24, 'dialogue', 3163, 'taku', '顾天鹏', '也可能只是打杂。', '', '', '', '', 's3164', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3164', 'chapter_24', 24, 'dialogue', 3164, 'ai_letter', '星野爱的信', '顾天鹏打杂也会很好看。', '', '', '', '', 's3165', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3165', 'chapter_24', 24, 'narration', 3165, '', '', '这句话显示已读以后，她又发来一句“这是夸奖”。', '', '', '', '', 's3166', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3166', 'chapter_24', 24, 'scene', 3166, '', '', '', 'bg ch23_tokyo_cafe_day', '', '', '', 's3167', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3167', 'chapter_24', 24, 'sprite', 3167, '', '', '', '', '[{"image": "koizumi reach", "pos": "cast_left"}]', '', '', 's3168', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3168', 'chapter_24', 24, 'sprite', 3168, '', '', '', '', '[{"image": "maki teach", "pos": "cast_right"}]', '', '', 's3169', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3169', 'chapter_24', 24, 'sprite', 3169, '', '', '', '', '[{"image": "nishida cafe", "pos": "cast_far_right"}]', '', '', 's3170', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3170', 'chapter_24', 24, 'narration', 3170, '', '', '第二天，顾天鹏照常到店。小泉花海笨手笨脚但认真，寺本真姬和西田秀树踩点上班，却干活利落。', '', '', '', '', 's3171', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3171', 'chapter_24', 24, 'narration', 3171, '', '', '咖啡店的工作逐渐变成日常：整理杯子、擦桌、确认库存、看寺本真姬演示不同单品的制作步骤。', '', '', '', '', 's3172', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3172', 'chapter_24', 24, 'narration', 3172, '', '', '小泉花海不太愿意把手里的活让出去。那不是排斥，只是害怕自己连简单的事都做不好。', '', '', '', '', 's3173', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3173', 'chapter_24', 24, 'narration', 3173, '', '', '九点整，寺本真姬和西田秀树几乎踩着秒针进门。寺本真姬总说电影至少看三遍，西田秀树则负责吐槽她。', '', '', '', '', 's3174', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3174', 'chapter_24', 24, 'sprite', 3174, '', '', '', '', '[{"image": "maki movie", "pos": "cast_right"}]', '', '', 's3175', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3175', 'chapter_24', 24, 'dialogue', 3175, 'maki', '寺本真姬', '我还做过更过分的。', '', '', '', '', 's3176', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3176', 'chapter_24', 24, 'dialogue', 3176, 'nishida', '西田秀树', '哈？', '', '', '', '', 's3177', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3177', 'chapter_24', 24, 'narration', 3177, '', '', '他们的吵闹让咖啡店多了一种稳定的日常感。顾天鹏逐渐能从那些无关紧要的斗嘴里判断一天是否正常。', '', '', '', '', 's3178', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3178', 'chapter_24', 24, 'dialogue', 3178, 'maki', '寺本真姬', '看电影看三遍才算看过。', '', '', '', '', 's3179', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3179', 'chapter_24', 24, 'dialogue', 3179, 'nishida', '西田秀树', '哪有这样说的。', '', '', '', '', 's3180', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3180', 'chapter_24', 24, 'narration', 3180, '', '', '午饭时，西田秀树提到最近有个偶像选拔节目正在预热。', '', '', '', '', 's3181', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3181', 'chapter_24', 24, 'dialogue', 3181, 'taku', '顾天鹏', '等等，能跟我说说那个节目吗？', '', '', '', '', 's3182', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3182', 'chapter_24', 24, 'narration', 3182, '', '', '那一刻，他忽然对“偶像选拔”这几个字变得格外在意。', '', '', '', '', 's3183', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3183', 'chapter_24', 24, 'dialogue', 3183, 'nishida', '西田秀树', '听说报名的人很多，最后能留下来的很少。', '', '', '', '', 's3184', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3184', 'chapter_24', 24, 'dialogue', 3184, 'maki', '寺本真姬', '那不是很正常吗？偶像这种东西本来就是筛出来的。', '', '', '', '', 's3185', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3185', 'chapter_24', 24, 'narration', 3185, '', '', '顾天鹏安静地听着，手里的乌冬面味道忽然像变淡了。', '', '', '', '', 's3186', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3186', 'chapter_25', 25, 'set', 3186, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3187', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3187', 'chapter_25', 25, 'scene', 3187, '', '', '', 'bg ch25_library_sunset', '', '', '', 's3188', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3188', 'chapter_25', 25, 'narration', 3188, '', '', '于是，星野爱做出决定', '', '', '', '', 's3189', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3189', 'chapter_25', 25, 'narration', 3189, '', '', '下午四点多，顾天鹏一个人坐在图书馆看《伊豆的舞女》。', '', '', '', '', 's3190', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3190', 'chapter_25', 25, 'narration', 3190, '', '', '图书馆安静得能听见自己的呼吸。手机震动时，他很快把书合上。', '', '', '', '', 's3191', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3191', 'chapter_25', 25, 'dialogue', 3191, 'ai_letter', '星野爱的信', '昨天没说完的那件事，明天见面说。', '', '', '', '', 's3192', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3192', 'chapter_25', 25, 'narration', 3192, '', '', '他离开图书馆时，落日沉在两栋高楼之间，鱼鳞般的云被染成橘红。', '', '', '', '', 's3193', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3193', 'chapter_25', 25, 'scene', 3193, '', '', '', 'bg ch23_tokyo_cafe_night', '', '', '', 's3194', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3194', 'chapter_25', 25, 'sprite', 3194, '', '', '', '', '[{"image": "nishida cafe", "pos": "cast_left"}]', '', '', 's3195', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3195', 'chapter_25', 25, 'sprite', 3195, '', '', '', '', '[{"image": "maki movie", "pos": "cast_right"}]', '', '', 's3196', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3196', 'chapter_25', 25, 'narration', 3196, '', '', '晚上交班前，寺本真姬问他是不是在等消息。顾天鹏说只是普通联络。', '', '', '', '', 's3197', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3197', 'chapter_25', 25, 'dialogue', 3197, 'maki', '寺本真姬', '普通联络也可以让人看起来不普通。', '', '', '', '', 's3198', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3198', 'chapter_25', 25, 'dialogue', 3198, 'nishida', '西田秀树', '这话你从电影里学来的？', '', '', '', '', 's3199', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3199', 'chapter_25', 25, 'dialogue', 3199, 'maki', '寺本真姬', '至少看三遍才算学会。', '', '', '', '', 's3200', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3200', 'chapter_25', 25, 'scene', 3200, '', '', '', 'bg ch30_apartment_phone', '', '', '', 's3201', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3201', 'chapter_25', 25, 'narration', 3201, '', '', '当天晚上，他又把偶像选拔节目的资料看了一遍。赛制、报名人数、前几届出道者名单，全都被他划进记忆里。', '', '', '', '', 's3202', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3202', 'chapter_25', 25, 'narration', 3202, '', '', '这些信息并不能让他更接近星野爱的决定，却能让那个决定变得不再只是一个词。', '', '', '', '', 's3203', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3203', 'chapter_25', 25, 'narration', 3203, '', '', '第二天上午，他跑步、吃早餐、听英语广播，然后按约定去车站。', '', '', '', '', 's3204', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3204', 'chapter_25', 25, 'set', 3204, '', '', '', '', '', 'ai_sprite_mode', 'true', 's3205', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3205', 'chapter_25', 25, 'set', 3205, '', '', '', '', '', 'ai_sprite_outfit', 'ch20_spring', 's3206', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3206', 'chapter_25', 25, 'set', 3206, '', '', '', '', '', 'ai_sprite_position', 'right', 's3207', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3207', 'chapter_25', 25, 'scene', 3207, '', '', '', 'bg ch20_sakura_slope', '', '', '', 's3208', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3208', 'chapter_25', 25, 'sprite', 3208, '', '', '', '', '[{"image": "heroine ch20_spring", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3209', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3209', 'chapter_25', 25, 'narration', 3209, '', '', '星野爱穿着白色长裙赶到他身边，气息还有些乱。', '', '', '', '', 's3210', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3210', 'chapter_25', 25, 'dialogue', 3210, 'ai', '星野爱', '对不起，来晚了！', '', '', '', '', 's3211', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3211', 'chapter_25', 25, 'dialogue', 3211, 'taku', '顾天鹏', '没关系，我也刚到。', '', '', '', '', 's3212', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3212', 'chapter_25', 25, 'narration', 3212, '', '', '他们沿着街道边走边聊。春日阳光明亮，面包房飘出香气，唱片店刚刚营业。', '', '', '', '', 's3213', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3213', 'chapter_25', 25, 'narration', 3213, '', '', '路边有人在画画，唱片店里飘出音乐。她像是真的很享受这段路，步子轻得几乎要跳起来。', '', '', '', '', 's3214', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3214', 'chapter_25', 25, 'dialogue', 3214, 'ai', '星野爱', '昨天没说完的那件事。', '', '', '', '', 's3215', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3215', 'chapter_25', 25, 'dialogue', 3215, 'ai', '星野爱', '我参加了。B小町，我们组合的名字。', '', '', '', '', 's3216', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3216', 'chapter_25', 25, 'dialogue', 3216, 'taku', '顾天鹏', 'B小町。', '', '', '', '', 's3217', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3217', 'chapter_25', 25, 'dialogue', 3217, 'ai', '星野爱', '事务所一开始只找到三个人，不过，我决定加入了。', '', '', '', '', 's3218', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3218', 'chapter_25', 25, 'narration', 3218, '', '', '她说出“决定加入”的时候，表情比前一天更稳，像已经把某个沉重的念头按进心里。', '', '', '', '', 's3219', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3219', 'chapter_25', 25, 'dialogue', 3219, 'ai', '星野爱', '其实我本来还在想，要不要拒绝。', '', '', '', '', 's3220', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3220', 'chapter_25', 25, 'dialogue', 3220, 'taku', '顾天鹏', '现在不想了？', '', '', '', '', 's3221', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3221', 'chapter_25', 25, 'dialogue', 3221, 'ai', '星野爱', '嗯。至少现在不想。', '', '', '', '', 's3222', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3222', 'chapter_25', 25, 'dialogue', 3222, 'taku', '顾天鹏', '那就去做。', '', '', '', '', 's3223', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3223', 'chapter_25', 25, 'dialogue', 3223, 'ai', '星野爱', '你说得好轻松。', '', '', '', '', 's3224', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3224', 'chapter_25', 25, 'dialogue', 3224, 'taku', '顾天鹏', '因为我不是你。', '', '', '', '', 's3225', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3225', 'chapter_25', 25, 'dialogue', 3225, 'ai', '星野爱', '这句倒是很诚实。', '', '', '', '', 's3226', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3226', 'chapter_26', 26, 'set', 3226, '', '', '', '', '', 'ai_sprite_mode', 'true', 's3227', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3227', 'chapter_26', 26, 'set', 3227, '', '', '', '', '', 'ai_sprite_outfit', 'ch20_spring', 's3228', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3228', 'chapter_26', 26, 'set', 3228, '', '', '', '', '', 'ai_sprite_position', 'right', 's3229', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3229', 'chapter_26', 26, 'scene', 3229, '', '', '', 'bg ch20_sakura_slope', '', '', '', 's3230', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3230', 'chapter_26', 26, 'sprite', 3230, '', '', '', '', '[{"image": "heroine ch20_spring", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3231', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3231', 'chapter_26', 26, 'narration', 3231, '', '', '谎言', '', '', '', '', 's3232', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3232', 'chapter_26', 26, 'dialogue', 3232, 'taku', '顾天鹏', '挺好的。', '', '', '', '', 's3233', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3233', 'chapter_26', 26, 'dialogue', 3233, 'ai', '星野爱', '挺好的？没有别的感想？或者没有什么想问我的？', '', '', '', '', 's3234', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3234', 'chapter_26', 26, 'dialogue', 3234, 'taku', '顾天鹏', '你估计也不想回答吧。那不是秘密？', '', '', '', '', 's3235', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3235', 'chapter_26', 26, 'dialogue', 3235, 'ai', '星野爱', '这次不是。特地找你出来，就是想告诉你。', '', '', '', '', 's3236', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3236', 'chapter_26', 26, 'narration', 3236, '', '', '她说另外三个人大概叫高峰、二宫、渡边。名字还没完全记熟，却已经被她放进同一张未来的表里。', '', '', '', '', 's3237', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3237', 'chapter_26', 26, 'dialogue', 3237, 'ai', '星野爱', '昨天白天就在忙这些。没回消息不是故意的，真的不是谎言。', '', '', '', '', 's3238', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3238', 'chapter_26', 26, 'dialogue', 3238, 'taku', '顾天鹏', '这倒无所谓。', '', '', '', '', 's3239', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3239', 'chapter_26', 26, 'dialogue', 3239, 'ai', '星野爱', '还是解释一下比较放心。', '', '', '', '', 's3240', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3240', 'chapter_26', 26, 'narration', 3240, '', '', '他们穿过斑马线，路过电影院、甜品店和忠犬八公。附近有人发传单，也有人推广自己的账号。', '', '', '', '', 's3241', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3241', 'chapter_26', 26, 'narration', 3241, '', '', '因为要参加选秀，组合成员之后要多在一起训练。', '', '', '', '', 's3242', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3242', 'chapter_26', 26, 'dialogue', 3242, 'ai', '星野爱', '可能很少有时间再像这样出来了。今天也是我特别申请的假。', '', '', '', '', 's3243', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3243', 'chapter_26', 26, 'narration', 3243, '', '', '她说“假”这个字的时候，语气像刚拿到一件很短暂的礼物。', '', '', '', '', 's3244', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3244', 'chapter_26', 26, 'dialogue', 3244, 'taku', '顾天鹏', '我很期待。选秀那天我一定去捧场。', '', '', '', '', 's3245', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3245', 'chapter_26', 26, 'dialogue', 3245, 'ai', '星野爱', '那不还是不确定吗？', '', '', '', '', 's3246', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3246', 'chapter_26', 26, 'dialogue', 3246, 'taku', '顾天鹏', '口渴吗？', '', '', '', '', 's3247', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3247', 'chapter_26', 26, 'dialogue', 3247, 'ai', '星野爱', '还好。', '', '', '', '', 's3248', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3248', 'chapter_26', 26, 'dialogue', 3248, 'taku', '顾天鹏', '快到我工作的地方了。要不要去看看？', '', '', '', '', 's3249', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3249', 'chapter_26', 26, 'dialogue', 3249, 'ai', '星野爱', '不会打扰到吧？', '', '', '', '', 's3250', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3250', 'chapter_26', 26, 'dialogue', 3250, 'taku', '顾天鹏', '只是正常光顾，顺便请你喝咖啡。', '', '', '', '', 's3251', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3251', 'chapter_26', 26, 'dialogue', 3251, 'ai', '星野爱', '我更想喝你做的。', '', '', '', '', 's3252', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3252', 'chapter_26', 26, 'dialogue', 3252, 'taku', '顾天鹏', '下次在上班时间来找我就行。', '', '', '', '', 's3253', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3253', 'chapter_26', 26, 'dialogue', 3253, 'ai', '星野爱', '好！只要训练结束，一有空我绝对来找你。', '', '', '', '', 's3254', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3254', 'chapter_26', 26, 'scene', 3254, '', '', '', 'bg ch23_tokyo_cafe_day', '', '', '', 's3255', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3255', 'chapter_26', 26, 'sprite', 3255, '', '', '', '', '[{"image": "koizumi tray", "pos": "cast_left"}]', '', '', 's3256', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3256', 'chapter_26', 26, 'sprite', 3256, '', '', '', '', '[{"image": "maki movie", "pos": "cast_right"}]', '', '', 's3257', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3257', 'chapter_26', 26, 'narration', 3257, '', '', '十一点左右，他们走进顾天鹏工作的咖啡店。值班的人看见星野爱，忍不住问他们是不是男女朋友。', '', '', '', '', 's3258', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3258', 'chapter_26', 26, 'narration', 3258, '', '', '星野爱一道谢便露出明亮笑容，男生女生都愣了一下。那是一种训练前就已经接近本能的光。', '', '', '', '', 's3259', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3259', 'chapter_26', 26, 'sprite', 3259, '', '', '', '', '[{"hide": "koizumi"}]', '', '', 's3260', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3260', 'chapter_26', 26, 'sprite', 3260, '', '', '', '', '[{"hide": "maki"}]', '', '', 's3261', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3261', 'chapter_26', 26, 'sprite', 3261, '', '', '', '', '[{"image": "heroine ch20_spring", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3262', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3262', 'chapter_26', 26, 'dialogue', 3262, 'ai', '星野爱', '是呢，我很喜欢他，当初就是我追的顾天鹏。', '', '', '', '', 's3263', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3263', 'chapter_26', 26, 'dialogue', 3263, 'taku', '顾天鹏', '没这回事。刚才那句是玩笑，我们是朋友。', '', '', '', '', 's3264', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3264', 'chapter_26', 26, 'narration', 3264, '', '', '他们坐到靠窗的位置。阳光透过玻璃照在桌上。', '', '', '', '', 's3265', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3265', 'chapter_26', 26, 'set', 3265, '', '', '', '', '', 'event_cg_mode', 'true', 's3266', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3266', 'chapter_26', 26, 'scene', 3266, '', '', '', 'cg ch26_ai_cafe_lie', '', '', '', 's3267', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3267', 'chapter_26', 26, 'narration', 3267, '', '', '外面有人在街边跳舞，玻璃把音乐和人声都隔得很远。', '', '', '', '', 's3268', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3268', 'chapter_26', 26, 'dialogue', 3268, 'taku', '顾天鹏', '又说谎了。', '', '', '', '', 's3269', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3269', 'chapter_26', 26, 'dialogue', 3269, 'ai', '星野爱', '偶像要学会表达爱意，正好在你这里先试一下。', '', '', '', '', 's3270', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3270', 'chapter_26', 26, 'dialogue', 3270, 'ai', '星野爱', '喜欢啊，爱啊什么的，好像也没那么难说出口。', '', '', '', '', 's3271', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3271', 'chapter_26', 26, 'dialogue', 3271, 'taku', '顾天鹏', '对其他人来说可能不是这么回事。', '', '', '', '', 's3272', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3272', 'chapter_26', 26, 'dialogue', 3272, 'ai', '星野爱', '搞不好我有当偶像的天赋？', '', '', '', '', 's3273', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3273', 'chapter_26', 26, 'dialogue', 3273, 'taku', '顾天鹏', '让我说的话，肯定会说有。', '', '', '', '', 's3274', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3274', 'chapter_26', 26, 'dialogue', 3274, 'ai', '星野爱', '你觉得是什么？', '', '', '', '', 's3275', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3275', 'chapter_26', 26, 'dialogue', 3275, 'taku', '顾天鹏', '说不过来。', '', '', '', '', 's3276', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3276', 'chapter_26', 26, 'dialogue', 3276, 'ai', '星野爱', '我觉得是谎言。', '', '', '', '', 's3277', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3277', 'chapter_26', 26, 'dialogue', 3277, 'taku', '顾天鹏', '不排除这个。', '', '', '', '', 's3278', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3278', 'chapter_26', 26, 'dialogue', 3278, 'ai', '星野爱', '喂，顾天鹏，我们现在是什么关系？你觉得。', '', '', '', '', 's3279', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3280', 'chapter_26', 26, 'dialogue', 3280, 'taku', '顾天鹏', '朋友。', '', '', '', '', 's3281', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3281', 'chapter_26', 26, 'jump', 3281, '', '', '', '', '', '', '', 's3286', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3282', 'chapter_26', 26, 'narration', 3282, '', '', '顾天鹏把这个词说出口的瞬间，星野爱的笑容停住了。', '', '', '', '', 's3283', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3283', 'chapter_26', 26, 'jump', 3283, '', '', '', '', '', '', '', 's3490', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3284', 'chapter_26', 26, 'narration', 3284, '', '', '顾天鹏没有回答。那份暧昧被留在咖啡店的阳光里，后来再也没有被认真捡起。', '', '', '', '', 's3285', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3285', 'chapter_26', 26, 'jump', 3285, '', '', '', '', '', '', '', 's3490', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3279', 'chapter_26', 26, 'menu', 3279, '', '', '', '', '', '', '', 's3286', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3286', 'chapter_27', 27, 'set', 3286, '', '', '', '', '', 'event_cg_mode', 'false', 's3287', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3287', 'chapter_27', 27, 'set', 3287, '', '', '', '', '', 'ai_sprite_mode', 'true', 's3288', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3288', 'chapter_27', 27, 'set', 3288, '', '', '', '', '', 'ai_sprite_outfit', 'ch20_spring', 's3289', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3289', 'chapter_27', 27, 'set', 3289, '', '', '', '', '', 'ai_sprite_position', 'right', 's3290', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3290', 'chapter_27', 27, 'scene', 3290, '', '', '', 'bg ch23_tokyo_cafe_day', '', '', '', 's3291', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3291', 'chapter_27', 27, 'sprite', 3291, '', '', '', '', '[{"image": "heroine ch20_spring", "pos": "heroine_ch12_ch13_right"}]', '', '', 's3292', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3292', 'chapter_27', 27, 'narration', 3292, '', '', '我推的舞女', '', '', '', '', 's3293', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3293', 'chapter_27', 27, 'dialogue', 3293, 'ai', '星野爱', '还有吗？', '', '', '', '', 's3294', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3294', 'chapter_27', 27, 'dialogue', 3294, 'taku', '顾天鹏', '没了。', '', '', '', '', 's3295', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3295', 'chapter_27', 27, 'dialogue', 3295, 'ai', '星野爱', '未免也太诚实了。', '', '', '', '', 's3296', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3296', 'chapter_27', 27, 'narration', 3296, '', '', '店员送来两杯抹茶星冰乐。星野爱低头插吸管，像在说天气一样平静。', '', '', '', '', 's3297', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3297', 'chapter_27', 27, 'dialogue', 3297, 'ai', '星野爱', '顾天鹏，我还挺喜欢你的。', '', '', '', '', 's3298', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3298', 'chapter_27', 27, 'dialogue', 3298, 'taku', '顾天鹏', '谎言。', '', '', '', '', 's3299', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3299', 'chapter_27', 27, 'narration', 3299, '', '', '她把喝进嘴里的饮料憋住，脸鼓起来。', '', '', '', '', 's3300', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3300', 'chapter_27', 27, 'dialogue', 3300, 'taku', '顾天鹏', '骗别人没问题，在我这里一点也行不通。', '', '', '', '', 's3301', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3301', 'chapter_27', 27, 'narration', 3301, '', '', '店员又送来一份草莓冰淇淋圣代，还自顾自判断他们处在“那种阶段”。星野爱笑着把误会收下。', '', '', '', '', 's3302', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3302', 'chapter_27', 27, 'dialogue', 3302, 'ai', '星野爱', '只是一句话而已，还有免费的圣代。就不能默默承受吗？', '', '', '', '', 's3303', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3303', 'chapter_27', 27, 'dialogue', 3303, 'taku', '顾天鹏', '我倒还好。', '', '', '', '', 's3304', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3304', 'chapter_27', 27, 'dialogue', 3304, 'ai', '星野爱', '那不就行咯。', '', '', '', '', 's3305', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3305', 'chapter_27', 27, 'narration', 3305, '', '', '两人喝完星冰乐。圣代几乎全被星野爱吃掉。顾天鹏问她偶像是否不需要身材管理。', '', '', '', '', 's3306', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3306', 'chapter_27', 27, 'dialogue', 3306, 'ai', '星野爱', '就一次而已，难得的机会，不会怎么样啦。', '', '', '', '', 's3307', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3307', 'chapter_27', 27, 'narration', 3307, '', '', '她把勺子放下，忽然像想起一直没问出口的问题。', '', '', '', '', 's3308', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3308', 'chapter_27', 27, 'dialogue', 3308, 'ai', '星野爱', '训练的地方很普通，也不是正式练习室。大家刚开始磨合，可能会有点乱。', '', '', '', '', 's3309', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3309', 'chapter_27', 27, 'dialogue', 3309, 'taku', '顾天鹏', '我可以坐远一点。', '', '', '', '', 's3310', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3310', 'chapter_27', 27, 'dialogue', 3310, 'ai', '星野爱', '倒也不用这么正式。', '', '', '', '', 's3311', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3311', 'chapter_27', 27, 'dialogue', 3311, 'ai', '星野爱', '有件事情一直没问。训练的时候，你能不能来？', '', '', '', '', 's3312', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3313', 'chapter_27', 27, 'dialogue', 3313, 'taku', '顾天鹏', '那行。有时间我就去。', '', '', '', '', 's3314', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3314', 'chapter_27', 27, 'dialogue', 3314, 'ai', '星野爱', '不用那么经常啦。', '', '', '', '', 's3315', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3315', 'chapter_27', 27, 'dialogue', 3315, 'taku', '顾天鹏', '那去的时候联系你。', '', '', '', '', 's3319', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3316', 'chapter_27', 27, 'narration', 3316, '', '', '顾天鹏摇了摇头。', '', '', '', '', 's3317', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3317', 'chapter_27', 27, 'dialogue', 3317, 'taku', '顾天鹏', '你们刚开始训练，我还是不要打扰。', '', '', '', '', 's3318', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3318', 'chapter_27', 27, 'jump', 3318, '', '', '', '', '', '', '', 's3497', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3312', 'chapter_27', 27, 'menu', 3312, '', '', '', '', '', '', '', 's3319', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3319', 'chapter_27', 27, 'narration', 3319, '', '', '星野爱笑着说这样一来，平常也可以互相接触了。', '', '', '', '', 's3320', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3320', 'chapter_27', 27, 'dialogue', 3320, 'taku', '顾天鹏', '互相打扰。', '', '', '', '', 's3321', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3321', 'chapter_27', 27, 'dialogue', 3321, 'ai', '星野爱', '到底叫什么都没关系吧。', '', '', '', '', 's3322', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3322', 'chapter_27', 27, 'narration', 3322, '', '', '那天晚上，顾天鹏在网上查了偶像选秀节目。报名者很多，能出道的几乎只有极少数。', '', '', '', '', 's3323', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3323', 'chapter_27', 27, 'narration', 3323, '', '', '他想到星野爱，总觉得她就是万里挑一的那个人。', '', '', '', '', 's3324', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3324', 'chapter_27', 27, 'narration', 3324, '', '', '屏幕上的资料一页页往下翻，他没有把那句话发给她。', '', '', '', '', 's3325', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3325', 'chapter_27', 27, 'narration', 3325, '', '', '他只是把手机扣在桌面上，开始想象她和另外三个名字站在同一个队形里的样子。', '', '', '', '', 's3326', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3326', 'chapter_28', 28, 'set', 3326, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3327', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3327', 'chapter_28', 28, 'set', 3327, '', '', '', '', '', 'event_cg_mode', 'false', 's3328', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3328', 'chapter_28', 28, 'scene', 3328, '', '', '', 'bg ch30_apartment_phone', '', '', '', 's3329', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3329', 'chapter_28', 28, 'sprite', 3329, '', '', '', '', '[{"image": "yuki phone", "pos": "cast_single_center"}]', '', '', 's3330', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3330', 'chapter_28', 28, 'narration', 3330, '', '', '从御茶之水开始', '', '', '', '', 's3331', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3331', 'chapter_28', 28, 'narration', 3331, '', '', '翌日清晨，顾天鹏跑步、洗澡、吃早餐。小仓友希给他打来电话，模仿他说“我是顾天鹏”。', '', '', '', '', 's3332', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3332', 'chapter_28', 28, 'dialogue', 3332, 'yuki', '小仓友希', '今天是第八次给你打电话的纪念日！', '', '', '', '', 's3333', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3333', 'chapter_28', 28, 'dialogue', 3333, 'taku', '顾天鹏', '那算什么纪念日？', '', '', '', '', 's3334', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3334', 'chapter_28', 28, 'dialogue', 3334, 'yuki', '小仓友希', '每次都设一个纪念日，就永远不会忘记一共打了几次电话。', '', '', '', '', 's3335', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3335', 'chapter_28', 28, 'dialogue', 3335, 'taku', '顾天鹏', '这本来也没什么好记。', '', '', '', '', 's3336', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3336', 'chapter_28', 28, 'dialogue', 3336, 'yuki', '小仓友希', '你不了解。', '', '', '', '', 's3337', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3337', 'chapter_28', 28, 'narration', 3337, '', '', '她又问他有没有和星野爱联系，语气装得随意。顾天鹏没有隐瞒。', '', '', '', '', 's3338', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3338', 'chapter_28', 28, 'dialogue', 3338, 'yuki', '小仓友希', '那今天也要去见她？', '', '', '', '', 's3339', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3339', 'chapter_28', 28, 'dialogue', 3339, 'taku', '顾天鹏', '下午去看训练。', '', '', '', '', 's3340', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3340', 'chapter_28', 28, 'dialogue', 3340, 'yuki', '小仓友希', '你还挺忙。', '', '', '', '', 's3341', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3341', 'chapter_28', 28, 'dialogue', 3341, 'taku', '顾天鹏', '工作也要去。', '', '', '', '', 's3342', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3342', 'chapter_28', 28, 'dialogue', 3342, 'yuki', '小仓友希', '那就更忙了。', '', '', '', '', 's3343', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3343', 'chapter_28', 28, 'narration', 3343, '', '', '小仓友希沉默几秒，又故作轻松地说别在路上迷路。', '', '', '', '', 's3344', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3344', 'chapter_28', 28, 'dialogue', 3344, 'yuki', '小仓友希', '御茶之水那边乐器店很多，看到吉他别傻站着。', '', '', '', '', 's3345', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3345', 'chapter_28', 28, 'dialogue', 3345, 'taku', '顾天鹏', '我不会。', '', '', '', '', 's3346', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3346', 'chapter_28', 28, 'dialogue', 3346, 'yuki', '小仓友希', '你会。', '', '', '', '', 's3347', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3347', 'chapter_28', 28, 'scene', 3347, '', '', '', 'bg ch23_tokyo_cafe_day', '', '', '', 's3348', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3348', 'chapter_28', 28, 'sprite', 3348, '', '', '', '', '[{"image": "koizumi reach", "pos": "cast_left"}]', '', '', 's3349', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3349', 'chapter_28', 28, 'sprite', 3349, '', '', '', '', '[{"image": "maki teach", "pos": "cast_right"}]', '', '', 's3350', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3350', 'chapter_28', 28, 'sprite', 3350, '', '', '', '', '[{"image": "nishida cafe", "pos": "cast_far_right"}]', '', '', 's3351', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3351', 'chapter_28', 28, 'narration', 3351, '', '', '上午的咖啡店一如往常。小泉花海把够不到的东西拜托给他，寺本真姬继续教他咖啡制作，西田秀树照常和她斗嘴。', '', '', '', '', 's3352', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3352', 'chapter_28', 28, 'narration', 3352, '', '', '中午营业结束，几个人脱下制服围裙离开。寺本真姬他们在阳光下商量去哪吃饭，顾天鹏说自己没什么胃口。', '', '', '', '', 's3353', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3353', 'chapter_28', 28, 'scene', 3353, '', '', '', 'bg ch25_library_sunset', '', '', '', 's3354', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3354', 'chapter_28', 28, 'narration', 3354, '', '', '中午结束营业后，顾天鹏一个人去书店。他给星野爱发消息，询问下午能不能过去看训练。', '', '', '', '', 's3355', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3355', 'chapter_28', 28, 'dialogue', 3355, 'ai_letter', '星野爱的信', '你下午要来吗？', '', '', '', '', 's3356', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3356', 'chapter_28', 28, 'dialogue', 3356, 'taku', '顾天鹏', '可以过去。', '', '', '', '', 's3357', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3357', 'chapter_28', 28, 'dialogue', 3357, 'ai_letter', '星野爱的信', '两点钟过来吧，那时候我们肯定在。', '', '', '', '', 's3358', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3358', 'chapter_28', 28, 'narration', 3358, '', '', '一点二十，他从涩谷站出发，在御茶之水下车。', '', '', '', '', 's3359', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3359', 'chapter_28', 28, 'scene', 3359, '', '', '', 'bg ch28_music_street', '', '', '', 's3360', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3360', 'chapter_28', 28, 'narration', 3360, '', '', '他沿着神田川前进，穿过挂满吉他和宣传海报的乐器街，绕过公园，爬上几十级石阶。', '', '', '', '', 's3361', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3361', 'chapter_28', 28, 'narration', 3361, '', '', '路边宣传海报琳琅满目，某家店门口摆着醒目的角色立牌。他没有停留。', '', '', '', '', 's3362', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3362', 'chapter_28', 28, 'scene', 3362, '', '', '', 'bg ch28_ochanomizu_steps', '', '', '', 's3363', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3363', 'chapter_28', 28, 'narration', 3363, '', '', '他绕过公园时，城市的声音像被树荫一层层削薄。石阶上方只剩风、叶子和远处少女数拍子的声音。', '', '', '', '', 's3364', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3364', 'chapter_28', 28, 'narration', 3364, '', '', '人烟逐渐变少。不远处的树荫底下，有少女的声音传来。', '', '', '', '', 's3365', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3365', 'chapter_29', 29, 'set', 3365, '', '', '', '', '', 'event_cg_mode', 'true', 's3366', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3366', 'chapter_29', 29, 'set', 3366, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3367', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3367', 'chapter_29', 29, 'scene', 3367, '', '', '', 'cg ch29_idol_practice', '', '', '', 's3368', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3368', 'chapter_29', 29, 'narration', 3368, '', '', '一切因你而起', '', '', '', '', 's3369', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3369', 'chapter_29', 29, 'narration', 3369, '', '', '四个少女在树荫下练习步伐。星野爱站在后方，认真跟着节拍。', '', '', '', '', 's3370', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3370', 'chapter_29', 29, 'narration', 3370, '', '', '右上角的女生注意到顾天鹏，动作慢了一拍。练习停下来，节拍声也跟着断掉。', '', '', '', '', 's3371', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3371', 'chapter_29', 29, 'set', 3371, '', '', '', '', '', 'event_cg_mode', 'false', 's3372', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3372', 'chapter_29', 29, 'scene', 3372, '', '', '', 'bg ch28_ochanomizu_steps', '', '', '', 's3373', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3373', 'chapter_29', 29, 'sprite', 3373, '', '', '', '', '[{"image": "sanae practice", "pos": "cast_group_left"}]', '', '', 's3374', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3374', 'chapter_29', 29, 'sprite', 3374, '', '', '', '', '[{"image": "ritsuko practice", "pos": "cast_group_midleft"}]', '', '', 's3375', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3375', 'chapter_29', 29, 'sprite', 3375, '', '', '', '', '[{"image": "heroine ch29_practice", "pos": "cast_group_midright"}]', '', '', 's3376', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3376', 'chapter_29', 29, 'sprite', 3376, '', '', '', '', '[{"image": "mai practice", "pos": "cast_group_right"}]', '', '', 's3377', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3377', 'chapter_29', 29, 'dialogue', 3377, 'sanae', '高峰早苗', '精神集中一点啦。我们时间不多，动作不整齐的话，到时候会被淘汰。', '', '', '', '', 's3378', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3378', 'chapter_29', 29, 'dialogue', 3378, 'mai', '渡边麻衣', '早上练了那么久，中午吃完饭又练到现在，稍微休息一下比较合适吧。', '', '', '', '', 's3379', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3379', 'chapter_29', 29, 'dialogue', 3379, 'ritsuko', '二宫律子', '对不起，都怪我。', '', '', '', '', 's3380', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3380', 'chapter_29', 29, 'dialogue', 3380, 'ai', '星野爱', '没办法的吧。社长和京子小姐也很希望我们成功。', '', '', '', '', 's3381', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3381', 'chapter_29', 29, 'dialogue', 3381, 'mai', '渡边麻衣', '小爱，你又把社长名字叫错了。', '', '', '', '', 's3382', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3382', 'chapter_29', 29, 'dialogue', 3382, 'ai', '星野爱', '咦？', '', '', '', '', 's3383', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3383', 'chapter_29', 29, 'narration', 3383, '', '', '短暂的插科打诨让气氛松了一点。星野爱这才发现顾天鹏已经到了。', '', '', '', '', 's3384', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3384', 'chapter_29', 29, 'dialogue', 3384, 'ai', '星野爱', '什么时候来的？', '', '', '', '', 's3385', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3385', 'chapter_29', 29, 'dialogue', 3385, 'taku', '顾天鹏', '刚刚才到。', '', '', '', '', 's3386', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3386', 'chapter_29', 29, 'dialogue', 3386, 'ai', '星野爱', '是不是看到我训练了？', '', '', '', '', 's3387', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3387', 'chapter_29', 29, 'dialogue', 3387, 'taku', '顾天鹏', '来晚了，什么都没看见。', '', '', '', '', 's3388', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3388', 'chapter_29', 29, 'dialogue', 3388, 'ai', '星野爱', '真可惜。', '', '', '', '', 's3389', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3389', 'chapter_29', 29, 'dialogue', 3389, 'taku', '顾天鹏', '有点。', '', '', '', '', 's3390', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3390', 'chapter_29', 29, 'dialogue', 3390, 'ai', '星野爱', '要不去那边坐？今天没涂防晒，还是尽量不要晒太阳比较好。', '', '', '', '', 's3391', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3391', 'chapter_29', 29, 'dialogue', 3391, 'taku', '顾天鹏', '会打扰训练吧？', '', '', '', '', 's3392', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3392', 'chapter_29', 29, 'dialogue', 3392, 'ai', '星野爱', '现在是休息时间。', '', '', '', '', 's3393', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3393', 'chapter_29', 29, 'narration', 3393, '', '', '她说完便很自然地拽住他的手腕。那动作太快，顾天鹏连拒绝的姿势都没摆出来。', '', '', '', '', 's3394', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3394', 'chapter_29', 29, 'narration', 3394, '', '', '休息时，星野爱把顾天鹏拉到树荫下，介绍给其他三个人。', '', '', '', '', 's3395', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3395', 'chapter_29', 29, 'dialogue', 3395, 'ai', '星野爱', '这就是我提过的顾天鹏，顾天鹏。', '', '', '', '', 's3396', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3396', 'chapter_29', 29, 'dialogue', 3396, 'sanae', '高峰早苗', '多亏了你，B小町才有小爱加入。谢谢。', '', '', '', '', 's3397', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3397', 'chapter_29', 29, 'dialogue', 3397, 'ritsuko', '二宫律子', '你、你好。', '', '', '', '', 's3398', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3398', 'chapter_29', 29, 'dialogue', 3398, 'mai', '渡边麻衣', '少年，有没有兴趣加入莓Pro事务所？', '', '', '', '', 's3399', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3399', 'chapter_29', 29, 'narration', 3399, '', '', '渡边麻衣拎着一袋饮料回来，把椰子水、矿泉水和绿茶分给大家。', '', '', '', '', 's3400', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3400', 'chapter_29', 29, 'dialogue', 3400, 'mai', '渡边麻衣', '这是早苗的，这是小爱的，这是律子的。', '', '', '', '', 's3401', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3401', 'chapter_29', 29, 'narration', 3401, '', '', '最后只剩一瓶无糖绿茶。渡边麻衣看了看顾天鹏，又看了看自己手里的饮料。', '', '', '', '', 's3402', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3402', 'chapter_29', 29, 'dialogue', 3402, 'mai', '渡边麻衣', '给你，我下去再买。', '', '', '', '', 's3403', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3403', 'chapter_29', 29, 'dialogue', 3403, 'taku', '顾天鹏', '谢谢，不用了。', '', '', '', '', 's3404', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3404', 'chapter_29', 29, 'dialogue', 3404, 'mai', '渡边麻衣', '真不用？', '', '', '', '', 's3405', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3405', 'chapter_29', 29, 'narration', 3405, '', '', '她立刻拧开瓶盖喝了一大口。', '', '', '', '', 's3406', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3406', 'chapter_29', 29, 'dialogue', 3406, 'mai', '渡边麻衣', '你真是个好人！', '', '', '', '', 's3407', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3407', 'chapter_29', 29, 'dialogue', 3407, 'taku', '顾天鹏', '谢谢你的夸奖。', '', '', '', '', 's3408', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3408', 'chapter_29', 29, 'dialogue', 3408, 'mai', '渡边麻衣', '你就是小爱说过的那个人呀？', '', '', '', '', 's3409', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3409', 'chapter_29', 29, 'narration', 3409, '', '', '顾天鹏看向星野爱。她歪头一笑。', '', '', '', '', 's3410', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3410', 'chapter_29', 29, 'dialogue', 3410, 'ai', '星野爱', '因为你的那句话，我才决定成为偶像。', '', '', '', '', 's3411', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3411', 'chapter_29', 29, 'narration', 3411, '', '', '顾天鹏一时间没有理解。她说得太自然，像早就决定把这句话在这里说给他听。', '', '', '', '', 's3412', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3412', 'chapter_29', 29, 'narration', 3412, '', '', '高峰早苗、二宫律子和渡边麻衣都看向他们。那几秒里，树荫下安静得能听见瓶盖被拧紧的声音。', '', '', '', '', 's3413', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3413', 'chapter_30', 30, 'set', 3413, '', '', '', '', '', 'event_cg_mode', 'false', 's3414', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3414', 'chapter_30', 30, 'set', 3414, '', '', '', '', '', 'ai_sprite_mode', 'true', 's3415', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3415', 'chapter_30', 30, 'set', 3415, '', '', '', '', '', 'ai_sprite_outfit', 'ch29_practice', 's3416', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3416', 'chapter_30', 30, 'set', 3416, '', '', '', '', '', 'ai_sprite_position', 'right', 's3417', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3417', 'chapter_30', 30, 'scene', 3417, '', '', '', 'bg ch28_ochanomizu_steps', '', '', '', 's3418', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3418', 'chapter_30', 30, 'sprite', 3418, '', '', '', '', '[{"image": "sanae practice", "pos": "cast_group_left"}]', '', '', 's3419', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3419', 'chapter_30', 30, 'sprite', 3419, '', '', '', '', '[{"image": "ritsuko practice", "pos": "cast_group_midleft"}]', '', '', 's3420', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3420', 'chapter_30', 30, 'sprite', 3420, '', '', '', '', '[{"image": "heroine ch29_practice", "pos": "cast_group_midright"}]', '', '', 's3421', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3421', 'chapter_30', 30, 'sprite', 3421, '', '', '', '', '[{"image": "mai practice", "pos": "cast_group_right"}]', '', '', 's3422', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3422', 'chapter_30', 30, 'narration', 3422, '', '', '一成不变', '', '', '', '', 's3423', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3423', 'chapter_30', 30, 'dialogue', 3423, 'taku', '顾天鹏', '因为我？', '', '', '', '', 's3424', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3424', 'chapter_30', 30, 'dialogue', 3424, 'ai', '星野爱', '嗯，没错。', '', '', '', '', 's3425', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3425', 'chapter_30', 30, 'narration', 3425, '', '', '四月的温度恰到好处。高峰早苗和二宫律子都察觉到气氛微妙，渡边麻衣却毫不客气地插嘴。', '', '', '', '', 's3426', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3426', 'chapter_30', 30, 'dialogue', 3426, 'mai', '渡边麻衣', '多亏了你！让小爱答应加入 B 小町可费了社长好大功夫。', '', '', '', '', 's3427', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3427', 'chapter_30', 30, 'dialogue', 3427, 'sanae', '高峰早苗', '笨蛋渡边，这个时候说什么呢。', '', '', '', '', 's3428', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3428', 'chapter_30', 30, 'dialogue', 3428, 'ritsuko', '二宫律子', '我也过去好了……', '', '', '', '', 's3429', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3429', 'chapter_30', 30, 'set', 3429, '', '', '', '', '', 'event_cg_mode', 'true', 's3430', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3430', 'chapter_30', 30, 'scene', 3430, '', '', '', 'cg ch30_ai_secret_training', '', '', '', 's3431', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3431', 'chapter_30', 30, 'narration', 3431, '', '', '其他人离开后，星野爱靠近一点，把手指放在唇边。', '', '', '', '', 's3432', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3432', 'chapter_30', 30, 'dialogue', 3432, 'ai', '星野爱', '那就当是秘密咯。', '', '', '', '', 's3433', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3433', 'chapter_30', 30, 'narration', 3433, '', '', '她笑得很自然，声音干净到像透明的水。', '', '', '', '', 's3434', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3434', 'chapter_30', 30, 'narration', 3434, '', '', '可那句话是谎言。一个毫无疑问的谎言。', '', '', '', '', 's3435', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3435', 'chapter_30', 30, 'narration', 3435, '', '', '顾天鹏甚至险些以为它是真的。也许连星野爱自己，都在那一瞬间相信了那句话。', '', '', '', '', 's3436', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3436', 'chapter_30', 30, 'narration', 3436, '', '', '他张开嘴，想问清楚那句话究竟指什么，最后却什么也没有说。', '', '', '', '', 's3437', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3437', 'chapter_30', 30, 'narration', 3437, '', '', '风吹进阳光里，橡树叶在头顶簌簌响。远处有人交谈，落在地上的叶片被踩碎。', '', '', '', '', 's3438', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3438', 'chapter_30', 30, 'narration', 3438, '', '', '星野爱却像什么都没发生，拿出手机给他看舞蹈视频。她指着屏幕讲解队形，语气认真得像在讲一件极其普通的事。', '', '', '', '', 's3439', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3439', 'chapter_30', 30, 'dialogue', 3439, 'ai', '星野爱', '这里要转身，然后第四拍要对齐。', '', '', '', '', 's3440', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3440', 'chapter_30', 30, 'dialogue', 3440, 'taku', '顾天鹏', '看起来很难。', '', '', '', '', 's3441', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3441', 'chapter_30', 30, 'dialogue', 3441, 'ai', '星野爱', '是吧？所以她们才一直说要练。', '', '', '', '', 's3442', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3442', 'chapter_30', 30, 'set', 3442, '', '', '', '', '', 'event_cg_mode', 'false', 's3443', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3443', 'chapter_30', 30, 'set', 3443, '', '', '', '', '', 'ai_sprite_mode', 'true', 's3444', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3444', 'chapter_30', 30, 'set', 3444, '', '', '', '', '', 'ai_sprite_outfit', 'ch30_practice_tired', 's3445', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3445', 'chapter_30', 30, 'scene', 3445, '', '', '', 'bg ch28_ochanomizu_steps', '', '', '', 's3446', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3446', 'chapter_30', 30, 'sprite', 3446, '', '', '', '', '[{"image": "sanae practice", "pos": "cast_group_left"}]', '', '', 's3447', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3447', 'chapter_30', 30, 'sprite', 3447, '', '', '', '', '[{"image": "ritsuko practice", "pos": "cast_group_midleft"}]', '', '', 's3448', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3448', 'chapter_30', 30, 'sprite', 3448, '', '', '', '', '[{"image": "heroine ch30_practice_tired", "pos": "cast_group_midright"}]', '', '', 's3449', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3449', 'chapter_30', 30, 'sprite', 3449, '', '', '', '', '[{"image": "mai practice", "pos": "cast_group_right"}]', '', '', 's3450', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3450', 'chapter_30', 30, 'narration', 3450, '', '', '两点四十多，B小町的休息结束。星野爱回去训练，顾天鹏坐在远处看着。', '', '', '', '', 's3451', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3451', 'chapter_30', 30, 'dialogue', 3451, 'ai', '星野爱', '还没准备走吧？', '', '', '', '', 's3452', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3452', 'chapter_30', 30, 'dialogue', 3452, 'taku', '顾天鹏', '时间还早。', '', '', '', '', 's3453', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3453', 'chapter_30', 30, 'dialogue', 3453, 'ai', '星野爱', '要是不嫌无聊，就留下来陪着我们训练，怎么样？', '', '', '', '', 's3454', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3454', 'chapter_30', 30, 'dialogue', 3454, 'taku', '顾天鹏', '没问题。本来也是因为这个来的。', '', '', '', '', 's3455', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3455', 'chapter_30', 30, 'dialogue', 3455, 'ai', '星野爱', '好的～', '', '', '', '', 's3456', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3456', 'chapter_30', 30, 'dialogue', 3456, 'sanae', '高峰早苗', '小爱这里的问题比较大，要多注意。渡边，第四拍没跟上。', '', '', '', '', 's3457', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3457', 'chapter_30', 30, 'dialogue', 3457, 'mai', '渡边麻衣', '我已经尽力啦。', '', '', '', '', 's3458', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3458', 'chapter_30', 30, 'dialogue', 3458, 'ritsuko', '二宫律子', '抱歉。', '', '', '', '', 's3459', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3459', 'chapter_30', 30, 'narration', 3459, '', '', '临近五点，训练结束。', '', '', '', '', 's3460', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3460', 'chapter_30', 30, 'dialogue', 3460, 'ai', '星野爱', '要不要一起吃饭？', '', '', '', '', 's3461', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3461', 'chapter_30', 30, 'dialogue', 3461, 'taku', '顾天鹏', '不用了。晚上还有工作，现在差不多要回去了。', '', '', '', '', 's3462', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3462', 'chapter_30', 30, 'dialogue', 3462, 'ai', '星野爱', '那我送你。', '', '', '', '', 's3463', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3463', 'chapter_30', 30, 'dialogue', 3463, 'taku', '顾天鹏', '训练那么久，怎么可能不饿。就这样吧，我先走了。', '', '', '', '', 's3464', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3464', 'chapter_30', 30, 'narration', 3464, '', '', '星野爱望着他离开的方向，欲言又止。', '', '', '', '', 's3465', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3465', 'chapter_30', 30, 'narration', 3465, '', '', '送他一程是借口，不饿也是谎言。她只是想在路上多说点话而已。', '', '', '', '', 's3466', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3466', 'chapter_30', 30, 'narration', 3466, '', '', '但这种想法又显得莫名其妙。直到顾天鹏已经走远，她也没想明白刚才究竟想说什么。', '', '', '', '', 's3467', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3467', 'chapter_30', 30, 'narration', 3467, '', '', '她只知道今天相处的时间太短，短到连一句普通的再见都显得不够。', '', '', '', '', 's3468', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3468', 'chapter_30', 30, 'scene', 3468, '', '', '', 'bg ch23_tokyo_cafe_night', '', '', '', 's3469', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3469', 'chapter_30', 30, 'narration', 3469, '', '', '顾天鹏提前十分钟回到咖啡店。六点换上制服，工作一直持续到九点。', '', '', '', '', 's3470', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3470', 'chapter_30', 30, 'scene', 3470, '', '', '', 'bg ch30_apartment_phone', '', '', '', 's3471', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3471', 'chapter_30', 30, 'narration', 3471, '', '', '回到家里，十一点三十多，他做完每天该做的事，换上干净短袖坐到书桌旁。', '', '', '', '', 's3472', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3472', 'chapter_30', 30, 'narration', 3472, '', '', '手机振动了一下。', '', '', '', '', 's3473', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3473', 'chapter_30', 30, 'sprite', 3473, '', '', '', '', '[{"image": "yuki phone", "pos": "cast_single_center"}]', '', '', 's3474', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3474', 'chapter_30', 30, 'dialogue', 3474, 'yuki', '小仓友希', '晚安。', '', '', '', '', 's3475', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3475', 'chapter_30', 30, 'narration', 3475, '', '', '消息很简单。', '', '', '', '', 's3476', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3476', 'chapter_30', 30, 'end', 3476, '', '', '', '', '', '', '', NULL, 'chapter_30');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3477', 'ending_karuizawa_fade', 0, 'set', 3477, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3478', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3478', 'ending_karuizawa_fade', 0, 'set', 3478, '', '', '', '', '', 'event_cg_mode', 'false', 's3479', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3479', 'ending_karuizawa_fade', 0, 'scene', 3479, '', '', '', 'bg ch17_pet_shop', '', '', '', 's3480', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3480', 'ending_karuizawa_fade', 0, 'narration', 3480, '', '', '顾天鹏没有接受那份兼职。', '', '', '', '', 's3481', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3481', 'ending_karuizawa_fade', 0, 'narration', 3481, '', '', '轻井泽的冬天仍然安静，猫、咖啡、书店和街景都只是旅途里经过的东西。', '', '', '', '', 's3482', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3482', 'ending_karuizawa_fade', 0, 'narration', 3482, '', '', '春天到来以前，他回了东京。后来某个四月，他路过一条开满樱花的坡道，却没有在那里停下。', '', '', '', '', 's3483', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3483', 'ending_karuizawa_fade', 0, 'end', 3483, '', '', '', '', '', '', '', NULL, 'ending_karuizawa_fade');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3484', 'ending_spring_no_line', 0, 'set', 3484, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3485', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3485', 'ending_spring_no_line', 0, 'set', 3485, '', '', '', '', '', 'event_cg_mode', 'false', 's3486', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3486', 'ending_spring_no_line', 0, 'scene', 3486, '', '', '', 'bg ch20_sakura_slope', '', '', '', 's3487', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3487', 'ending_spring_no_line', 0, 'narration', 3487, '', '', '照片被她收下了，联系方式却没有交换。', '', '', '', '', 's3488', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3488', 'ending_spring_no_line', 0, 'narration', 3488, '', '', '樱花仍旧落在他们之间，电车也照常驶过。只是春天再明亮，也没有办法替沉默发送消息。', '', '', '', '', 's3489', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3489', 'ending_spring_no_line', 0, 'end', 3489, '', '', '', '', '', '', '', NULL, 'ending_spring_no_line');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3490', 'ending_overclear_relationship', 0, 'set', 3490, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3491', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3491', 'ending_overclear_relationship', 0, 'set', 3491, '', '', '', '', '', 'event_cg_mode', 'false', 's3492', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3492', 'ending_overclear_relationship', 0, 'scene', 3492, '', '', '', 'bg ch23_tokyo_cafe_night', '', '', '', 's3493', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3493', 'ending_overclear_relationship', 0, 'narration', 3493, '', '', '那个答案太快，也太明确。', '', '', '', '', 's3494', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3494', 'ending_overclear_relationship', 0, 'narration', 3494, '', '', '星野爱笑着把话题带过去，像什么都没有发生。可之后的联系变得礼貌，训练邀请也没有再出现。', '', '', '', '', 's3495', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3495', 'ending_overclear_relationship', 0, 'narration', 3495, '', '', '有些关系不是不能靠近，只是不能用错误的名字靠近。', '', '', '', '', 's3496', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3496', 'ending_overclear_relationship', 0, 'end', 3496, '', '', '', '', '', '', '', NULL, 'ending_overclear_relationship');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3497', 'ending_unvisited_training', 0, 'set', 3497, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3498', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3498', 'ending_unvisited_training', 0, 'set', 3498, '', '', '', '', '', 'event_cg_mode', 'false', 's3499', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3499', 'ending_unvisited_training', 0, 'scene', 3499, '', '', '', 'bg ch28_ochanomizu_steps', '', '', '', 's3500', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3500', 'ending_unvisited_training', 0, 'narration', 3500, '', '', '顾天鹏没有去御茶之水。', '', '', '', '', 's3501', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3501', 'ending_unvisited_training', 0, 'narration', 3501, '', '', '星野爱仍然开始训练，B小町也仍然向选秀节目靠近。只是她没有机会在树荫下对他说，那一切因他而起。', '', '', '', '', 's3502', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3502', 'ending_unvisited_training', 0, 'end', 3502, '', '', '', '', '', '', '', NULL, 'ending_unvisited_training');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3503', 'ending_summer_promise', 0, 'set', 3503, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3504', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3504', 'ending_summer_promise', 0, 'set', 3504, '', '', '', '', '', 'ai_sprite_position', 'center', 's3505', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3505', 'ending_summer_promise', 0, 'set', 3505, '', '', '', '', '', 'event_cg_mode', 'false', 's3506', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3506', 'ending_summer_promise', 0, 'scene', 3506, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's3507', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3507', 'ending_summer_promise', 0, 'narration', 3507, '', '', '顾天鹏没有立刻追去车站，也没有把那封信当成故事的结尾。', '', '', '', '', 's3508', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3508', 'ending_summer_promise', 0, 'narration', 3508, '', '', '他在旧轻井泽的街上走了很久，最后停在那家他们曾经路过的服装店前。', '', '', '', '', 's3509', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3509', 'ending_summer_promise', 0, 'narration', 3509, '', '', '橱窗里，夏天的裙子已经换到更显眼的位置。', '', '', '', '', 's3510', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3510', 'ending_summer_promise', 0, 'dialogue', 3510, 'taku', '顾天鹏', '到时候再买也不迟。', '', '', '', '', 's3511', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3511', 'ending_summer_promise', 0, 'narration', 3511, '', '', '他说过这句话。', '', '', '', '', 's3512', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3512', 'ending_summer_promise', 0, 'narration', 3512, '', '', '于是他推开门，把那件衣服买了下来。', '', '', '', '', 's3513', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3513', 'ending_summer_promise', 0, 'narration', 3513, '', '', '不是为了替她决定什么，只是为了把一个还没来得及抵达的季节，好好留住。', '', '', '', '', 's3514', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3514', 'ending_summer_promise', 0, 'scene', 3514, '', '', '', 'bg station_sunbreak', '', '', '', 's3515', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3515', 'ending_summer_promise', 0, 'narration', 3515, '', '', '后来，冬天过去，春天也过去。', '', '', '', '', 's3516', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3516', 'ending_summer_promise', 0, 'narration', 3516, '', '', '顾天鹏开始工作，按时吃饭，继续跑步，也继续读那本被她翻过的书。', '', '', '', '', 's3517', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3517', 'ending_summer_promise', 0, 'narration', 3517, '', '', '他没有把她变成必须追回来的目标。', '', '', '', '', 's3518', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3518', 'ending_summer_promise', 0, 'narration', 3518, '', '', '只是每到下雨的列车，每到甜点店的橱窗，每到有人说起夏天，他都会想起她。', '', '', '', '', 's3519', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3519', 'ending_summer_promise', 0, 'narration', 3519, '', '', '七月的第一个周末，他收到一张没有署名的明信片。', '', '', '', '', 's3520', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3520', 'ending_summer_promise', 0, 'dialogue', 3520, 'ai_letter', '星野爱的信', '夏天到了。那件衣服，还在吗？', '', '', '', '', 's3521', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3521', 'ending_summer_promise', 0, 'narration', 3521, '', '', '字迹很轻，像害怕把什么惊醒。', '', '', '', '', 's3522', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3522', 'ending_summer_promise', 0, 'narration', 3522, '', '', '顾天鹏看了很久，终于笑出来。', '', '', '', '', 's3523', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3523', 'ending_summer_promise', 0, 'scene', 3523, '', '', '', 'bg ch10_ice_cream_shop', '', '', '', 's3524', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3524', 'ending_summer_promise', 0, 'narration', 3524, '', '', '他们在夏天的轻井泽重逢。', '', '', '', '', 's3525', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3525', 'ending_summer_promise', 0, 'narration', 3525, '', '', '星野爱戴着帽子，站在冰淇淋店门口，像只是迟到了几分钟。', '', '', '', '', 's3526', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3526', 'ending_summer_promise', 0, 'dialogue', 3526, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's3527', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3527', 'ending_summer_promise', 0, 'dialogue', 3527, 'taku', '顾天鹏', '我在。', '', '', '', '', 's3528', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3528', 'ending_summer_promise', 0, 'narration', 3528, '', '', '她听见这句话，眼睛弯起来。', '', '', '', '', 's3529', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3529', 'ending_summer_promise', 0, 'dialogue', 3529, 'ai', '星野爱', '衣服呢？', '', '', '', '', 's3530', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3530', 'ending_summer_promise', 0, 'dialogue', 3530, 'taku', '顾天鹏', '在。', '', '', '', '', 's3531', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3531', 'ending_summer_promise', 0, 'dialogue', 3531, 'ai', '星野爱', '那就好。', '', '', '', '', 's3532', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3532', 'ending_summer_promise', 0, 'narration', 3532, '', '', '她没有解释自己为什么离开，也没有立刻把所有难过都说清楚。', '', '', '', '', 's3533', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3533', 'ending_summer_promise', 0, 'narration', 3533, '', '', '顾天鹏也没有催。', '', '', '', '', 's3534', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3534', 'ending_summer_promise', 0, 'narration', 3534, '', '', '夏天很长，长到足够让他们把没说完的话慢慢补上。', '', '', '', '', 's3535', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3535', 'ending_summer_promise', 0, 'narration', 3535, '', '', '夏天的风从街角吹来，把他们没说完的话轻轻往前推。', '', '', '', '', 's3536', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3536', 'ending_summer_promise', 0, 'end', 3536, '', '', '', '', '', '', '', NULL, 'ending_summer_promise');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3537', 'route_main_search', 16, 'set', 3537, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3538', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3538', 'route_main_search', 16, 'set', 3538, '', '', '', '', '', 'ai_sprite_position', 'center', 's3539', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3539', 'route_main_search', 16, 'set', 3539, '', '', '', '', '', 'event_cg_mode', 'false', 's3540', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3540', 'route_main_search', 16, 'scene', 3540, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's3541', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3541', 'route_main_search', 16, 'narration', 3541, '', '', '顾天鹏没有把退房手续立刻办完。', '', '', '', '', 's3542', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3542', 'route_main_search', 16, 'narration', 3542, '', '', '他先去前台询问清晨最早离开的客人，又把车站方向、出租车乘车点和旅馆门前被雨水打湿的石阶，一处一处重新走过。', '', '', '', '', 's3543', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3543', 'route_main_search', 16, 'narration', 3543, '', '', '星野爱留下的话很清楚。不要来找我。', '', '', '', '', 's3544', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3544', 'route_main_search', 16, 'narration', 3544, '', '', '可越是清楚，那句话就越像一扇被人从里面反锁的门。', '', '', '', '', 's3545', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3545', 'route_main_search', 16, 'dialogue', 3545, 'taku', '顾天鹏', '如果这也是谎言呢。', '', '', '', '', 's3546', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3546', 'route_main_search', 16, 'narration', 3546, '', '', '他轻声说出口。', '', '', '', '', 's3547', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3547', 'route_main_search', 16, 'narration', 3547, '', '', '能力没有回应。因为那句话不是她亲口说给他听的，只是一行落在纸上的字。', '', '', '', '', 's3548', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3548', 'route_main_search', 16, 'narration', 3548, '', '', '顾天鹏把信纸贴回胸口。', '', '', '', '', 's3549', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3549', 'route_main_search', 16, 'dialogue', 3549, 'taku', '顾天鹏', '那我只能自己判断。', '', '', '', '', 's3550', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3550', 'route_main_search', 16, 'scene', 3550, '', '', '', 'bg ch9_karuizawa_bus_stop', '', '', '', 's3551', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3551', 'route_main_search', 16, 'narration', 3551, '', '', '公交站台上还残留着昨夜的雨。', '', '', '', '', 's3552', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3552', 'route_main_search', 16, 'narration', 3552, '', '', '他从时刻表上确认最早一班车的方向，又向站务员描述清晨拖着行李箱的少女。', '', '', '', '', 's3553', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3553', 'route_main_search', 16, 'narration', 3553, '', '', '得到的答案并不完整：白色裙子，浅色外套，很安静，似乎没有买去东京的票。', '', '', '', '', 's3554', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3554', 'route_main_search', 16, 'narration', 3554, '', '', '不是东京。', '', '', '', '', 's3555', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3555', 'route_main_search', 16, 'narration', 3555, '', '', '这个结论让他心脏缓慢地跳了一下。', '', '', '', '', 's3556', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3556', 'route_main_search', 16, 'narration', 3556, '', '', '轻井泽之外，还有长野、还有高崎、还有更远的某个站台。', '', '', '', '', 's3557', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3557', 'route_main_search', 16, 'narration', 3557, '', '', '她并不是凭空消失。只是把自己藏进了无数可能性里。', '', '', '', '', 's3558', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3558', 'route_main_search', 16, 'scene', 3558, '', '', '', 'bg train_table_rain', '', '', '', 's3559', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3559', 'route_main_search', 16, 'narration', 3559, '', '', '午后，顾天鹏坐上离开轻井泽的列车。', '', '', '', '', 's3560', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3560', 'route_main_search', 16, 'narration', 3560, '', '', '车窗外的雨线不断后退，像有人把这几天的风景一格一格卷回胶片。', '', '', '', '', 's3561', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3561', 'route_main_search', 16, 'narration', 3561, '', '', '他摊开随身带着的地图，在每一个可能换乘的车站旁做下记号。', '', '', '', '', 's3562', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3562', 'route_main_search', 16, 'narration', 3562, '', '', '这不是浪漫的追逐。', '', '', '', '', 's3563', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3563', 'route_main_search', 16, 'narration', 3563, '', '', '也不是笃定能抵达结局的冒险。', '', '', '', '', 's3564', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3564', 'route_main_search', 16, 'narration', 3564, '', '', '只是他第一次不愿把一个人的离开，轻易理解成故事的句号。', '', '', '', '', 's3565', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3565', 'route_main_search', 16, 'dialogue', 3565, 'taku', '顾天鹏', '爱。', '', '', '', '', 's3566', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3566', 'route_main_search', 16, 'narration', 3566, '', '', '名字落在车厢的低声轰鸣里。', '', '', '', '', 's3567', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3567', 'route_main_search', 16, 'dialogue', 3567, 'taku', '顾天鹏', '如果还能再相见，我会先问你过得好不好。', '', '', '', '', 's3568', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3568', 'route_main_search', 16, 'narration', 3568, '', '', '他顿了顿，把笔尖按在纸上。', '', '', '', '', 's3569', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3569', 'route_main_search', 16, 'dialogue', 3569, 'taku', '顾天鹏', '然后再问，你到底想不想被找到。', '', '', '', '', 's3570', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3570', 'route_main_search', 16, 'narration', 3570, '', '', '列车驶入隧道，窗外短暂地黑了下去。', '', '', '', '', 's3571', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3571', 'route_main_search', 16, 'narration', 3571, '', '', '黑暗中，顾天鹏看见自己的倒影。', '', '', '', '', 's3572', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3572', 'route_main_search', 16, 'narration', 3572, '', '', '那张脸不再像一个被留在原地的人。', '', '', '', '', 's3573', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3573', 'route_main_search', 16, 'narration', 3573, '', '', '列车驶出隧道时，远处露出一线很淡的天光。', '', '', '', '', 's3574', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3574', 'route_main_search', 16, 'end', 3574, '', '', '', '', '', '', '', NULL, 'route_main_search');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3575', 'route_side_memory', 16, 'set', 3575, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3576', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3576', 'route_side_memory', 16, 'set', 3576, '', '', '', '', '', 'ai_sprite_position', 'center', 's3577', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3577', 'route_side_memory', 16, 'set', 3577, '', '', '', '', '', 'event_cg_mode', 'false', 's3578', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3578', 'route_side_memory', 16, 'scene', 3578, '', '', '', 'bg ch10_inn_evening_room', '', '', '', 's3579', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3579', 'route_side_memory', 16, 'narration', 3579, '', '', '顾天鹏最后还是没有去车站询问。', '', '', '', '', 's3580', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3580', 'route_side_memory', 16, 'narration', 3580, '', '', '这并不是因为他真的相信那封信里的每一个字。', '', '', '', '', 's3581', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3581', 'route_side_memory', 16, 'narration', 3581, '', '', '只是他忽然意识到，追上去并不一定意味着靠近。', '', '', '', '', 's3582', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3582', 'route_side_memory', 16, 'narration', 3582, '', '', '有些人离开时已经用尽了力气。如果连这点距离都不肯留给她，也许反而会把那几天一起弄坏。', '', '', '', '', 's3583', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3583', 'route_side_memory', 16, 'narration', 3583, '', '', '他把信收好，替她退掉了没有用完的早餐券。', '', '', '', '', 's3584', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3584', 'route_side_memory', 16, 'narration', 3584, '', '', '旅馆老板娘问他是否还要续住一天。', '', '', '', '', 's3585', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3585', 'route_side_memory', 16, 'narration', 3585, '', '', '顾天鹏想了想，点头。', '', '', '', '', 's3586', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3586', 'route_side_memory', 16, 'scene', 3586, '', '', '', 'bg ch12_kumoba_pond', '', '', '', 's3587', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3587', 'route_side_memory', 16, 'narration', 3587, '', '', '他一个人去了云场池。', '', '', '', '', 's3588', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3588', 'route_side_memory', 16, 'narration', 3588, '', '', '水面仍旧明亮，秋天仍旧倒在里面，像昨天没有发生过任何告别。', '', '', '', '', 's3589', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3589', 'route_side_memory', 16, 'narration', 3589, '', '', '他站在岸边，把那张没有丢掉的照片举到眼前。', '', '', '', '', 's3590', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3590', 'route_side_memory', 16, 'narration', 3590, '', '', '照片里的她笑得很好看。', '', '', '', '', 's3591', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3591', 'route_side_memory', 16, 'narration', 3591, '', '', '现实里只剩风吹过水面，细小的波纹把天空切成无数碎片。', '', '', '', '', 's3592', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3592', 'route_side_memory', 16, 'dialogue', 3592, 'taku', '顾天鹏', '你看。', '', '', '', '', 's3593', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3593', 'route_side_memory', 16, 'narration', 3593, '', '', '顾天鹏对着空无一人的身旁说。', '', '', '', '', 's3594', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3594', 'route_side_memory', 16, 'dialogue', 3594, 'taku', '顾天鹏', '今天的秋天也掉进水里了。', '', '', '', '', 's3595', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3595', 'route_side_memory', 16, 'narration', 3595, '', '', '没有人回答他。', '', '', '', '', 's3596', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3596', 'route_side_memory', 16, 'narration', 3596, '', '', '但这一次，沉默没有把他推回原地。', '', '', '', '', 's3597', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3597', 'route_side_memory', 16, 'scene', 3597, '', '', '', 'bg ch13_miharashidai_sunset', '', '', '', 's3598', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3598', 'route_side_memory', 16, 'narration', 3598, '', '', '傍晚，他又去了见晴台。', '', '', '', '', 's3599', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3599', 'route_side_memory', 16, 'narration', 3599, '', '', '秋千还在那里，藤条在风里轻轻晃动。', '', '', '', '', 's3600', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3600', 'route_side_memory', 16, 'narration', 3600, '', '', '顾天鹏坐上去，只晃了一下就停住。', '', '', '', '', 's3601', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3601', 'route_side_memory', 16, 'narration', 3601, '', '', '他终于明白，一个人完成两个人的旅行，并不是为了假装她还在。', '', '', '', '', 's3602', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3602', 'route_side_memory', 16, 'narration', 3602, '', '', '而是为了确认她确实来过。', '', '', '', '', 's3603', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3603', 'route_side_memory', 16, 'narration', 3603, '', '', '确认那几天的开心、害怕、向日葵和拙劣的玩笑，都不是可以被一封信完全带走的东西。', '', '', '', '', 's3604', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3604', 'route_side_memory', 16, 'narration', 3604, '', '', '夕阳落下去以前，他把那张照片放回书页。', '', '', '', '', 's3605', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3605', 'route_side_memory', 16, 'dialogue', 3605, 'taku', '顾天鹏', '如果还能再相见。', '', '', '', '', 's3606', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3606', 'route_side_memory', 16, 'narration', 3606, '', '', '他望着远处的山线，声音很轻。', '', '', '', '', 's3607', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3607', 'route_side_memory', 16, 'dialogue', 3607, 'taku', '顾天鹏', '我会告诉你，轻井泽的秋天，我替你走完了。', '', '', '', '', 's3608', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3608', 'route_side_memory', 16, 'narration', 3608, '', '', '风吹过树梢。', '', '', '', '', 's3609', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3609', 'route_side_memory', 16, 'narration', 3609, '', '', '夕阳完全落下去的时候，他终于能把那几天称作回忆。', '', '', '', '', 's3610', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3610', 'route_side_memory', 16, 'end', 3610, '', '', '', '', '', '', '', NULL, 'route_side_memory');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3611', 'ending_leaf_bookmark', 0, 'set', 3611, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3612', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3612', 'ending_leaf_bookmark', 0, 'set', 3612, '', '', '', '', '', 'ai_sprite_position', 'center', 's3613', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3613', 'ending_leaf_bookmark', 0, 'set', 3613, '', '', '', '', '', 'event_cg_mode', 'false', 's3614', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3614', 'ending_leaf_bookmark', 0, 'scene', 3614, '', '', '', 'bg ch9_roadside_steps', '', '', '', 's3615', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3615', 'ending_leaf_bookmark', 0, 'narration', 3615, '', '', '那天之后，他们没有立刻把喜欢的理由说清楚。', '', '', '', '', 's3616', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3616', 'ending_leaf_bookmark', 0, 'narration', 3616, '', '', '红色落叶被夹进《了不起的盖茨比》里，叶脉薄得像一张不敢寄出的信。', '', '', '', '', 's3617', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3617', 'ending_leaf_bookmark', 0, 'narration', 3617, '', '', '星野爱偶尔会问一句：', '', '', '', '', 's3618', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3618', 'ending_leaf_bookmark', 0, 'dialogue', 3618, 'ai', '星野爱', '保证金还在吗？', '', '', '', '', 's3619', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3619', 'ending_leaf_bookmark', 0, 'narration', 3619, '', '', '顾天鹏每次都把书拿出来给她看。叶子越来越干，颜色却没有完全褪掉。', '', '', '', '', 's3620', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3620', 'ending_leaf_bookmark', 0, 'narration', 3620, '', '', '旅行后来还是走到了分别。只是这一次，她留下的信里多了一行字。', '', '', '', '', 's3621', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3621', 'ending_leaf_bookmark', 0, 'dialogue', 3621, 'ai_letter', '星野爱的信', '冬天的理由，我想起来了。因为那几天，有人把我的秘密当成秘密保管。', '', '', '', '', 's3622', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3622', 'ending_leaf_bookmark', 0, 'narration', 3622, '', '', '很久以后，顾天鹏在夏天打开那本书。落叶已经脆得不能再碰，夹在书页里的影子却还完整。', '', '', '', '', 's3623', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3623', 'ending_leaf_bookmark', 0, 'narration', 3623, '', '', '他终于把自己的答案写在空白处：', '', '', '', '', 's3624', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3624', 'ending_leaf_bookmark', 0, 'dialogue', 3624, 'taku', '顾天鹏', '因为夏天适合重逢。', '', '', '', '', 's3625', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3625', 'ending_leaf_bookmark', 0, 'narration', 3625, '', '', '窗外蝉声渐起，夏天终于替那片叶子补上了迟来的回答。', '', '', '', '', 's3626', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3626', 'ending_leaf_bookmark', 0, 'end', 3626, '', '', '', '', '', '', '', NULL, 'ending_leaf_bookmark');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3627', 'ending_missed_companion', 0, 'set', 3627, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3628', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3628', 'ending_missed_companion', 0, 'set', 3628, '', '', '', '', '', 'ai_sprite_position', 'center', 's3629', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3629', 'ending_missed_companion', 0, 'set', 3629, '', '', '', '', '', 'event_cg_mode', 'false', 's3630', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3630', 'ending_missed_companion', 0, 'scene', 3630, '', '', '', 'bg train_table_night', '', '', '', 's3631', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3631', 'ending_missed_companion', 0, 'narration', 3631, '', '', '夜色降下来以后，两个人之间重新变得安静。', '', '', '', '', 's3632', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3632', 'ending_missed_companion', 0, 'narration', 3632, '', '', '星野爱没有再提出同行，也没有表现出失望。', '', '', '', '', 's3633', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3633', 'ending_missed_companion', 0, 'narration', 3633, '', '', '她只是把攻略收回包里，趴在桌上睡着了。', '', '', '', '', 's3634', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3634', 'ending_missed_companion', 0, 'narration', 3634, '', '', '顾天鹏看着窗玻璃里的倒影，忽然意识到，有些故事并不会因为相遇就自动开始。', '', '', '', '', 's3635', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3635', 'ending_missed_companion', 0, 'narration', 3635, '', '', '第二天清晨，他们在越后汤泽的站台分别。', '', '', '', '', 's3636', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3636', 'ending_missed_companion', 0, 'narration', 3636, '', '', '她拖着白色行李箱走进人群，没有回头。', '', '', '', '', 's3637', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3637', 'ending_missed_companion', 0, 'narration', 3637, '', '', '顾天鹏后来一个人泡温泉、看雪、吃荞麦面。', '', '', '', '', 's3638', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3638', 'ending_missed_companion', 0, 'narration', 3638, '', '', '那些风景都很好，只是再也没有谁站在旁边说自己是世界上最贪婪的少女。', '', '', '', '', 's3639', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3639', 'ending_missed_companion', 0, 'narration', 3639, '', '', '后来他再想起那趟列车，只记得窗外的雪很白，身边的位置很空。', '', '', '', '', 's3640', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3640', 'ending_missed_companion', 0, 'end', 3640, '', '', '', '', '', '', '', NULL, 'ending_missed_companion');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3641', 'ending_empty_encouragement', 0, 'set', 3641, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3642', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3642', 'ending_empty_encouragement', 0, 'set', 3642, '', '', '', '', '', 'ai_sprite_position', 'center', 's3643', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3643', 'ending_empty_encouragement', 0, 'set', 3643, '', '', '', '', '', 'event_cg_mode', 'false', 's3644', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3644', 'ending_empty_encouragement', 0, 'scene', 3644, '', '', '', 'bg ch5_summit_sunset', '', '', '', 's3645', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3645', 'ending_empty_encouragement', 0, 'narration', 3645, '', '', '黄昏把雪地染成温柔的金色。', '', '', '', '', 's3646', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3646', 'ending_empty_encouragement', 0, 'narration', 3646, '', '', '星野爱听完那句鼓励，笑着点了点头。', '', '', '', '', 's3647', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3647', 'ending_empty_encouragement', 0, 'narration', 3647, '', '', '那笑容没有错，却也没有真正抵达她心里。', '', '', '', '', 's3648', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3648', 'ending_empty_encouragement', 0, 'narration', 3648, '', '', '顾天鹏很久以后才明白，有些时候，急着把人从难过里拉出来，反而会让对方更确信自己不该开口。', '', '', '', '', 's3649', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3649', 'ending_empty_encouragement', 0, 'narration', 3649, '', '', '下山以后，她仍然活泼，仍然会开玩笑。', '', '', '', '', 's3650', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3650', 'ending_empty_encouragement', 0, 'narration', 3650, '', '', '只是那些更深的话，再也没有被她拿出来过。', '', '', '', '', 's3651', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3651', 'ending_empty_encouragement', 0, 'narration', 3651, '', '', '旅行结束那天，她礼貌地道谢，像谢过一位偶然同行的好人。', '', '', '', '', 's3652', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3652', 'ending_empty_encouragement', 0, 'narration', 3652, '', '', '那些没能继续说下去的话，最终和山顶的风一起散在雪里。', '', '', '', '', 's3653', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3653', 'ending_empty_encouragement', 0, 'end', 3653, '', '', '', '', '', '', '', NULL, 'ending_empty_encouragement');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3654', 'ending_light_answer', 0, 'set', 3654, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3655', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3655', 'ending_light_answer', 0, 'set', 3655, '', '', '', '', '', 'ai_sprite_position', 'center', 's3656', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3656', 'ending_light_answer', 0, 'set', 3656, '', '', '', '', '', 'event_cg_mode', 'false', 's3657', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3657', 'ending_light_answer', 0, 'scene', 3657, '', '', '', 'bg ch10_white_church_wedding', '', '', '', 's3658', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3658', 'ending_light_answer', 0, 'narration', 3658, '', '', '掌声渐渐远去，白鸽也飞过屋檐。', '', '', '', '', 's3659', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3659', 'ending_light_answer', 0, 'narration', 3659, '', '', '顾天鹏给出了一个很认真的答案，可它太轻了。', '', '', '', '', 's3660', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3660', 'ending_light_answer', 0, 'narration', 3660, '', '', '星野爱把那句“会的”收下，像收下一张漂亮却没有重量的明信片。', '', '', '', '', 's3661', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3661', 'ending_light_answer', 0, 'narration', 3661, '', '', '他们仍然去吃午饭，仍然买蛋糕，也仍然在夜里分掉那块巧克力奶油。', '', '', '', '', 's3662', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3662', 'ending_light_answer', 0, 'narration', 3662, '', '', '可那扇门已经重新关上。', '', '', '', '', 's3663', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3663', 'ending_light_answer', 0, 'narration', 3663, '', '', '第二天早晨，她离开得很早，信里只写着一句：', '', '', '', '', 's3664', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3664', 'ending_light_answer', 0, 'dialogue', 3664, 'ai_letter', '星野爱的信', '谢谢你。你是个温柔的人。', '', '', '', '', 's3665', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3665', 'ending_light_answer', 0, 'narration', 3665, '', '', '温柔有时并不够。', '', '', '', '', 's3666', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3666', 'ending_light_answer', 0, 'narration', 3666, '', '', '信纸被他折回原样，轻得几乎拿不住。', '', '', '', '', 's3667', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3667', 'ending_light_answer', 0, 'end', 3667, '', '', '', '', '', '', '', NULL, 'ending_light_answer');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3668', 'ending_too_close', 0, 'set', 3668, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3669', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3669', 'ending_too_close', 0, 'set', 3669, '', '', '', '', '', 'ai_sprite_position', 'center', 's3670', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3670', 'ending_too_close', 0, 'set', 3670, '', '', '', '', '', 'event_cg_mode', 'false', 's3671', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3671', 'ending_too_close', 0, 'scene', 3671, '', '', '', 'bg ch13_miharashidai_sunset', '', '', '', 's3672', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3672', 'ending_too_close', 0, 'narration', 3672, '', '', '顾天鹏靠近得太快。', '', '', '', '', 's3673', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3673', 'ending_too_close', 0, 'narration', 3673, '', '', '星野爱没有躲开，只是把水瓶握得很紧，指节一点点泛白。', '', '', '', '', 's3674', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3674', 'ending_too_close', 0, 'dialogue', 3674, 'ai', '星野爱', '对不起，我没事。', '', '', '', '', 's3675', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3675', 'ending_too_close', 0, 'narration', 3675, '', '', '她笑起来，笑得比刚才更像没事。', '', '', '', '', 's3676', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3676', 'ending_too_close', 0, 'narration', 3676, '', '', '顾天鹏停在她身边，却忽然发现自己已经错过了最该停下来的距离。', '', '', '', '', 's3677', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3677', 'ending_too_close', 0, 'narration', 3677, '', '', '那天晚上，她没有再哭。', '', '', '', '', 's3678', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3678', 'ending_too_close', 0, 'narration', 3678, '', '', '第二天，她也没有留下那封更长的信。', '', '', '', '', 's3679', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3679', 'ending_too_close', 0, 'narration', 3679, '', '', '桌上只有一张便签，字迹工整得像练习过很多遍。', '', '', '', '', 's3680', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3680', 'ending_too_close', 0, 'dialogue', 3680, 'ai_letter', '星野爱的信', '我先走了。祝你之后旅行顺利。', '', '', '', '', 's3681', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3681', 'ending_too_close', 0, 'narration', 3681, '', '', '那张便签在桌上停了很久，像一扇再也没有被敲响的门。', '', '', '', '', 's3682', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3682', 'ending_too_close', 0, 'end', 3682, '', '', '', '', '', '', '', NULL, 'ending_too_close');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3683', 'ending_white_church', 0, 'set', 3683, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3684', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3684', 'ending_white_church', 0, 'set', 3684, '', '', '', '', '', 'ai_sprite_position', 'center', 's3685', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3685', 'ending_white_church', 0, 'set', 3685, '', '', '', '', '', 'event_cg_mode', 'false', 's3686', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3686', 'ending_white_church', 0, 'scene', 3686, '', '', '', 'bg ch10_white_church_wedding', '', '', '', 's3687', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3687', 'ending_white_church', 0, 'narration', 3687, '', '', '那天他们没有继续站在教堂前看别人的婚礼。', '', '', '', '', 's3688', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3688', 'ending_white_church', 0, 'narration', 3688, '', '', '星野爱拉着他绕到教堂后面，那里没有掌声，只有一排被风吹得发亮的树。', '', '', '', '', 's3689', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3689', 'ending_white_church', 0, 'dialogue', 3689, 'ai', '星野爱', '以后再确认，听起来像拖延。', '', '', '', '', 's3690', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3690', 'ending_white_church', 0, 'dialogue', 3690, 'taku', '顾天鹏', '也可以叫预约。', '', '', '', '', 's3691', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3691', 'ending_white_church', 0, 'narration', 3691, '', '', '她笑了很久。', '', '', '', '', 's3692', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3692', 'ending_white_church', 0, 'narration', 3692, '', '', '后来那句话没有马上兑现。她仍然离开，仍然留下信。', '', '', '', '', 's3693', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3693', 'ending_white_church', 0, 'narration', 3693, '', '', '可很多年后，顾天鹏收到一张白色教堂的照片。', '', '', '', '', 's3694', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3694', 'ending_white_church', 0, 'dialogue', 3694, 'ai_letter', '星野爱的信', '预约还算数吗？', '', '', '', '', 's3695', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3695', 'ending_white_church', 0, 'narration', 3695, '', '', '照片背面没有地址，只盖着轻井泽的邮戳。', '', '', '', '', 's3696', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3696', 'ending_white_church', 0, 'narration', 3696, '', '', '顾天鹏把照片翻过来，指尖停在那枚轻井泽邮戳上。', '', '', '', '', 's3697', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3697', 'ending_white_church', 0, 'end', 3697, '', '', '', '', '', '', '', NULL, 'ending_white_church');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3698', 'ending_silver_chain', 0, 'set', 3698, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3699', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3699', 'ending_silver_chain', 0, 'set', 3699, '', '', '', '', '', 'ai_sprite_position', 'center', 's3700', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3700', 'ending_silver_chain', 0, 'set', 3700, '', '', '', '', '', 'event_cg_mode', 'false', 's3701', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3701', 'ending_silver_chain', 0, 'scene', 3701, '', '', '', 'bg ch10_old_karuizawa_street', '', '', '', 's3702', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3702', 'ending_silver_chain', 0, 'narration', 3702, '', '', '离开饰品店时，星野爱没有买下那对手链。', '', '', '', '', 's3703', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3703', 'ending_silver_chain', 0, 'narration', 3703, '', '', '可是走出几步以后，她又回头看了一眼。', '', '', '', '', 's3704', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3704', 'ending_silver_chain', 0, 'dialogue', 3704, 'ai', '星野爱', '那个真的有点太直白了。', '', '', '', '', 's3705', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3705', 'ending_silver_chain', 0, 'dialogue', 3705, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's3706', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3706', 'ending_silver_chain', 0, 'dialogue', 3706, 'ai', '星野爱', '所以才会记住。', '', '', '', '', 's3707', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3707', 'ending_silver_chain', 0, 'narration', 3707, '', '', '傍晚时，顾天鹏偷偷折回去，把其中一条买了下来。', '', '', '', '', 's3708', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3708', 'ending_silver_chain', 0, 'narration', 3708, '', '', '他没有送出去，只把它放进书页里，和那张云场池的照片夹在一起。', '', '', '', '', 's3709', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3709', 'ending_silver_chain', 0, 'narration', 3709, '', '', '很多年后，银色坠子仍然没有氧化，像某个始终没有说出口的答案。', '', '', '', '', 's3710', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3710', 'ending_silver_chain', 0, 'narration', 3710, '', '', '书页合上时，银光仍在很深的地方静静亮着。', '', '', '', '', 's3711', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3711', 'ending_silver_chain', 0, 'end', 3711, '', '', '', '', '', '', '', NULL, 'ending_silver_chain');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3712', 'ending_sunflower_between', 0, 'set', 3712, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3713', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3713', 'ending_sunflower_between', 0, 'set', 3713, '', '', '', '', '', 'ai_sprite_position', 'center', 's3714', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3714', 'ending_sunflower_between', 0, 'set', 3714, '', '', '', '', '', 'event_cg_mode', 'false', 's3715', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3715', 'ending_sunflower_between', 0, 'scene', 3715, '', '', '', 'bg ch13_miharashidai_sunset', '', '', '', 's3716', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3716', 'ending_sunflower_between', 0, 'narration', 3716, '', '', '向日葵被放在两个人中间。', '', '', '', '', 's3717', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3717', 'ending_sunflower_between', 0, 'narration', 3717, '', '', '它不属于谁，也没有替谁承担所有重量。', '', '', '', '', 's3718', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3718', 'ending_sunflower_between', 0, 'narration', 3718, '', '', '星野爱看着那枝花，终于慢慢低下头。', '', '', '', '', 's3719', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3719', 'ending_sunflower_between', 0, 'dialogue', 3719, 'ai', '星野爱', '这样的话，好像就不会弄脏了。', '', '', '', '', 's3720', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3720', 'ending_sunflower_between', 0, 'dialogue', 3720, 'taku', '顾天鹏', '嗯。', '', '', '', '', 's3721', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3721', 'ending_sunflower_between', 0, 'dialogue', 3721, 'ai', '星野爱', '因为不是我一个人的东西。', '', '', '', '', 's3722', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3722', 'ending_sunflower_between', 0, 'narration', 3722, '', '', '他们在夕阳里坐到很晚。', '', '', '', '', 's3723', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3723', 'ending_sunflower_between', 0, 'narration', 3723, '', '', '之后的某一天，顾天鹏收到一张照片。照片里只有一枝向日葵，插在透明玻璃瓶里。', '', '', '', '', 's3724', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3724', 'ending_sunflower_between', 0, 'dialogue', 3724, 'ai_letter', '星野爱的信', '它还在朝着太阳。', '', '', '', '', 's3725', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3725', 'ending_sunflower_between', 0, 'narration', 3725, '', '', '那一刻，他才明白，有些太阳确实可以被好好保存下来。', '', '', '', '', 's3726', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3726', 'ending_sunflower_between', 0, 'end', 3726, '', '', '', '', '', '', '', NULL, 'ending_sunflower_between');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3727', 'ending_bench_dawn', 0, 'set', 3727, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3728', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3728', 'ending_bench_dawn', 0, 'set', 3728, '', '', '', '', '', 'ai_sprite_position', 'center', 's3729', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3729', 'ending_bench_dawn', 0, 'set', 3729, '', '', '', '', '', 'event_cg_mode', 'false', 's3730', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3730', 'ending_bench_dawn', 0, 'scene', 3730, '', '', '', 'bg ch14_roadside_bench_night', '', '', '', 's3731', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3731', 'ending_bench_dawn', 0, 'narration', 3731, '', '', '那一晚，他们真的坐了很久。', '', '', '', '', 's3732', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3732', 'ending_bench_dawn', 0, 'narration', 3732, '', '', '没有人急着许诺，也没有人急着把明天安排成某种正确答案。', '', '', '', '', 's3733', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3733', 'ending_bench_dawn', 0, 'narration', 3733, '', '', '星野爱靠在长椅另一端，闭着眼睛，像只是想确认身旁还有人。', '', '', '', '', 's3734', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3734', 'ending_bench_dawn', 0, 'dialogue', 3734, 'ai', '星野爱', '顾天鹏。', '', '', '', '', 's3735', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3735', 'ending_bench_dawn', 0, 'dialogue', 3735, 'taku', '顾天鹏', '我在。', '', '', '', '', 's3736', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3736', 'ending_bench_dawn', 0, 'dialogue', 3736, 'ai', '星野爱', '明天如果我还是很麻烦呢？', '', '', '', '', 's3737', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3737', 'ending_bench_dawn', 0, 'dialogue', 3737, 'taku', '顾天鹏', '那就明天再说。', '', '', '', '', 's3738', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3738', 'ending_bench_dawn', 0, 'narration', 3738, '', '', '天快亮的时候，她没有离开。', '', '', '', '', 's3739', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3739', 'ending_bench_dawn', 0, 'narration', 3739, '', '', '她只是把那封写了一半的信揉成很小的一团，塞进口袋里。', '', '', '', '', 's3740', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3740', 'ending_bench_dawn', 0, 'narration', 3740, '', '', '晨光从路尽头慢慢漫过来，把那张没有寄出的信照得很亮。', '', '', '', '', 's3741', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3741', 'ending_bench_dawn', 0, 'end', 3741, '', '', '', '', '', '', '', NULL, 'ending_bench_dawn');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3742', 'ending_quiet_parting', 0, 'set', 3742, '', '', '', '', '', 'ai_sprite_mode', 'false', 's3743', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3743', 'ending_quiet_parting', 0, 'set', 3743, '', '', '', '', '', 'ai_sprite_position', 'center', 's3744', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3744', 'ending_quiet_parting', 0, 'set', 3744, '', '', '', '', '', 'event_cg_mode', 'true', 's3745', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3745', 'ending_quiet_parting', 0, 'scene', 3745, '', '', '', 'cg ch15_empty_room_letter', '', '', '', 's3746', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3746', 'ending_quiet_parting', 0, 'narration', 3746, '', '', '顾天鹏醒来时，窗外的竹林被晨雾压得很低。', '', '', '', '', 's3747', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3747', 'ending_quiet_parting', 0, 'narration', 3747, '', '', '旁边的被褥已经冷了，桌上只剩一封折好的信。', '', '', '', '', 's3748', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3748', 'ending_quiet_parting', 0, 'narration', 3748, '', '', '信里没有责怪，也没有请求，只写着一句很轻的话：', '', '', '', '', 's3749', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3749', 'ending_quiet_parting', 0, 'dialogue', 3749, 'ai_letter', '星野爱的信', '谢谢你陪我走到这里。接下来的路，我想一个人试试看。', '', '', '', '', 's3750', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3750', 'ending_quiet_parting', 0, 'narration', 3750, '', '', '他把那句话读了很久。', '', '', '', '', 's3751', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3751', 'ending_quiet_parting', 0, 'narration', 3751, '', '', '如果昨晚多停一会儿，如果没有把她的计划当成玩笑，也许故事还会继续。', '', '', '', '', 's3752', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3752', 'ending_quiet_parting', 0, 'narration', 3752, '', '', '可是选择已经落下，像清晨合上的门。', '', '', '', '', 's3753', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3753', 'ending_quiet_parting', 0, 'narration', 3753, '', '', '她没有等到明天。', '', '', '', '', 's3754', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3754', 'ending_quiet_parting', 0, 'narration', 3754, '', '', '清晨的门缝里没有回声，只剩信纸在桌上安静地等他醒来。', '', '', '', '', 's3755', '');
INSERT INTO sekai_GaLaGame_lies_story_nodes (node_key, label_name, chapter_no, node_type, seq_no, speaker_key, speaker_name, text, bg_image, sprites, set_var, set_value, next_key, ending_key) VALUES ('s3755', 'ending_quiet_parting', 0, 'end', 3755, '', '', '', '', '', '', '', NULL, 'ending_quiet_parting');
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s55', '主动伸手接过行李箱', 's56', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s55', '等她开口以后再动作', 's59', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s314', '一起走吧', 's315', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s314', '先把规则说清楚', 's318', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s314', '还是各走各的', 's335', 2);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s480', '承认自己其实也饿了', 's481', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s480', '继续维护不太成功的体面', 's491', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s684', '走标着路牌的左侧山道', 's685', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s684', '陪她往没有脚印的雪地多看一眼', 's693', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s883', '急着告诉她你可以', 's884', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s883', '先把她的话完整接住', 's892', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s922', '把备用暖宝宝递给她', 's923', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s922', '提醒她回房先换干衣服', 's929', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1091', '认真邀请她一起晨跑', 's1092', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1091', '只是开个不会被答应的玩笑', 's1098', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1407', '让她决定最后一天的安排', 's1408', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1407', '按攻略补完还没去过的地点', 's1412', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1758', '告诉她自己喜欢夏天', 's1759', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1758', '继续把理由留成秘密', 's1767', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1949', '认真回答她会的', 's1950', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1949', '先问她为什么这么想', 's1957', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s1949', '把答案留给以后', 's1965', 2);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s2162', '只买一朵，按她说的来', 's2163', 0);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s2162', '买两朵，把另一朵留给自己', 's2169', 1);
INSERT INTO sekai_GaLaGame_lies_choices (node_key, option_text, next_key, order_no) VALUES ('s2282', '认真看看那对手链', 's2283', 0);
